def _detect_free_positions(eq_text, eq_vars):
    """Detect which variable positions in the hypothesis are 'free' — i.e.,
    the output is independent of that variable's value.
    Returns list of (position_index, variable_name) that are free on LHS or RHS."""
    parts = eq_text.split('=', 1)
    if len(parts) != 2:
        return [], []

    lhs = parts[0].strip()
    rhs = parts[1].strip()
    lhs_vars = set(re.findall(r'\b([a-z])\b', lhs))
    rhs_vars = set(re.findall(r'\b([a-z])\b', rhs))

    # Variables in RHS but not LHS → LHS is independent of them
    # Variables in LHS but not RHS → RHS is independent of them
    rhs_only = [(i, v) for i, v in enumerate(eq_vars) if v in rhs_vars and v not in lhs_vars]
    lhs_only = [(i, v) for i, v in enumerate(eq_vars) if v in lhs_vars and v not in rhs_vars]
    return lhs_only, rhs_only


def _build_independence_lemma(eq_text, eq_vars, free_pos_idx, free_var):
    """Given a free variable position, build a proof that the operation is
    independent of that argument position.

    If free_var is in RHS only, then varying it doesn't change LHS.
    So: h(x,...,a,...) and h(x,...,b,...) give same LHS,
    therefore the two RHS expressions are equal.

    Returns (lean_proof, lemma_statement) or None."""
    parts = eq_text.split('=', 1)
    if len(parts) != 2:
        return None
    lhs = parts[0].strip()
    rhs = parts[1].strip()

    # Build two instantiations differing only in the free position
    args_a = list(eq_vars)
    args_b = list(eq_vars)
    # Use 'a' and 'b' as the differing values, rename other vars if conflict
    used_vars = set(eq_vars)
    fresh = []
    for candidate in 'abcdefghijklmnopqrstuvwxyz':
        if candidate not in used_vars:
            fresh.append(candidate)
        if len(fresh) >= 2:
            break
    if len(fresh) < 2:
        return None

    args_a[free_pos_idx] = fresh[0]
    args_b[free_pos_idx] = fresh[1]

    # The lemma: (h args_a).symm.trans (h args_b) gives:
    # rhs[free_var → a] = rhs[free_var → b]
    rhs_a = re.sub(r'\b' + free_var + r'\b', fresh[0], rhs)
    rhs_b = re.sub(r'\b' + free_var + r'\b', fresh[1], rhs)

    return {
        'args_a': args_a,
        'args_b': args_b,
        'free_var': free_var,
        'free_pos': free_pos_idx,
        'fresh': fresh,
        'rhs_a': rhs_a,
        'rhs_b': rhs_b,
    }


def try_calc_chain_proof(problem, eq1_text, eq2_text, max_depth=5):
    """Try to find a calc-chain proof by BFS over rewriting steps.
    Each step applies h with some substitution, using the whole equation as a rewrite.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()
    g_lhs = eq2_lhs.replace(' ', '')
    g_rhs = eq2_rhs.replace(' ', '')

    # Pre-compute all useful h instantiations (with goal variables)
    all_insts = {}  # (lhs_norm, rhs_norm) -> args_string
    for combo in product(eq2_vars, repeat=len(eq1_vars)):
        new_lhs = simultaneous_subst(eq1_lhs, eq1_vars, combo)
        new_rhs = simultaneous_subst(eq1_rhs, eq1_vars, combo)
        nl = new_lhs.replace(' ', '')
        nr = new_rhs.replace(' ', '')
        if nl == nr:
            continue
        if nl not in all_insts:
            all_insts[nl] = {}
        all_insts[nl][nr] = ' '.join(combo)
        # Also store reverse direction
        if nr not in all_insts:
            all_insts[nr] = {}
        if nl not in all_insts[nr]:
            all_insts[nr][nl] = '(' + ' '.join(combo) + ').symm'

    # BFS from goal LHS to goal RHS
    # State: current normalized expression
    # Transition: apply any h-instantiation that matches current expression on LHS side
    visited = {g_lhs: (None, None)}  # expr -> (prev_expr, args_to_get_here)
    frontier = [g_lhs]

    for depth in range(max_depth):
        next_frontier = []
        for expr in frontier:
            if expr not in all_insts:
                continue
            for target, args in all_insts[expr].items():
                if target in visited:
                    continue
                visited[target] = (expr, args)
                if target == g_rhs:
                    # Found a path! Reconstruct it
                    path = []
                    cur = g_rhs
                    while visited[cur][0] is not None:
                        prev, a = visited[cur]
                        path.append((prev, cur, a))
                        cur = prev
                    path.reverse()

                    # Build calc proof
                    intro = f"intro {' '.join(eq2_vars)}"
                    calc_lines = [intro, "calc"]
                    for i, (frm, to, a) in enumerate(path):
                        # Recover the non-normalized form for the first line
                        if i == 0:
                            calc_lines.append(f"  _ = _ := by exact h {a}")
                        else:
                            if a.startswith('(') and a.endswith(').symm'):
                                real_args = a[1:-6]
                                calc_lines.append(f"  _ = _ := by exact (h {real_args}).symm")
                            else:
                                calc_lines.append(f"  _ = _ := by exact h {a}")

                    proof = '\n'.join(calc_lines)
                    code = make_true_code(problem, proof)
                    result = call_judge("true", code)
                    if result.get("status") == "accepted":
                        return True

                    # If the _ = _ style doesn't work, try with explicit terms
                    # (Lean may need help inferring the intermediate terms)
                    # Skip for now — will be handled by LLM if this fails

                next_frontier.append(target)
        frontier = next_frontier
        if not frontier:
            break

    return False


def try_compound_calc_proof(problem, eq1_text, eq2_text, max_judge_calls=3):
    """Try a calc-chain proof where h-arguments can be compound terms (e.g., x ◇ y).
    This extends try_calc_chain_proof by considering substitutions with terms
    built from goal variables, not just bare variables.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()
    g_lhs = eq2_lhs.replace(' ', '')
    g_rhs = eq2_rhs.replace(' ', '')

    # Generate compound terms from goal variables: bare vars + all pairwise (a ◇ b)
    bare_terms = list(eq2_vars)
    compound_only = []
    for a in eq2_vars:
        for b in eq2_vars:
            compound_only.append(f"({a} ◇ {b})")

    n_h = len(eq1_vars)  # number of h-arguments
    n_b = len(bare_terms)
    n_c = len(compound_only)

    # Build instantiations by iterating combos ordered by number of compound terms.
    # k=0: all bare (already handled by try_calc_chain_proof, skip)
    # k=1: exactly one compound argument position — n_h * n_c * n_b^(n_h-1)
    # k=2: exactly two compound positions — C(n_h,2) * n_c^2 * n_b^(n_h-2)
    all_insts = {}

    def _add_combo(combo):
        new_lhs = simultaneous_subst(eq1_lhs, eq1_vars, combo)
        new_rhs = simultaneous_subst(eq1_rhs, eq1_vars, combo)
        nl = new_lhs.replace(' ', '')
        nr = new_rhs.replace(' ', '')
        if nl == nr:
            return
        if nl not in all_insts:
            all_insts[nl] = {}
        all_insts[nl][nr] = ' '.join(combo)
        if nr not in all_insts:
            all_insts[nr] = {}
        if nl not in all_insts[nr]:
            all_insts[nr][nl] = '(' + ' '.join(combo) + ').symm'

    # k=1: one compound position, rest bare
    k1_count = n_h * n_c * (n_b ** max(n_h - 1, 0))
    if k1_count <= 200000:
        for pos in range(n_h):
            for ct in compound_only:
                for bare_combo in product(bare_terms, repeat=n_h - 1):
                    combo = list(bare_combo[:pos]) + [ct] + list(bare_combo[pos:])
                    _add_combo(combo)

    # k=2: two compound positions, rest bare (if h has >= 2 args)
    if n_h >= 2:
        k2_count = len(list(combinations(range(n_h), 2))) * (n_c ** 2) * (n_b ** max(n_h - 2, 0))
        if k2_count <= 200000:
            for pos1, pos2 in combinations(range(n_h), 2):
                for ct1 in compound_only:
                    for ct2 in compound_only:
                        for bare_combo in product(bare_terms, repeat=n_h - 2):
                            combo = list(bare_combo)
                            combo.insert(pos1, ct1)
                            combo.insert(pos2, ct2)
                            _add_combo(combo)

    # BFS from goal LHS to goal RHS (3-step max)
    visited = {g_lhs: (None, None)}
    frontier = [g_lhs]
    calls_used = 0

    for depth in range(3):
        next_frontier = []
        for expr in frontier:
            if expr not in all_insts:
                continue
            for target, args in all_insts[expr].items():
                if target in visited:
                    continue
                visited[target] = (expr, args)
                if target == g_rhs:
                    path = []
                    cur = g_rhs
                    while visited[cur][0] is not None:
                        prev, a = visited[cur]
                        path.append((prev, cur, a))
                        cur = prev
                    path.reverse()

                    intro = f"intro {' '.join(eq2_vars)}"
                    calc_lines = [intro, "calc"]
                    for i, (frm, to, a) in enumerate(path):
                        if a.startswith('(') and a.endswith(').symm'):
                            real_args = a[1:-6]
                            calc_lines.append(f"  _ = _ := by exact (h {real_args}).symm")
                        else:
                            calc_lines.append(f"  _ = _ := by exact h {a}")

                    proof = '\n'.join(calc_lines)
                    code = make_true_code(problem, proof)
                    result = call_judge("true", code)
                    calls_used += 1
                    if result.get("status") == "accepted":
                        return True
                    if calls_used >= max_judge_calls:
                        return False

                next_frontier.append(target)
        frontier = next_frontier
        if not frontier:
            break

    return False


def try_rw_chain_proof(problem, eq1_text, eq2_text, max_judge_calls=6):
    """Try a proof using rw tactics instead of calc chains.
    Sometimes Lean's unifier works better with rw [h args] patterns.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)
    intro = f"intro {' '.join(eq2_vars)}"

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()

    # Collect candidate combos — prioritize by structural relevance
    scored_combos = []
    for combo in product(eq2_vars, repeat=len(eq1_vars)):
        new_lhs = simultaneous_subst(eq1_lhs, eq1_vars, combo)
        new_rhs = simultaneous_subst(eq1_rhs, eq1_vars, combo)
        nl = new_lhs.replace(' ', '')
        nr = new_rhs.replace(' ', '')
        if nl == nr:
            continue
        # Score: how many characters overlap with the goal equation
        score = (string_overlap(nl, eq2_lhs.replace(' ', '')) +
                 string_overlap(nr, eq2_rhs.replace(' ', '')))
        scored_combos.append((score, combo))
    scored_combos.sort(reverse=True)

    # Strategy 1: Single rw step with best combos (uses 2 judge calls max)
    proofs_to_try = []
    seen = set()
    for _, combo in scored_combos[:3]:
        args = ' '.join(combo)
        p1 = f"{intro}\nrw [h {args}]"
        p2 = f"{intro}\nrw [← h {args}]"
        if p1 not in seen:
            proofs_to_try.append(p1)
            seen.add(p1)
        if p2 not in seen:
            proofs_to_try.append(p2)
            seen.add(p2)

    # Strategy 2: Two rw steps with the top 4 combos (limited)
    top_combos = [c for _, c in scored_combos[:4]]
    for i, c1 in enumerate(top_combos):
        for c2 in top_combos:
            a1 = ' '.join(c1)
            a2 = ' '.join(c2)
            for p in [
                f"{intro}\nrw [h {a1}]\nrw [h {a2}]",
                f"{intro}\nrw [← h {a1}]\nrw [h {a2}]",
                f"{intro}\nrw [h {a1}]\nrw [← h {a2}]",
            ]:
                if p not in seen:
                    proofs_to_try.append(p)
                    seen.add(p)

    # Submit limited candidates
    calls = 0
    for proof in proofs_to_try:
        if calls >= max_judge_calls:
            break
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True

    return False


def try_congr_arg_proof(problem, eq1_text, eq2_text, max_judge_calls=3):
    """Try proofs using congr_arg to apply an equation to sub-expressions.

    Pattern 1 (iterated): If eq1 is single-variable `a ◇ a = f(a)` and eq2 is
    the iterated version `a ◇ a = f(f(a))`, prove by chaining h(x) with congr_arg.

    Pattern 2 (constant bridge): From eq1 derive that (a◇a)◇b is constant in b,
    and (c◇a)◇c = f(a) for all c; bridge through c = x◇x to show f is constant.

    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    intro = f"intro {' '.join(eq2_vars)}"
    calls = 0

    # ── Pattern 1: Single-variable iterated congr_arg ──
    if len(eq1_vars) == 1 and len(eq2_vars) == 1:
        v = eq2_vars[0]
        # Try: exact (h x).trans (congr_arg (· ◇ x) (h x))
        proof = f"{intro}\nexact (h {v}).trans (congr_arg (\u00b7 \u25c7 {v}) (h {v}))"
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True
        if calls >= max_judge_calls:
            return False

        # Try simp-based rewriting
        for direction in ["\u2190 ", ""]:
            proof = f"{intro}\nsimp only [{direction}h {v}]"
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True
            if calls >= max_judge_calls:
                return False

    # ── Pattern 2: Constant bridge (3-var hypothesis → 3 or 4-var goal) ──
    if len(eq1_vars) == 3 and len(eq2_vars) in (3, 4):
        gv = eq2_vars
        proofs = _build_bridge_proofs(eq1_vars, gv, intro)
        for proof in proofs:
            if calls >= max_judge_calls:
                break
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True

    return False


def _build_bridge_proofs(eq1_vars, goal_vars, intro):
    """Generate constant-bridge proof candidates for 3-var hypothesis."""
    proofs = []
    v = eq1_vars

    # For 3-var hypothesis with structure (a◇a)◇b = (c◇a)◇c:
    # hconst = h a b a  (3rd arg = 1st)  → constancy
    # hcomm  = (h a a c).symm  (2nd arg = 1st) → pivot
    # Bridge: step through c = x◇x

    # Try the canonical permutation (matching the structure of Equation4616)
    const_args = "a b a"
    comm_args = "a a c"

    if len(goal_vars) == 4:
        gx, gy, gz, gw = goal_vars
        proof = (
            f"{intro}\n"
            f"have hconst : \u2200 (a b : G), (a \u25c7 a) \u25c7 b = (a \u25c7 a) \u25c7 a := "
            f"fun a b => h {const_args}\n"
            f"have hcomm : \u2200 (a c : G), (c \u25c7 a) \u25c7 c = (a \u25c7 a) \u25c7 a := "
            f"fun a c => (h {comm_args}).symm\n"
            f"have step1 := hcomm {gx} ({gx} \u25c7 {gx})\n"
            f"have step2 := hcomm {gz} ({gx} \u25c7 {gx})\n"
            f"have step3 := congr_arg (\u00b7 \u25c7 ({gx} \u25c7 {gx})) (hconst {gx} {gz})\n"
            f"calc ({gx} \u25c7 {gx}) \u25c7 {gy}\n"
            f"    = ({gx} \u25c7 {gx}) \u25c7 {gx} := hconst {gx} {gy}\n"
            f"  _ = (({gx} \u25c7 {gx}) \u25c7 {gx}) \u25c7 ({gx} \u25c7 {gx}) := step1.symm\n"
            f"  _ = (({gx} \u25c7 {gx}) \u25c7 {gz}) \u25c7 ({gx} \u25c7 {gx}) := step3.symm\n"
            f"  _ = ({gz} \u25c7 {gz}) \u25c7 {gz} := step2\n"
            f"  _ = ({gz} \u25c7 {gz}) \u25c7 {gw} := (hconst {gz} {gw}).symm"
        )
        proofs.append(proof)

    if len(goal_vars) == 3:
        gx, gy, gz = goal_vars
        proof = (
            f"{intro}\n"
            f"have hconst : \u2200 (a b : G), (a \u25c7 a) \u25c7 b = (a \u25c7 a) \u25c7 a := "
            f"fun a b => h {const_args}\n"
            f"have hcomm : \u2200 (a c : G), (c \u25c7 a) \u25c7 c = (a \u25c7 a) \u25c7 a := "
            f"fun a c => (h {comm_args}).symm\n"
            f"have step1 := hcomm {gx} ({gx} \u25c7 {gx})\n"
            f"have step2 := hcomm {gz} ({gx} \u25c7 {gx})\n"
            f"have step3 := congr_arg (\u00b7 \u25c7 ({gx} \u25c7 {gx})) (hconst {gx} {gz})\n"
            f"calc ({gx} \u25c7 {gx}) \u25c7 {gy}\n"
            f"    = ({gx} \u25c7 {gx}) \u25c7 {gx} := hconst {gx} {gy}\n"
            f"  _ = (({gx} \u25c7 {gx}) \u25c7 {gx}) \u25c7 ({gx} \u25c7 {gx}) := step1.symm\n"
            f"  _ = (({gx} \u25c7 {gx}) \u25c7 {gz}) \u25c7 ({gx} \u25c7 {gx}) := step3.symm\n"
            f"  _ = ({gz} \u25c7 {gz}) \u25c7 {gz} := step2\n"
            f"  _ = ({gz} \u25c7 {gz}) \u25c7 {gy} := (hconst {gz} {gy}).symm"
        )
        proofs.append(proof)

    return proofs


def try_simp_proof(problem, eq1_text, eq2_text, max_judge_calls=2):
    """Try proofs using simp only [h] and simp only [← h].
    This is a powerful general strategy — Lean's simplifier can often
    close goals that involve repeated application of the hypothesis.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq2_vars = parse_variables(eq2_text)
    intro = f"intro {' '.join(eq2_vars)}"
    calls = 0

    for direction in ["", "← "]:
        if calls >= max_judge_calls:
            break
        proof = f"{intro}\nsimp only [{direction}h]"
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True

    return False


def try_simp_with_constancy(problem, eq1_text, eq2_text, max_judge_calls=2):
    """Try simp only [h, hconst, ...] after deriving constancy lemmas.
    The simplifier can handle deeper rewriting chains when given both
    the hypothesis and derived constancy lemmas.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)
    constancy_info, lhs_only, rhs_only = build_constancy_info(eq1_text, eq1_vars, eq2_vars)
    if not constancy_info:
        return False

    intro = f"intro {' '.join(eq2_vars)}"
    calls = 0

    # Build have lines for all constancy lemmas
    ci_have_lines = []
    ci_names = []
    for i, ci in enumerate(constancy_info):
        name = "hconst" if i == 0 else f"hconst{i+1}"
        line = ci['have_line']
        if i > 0:
            line = line.replace('hconst', name, 1)
        ci_have_lines.append(line)
        ci_names.append(name)

    have_block = "\n".join(ci_have_lines)
    simp_names = ", ".join(ci_names)

    # Try various simp combinations
    simp_variants = [
        f"simp only [h, {simp_names}]",
        f"simp only [\u2190 h, {simp_names}]",
        f"simp only [{simp_names}, h]",
        f"simp only [{simp_names}, \u2190 h]",
    ]

    for simp_tactic in simp_variants:
        if calls >= max_judge_calls:
            break
        proof = f"{intro}\n{have_block}\n{simp_tactic}"
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True

    return False


def try_rw_simp_proof(problem, eq1_text, eq2_text, max_judge_calls=2):
    """Try rw [h args] followed by simp only [h] or simp only [← h].
    One strategic rewrite can transform the goal into something simp can close.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)
    intro = f"intro {' '.join(eq2_vars)}"

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()

    # Find combos where h-instantiation touches the goal
    scored_combos = []
    for combo in product(eq2_vars, repeat=len(eq1_vars)):
        new_lhs = simultaneous_subst(eq1_lhs, eq1_vars, combo)
        new_rhs = simultaneous_subst(eq1_rhs, eq1_vars, combo)
        nl = new_lhs.replace(' ', '')
        nr = new_rhs.replace(' ', '')
        if nl == nr:
            continue
        g_lhs = eq2_lhs.replace(' ', '')
        g_rhs = eq2_rhs.replace(' ', '')
        score = (string_overlap(nl, g_lhs) + string_overlap(nr, g_rhs) +
                 string_overlap(nl, g_rhs) + string_overlap(nr, g_lhs))
        scored_combos.append((score, combo))
    scored_combos.sort(reverse=True)

    calls = 0
    tried = set()
    for _, combo in scored_combos[:4]:
        args = ' '.join(combo)
        for rw_dir in ["", "\u2190 "]:
            for simp_dir in ["", "\u2190 "]:
                proof = f"{intro}\nrw [{rw_dir}h {args}]\nsimp only [{simp_dir}h]"
                if proof in tried:
                    continue
                tried.add(proof)
                if calls >= max_judge_calls:
                    return False
                code = make_true_code(problem, proof)
                result = call_judge("true", code)
                calls += 1
                if result.get("status") == "accepted":
                    return True

    return False


def try_specialized_simp(problem, eq1_text, eq2_text, max_judge_calls=2):
    """Try simp with a specialized version of the hypothesis.
    When the hypothesis LHS is a single variable x, derive h_spec by
    substituting all other variables to x: x = f(x, x, ..., x).
    Then simp only [h_spec] can handle goals by repeated rewriting.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    if len(parts1) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()

    # Only handle single-variable LHS
    if not re.match(r'^[a-z]$', eq1_lhs):
        return False

    lhs_var = eq1_lhs
    lhs_vars = set(re.findall(r'\b([a-z])\b', eq1_lhs))
    rhs_vars = set(re.findall(r'\b([a-z])\b', eq1_rhs))

    # Need at least one free variable
    if not (rhs_vars - lhs_vars):
        return False

    # Build h_spec args: map all vars to the LHS variable
    spec_args = ' '.join([lhs_var] * len(eq1_vars))
    # Build the specialized RHS
    spec_rhs = eq1_rhs
    for v in eq1_vars:
        if v != lhs_var:
            spec_rhs = re.sub(r'\b' + v + r'\b', lhs_var, spec_rhs)

    # Skip if specialized RHS is trivially the same as LHS
    if spec_rhs.replace(' ', '') == lhs_var:
        return False

    intro = f"intro {' '.join(eq2_vars)}"
    have_line = (
        f"have h_spec : \u2200 ({lhs_var} : G), "
        f"{lhs_var} = {spec_rhs} := fun {lhs_var} => h {spec_args}"
    )

    calls = 0
    for direction in ["", "\u2190 "]:
        if calls >= max_judge_calls:
            break
        proof = f"{intro}\n{have_line}\nsimp only [{direction}h_spec]"
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True

    return False


def try_have_chain_proof(problem, eq1_text, eq2_text, max_judge_calls=3):
    """Try proofs using `have` lemmas with independence/constancy arguments.

    When a hypothesis has free variables (appearing on only one side),
    we can derive constancy lemmas and use them to close the goal.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    intro = f"intro {' '.join(eq2_vars)}"
    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()

    lhs_only, rhs_only = _detect_free_positions(eq1_text, eq1_vars)
    if not lhs_only and not rhs_only:
        return False

    calls = 0

    # If there are variables only on RHS of hypothesis:
    # Then LHS is constant w.r.t. those variables.
    # This means: for any instantiation of non-free vars, the LHS value is fixed
    # regardless of the free variable.
    # Proof technique: (h args_a).symm.trans (h args_b) gives rhs_a = rhs_b
    for pos, fvar in rhs_only:
        info = _build_independence_lemma(eq1_text, eq1_vars, pos, fvar)
        if not info:
            continue

        # Build a constancy have-lemma
        fresh_a, fresh_b = info['fresh']
        other_vars = [v for i, v in enumerate(eq1_vars) if i != pos]
        quant_vars = other_vars + [fresh_a, fresh_b]

        args_a_str = ' '.join(info['args_a'])
        args_b_str = ' '.join(info['args_b'])

        # have hconst : ∀ (other_vars a b : G), rhs_a = rhs_b
        lemma_proof = f"(h {args_a_str}).symm.trans (h {args_b_str})"
        have_line = (
            f"have hconst : ∀ ({' '.join(quant_vars)} : G), "
            f"{info['rhs_a']} = {info['rhs_b']} := "
            f"fun {' '.join(quant_vars)} => {lemma_proof}"
        )

        # Try: intro; have hconst; exact hconst args
        # The args to hconst should match the goal variables
        for combo in product(eq2_vars, repeat=len(quant_vars)):
            if calls >= max_judge_calls:
                return False
            args = ' '.join(combo)
            proof = f"{intro}\n{have_line}\nexact hconst {args}"
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True
            break  # Only try the most natural combo

    # Similarly for variables only on LHS
    for pos, fvar in lhs_only:
        info = _build_independence_lemma(eq1_text, eq1_vars, pos, fvar)
        if not info:
            continue

        fresh_a, fresh_b = info['fresh']
        other_vars = [v for i, v in enumerate(eq1_vars) if i != pos]
        quant_vars = other_vars + [fresh_a, fresh_b]

        args_a_str = ' '.join(info['args_a'])
        args_b_str = ' '.join(info['args_b'])

        # When fvar is LHS-only: varying it doesn't change RHS
        # So h(args_a) gives lhs_a = rhs, h(args_b) gives lhs_b = rhs
        # Therefore (h args_a).trans (h args_b).symm gives lhs_a = lhs_b
        lhs_a = re.sub(r'\b' + fvar + r'\b', fresh_a, eq1_lhs)
        lhs_b = re.sub(r'\b' + fvar + r'\b', fresh_b, eq1_lhs)

        lemma_proof = f"(h {args_a_str}).trans (h {args_b_str}).symm"
        have_line = (
            f"have hconst : ∀ ({' '.join(quant_vars)} : G), "
            f"{lhs_a} = {lhs_b} := "
            f"fun {' '.join(quant_vars)} => {lemma_proof}"
        )

        for combo in product(eq2_vars, repeat=len(quant_vars)):
            if calls >= max_judge_calls:
                return False
            args = ' '.join(combo)
            proof = f"{intro}\n{have_line}\nexact hconst {args}"
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True
            break

    return False


def try_constant_proof(problem, eq1_text, eq2_text, max_judge_calls=4):
    """Try proofs for equations where the hypothesis makes some terms constant.

    When some variables appear only on one side of the hypothesis, the other
    side is constant w.r.t. those variables. We can use this to find
    2-step trans proofs through the constant value using compound arguments.

    Example: x ◇ y = (z ◇ z) ◇ z → both x◇y and (z◇z)◇z equal a constant.
    Any expression built from ◇ can be plugged in for x,y,z.

    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()

    lhs_vars = set(re.findall(r'\b([a-z])\b', eq1_lhs))
    rhs_vars = set(re.findall(r'\b([a-z])\b', eq1_rhs))

    intro = f"intro {' '.join(eq2_vars)}"
    calls = 0

    lhs_only = lhs_vars - rhs_vars
    rhs_only = rhs_vars - lhs_vars

    if not lhs_only and not rhs_only:
        return False

    # Build compound terms from goal variables (depth 0, 1, 2)
    terms = list(eq2_vars)
    for a in eq2_vars:
        for b in eq2_vars:
            terms.append(f"({a} \u25c7 {b})")
    if len(eq2_vars) <= 5:
        for a in eq2_vars:
            for b in eq2_vars:
                for c in eq2_vars:
                    terms.append(f"(({a} \u25c7 {b}) \u25c7 {c})")
                    terms.append(f"({a} \u25c7 ({b} \u25c7 {c}))")

    g_lhs = eq2_lhs.replace(' ', '')
    g_rhs = eq2_rhs.replace(' ', '')

    # Find h-instantiations matching each side of eq2 via unification
    def _unify_expr(template_str, target_str, tvars):
        """Try to find a substitution of tvars that makes template match target.
        Returns dict mapping var -> Lean expression, or None."""
        # Parse both into tree form
        def _parse(s):
            s = s.strip()
            while len(s) >= 2 and s[0] == '(' and s[-1] == ')':
                depth = 0; matched = True
                for i, c in enumerate(s):
                    if c == '(': depth += 1
                    elif c == ')': depth -= 1
                    if depth == 0 and i < len(s) - 1: matched = False; break
                if matched: s = s[1:-1].strip()
                else: break
            # Find outermost ◇
            depth = 0; last_op = -1
            for i, c in enumerate(s):
                if c == '(': depth += 1
                elif c == ')': depth -= 1
                elif c == '\u25c7' and depth == 0: last_op = i
            if last_op >= 0:
                return ('op', _parse(s[:last_op]), _parse(s[last_op+1:]))
            return ('var', s.strip())

        def _match(tpl, tgt, subst):
            if tpl[0] == 'var' and tpl[1] in tvars:
                v = tpl[1]
                # Reconstruct target as string
                tgt_str = _tree_to_str(tgt)
                if v in subst:
                    return subst[v] == tgt_str
                subst[v] = tgt_str
                return True
            if tpl[0] == 'var' and tgt[0] == 'var':
                return tpl[1] == tgt[1]
            if tpl[0] == 'op' and tgt[0] == 'op':
                s = dict(subst)
                if _match(tpl[1], tgt[1], s) and _match(tpl[2], tgt[2], s):
                    subst.update(s)
                    return True
            return False

        def _tree_to_str(t):
            if t[0] == 'var':
                return t[1]
            return f"({_tree_to_str(t[1])} \u25c7 {_tree_to_str(t[2])})"

        tpl_tree = _parse(template_str)
        tgt_tree = _parse(target_str)
        subst = {}
        if _match(tpl_tree, tgt_tree, subst):
            return subst
        return None

    tvar_set = set(eq1_vars)

    def _unify_and_format(template, target):
        """Unify template with target and return Lean args string, or None.
        For free variables not in the template, fill with the first goal var."""
        subst = _unify_expr(template, target, tvar_set)
        if subst is None:
            return None
        # Fill unbound vars (free variables) with the first available goal var
        default_fill = eq2_vars[0] if eq2_vars else 'x'
        for v in eq1_vars:
            if v not in subst:
                subst[v] = default_fill
        return ' '.join(subst[v] for v in eq1_vars)

    lhs_match_gl = _unify_and_format(eq1_lhs, eq2_lhs)
    lhs_match_gr = _unify_and_format(eq1_lhs, eq2_rhs)
    rhs_match_gl = _unify_and_format(eq1_rhs, eq2_lhs)
    rhs_match_gr = _unify_and_format(eq1_rhs, eq2_rhs)

    # Try various 2-step chains through the constant
    candidates = []
    # h(a1) : gl = rhs_const, h(a2) : gr = rhs_const → gl = rhs_const = gr
    if lhs_match_gl and lhs_match_gr:
        candidates.append(f"{intro}\nexact (h {lhs_match_gl}).trans (h {lhs_match_gr}).symm")
    # (h a1).symm : lhs_const = gl, (h a2).symm : lhs_const = gr
    if rhs_match_gl and rhs_match_gr:
        candidates.append(f"{intro}\nexact (h {rhs_match_gl}).symm.trans (h {rhs_match_gr}).symm")
    # h(a1) : gl = rhs_c, (h a2) : lhs_c = gr, need rhs_c = lhs_c
    if lhs_match_gl and rhs_match_gr:
        candidates.append(f"{intro}\nexact (h {lhs_match_gl}).trans (h {rhs_match_gr})")
    if rhs_match_gl and lhs_match_gr:
        candidates.append(f"{intro}\nexact (h {rhs_match_gl}).symm.trans (h {lhs_match_gr}).symm")

    for proof in candidates:
        if calls >= max_judge_calls:
            break
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True

    # Try congruence-based approach:
    # If goal is f(a) = f(b) for some common structure f, prove a = b first
    # using the constant-value property, then apply congr_arg.
    if calls < max_judge_calls:
        # Check if goal sides share common outer structure
        def _parse_tree(s):
            s = s.strip()
            while len(s) >= 2 and s[0] == '(' and s[-1] == ')':
                depth = 0; matched = True
                for i, c in enumerate(s):
                    if c == '(': depth += 1
                    elif c == ')': depth -= 1
                    if depth == 0 and i < len(s) - 1: matched = False; break
                if matched: s = s[1:-1].strip()
                else: break
            depth = 0; last_op = -1
            for i, c in enumerate(s):
                if c == '(': depth += 1
                elif c == ')': depth -= 1
                elif c == '\u25c7' and depth == 0: last_op = i
            if last_op >= 0:
                return ('op', _parse_tree(s[:last_op]), _parse_tree(s[last_op+1:]))
            return ('var', s.strip())

        def _tree_str(t):
            if t[0] == 'var': return t[1]
            return f"({_tree_str(t[1])} \u25c7 {_tree_str(t[2])})"

        gl = _parse_tree(eq2_lhs)
        gr = _parse_tree(eq2_rhs)

        # Check: both are op and share left or right subtree
        if gl[0] == 'op' and gr[0] == 'op':
            gl_left, gl_right = _tree_str(gl[1]), _tree_str(gl[2])
            gr_left, gr_right = _tree_str(gr[1]), _tree_str(gr[2])

            # Same left side: x ◇ a = x ◇ b → need a = b
            if gl_left == gr_left and gl_right != gr_right:
                inner_a = gl_right
                inner_b = gr_right
                # Try to prove inner_a = inner_b via h trans
                inner_lhs_a = _unify_and_format(eq1_lhs, inner_a)
                inner_lhs_b = _unify_and_format(eq1_lhs, inner_b)
                if inner_lhs_a and inner_lhs_b:
                    proof = (
                        f"{intro}\n"
                        f"exact congr_arg ({gl_left} \u25c7 \u00b7) ((h {inner_lhs_a}).trans (h {inner_lhs_b}).symm)"
                    )
                    if calls < max_judge_calls:
                        code = make_true_code(problem, proof)
                        result = call_judge("true", code)
                        calls += 1
                        if result.get("status") == "accepted":
                            return True

                inner_rhs_a = _unify_and_format(eq1_rhs, inner_a)
                inner_rhs_b = _unify_and_format(eq1_rhs, inner_b)
                if inner_rhs_a and inner_rhs_b:
                    proof = (
                        f"{intro}\n"
                        f"exact congr_arg ({gl_left} \u25c7 \u00b7) ((h {inner_rhs_a}).symm.trans (h {inner_rhs_b}).symm)"
                    )
                    if calls < max_judge_calls:
                        code = make_true_code(problem, proof)
                        result = call_judge("true", code)
                        calls += 1
                        if result.get("status") == "accepted":
                            return True

            # Same right side: a ◇ x = b ◇ x → need a = b
            if gl_right == gr_right and gl_left != gr_left:
                inner_a = gl_left
                inner_b = gr_left
                inner_lhs_a = _unify_and_format(eq1_lhs, inner_a)
                inner_lhs_b = _unify_and_format(eq1_lhs, inner_b)
                if inner_lhs_a and inner_lhs_b:
                    proof = (
                        f"{intro}\n"
                        f"exact congr_arg (\u00b7 \u25c7 {gl_right}) ((h {inner_lhs_a}).trans (h {inner_lhs_b}).symm)"
                    )
                    if calls < max_judge_calls:
                        code = make_true_code(problem, proof)
                        result = call_judge("true", code)
                        calls += 1
                        if result.get("status") == "accepted":
                            return True

                inner_rhs_a = _unify_and_format(eq1_rhs, inner_a)
                inner_rhs_b = _unify_and_format(eq1_rhs, inner_b)
                if inner_rhs_a and inner_rhs_b:
                    proof = (
                        f"{intro}\n"
                        f"exact congr_arg (\u00b7 \u25c7 {gl_right}) ((h {inner_rhs_a}).symm.trans (h {inner_rhs_b}).symm)"
                    )
                    if calls < max_judge_calls:
                        code = make_true_code(problem, proof)
                        result = call_judge("true", code)
                        calls += 1
                        if result.get("status") == "accepted":
                            return True

    return False


def try_deep_constancy_proof(problem, eq1_text, eq2_text, max_judge_calls=3):
    """Try proofs by deriving reduction lemmas via h(compound) + rw [(h ...).symm].

    For hypotheses of the form x = f(x, y_free, z_free), this:
    1. Applies h to compound subterms along the spine of the RHS
    2. Uses rw [(h args).symm] to simplify inner occurrences
    3. Derives a reduction lemma, then uses it + constancy to close the goal

    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    intro = f"intro {' '.join(eq2_vars)}"
    calls = 0

    # Only works when LHS is a single variable (x = f(x, y, z) form)
    if not re.match(r'^[a-z]$', eq1_lhs):
        return False

    lhs_var = eq1_lhs
    rhs_vars = set(re.findall(r'\b([a-z])\b', eq1_rhs))
    free_vars = sorted(rhs_vars - {lhs_var})
    if not free_vars:
        return False

    rhs_tree = parse_op_tree(eq1_rhs)
    if rhs_tree[0] != 'op':
        return False

    # Find the spine: path from root to the first occurrence of lhs_var
    def find_spine(tree, var, prefix=''):
        if tree[0] == 'var':
            return [(prefix, tree)] if tree[1] == var else None
        if tree[0] != 'op':
            return None
        lp = find_spine(tree[1], var, prefix + 'L')
        if lp is not None:
            return [(prefix, tree)] + lp
        rp = find_spine(tree[2], var, prefix + 'R')
        if rp is not None:
            return [(prefix, tree)] + rp
        return None

    spine = find_spine(rhs_tree, lhs_var)
    if not spine or len(spine) < 3:
        return False

    # spine[0] = (root, full_rhs_tree), spine[-1] = (leaf_path, var_node)
    # Intermediate nodes spine[1...-1] are compound subterms containing lhs_var

    # Strategy: for each intermediate spine node, try:
    # have lem1 := h <spine_node> <free_args>  -- gives spine_node = f(spine_node, ...)
    # Then rw [(h <args>).symm] at lem1  -- simplifies inner f(...) to x
    # This produces a "reduction lemma" that simplifies the spine node.
    # Then use this + constancy to build a deeper constancy, closing the goal.

    # Build free-var argument lists for h calls
    h_arity = len(eq1_vars)
    bound_pos = eq1_vars.index(lhs_var) if lhs_var in eq1_vars else 0

    # For each spine subtree (skip leaf x and full RHS):
    for si in range(1, len(spine) - 1):
        _, subtree = spine[si]
        st_str = tree_to_str(subtree)

        # Build h(<subtree>, free_args):
        # Replace lhs_var with st_str, keep free vars as fresh names
        h_args = []
        for vi, v in enumerate(eq1_vars):
            if v == lhs_var:
                h_args.append(f"({st_str})")
            else:
                h_args.append(v)
        h_compound = ' '.join(h_args)

        # Build (h <original_vars>).symm for the inner rw
        h_inner = ' '.join(eq1_vars)

        # Proof template: derive lem1 via h(compound) + rw [h.symm], then use lem1
        # Pattern: have lem1 := ...; then try various closures
        lem1_have = (
            f"have lem1 : ∀ ({' '.join(eq1_vars)} : G), _ := by\n"
            f"    intro {' '.join(eq1_vars)}\n"
            f"    have h1 := h {h_compound}\n"
            f"    rw [(h {h_inner}).symm] at h1\n"
            f"    exact h1"
        )

        # Try: intro vars; lem1; then derive deeper constancy and close
        # Build constancy from lem1 + h
        constancy_info, _, rhs_only = build_constancy_info(eq1_text, eq1_vars, eq2_vars)
        ci_block = ""
        ci_names = []
        if constancy_info:
            for i, ci in enumerate(constancy_info):
                name = "hconst" if i == 0 else f"hconst{i+1}"
                line = ci['have_line']
                if i > 0:
                    line = line.replace('hconst', name, 1)
                ci_block += line + "\n"
                ci_names.append(name)

        # Try several closure strategies with lem1 + constancy
        proofs = []

        # Closure 1: lem1 + constancy + simp
        if ci_names:
            simp_args = ", ".join(ci_names)
            proofs.append(
                f"{intro}\n{ci_block}{lem1_have}\n"
                f"simp only [lem1, h, {simp_args}]"
            )
            proofs.append(
                f"{intro}\n{ci_block}{lem1_have}\n"
                f"simp only [← lem1, h, {simp_args}]"
            )

        # Closure 2: just lem1 + h with simp
        proofs.append(
            f"{intro}\n{lem1_have}\n"
            f"simp only [lem1, h]"
        )
        proofs.append(
            f"{intro}\n{lem1_have}\n"
            f"simp only [← lem1, ← h]"
        )

        for proof in proofs:
            if calls >= max_judge_calls:
                return False
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True

    return False


def try_simp_rewrite_proof(problem, eq1_text, eq2_text, max_judge_calls=8):
    """Try proofs using Lean's simp tactic with derived rewrite lemmas.

    For self-referential hypotheses (x = F(x, free_vars)), derives:
    1. hconst: constancy lemma(s) for each free variable
    2. h.symm as backward rewrite: F(x,y,z) → x (collapsing)
    3. Compound constancy: h applied to compound terms + constancy

    Key insight: ← h (backward) collapses pattern matches. h (forward) expands
    but diverges since LHS matches everything. So we use:
    - ← h for normalization (shrinking)
    - hconst for equating different free var instantiations
    - Specific rw steps for targeted expansions

    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()

    lhs_vars = set(re.findall(r'\b([a-z])\b', eq1_lhs))
    rhs_vars = set(re.findall(r'\b([a-z])\b', eq1_rhs))
    rhs_only = sorted(rhs_vars - lhs_vars)
    lhs_only = sorted(lhs_vars - rhs_vars)

    if not rhs_only and not lhs_only:
        return False  # No free vars, constancy doesn't apply

    intro = f"intro {' '.join(eq2_vars)}"
    calls = 0

    # Build constancy lemmas
    constancy_info, _, _ = build_constancy_info(eq1_text, eq1_vars, eq2_vars)
    ci_block = ""
    ci_names = []
    for i, ci in enumerate(constancy_info):
        name = "hc" if i == 0 else f"hc{i+1}"
        line = ci['have_line']
        if i > 0:
            line = line.replace('hconst', name, 1)
        else:
            line = line.replace('hconst', name, 1)
        ci_block += line + "\n"
        ci_names.append(name)

    if not ci_names:
        return False

    proofs = []

    # Strategy 1: simp [← h, hc] — backward collapse + constancy
    # ← h: F(x,y,z) → x (collapse pattern to core var)
    # hc: equate different free var instantiations
    simp_bwd = ", ".join(["← h"] + ci_names)
    proofs.append(f"{intro}\n{ci_block}simp only [{simp_bwd}]")

    # Strategy 2: conv on LHS with rw [h], then simp [← h, hc]
    # Expand goal_lhs once, then normalize backward
    for v in eq2_vars:
        args = ' '.join(eq1_vars)
        proofs.append(
            f"{intro}\n{ci_block}"
            f"conv_lhs => rw [show {eq2_vars[0]} = _ from h {' '.join(eq2_vars[:len(eq1_vars)])}]\n"
            f"simp only [← h, {', '.join(ci_names)}]"
        )
        break  # Only try once

    # Strategy 3: conv on RHS with rw [h], then simp [← h, hc]
    proofs.append(
        f"{intro}\n{ci_block}"
        f"conv_rhs => rw [show {eq2_vars[0]} = _ from h {' '.join(eq2_vars[:len(eq1_vars)])}]\n"
        f"simp only [← h, {', '.join(ci_names)}]"
    )

    # Strategy 4: rw [h] on specific subterm then simp
    # For each goal var, try: rw [show <var> = ... from h <args>]
    for target_var in eq2_vars[:3]:
        args_list = [target_var if v == eq1_vars[0] else eq2_vars[0] for v in eq1_vars]
        args_str = ' '.join(args_list)
        rhs_inst = simultaneous_subst(eq1_rhs, eq1_vars, args_list)
        proofs.append(
            f"{intro}\n{ci_block}"
            f"rw [show {target_var} = {rhs_inst} from h {args_str}]\n"
            f"simp only [← h, {', '.join(ci_names)}]"
        )

    # Strategy 5: Multiple rw steps expanding different vars, then simp backward
    if len(eq2_vars) >= 2:
        v1, v2 = eq2_vars[0], eq2_vars[1]
        args1 = [v1 if v == eq1_vars[0] else v1 for v in eq1_vars]
        args2 = [v2 if v == eq1_vars[0] else v1 for v in eq1_vars]
        rhs1 = simultaneous_subst(eq1_rhs, eq1_vars, args1)
        rhs2 = simultaneous_subst(eq1_rhs, eq1_vars, args2)
        proofs.append(
            f"{intro}\n{ci_block}"
            f"rw [show {v1} = {rhs1} from h {' '.join(args1)}, "
            f"show {v2} = {rhs2} from h {' '.join(args2)}]\n"
            f"simp only [← h, {', '.join(ci_names)}]"
        )

    # Strategy 6: Derive that all values of form x ◇ x are equal
    # have hsq : ∀ (a b : G), a ◇ a = b ◇ b (if derivable)
    # This is a 2-step derivation using constancy
    if len(eq1_vars) >= 2 and rhs_only:
        # Try: have hsq := by ... and then simp with it
        proofs.append(
            f"{intro}\n{ci_block}"
            f"simp only [← h, {', '.join(ci_names)}]"
        )

    for proof in proofs:
        if calls >= max_judge_calls:
            return False
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        calls += 1
        if result.get("status") == "accepted":
            return True

    return False


def try_subexpr_bfs_proof(problem, eq1_text, eq2_text, max_judge_calls=3, max_depth=5, time_limit=30, seed_terms=None):
    """Bidirectional BFS over expression trees with h-pattern matching.

    Searches from both goal_lhs and goal_rhs simultaneously, meeting in the middle.
    Uses unify_tree to match h's LHS/RHS patterns against any subexpression,
    allowing compound variable bindings.

    If seed_terms is provided, these expressions are added as pre-seeded nodes
    connected to the start (as if they were reached in 0 steps), allowing the BFS
    to explore from LLM-suggested intermediates.

    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    import time
    from itertools import product as _prod
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()

    h_lhs_tree = parse_op_tree(eq1_lhs)
    h_rhs_tree = parse_op_tree(eq1_rhs)
    gl_tree = parse_op_tree(eq2_lhs)
    gr_tree = parse_op_tree(eq2_rhs)

    # Build pool of terms to substitute for free variables
    fill_terms = list(eq2_vars)
    for a in eq2_vars:
        for b in eq2_vars:
            fill_terms.append(f'{a} ◇ {b}')
            if len(fill_terms) > 10:
                break
        if len(fill_terms) > 10:
            break

    # Add LLM-suggested seed terms to the fill pool
    if seed_terms:
        for t in seed_terms:
            t = t.strip()
            if t and t not in fill_terms:
                fill_terms.append(t)

    h_vars_set = set(eq1_vars)

    # Compute constancy info: which h-vars are "free" (only on one side)?
    h_lhs_vars = set(re.findall(r'\b([a-z])\b', eq1_lhs))
    h_rhs_vars = set(re.findall(r'\b([a-z])\b', eq1_rhs))
    rhs_only_vars = sorted(h_rhs_vars - h_lhs_vars)  # free vars on RHS
    lhs_only_vars = sorted(h_lhs_vars - h_rhs_vars)  # free vars on LHS

    # For constancy rewrites, we also need a pool of substitution targets
    # These are the values we substitute for free vars
    const_fill = list(eq2_vars)  # keep small to avoid explosion

    def _all_completions(s):
        free = [v for v in eq1_vars if v not in s]
        if not free:
            return [dict(s)]
        if len(free) > 3:
            return []  # too many combos, skip
        # For 3 free vars, use only goal variables (no compounds) to limit explosion
        pool = eq2_vars if len(free) >= 3 else fill_terms
        return [dict(s, **{v: val for v, val in zip(free, combo)})
                for combo in _prod(pool, repeat=len(free))]

    def _format_args(full_s):
        parts = []
        for v in eq1_vars:
            val = full_s.get(v, eq2_vars[0] if eq2_vars else 'x')
            if '◇' in val:
                parts.append(f'({val})')
            else:
                parts.append(val)
        return ' '.join(parts)

    def _subst_tree(tree, subst):
        if tree[0] == 'var':
            return parse_op_tree(subst[tree[1]]) if tree[1] in subst else tree
        return ('op', _subst_tree(tree[1], subst), _subst_tree(tree[2], subst))

    def _tree_size(t):
        if t[0] == 'var': return 1
        return 1 + _tree_size(t[1]) + _tree_size(t[2])

    MAX_SIZE = 20

    def _gen_rewrites(tree, path=''):
        results = []
        for pattern, repl, is_sym in [(h_lhs_tree, h_rhs_tree, False),
                                       (h_rhs_tree, h_lhs_tree, True)]:
            s = unify_tree(pattern, tree, h_vars_set)
            if s is not None:
                for full_s in _all_completions(s):
                    r = _subst_tree(repl, full_s)
                    if _tree_size(r) <= MAX_SIZE:
                        results.append((path, r, _format_args(full_s), is_sym))

        # Constancy rewrites: match h_rhs pattern, change free vars
        # If h: x = f(x,y,z) where y,z are rhs_only, then
        # f(x,y1,z1) = f(x,y2,z2) via (h x y1 z1).symm.trans (h x y2 z2)
        if rhs_only_vars:
            s = unify_tree(h_rhs_tree, tree, h_vars_set)
            if s is not None:
                for full_s_orig in _all_completions(s):
                    orig_args = _format_args(full_s_orig)
                    # Try changing each combination of free vars
                    free_positions = [eq1_vars.index(v) for v in rhs_only_vars if v in eq1_vars]
                    for new_vals in _prod(const_fill, repeat=len(free_positions)):
                        full_s_new = dict(full_s_orig)
                        changed = False
                        for pos_idx, new_val in zip(free_positions, new_vals):
                            old_val = full_s_orig.get(eq1_vars[pos_idx], '')
                            if old_val != new_val:
                                full_s_new[eq1_vars[pos_idx]] = new_val
                                changed = True
                        if not changed:
                            continue
                        r = _subst_tree(h_rhs_tree, full_s_new)
                        if _tree_size(r) <= MAX_SIZE:
                            new_args = _format_args(full_s_new)
                            # Encode constancy step: CONST|orig_args|new_args
                            results.append((path, r, f"CONST|{orig_args}|{new_args}", False))

        # Similarly for lhs_only constancy: match h_lhs, change free vars on LHS
        if lhs_only_vars:
            s = unify_tree(h_lhs_tree, tree, h_vars_set)
            if s is not None:
                for full_s_orig in _all_completions(s):
                    orig_args = _format_args(full_s_orig)
                    free_positions = [eq1_vars.index(v) for v in lhs_only_vars if v in eq1_vars]
                    for new_vals in _prod(const_fill, repeat=len(free_positions)):
                        full_s_new = dict(full_s_orig)
                        changed = False
                        for pos_idx, new_val in zip(free_positions, new_vals):
                            old_val = full_s_orig.get(eq1_vars[pos_idx], '')
                            if old_val != new_val:
                                full_s_new[eq1_vars[pos_idx]] = new_val
                                changed = True
                        if not changed:
                            continue
                        r = _subst_tree(h_lhs_tree, full_s_new)
                        if _tree_size(r) <= MAX_SIZE:
                            new_args = _format_args(full_s_new)
                            # LHS constancy: (h orig).trans (h new).symm
                            results.append((path, r, f"LCONST|{orig_args}|{new_args}", False))

        if tree[0] == 'op':
            for p, sub_r, a, sym in _gen_rewrites(tree[1], path + 'L'):
                full = ('op', sub_r, tree[2])
                if _tree_size(full) <= MAX_SIZE:
                    results.append((p, full, a, sym))
            for p, sub_r, a, sym in _gen_rewrites(tree[2], path + 'R'):
                full = ('op', tree[1], sub_r)
                if _tree_size(full) <= MAX_SIZE:
                    results.append((p, full, a, sym))
        return results

    def tree_norm(tree):
        return tree_to_str(tree).replace(' ', '')

    def _extract_chain(visited, target_norm):
        chain = []
        cur = target_norm
        while visited[cur] is not None:
            pn, rpath, rargs, rsymm, ptree, rtree = visited[cur]
            chain.append((rpath, rargs, rsymm, ptree, rtree))
            cur = pn
        chain.reverse()
        return chain

    # Bidirectional BFS: forward from goal_lhs, backward from goal_rhs
    fwd_start = tree_norm(gl_tree)
    bwd_start = tree_norm(gr_tree)

    if fwd_start == bwd_start:
        # goal_lhs = goal_rhs trivially
        proof = f"intro {' '.join(eq2_vars)}\nrfl"
        code = make_true_code(problem, proof)
        result = call_judge("true", code)
        return result.get("status") == "accepted"

    # norm -> (prev_norm, path, args, is_symm, prev_tree, result_tree) or None for start
    fwd_visited = {fwd_start: None}
    bwd_visited = {bwd_start: None}
    fwd_frontier = [(gl_tree, fwd_start)]
    bwd_frontier = [(gr_tree, bwd_start)]
    fwd_trees = {fwd_start: gl_tree}  # norm -> tree
    bwd_trees = {bwd_start: gr_tree}
    calls = 0
    t0 = time.time()
    STATE_LIMIT = 120000

    for depth in range(max_depth):
        if time.time() - t0 > time_limit:
            break

        # Expand forward frontier
        fwd_next = []
        for tree, tnorm in fwd_frontier:
            if time.time() - t0 > time_limit:
                break
            for path, new_tree, args, is_symm in _gen_rewrites(tree):
                nn = tree_norm(new_tree)
                if nn in fwd_visited:
                    continue
                fwd_visited[nn] = (tnorm, path, args, is_symm, tree, new_tree)
                fwd_trees[nn] = new_tree
                fwd_next.append((new_tree, nn))
                # Check if meets backward
                if nn in bwd_visited:
                    fwd_chain = _extract_chain(fwd_visited, nn)
                    bwd_chain_raw = _extract_chain(bwd_visited, nn)
                    # Reverse backward chain: each step goes from child to parent
                    # Flip is_symm, swap prev_tree and result_tree
                    bwd_chain = []
                    for rp, ra, rs, pt, rt in reversed(bwd_chain_raw):
                        bwd_chain.append((rp, ra, not rs, rt, pt))
                    chain = fwd_chain + bwd_chain
                    proof = _build_tree_bfs_proof(eq2_vars, eq2_lhs, eq2_rhs, chain)
                    code = make_true_code(problem, proof)
                    result = call_judge("true", code)
                    calls += 1
                    if result.get("status") == "accepted":
                        return True
                    if calls >= max_judge_calls:
                        return False
            if len(fwd_visited) + len(bwd_visited) > STATE_LIMIT:
                break
        fwd_frontier = fwd_next

        if time.time() - t0 > time_limit:
            break
        if len(fwd_visited) + len(bwd_visited) > STATE_LIMIT:
            break

        # Expand backward frontier
        bwd_next = []
        for tree, tnorm in bwd_frontier:
            if time.time() - t0 > time_limit:
                break
            for path, new_tree, args, is_symm in _gen_rewrites(tree):
                nn = tree_norm(new_tree)
                if nn in bwd_visited:
                    continue
                bwd_visited[nn] = (tnorm, path, args, is_symm, tree, new_tree)
                bwd_trees[nn] = new_tree
                bwd_next.append((new_tree, nn))
                # Check if meets forward
                if nn in fwd_visited:
                    fwd_chain = _extract_chain(fwd_visited, nn)
                    bwd_chain_raw = _extract_chain(bwd_visited, nn)
                    bwd_chain = []
                    for rp, ra, rs, pt, rt in reversed(bwd_chain_raw):
                        bwd_chain.append((rp, ra, not rs, rt, pt))
                    chain = fwd_chain + bwd_chain
                    proof = _build_tree_bfs_proof(eq2_vars, eq2_lhs, eq2_rhs, chain)
                    code = make_true_code(problem, proof)
                    result = call_judge("true", code)
                    calls += 1
                    if result.get("status") == "accepted":
                        return True
                    if calls >= max_judge_calls:
                        return False
            if len(fwd_visited) + len(bwd_visited) > STATE_LIMIT:
                break
        bwd_frontier = bwd_next

        if not fwd_frontier and not bwd_frontier:
            break
        if len(fwd_visited) + len(bwd_visited) > STATE_LIMIT:
            break

    return False


def _build_tree_bfs_proof(eq2_vars, eq2_lhs, eq2_rhs, chain):
    """Build a Lean proof from a chain of tree-level h-rewrites.
    chain: list of (path, args_str, is_symm, tree_before_step, tree_after_step)
    args_str can be:
      - normal h args like "x y z"
      - "CONST|orig_args|new_args" for constancy via (h orig).symm.trans (h new)
      - "LCONST|orig_args|new_args" for LHS constancy via (h orig).trans (h new).symm
    """
    intro = f"intro {' '.join(eq2_vars)}"

    def _step_just(path, args, is_symm, tree):
        if args.startswith("CONST|"):
            # Constancy: (h orig_args).symm.trans (h new_args)
            parts = args.split("|", 2)
            orig_args = parts[1]
            new_args = parts[2]
            h_expr = f"(h {orig_args}).symm.trans (h {new_args})"
        elif args.startswith("LCONST|"):
            # LHS constancy: (h orig_args).trans (h new_args).symm
            parts = args.split("|", 2)
            orig_args = parts[1]
            new_args = parts[2]
            h_expr = f"(h {orig_args}).trans (h {new_args}).symm"
        else:
            h_expr = f"(h {args}).symm" if is_symm else f"h {args}"
        if not path:
            return h_expr
        return wrap_congr_arg(tree, path, h_expr)

    if len(chain) == 1:
        path, args, is_symm, tree, _ = chain[0]
        return f"{intro}\nexact {_step_just(path, args, is_symm, tree)}"

    lines = [intro, f"calc {eq2_lhs}"]

    for i, (path, args, is_symm, tree, result_tree) in enumerate(chain):
        just = _step_just(path, args, is_symm, tree)
        inter_str = tree_to_str(result_tree)

        if i < len(chain) - 1:
            lines.append(f"  _ = {inter_str} := {just}")
        else:
            lines.append(f"  _ = {eq2_rhs} := {just}")

    return '\n'.join(lines)


def try_constancy_calc_proof(problem, eq1_text, eq2_text, max_judge_calls=4):
    """Try multi-step proofs using constancy lemmas derived from free variables.
    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts2 = eq2_text.split('=', 1)
    if len(parts2) != 2:
        return False
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()

    constancy_info, lhs_only, rhs_only = build_constancy_info(eq1_text, eq1_vars, eq2_vars)
    if not constancy_info:
        return False

    intro = f"intro {' '.join(eq2_vars)}"
    default_fill = eq2_vars[0] if eq2_vars else 'x'

    gl_tree = parse_op_tree(eq2_lhs)
    gr_tree = parse_op_tree(eq2_rhs)

    proof_steps = find_constancy_steps(gl_tree, gr_tree, constancy_info, default_fill)
    if not proof_steps:
        return False

    proof = build_constancy_proof(intro, eq2_lhs, eq2_rhs, gl_tree, gr_tree,
                                  proof_steps, constancy_info)
    code = make_true_code(problem, proof)
    result = call_judge("true", code)
    if result.get("status") == "accepted":
        return True

    return False


def try_hybrid_calc_proof(problem, eq1_text, eq2_text, max_judge_calls=4):
    """Try proofs combining h-instantiation steps with constancy steps.

    Pattern 1: h(args) then constancy steps (goal_lhs →h→ intermediate →const→ goal_rhs)
    Pattern 2: constancy then h(args) (goal_lhs →const→ intermediate →h→ goal_rhs)
    Pattern 3: h then h then constancy (depth 2 h-chain + constancy)

    Returns True if accepted, False otherwise. Uses 0 LLM calls."""
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)

    parts1 = eq1_text.split('=', 1)
    parts2 = eq2_text.split('=', 1)
    if len(parts1) != 2 or len(parts2) != 2:
        return False

    eq1_lhs = parts1[0].strip()
    eq1_rhs = parts1[1].strip()
    eq2_lhs = parts2[0].strip()
    eq2_rhs = parts2[1].strip()
    g_lhs = eq2_lhs.replace(' ', '')
    g_rhs = eq2_rhs.replace(' ', '')

    constancy_info, lhs_only, rhs_only = build_constancy_info(eq1_text, eq1_vars, eq2_vars)
    if not constancy_info:
        return False

    intro = f"intro {' '.join(eq2_vars)}"
    default_fill = eq2_vars[0] if eq2_vars else 'x'
    calls = 0

    # Pre-compute h-instantiations (bare variables + compound terms from eq2_vars)
    h_insts = {}  # normalized_expr -> {normalized_target: args_string}

    def _add_h_inst(combo):
        new_lhs = simultaneous_subst(eq1_lhs, eq1_vars, combo)
        new_rhs = simultaneous_subst(eq1_rhs, eq1_vars, combo)
        nl = new_lhs.replace(' ', '')
        nr = new_rhs.replace(' ', '')
        if nl == nr:
            return
        args = ' '.join(combo)
        if nl not in h_insts:
            h_insts[nl] = {}
        if nr not in h_insts[nl]:
            h_insts[nl][nr] = args
        if nr not in h_insts:
            h_insts[nr] = {}
        if nl not in h_insts[nr]:
            h_insts[nr][nl] = args + "|symm"

    # Bare variable combos
    for combo in product(eq2_vars, repeat=len(eq1_vars)):
        _add_h_inst(combo)

    # Compound terms: (a ◇ b) for all pairs
    compound_terms = [f"({a} \u25c7 {b})" for a in eq2_vars for b in eq2_vars]
    n_h = len(eq1_vars)
    n_b = len(eq2_vars)
    n_c = len(compound_terms)

    # k=1: exactly one compound argument position, rest bare
    k1_count = n_h * n_c * (n_b ** max(n_h - 1, 0))
    if k1_count <= 50000:
        for pos in range(n_h):
            for ct in compound_terms:
                for bare_combo in product(eq2_vars, repeat=n_h - 1):
                    combo = list(bare_combo[:pos]) + [ct] + list(bare_combo[pos:])
                    _add_h_inst(combo)

    # Pattern 1: h-step from goal_lhs, then constancy to goal_rhs
    if g_lhs in h_insts:
        for intermediate_norm, args in h_insts[g_lhs].items():
            # Parse intermediate as a tree, check constancy to goal_rhs
            inter_str = _denormalize(intermediate_norm, eq2_vars)
            if inter_str is None:
                continue
            inter_tree = parse_op_tree(inter_str)
            gr_tree = parse_op_tree(eq2_rhs)
            if inter_tree == gr_tree:
                continue  # Would be handled by calc_chain_proof
            csteps = find_constancy_steps(inter_tree, gr_tree, constancy_info, default_fill)
            if not csteps:
                continue

            # Build proof: h-step then constancy
            symm = args.endswith("|symm")
            h_args = args.replace("|symm", "")
            h_step = f"(h {h_args}).symm" if symm else f"h {h_args}"

            const_proof = build_constancy_proof(
                intro, inter_str, eq2_rhs, inter_tree, gr_tree,
                csteps, constancy_info
            )
            # Extract have lines and calc body from const_proof
            const_lines = const_proof.split('\n')
            have_lines = [l for l in const_lines if l.startswith('have ')]
            # Build combined calc
            calc_lines = [f"calc {eq2_lhs}"]
            calc_lines.append(f"  _ = {inter_str} := {h_step}")
            # Add constancy steps
            current_tree = inter_tree
            for i, (path, cargs, csymm, ci_idx) in enumerate(csteps):
                ci_used_map = {}
                for _, _, _, cidx in csteps:
                    if cidx not in ci_used_map:
                        ci_used_map[cidx] = "hconst" if len(ci_used_map) == 0 else f"hconst{len(ci_used_map)+1}"
                hname = ci_used_map[ci_idx]
                inner = f"({hname} {cargs})" if not csymm else f"({hname} {cargs}).symm"
                step_proof = wrap_congr_arg(current_tree, path, inner)
                target_sub = get_subtree(gr_tree, path)
                current_tree = apply_rewrite_at(current_tree, path, target_sub)
                current_str = tree_to_str(current_tree)
                if i < len(csteps) - 1:
                    calc_lines.append(f"  _ = {current_str} := {step_proof}")
                else:
                    calc_lines.append(f"  _ = {eq2_rhs} := {step_proof}")

            # Build ci_used for have lines
            ci_used = {}
            ci_have_lines = []
            idx = 1
            for _, _, _, cidx in csteps:
                if cidx not in ci_used:
                    name = "hconst" if idx == 1 else f"hconst{idx}"
                    line = constancy_info[cidx]['have_line']
                    if idx > 1:
                        line = line.replace('hconst', name, 1)
                    ci_have_lines.append(line)
                    ci_used[cidx] = name
                    idx += 1

            proof = f"{intro}\n" + "\n".join(ci_have_lines) + "\n" + "\n".join(calc_lines)
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True
            if calls >= max_judge_calls:
                return False

    # Pattern 2: constancy from goal_lhs, then h-step to goal_rhs
    if g_rhs in h_insts:
        for intermediate_norm, args in h_insts[g_rhs].items():
            inter_str = _denormalize(intermediate_norm, eq2_vars)
            if inter_str is None:
                continue
            inter_tree = parse_op_tree(inter_str)
            gl_tree = parse_op_tree(eq2_lhs)
            if gl_tree == inter_tree:
                continue
            csteps = find_constancy_steps(gl_tree, inter_tree, constancy_info, default_fill)
            if not csteps:
                continue

            # The h-step goes from intermediate to goal_rhs
            # args maps intermediate_norm → g_rhs
            symm = args.endswith("|symm")
            h_args = args.replace("|symm", "")
            # Since h_insts[g_rhs][intermediate_norm] = args means intermediate_norm →args→ g_rhs
            # Wait, h_insts[g_rhs] maps targets reachable from g_rhs. So intermediate_norm is a target from g_rhs.
            # That means g_rhs →args→ intermediate_norm. We need intermediate →h→ goal_rhs.
            # So we need the reverse: intermediate_norm →args_rev→ g_rhs
            # Actually h_insts[g_rhs][intermediate_norm] = args means g_rhs can reach intermediate_norm via args.
            # We need intermediate to reach g_rhs: so we go h_insts[intermediate_norm][g_rhs]
            if intermediate_norm not in h_insts or g_rhs not in h_insts[intermediate_norm]:
                continue
            h_args2 = h_insts[intermediate_norm][g_rhs]
            symm2 = h_args2.endswith("|symm")
            h_args2_clean = h_args2.replace("|symm", "")
            h_step = f"(h {h_args2_clean}).symm" if symm2 else f"h {h_args2_clean}"

            # Build have lines for constancy
            ci_used = {}
            ci_have_lines = []
            idx = 1
            for _, _, _, cidx in csteps:
                if cidx not in ci_used:
                    name = "hconst" if idx == 1 else f"hconst{idx}"
                    line = constancy_info[cidx]['have_line']
                    if idx > 1:
                        line = line.replace('hconst', name, 1)
                    ci_have_lines.append(line)
                    ci_used[cidx] = name
                    idx += 1

            # Build calc chain: constancy steps then h-step
            calc_lines = [f"calc {eq2_lhs}"]
            current_tree = gl_tree
            for i, (path, cargs, csymm, ci_idx) in enumerate(csteps):
                hname = ci_used[ci_idx]
                inner = f"({hname} {cargs})" if not csymm else f"({hname} {cargs}).symm"
                step_proof = wrap_congr_arg(current_tree, path, inner)
                target_sub = get_subtree(inter_tree, path)
                current_tree = apply_rewrite_at(current_tree, path, target_sub)
                current_str = tree_to_str(current_tree)
                calc_lines.append(f"  _ = {current_str} := {step_proof}")
            calc_lines.append(f"  _ = {eq2_rhs} := {h_step}")

            proof = f"{intro}\n" + "\n".join(ci_have_lines) + "\n" + "\n".join(calc_lines)
            code = make_true_code(problem, proof)
            result = call_judge("true", code)
            calls += 1
            if result.get("status") == "accepted":
                return True
            if calls >= max_judge_calls:
                return False

    # Pattern 3: 2-step h-chain then constancy
    if g_lhs in h_insts:
        for mid1_norm, args1 in h_insts[g_lhs].items():
            if mid1_norm not in h_insts:
                continue
            for mid2_norm, args2 in h_insts[mid1_norm].items():
                if mid2_norm == g_lhs or mid2_norm == g_rhs:
                    continue  # Skip loops and direct matches
                mid2_str = _denormalize(mid2_norm, eq2_vars)
                if mid2_str is None:
                    continue
                mid2_tree = parse_op_tree(mid2_str)
                gr_tree = parse_op_tree(eq2_rhs)
                if mid2_tree == gr_tree:
                    continue
                csteps = find_constancy_steps(mid2_tree, gr_tree, constancy_info, default_fill)
                if not csteps:
                    continue

                mid1_str = _denormalize(mid1_norm, eq2_vars)
                if mid1_str is None:
                    continue

                symm1 = args1.endswith("|symm")
                h1 = args1.replace("|symm", "")
                h1_step = f"(h {h1}).symm" if symm1 else f"h {h1}"
                symm2 = args2.endswith("|symm")
                h2 = args2.replace("|symm", "")
                h2_step = f"(h {h2}).symm" if symm2 else f"h {h2}"

                ci_used = {}
                ci_have_lines = []
                idx = 1
                for _, _, _, cidx in csteps:
                    if cidx not in ci_used:
                        name = "hconst" if idx == 1 else f"hconst{idx}"
                        line = constancy_info[cidx]['have_line']
                        if idx > 1:
                            line = line.replace('hconst', name, 1)
                        ci_have_lines.append(line)
                        ci_used[cidx] = name
                        idx += 1

                calc_lines = [f"calc {eq2_lhs}"]
                calc_lines.append(f"  _ = {mid1_str} := {h1_step}")
                calc_lines.append(f"  _ = {mid2_str} := {h2_step}")
                current_tree = mid2_tree
                for i, (path, cargs, csymm, ci_idx) in enumerate(csteps):
                    hname = ci_used[ci_idx]
                    inner = f"({hname} {cargs})" if not csymm else f"({hname} {cargs}).symm"
                    step_proof = wrap_congr_arg(current_tree, path, inner)
                    target_sub = get_subtree(gr_tree, path)
                    current_tree = apply_rewrite_at(current_tree, path, target_sub)
                    current_str = tree_to_str(current_tree)
                    if i < len(csteps) - 1:
                        calc_lines.append(f"  _ = {current_str} := {step_proof}")
                    else:
                        calc_lines.append(f"  _ = {eq2_rhs} := {step_proof}")

                proof = f"{intro}\n" + "\n".join(ci_have_lines) + "\n" + "\n".join(calc_lines)
                code = make_true_code(problem, proof)
                result = call_judge("true", code)
                calls += 1
                if result.get("status") == "accepted":
                    return True
                if calls >= max_judge_calls:
                    return False

    return False


def _denormalize(norm_expr, eq2_vars):
    """Convert a normalized (no-space) expression back to readable form.
    This is approximate — adds spaces around ◇ operators."""
    # Simply add spaces around ◇
    result = norm_expr.replace('\u25c7', ' \u25c7 ')
    # Verify it parses
    try:
        parse_op_tree(result)
        return result
    except Exception:
        return None



def main():
    startup = read_message()
    problem = startup["problem"]
    eq1_text = problem["equation1"]
    eq2_text = problem["equation2"]

    # Stage 0: Known counterexample lookup
    n, table = known_counterexample(problem["eq1_id"], problem["eq2_id"])
    if n is not None:
        result = call_judge("false", make_false_code(problem, n, table))
        if result.get("status") == "accepted":
            return

    # Stage 1: Brute-force
    search_notes = []
    n, table = exhaustive_counterexample(eq1_text, eq2_text, max_n=3)
    if n is not None:
        result = call_judge("false", make_false_code(problem, n, table))
        if result.get("status") == "accepted":
            return
        search_notes.append(f"Found Fin {n} counterexample but judge rejected")
    else:
        search_notes.append("No counterexample on Fin 2-3 (exhaustive)")

    n, table = extended_counterexample(eq1_text, eq2_text, max_n=5, random_attempts=5000)
    if n is not None:
        result = call_judge("false", make_false_code(problem, n, table))
        if result.get("status") == "accepted":
            return
        search_notes.append(f"Found Fin {n} extended counterexample but judge rejected")
    else:
        search_notes.append("No counterexample on Fin 4-5 (structured + random)")

    n, table = backtrack_counterexample(eq1_text, eq2_text, sizes=(4, 5), time_limit=10)
    if n is not None:
        result = call_judge("false", make_false_code(problem, n, table))
        if result.get("status") == "accepted":
            return
        search_notes.append(f"Found Fin {n} backtrack counterexample but judge rejected")
    else:
        search_notes.append("No counterexample on Fin 4-5 (backtracking)")

    # Stage 2: Singleton
    if try_singleton(problem, eq1_text, eq2_text):
        return
    search_notes.append("Singleton collapse: not applicable")

    # Stage 3: Deterministic proof strategies (0 LLM calls)
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)
    h_insts = compute_h_instantiations(eq1_text, eq1_vars, eq2_vars)

    # Try direct proof via substitution search (0 LLM calls)
    if try_direct_proof(problem, eq1_text, eq2_text):
        return

    # Try library proof via EquationSearch theorem reference (0 LLM calls)
    if try_library_proof(problem):
        return

    # Try calc chain proof via BFS over h-instantiations (0 LLM calls)
    if try_calc_chain_proof(problem, eq1_text, eq2_text):
        return

    # Try compound calc chain proof with compound terms (0 LLM calls)
    if try_compound_calc_proof(problem, eq1_text, eq2_text):
        return

    # Try constancy calc proof with congr_arg chains (0 LLM calls)
    if try_constancy_calc_proof(problem, eq1_text, eq2_text):
        return

    # Try hybrid h-step + constancy proof (0 LLM calls)
    if try_hybrid_calc_proof(problem, eq1_text, eq2_text):
        return

    # Try deep constancy proof via spine analysis + compound h-rewriting (0 LLM calls)
    if try_deep_constancy_proof(problem, eq1_text, eq2_text):
        return

    # Try subexpression BFS with bidirectional tree pattern matching (0 LLM calls)
    if try_subexpr_bfs_proof(problem, eq1_text, eq2_text):
        return

    # Stage 4: Phase 1 — ask LLM for analysis only (no code).
    # No per-problem call cap; pacing is bounded by the wall-clock timeout.
    structure = analyze_equation_structure(eq1_text, eq2_text)
    lemmas = []
    parts = eq1_text.split('=', 1)
    if len(parts) == 2:
        rhs = parts[1].strip()
        lhs = parts[0].strip()
        # Show h(x,x,...,x)
        unified = rhs
        for v in eq1_vars:
            unified = re.sub(r'\b' + v + r'\b', 'x', unified)
        lemmas.append(f"h({','.join(['x']*len(eq1_vars))}): {lhs.replace(eq1_vars[0],'x') if len(lhs)==1 else lhs} = {unified}")

    context = {
        "phase": "1_analysis",
        "analysis": "\n".join(search_notes + structure),
        "key_specialization": "\n".join(lemmas) if lemmas else "",
    }

    llm_result = call_llm(context)
    if "error" in llm_result:
        return

    response_text = llm_result.get("response", "")
    phase1 = extract_json(response_text)

    # Parse phase 1 result
    llm_verdict = "true"  # default
    llm_strategy = ""
    if phase1:
        llm_verdict = phase1.get("verdict", "true")
        llm_strategy = phase1.get("strategy", "")

    search_notes.append(f"LLM analysis: verdict={llm_verdict}, strategy={llm_strategy[:200]}")

    # If LLM says false, try harder counterexample search with LLM-suggested size
    if llm_verdict == "false":
        # Try Fin 3-5 with more random attempts
        for sz in range(3, 6):
            n2, table2 = extended_counterexample(eq1_text, eq2_text, max_n=sz, random_attempts=10000)
            if n2 is not None:
                result = call_judge("false", make_false_code(problem, n2, table2))
                if result.get("status") == "accepted":
                    return

    # Stage 5: Phase 2 — ask LLM for implementation. Loop until wall-clock
    # watchdog terminates us or we hit an LLM error (e.g. API unavailable).
    seen_answers = set()
    false_attempts = 0

    deep_hints = deep_proof_analysis(eq1_text, eq2_text)
    if deep_hints:
        search_notes.extend(deep_hints)

    rnd = -1
    while True:
        rnd += 1
        context = {
            "phase": "2_implementation",
            "analysis": "\n".join(search_notes),
            "strategy": llm_strategy,
            "target_verdict": llm_verdict,
        }
        if h_insts:
            context["h_instantiations"] = "\n".join(f"  {h}" for h in h_insts[:8])
        if false_attempts >= 2:
            context["verdict_hint"] = (
                f"IMPORTANT: {false_attempts} counterexample attempts ALL failed. "
                "This is TRUE. Write a tactic proof, NOT a counterexample."
            )

        overrides = None
        if rnd > 0:
            overrides = {"temperature": min(0.3 + rnd * 0.15, 0.9), "seed": rnd}
        llm_result = call_llm(context, overrides=overrides)
        if "error" in llm_result:
            break

        answer = extract_json(llm_result.get("response", ""))
        if not answer:
            continue

        verdict = answer.get("verdict")
        if verdict == "true":
            proof = clean_proof(answer.get("proof", ""))
            if not proof:
                continue
            if proof in seen_answers:
                search_notes.append(f"Phase2 round {rnd}: duplicate proof")
                continue
            seen_answers.add(proof)
            code = make_true_code(problem, proof)
        elif verdict == "false":
            tbl = answer.get("counterexample_table")
            if not tbl or not isinstance(tbl, list):
                continue
            n = len(tbl)
            if n < 2 or n > 7:
                continue
            tbl_key = str(tbl)
            if tbl_key in seen_answers:
                search_notes.append(f"Phase2 round {rnd}: duplicate table")
                continue
            seen_answers.add(tbl_key)
            sat1, sat2 = verify_counterexample(eq1_text, eq2_text, n, tbl)
            if not sat1:
                false_attempts += 1
                search_notes.append(f"Phase2 round {rnd}: table fails {problem['eq1_id']} locally")
                continue
            if sat2:
                false_attempts += 1
                search_notes.append(f"Phase2 round {rnd}: table satisfies both eqs locally")
                continue
            code = make_false_code(problem, n, tbl)
        else:
            continue

        result = call_judge(verdict, code)
        if result.get("status") == "accepted":
            return

        stderr = result.get("stderr", "") or result.get("message", "")
        error_info = parse_lean_error(stderr)
        search_notes.append(f"Phase2 round {rnd}: {result.get('status')}, error={error_info['type']}")


if __name__ == "__main__":
    main()

"""
Marathon baseline solver — sequential, deterministic, no LLM.

Acts as the contract reference and the smoke baseline for marathon mode.
Two operating modes, dispatched by env vars:

    JUDGE_MARATHON_MANIFEST set  → marathon: read manifest, write JSONL
    (env vars unset)             → Solo: stdin/stdout JSON protocol

Strategy (both modes):

    For every problem, run a small finite-magma brute-force search up to
    Fin 3. If a counterexample is found, emit a "false" certificate using
    JudgeFinOp's ``finOpTable`` + ``decideFin!`` (same shape as
    examples/solo/demos/baseline). If no counterexample is found in the
    allotted slice, skip the problem (it will be reported as
    ``not_attempted`` in the marathon summary).

This baseline does not call the LLM and does not aim to maximize score —
it exists to prove the marathon E2E pipeline runs cleanly. Real solvers
(triage, fewshot) build on top of this contract.
"""

PROMPT = """You are solving equational theory problems in Lean 4.

Does {problem.equation1_id} imply {problem.equation2_id}?
Hypothesis: {problem.equation1}
Goal: {problem.equation2}

If true, provide a proof body (tactics only).
If false, provide a counterexample table on Fin N.

Previous attempts:
{history.attempts}

Respond with ONLY JSON, no markdown:
{"verdict": "true", "proof": "<tactic body>"}
or
{"verdict": "false", "counterexample_table": [[0,1],[1,0]]}
"""


import json
import os
import re
import sys
import time
from itertools import product


# ───────── Equation parsing & brute-force counterexample search ─────────

def _parse_equation(text):
    variables = []
    seen = set()
    for v in re.findall(r"\b([a-z])\b", text):
        if v not in seen:
            seen.add(v)
            variables.append(v)
    lhs_str, rhs_str = text.split("=", 1)

    def _to_expr(s):
        s = s.strip()
        while len(s) >= 2 and s[0] == "(" and s[-1] == ")":
            depth = 0
            matched = True
            for i, c in enumerate(s):
                if c == "(":
                    depth += 1
                elif c == ")":
                    depth -= 1
                if depth == 0 and i < len(s) - 1:
                    matched = False
                    break
            if matched:
                s = s[1:-1].strip()
            else:
                break
        depth = 0
        last_op = -1
        for i, c in enumerate(s):
            if c == "(":
                depth += 1
            elif c == ")":
                depth -= 1
            elif c == "\u25c7" and depth == 0:
                last_op = i
        if last_op >= 0:
            left = _to_expr(s[:last_op])
            right = _to_expr(s[last_op + 1:])
            return lambda env, l=left, r=right: env["op"](l(env), r(env))
        s = s.strip()
        if len(s) == 1 and s in seen:
            return lambda env, v=s: env[v]
        raise ValueError(f"cannot parse: {s!r}")

    return variables, _to_expr(lhs_str), _to_expr(rhs_str)


def _check_eq(variables, lhs_fn, rhs_fn, n, op):
    for vals in product(range(n), repeat=len(variables)):
        env = {"op": op}
        for v, val in zip(variables, vals):
            env[v] = val
        if lhs_fn(env) != rhs_fn(env):
            return False
    return True


def search_counterexample(eq1_text, eq2_text, max_n=3, time_budget=None):
    """Brute-force enumerate Magma tables on Fin 2..max_n.

    Returns ``(n, table)`` for the first table that satisfies ``eq1`` and
    refutes ``eq2``, or ``(None, None)`` if no such table exists in the
    search space (or the time budget runs out).
    """
    try:
        lhs_vars, lhs_l, lhs_r = _parse_equation(eq1_text)
        rhs_vars, rhs_l, rhs_r = _parse_equation(eq2_text)
    except (ValueError, IndexError):
        return None, None
    deadline = (time.monotonic() + time_budget) if time_budget else None
    for n in range(2, max_n + 1):
        total = n ** (n * n)
        for enc in range(total):
            if deadline is not None and time.monotonic() > deadline:
                return None, None
            table = [[(enc // (n ** (i * n + j))) % n for j in range(n)]
                     for i in range(n)]
            op = lambda a, b, t=table: t[a][b]
            if not _check_eq(lhs_vars, lhs_l, lhs_r, n, op):
                continue
            if _check_eq(rhs_vars, rhs_l, rhs_r, n, op):
                continue
            return n, table
    return None, None


# ───────── Lean code generators ─────────

def make_false_code(n, table):
    table_str = json.dumps(table)
    return (
        "import JudgeProblem\n"
        "import JudgeDecide.DecideBang\n"
        "import JudgeFinOp.MemoFinOp\n"
        "open MemoFinOp\n\n"
        "def submission : Goal := by\n"
        f"  let m : Magma (Fin {n}) := {{\n"
        f"    op := finOpTable \"{table_str}\"\n"
        f"  }}\n"
        f"  refine \u27e8Fin {n}, m, ?_\u27e9\n"
        f"  decideFin!\n"
    )


# ───────── Marathon-mode driver ─────────

def _load_manifest(path):
    out = []
    with open(path, encoding="utf-8") as fh:
        for raw in fh:
            raw = raw.strip()
            if not raw:
                continue
            try:
                out.append(json.loads(raw))
            except json.JSONDecodeError:
                continue
    return out


def _append_answer(output_path, entry):
    """Append-only write — single JSON line, fsync so nothing is lost on SIGTERM."""
    line = json.dumps(entry, ensure_ascii=False) + "\n"
    with open(output_path, "a", encoding="utf-8") as fh:
        fh.write(line)
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except OSError:
            pass


def run_marathon():
    manifest_path = os.environ["JUDGE_MARATHON_MANIFEST"]
    output_path = os.environ["JUDGE_MARATHON_OUTPUT"]
    budget_seconds = float(os.environ.get("JUDGE_MARATHON_BUDGET_SECONDS", "3600"))
    deadline = time.monotonic() + budget_seconds

    problems = _load_manifest(manifest_path)
    # Trivial triage: keep manifest order, but cap the per-problem search so
    # one stubborn problem can't eat the whole budget. Reserve a tail margin
    # so a SIGTERM near the end still leaves a moment to finish a write.
    tail_margin = 5.0
    per_problem_cap = max(2.0, budget_seconds / max(1, len(problems)))

    for prob in problems:
        if time.monotonic() + tail_margin >= deadline:
            break
        try:
            n, table = search_counterexample(
                prob["equation1"], prob["equation2"],
                max_n=3, time_budget=per_problem_cap,
            )
        except Exception:  # noqa: BLE001 — solver must never crash mid-marathon
            continue
        if n is None:
            continue
        code = make_false_code(n, table)
        _append_answer(output_path, {
            "id": prob["id"],
            "verdict": "false",
            "code": code,
        })


# ───────── Solo fallback (keeps the file dual-mode) ─────────

def _read_message():
    line = sys.stdin.readline()
    if not line:
        sys.exit(0)
    return json.loads(line.strip())


def _send_message(msg):
    print(json.dumps(msg), flush=True)


def run_solo():
    """Minimal Solo path: brute-force counterexample only, no LLM, no proof.

    This baseline isn't intended as a competitive Solo solver; the path
    exists so the dual-mode contract holds. A submission that wants to be
    competitive on Solo should start from one of the LLM-using Solo demos
    under ``examples/solo/demos/`` (e.g. ``twophase`` or ``opnorm``).
    """
    startup = _read_message()
    problem = startup["problem"]
    n, table = search_counterexample(problem["equation1"], problem["equation2"], max_n=3)
    if n is None:
        return
    code = make_false_code(n, table)
    _send_message({"call": "judge", "verdict": "false", "code": code})
    _read_message()


def main():
    if "JUDGE_MARATHON_MANIFEST" in os.environ:
        run_marathon()
    else:
        run_solo()


if __name__ == "__main__":
    main()

"""
Marathon triage solver — two-pass with budget-aware priority.

Strategy:

  Pass A (cheap, free):
    Run brute-force counterexample search (Fin 2..3) on every problem.
    Roughly 40-50% of normal-distribution problems are counterexampled.
    Tokens spent: zero.

  Pass B (LLM, budget-aware):
    Sort the remaining (likely answer=true) problems by a difficulty
    heuristic — shorter total equation length first, fewer variables
    second. Walk in that order; for each problem ask the LLM for a
    Lean tactic body. Skip on parse fail or LLM error. Stop early when
    the projected cost of the next call would exceed remaining budget.

  Pass C (deeper-thought retry, budget permitting):
    Walk problems Pass B left *unsubmitted* (parse fail, empty body,
    LLM error, missing counterexample) and retry once with bumped
    reasoning effort and a larger output cap. Pass-B successes are
    never retried — last-write-wins scoring would let a context-free
    retry overwrite a working answer with a worse one.

Cross-problem experience reuse: each successful Lean proof body is
appended to ``<scratch>/proof_patterns.jsonl`` so future demos can
mine it. The current solver does not yet reuse patterns from prior
problems mid-run — that's the next iteration.

Token budget discipline:
  * marathon_llm.call_llm self-polices and refuses calls past the cap.
  * The proxy enforces the cap at the network layer via a pessimistic
    reservation (prompt_estimate + clamped max_tokens) — it returns
    402 BEFORE forwarding upstream when the reservation would overshoot.
  * The runner watchdog reads the proxy's settled-only counter (so an
    exact-budget legal reservation isn't killed mid-flight) and
    SIGTERMs the solver if billed cost exceeds the budget after settle.
  * This solver additionally reserves PASS_C_MIN_BUDGET_FRACTION of
    cap_tokens for Pass C, so a thirsty Pass B can't drain the
    budget before the deeper-thought retry gets a turn.
"""

PROMPT_FIRST_TRY = """You are solving an equational-theory implication in Lean 4.

Given two equational laws on a magma G with operation ◇:

  Law A ({problem.equation1_id}): {problem.equation1}
  Law B ({problem.equation2_id}): {problem.equation2}

Decide whether every magma satisfying A also satisfies B.

The proof goes inside this template (don't restate it):

    def submission : Goal := by
      intro G _ h
      <YOUR TACTIC BODY HERE>

``h : <Law A>`` is in scope. Use ``exact``, ``rw``, ``simp [h]``, ``intro``,
``apply``, ``have``, ``calc``, etc. No imports. No theorem statements.

If you believe the implication is FALSE, return a 2-D table on Fin n
(2 ≤ n ≤ 4) instead.

Reply with ONLY one JSON object, no markdown:

    {"verdict": "true",  "proof": "<tactic body>"}
or
    {"verdict": "false", "counterexample_table": [[0,1],[1,0]]}
"""

PROMPT = PROMPT_FIRST_TRY  # for prompt extraction by the proxy (Solo mode)


import json
import os
import re
import sys
import time
from itertools import product
from pathlib import Path


_LIB_DIR = os.environ.get("JUDGE_MARATHON_LIB_DIR")
if _LIB_DIR and _LIB_DIR not in sys.path:
    sys.path.insert(0, _LIB_DIR)


PASS_C_MIN_BUDGET_FRACTION = 0.10  # Reserve 10% of token budget for Pass C; skip if less.


# ───────── Equation parsing & brute-force ─────────

def _parse_equation(text):
    variables = []
    seen = set()
    for v in re.findall(r"\b([a-z])\b", text):
        if v not in seen:
            seen.add(v)
            variables.append(v)
    lhs_str, rhs_str = text.split("=", 1)

    def _to_expr(s):
        s = s.strip()
        while len(s) >= 2 and s[0] == "(" and s[-1] == ")":
            depth = 0
            matched = True
            for i, c in enumerate(s):
                if c == "(":
                    depth += 1
                elif c == ")":
                    depth -= 1
                if depth == 0 and i < len(s) - 1:
                    matched = False
                    break
            if matched:
                s = s[1:-1].strip()
            else:
                break
        depth = 0
        last_op = -1
        for i, c in enumerate(s):
            if c == "(":
                depth += 1
            elif c == ")":
                depth -= 1
            elif c == "\u25c7" and depth == 0:
                last_op = i
        if last_op >= 0:
            left = _to_expr(s[:last_op])
            right = _to_expr(s[last_op + 1:])
            return lambda env, l=left, r=right: env["op"](l(env), r(env))
        s = s.strip()
        if len(s) == 1 and s in seen:
            return lambda env, v=s: env[v]
        raise ValueError(f"cannot parse: {s!r}")

    return variables, _to_expr(lhs_str), _to_expr(rhs_str)


def _check_eq(variables, lhs_fn, rhs_fn, n, op):
    for vals in product(range(n), repeat=len(variables)):
        env = {"op": op}
        for v, val in zip(variables, vals):
            env[v] = val
        if lhs_fn(env) != rhs_fn(env):
            return False
    return True


def search_counterexample(eq1_text, eq2_text, max_n=3, time_budget=None):
    try:
        lhs_vars, lhs_l, lhs_r = _parse_equation(eq1_text)
        rhs_vars, rhs_l, rhs_r = _parse_equation(eq2_text)
    except (ValueError, IndexError):
        return None, None
    deadline = (time.monotonic() + time_budget) if time_budget else None
    for n in range(2, max_n + 1):
        total = n ** (n * n)
        for enc in range(total):
            if deadline is not None and time.monotonic() > deadline:
                return None, None
            table = [[(enc // (n ** (i * n + j))) % n for j in range(n)]
                     for i in range(n)]
            op = lambda a, b, t=table: t[a][b]
            if not _check_eq(lhs_vars, lhs_l, lhs_r, n, op):
                continue
            if _check_eq(rhs_vars, rhs_l, rhs_r, n, op):
                continue
            return n, table
    return None, None


# ───────── Lean code generators ─────────

def make_false_code(n, table):
    table_str = json.dumps(table)
    return (
        "import JudgeProblem\n"
        "import JudgeDecide.DecideBang\n"
        "import JudgeFinOp.MemoFinOp\n"
        "open MemoFinOp\n\n"
        "def submission : Goal := by\n"
        f"  let m : Magma (Fin {n}) := {{\n"
        f"    op := finOpTable \"{table_str}\"\n"
        f"  }}\n"
        f"  refine \u27e8Fin {n}, m, ?_\u27e9\n"
        f"  decideFin!\n"
    )


def make_true_code(proof_body):
    proof_body = proof_body.strip()
    if ":= by" in proof_body:
        proof_body = re.sub(r"^.*?:=\s*by\s*\n?", "", proof_body, count=1, flags=re.DOTALL)
    proof_body = re.sub(r"^\s*by\s+", "", proof_body)
    proof_body = re.sub(r"^\s*import\s+.*\n?", "", proof_body, flags=re.MULTILINE)
    lines = proof_body.split("\n")
    indented = "\n".join("  " + ln if ln.strip() else "" for ln in lines)
    return (
        "import JudgeProblem\n\n"
        "def submission : Goal := by\n"
        "  intro G _ h\n"
        f"{indented}\n"
    )


def _extract_json(text):
    text = re.sub(r"<think>[\s\S]*?</think>", "", text or "").strip()
    text = re.sub(r"^```(?:json)?\s*\n?", "", text)
    text = re.sub(r"\n?```\s*$", "", text)
    try:
        return json.loads(text.strip())
    except Exception:
        pass
    m = re.search(r"\{[\s\S]*\}", text)
    if m:
        try:
            return json.loads(m.group())
        except Exception:
            pass
    return None


def _fill_first(prob):
    eq1_name = f"Equation{prob['eq1_id']}"
    eq2_name = f"Equation{prob['eq2_id']}"
    return (PROMPT_FIRST_TRY
            .replace("{problem.equation1}", prob.get("equation1", ""))
            .replace("{problem.equation2}", prob.get("equation2", ""))
            .replace("{problem.equation1_id}", eq1_name)
            .replace("{problem.equation2_id}", eq2_name))


# ───────── Triage scoring ─────────

def difficulty_score(prob):
    """Smaller is easier. Combine equation char length + distinct-var count."""
    eq1 = prob.get("equation1", "")
    eq2 = prob.get("equation2", "")
    var_count = len(set(re.findall(r"\b([a-z])\b", eq1 + " " + eq2)))
    return (len(eq1) + len(eq2)) + 5 * var_count


# ───────── Marathon driver ─────────

def _load_manifest(path):
    out = []
    with open(path, encoding="utf-8") as fh:
        for raw in fh:
            raw = raw.strip()
            if not raw:
                continue
            try:
                out.append(json.loads(raw))
            except json.JSONDecodeError:
                continue
    return out


def _append_answer(output_path, entry):
    line = json.dumps(entry, ensure_ascii=False) + "\n"
    with open(output_path, "a", encoding="utf-8") as fh:
        fh.write(line)
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except OSError:
            pass


def _record_pattern(scratch_dir, prob, proof_body):
    """Append a winning proof pattern to scratch (cross-problem reuse hook)."""
    try:
        path = Path(scratch_dir) / "proof_patterns.jsonl"
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({
                "id": prob["id"],
                "eq1_id": prob.get("eq1_id"),
                "eq2_id": prob.get("eq2_id"),
                "proof": proof_body,
            }) + "\n")
    except OSError:
        pass


def run_marathon():
    try:
        from marathon_llm import call_llm, tokens_used
    except ImportError:
        call_llm = None  # type: ignore[assignment]

        def tokens_used():  # noqa: D401
            return 0

    manifest_path = os.environ["JUDGE_MARATHON_MANIFEST"]
    output_path = os.environ["JUDGE_MARATHON_OUTPUT"]
    scratch_dir = os.environ["JUDGE_MARATHON_SCRATCH_DIR"]
    budget_seconds = float(os.environ.get("JUDGE_MARATHON_BUDGET_SECONDS", "3600"))
    cap_tokens = int(os.environ.get("JUDGE_MARATHON_BUDGET_TOKENS", "0"))
    deadline = time.monotonic() + budget_seconds
    tail_margin = 15.0

    # max_output_tokens is moderate (8192). The marathon_llm helper refuses
    # any call where ``estimated_prompt + max_output_tokens > budget_tokens``,
    # so on a compressed marathon (e.g. ``compression_ratio=0.5`` × 5 problems
    # × 65536 tokens = 32k cap) a 32k max_out blocks every call. 8192 fits
    # the median equational-theory proof body comfortably; non-compressed
    # contestants can raise this as needed.
    llm_config = {
        "model": os.environ.get("JUDGE_MARATHON_MODEL", "openai/gpt-oss-120b"),
        "provider": "deepinfra/bf16",
        "max_output_tokens": 8192,
        "temperature": 0.0,
        "reasoning_effort": "low",
        "use_seed": True,
        "seed": 0,
        "http_timeout_seconds": 600.0,
    }

    problems = _load_manifest(manifest_path)
    solved: set[str] = set()
    submitted_in_b: set[str] = set()  # Pass-B IDs with any answer appended

    # ── Pass A: brute-force counterexample on every problem ──
    for prob in problems:
        if time.monotonic() + tail_margin >= deadline:
            break
        try:
            n, table = search_counterexample(prob["equation1"], prob["equation2"],
                                             max_n=3, time_budget=4.0)
        except Exception:  # noqa: BLE001
            continue
        if n is None:
            continue
        _append_answer(output_path, {
            "id": prob["id"], "verdict": "false",
            "code": make_false_code(n, table),
        })
        solved.add(prob["id"])

    # ── Pass B: LLM, sorted by difficulty ──
    if call_llm is None:
        return
    remaining = [p for p in problems if p["id"] not in solved]
    remaining.sort(key=difficulty_score)

    # cap_tokens semantics (mirrors marathon_llm._budget_cap): >0 finite,
    # 0 deny-all, <0 unlimited. Reserve only applies in the finite case;
    # the per-iteration break gates also only fire there.
    pass_c_reserve = int(cap_tokens * PASS_C_MIN_BUDGET_FRACTION) if cap_tokens > 0 else 0

    for prob in remaining:
        if time.monotonic() + tail_margin >= deadline:
            break
        if cap_tokens > 0 and tokens_used() + pass_c_reserve >= cap_tokens:
            break
        prompt = _fill_first(prob)
        try:
            resp = call_llm(prompt, config=llm_config)
        except Exception:  # noqa: BLE001
            continue
        if "error" in resp:
            if "exhausted" in str(resp.get("error", "")):
                break
            continue
        obj = _extract_json(resp.get("response", ""))
        if not isinstance(obj, dict):
            continue
        verdict = obj.get("verdict")
        if verdict == "true":
            body = obj.get("proof", "")
            if not body:
                continue
            code = make_true_code(body)
            _append_answer(output_path, {"id": prob["id"], "verdict": "true", "code": code})
            submitted_in_b.add(prob["id"])
            _record_pattern(scratch_dir, prob, body)
        elif verdict == "false":
            tbl = obj.get("counterexample_table")
            if isinstance(tbl, list) and tbl:
                _append_answer(output_path, {
                    "id": prob["id"], "verdict": "false",
                    "code": make_false_code(len(tbl), tbl),
                })
                submitted_in_b.add(prob["id"])

    # ── Pass C: deeper-thought retry on Pass-B *no-shows* ──
    # Only problems Pass B left without any submission (parse fail, empty
    # body, LLM error, missing counterexample). Pass-B successes are never
    # retried — last-write-wins scoring would let a context-free retry
    # overwrite a working answer with a worse one.
    # Enter Pass C unconditionally on unlimited (cap_tokens<0) or when
    # the finite cap still has headroom. cap_tokens==0 (deny-all) skips
    # Pass C since LLM calls would be refused anyway.
    pass_c_ok = cap_tokens < 0 or (cap_tokens > 0 and tokens_used() < cap_tokens - pass_c_reserve // 2)
    if pass_c_ok:
        deep_config = dict(llm_config)
        deep_config["reasoning_effort"] = "high"
        deep_config["max_output_tokens"] = 16384
        for prob in remaining:
            if time.monotonic() + tail_margin >= deadline:
                break
            if cap_tokens > 0 and tokens_used() >= cap_tokens:
                break
            pid = prob["id"]
            if pid in submitted_in_b:
                continue
            prompt = _fill_first(prob)
            try:
                resp = call_llm(prompt, config=deep_config)
            except Exception:  # noqa: BLE001
                continue
            if "error" in resp:
                if "exhausted" in str(resp.get("error", "")):
                    break
                continue
            obj = _extract_json(resp.get("response", ""))
            if not isinstance(obj, dict):
                continue
            verdict = obj.get("verdict")
            if verdict == "true":
                body = obj.get("proof", "")
                if not body:
                    continue
                _append_answer(output_path, {
                    "id": pid, "verdict": "true", "code": make_true_code(body),
                })
                _record_pattern(scratch_dir, prob, body)
            elif verdict == "false":
                tbl = obj.get("counterexample_table")
                if isinstance(tbl, list) and tbl:
                    _append_answer(output_path, {
                        "id": pid, "verdict": "false",
                        "code": make_false_code(len(tbl), tbl),
                    })


# ───────── Solo fallback ─────────

def _read_message():
    line = sys.stdin.readline()
    if not line:
        sys.exit(0)
    return json.loads(line.strip())


def _send_message(msg):
    print(json.dumps(msg), flush=True)


def run_solo():
    """Brute-force-only Solo path; not a competitive contender."""
    startup = _read_message()
    problem = startup["problem"]
    n, table = search_counterexample(problem["equation1"], problem["equation2"], max_n=3)
    if n is None:
        return
    _send_message({"call": "judge", "verdict": "false", "code": make_false_code(n, table)})
    _read_message()


def main():
    if "JUDGE_MARATHON_MANIFEST" in os.environ:
        run_marathon()
    else:
        run_solo()


if __name__ == "__main__":
    main()

"""
Stage 2 Solver — Foundation v0.1
================================

Single-file Python solver for the SAIR Mathematics Distillation Challenge
Stage 2. Implements the architecture from stage2_strategy_note_v3.md:

    Router (Stage 1 rule engine)
      → Layer 1 deterministic templates (X1, affine, projections)
      → Brute-force counterexample search (Fin 2..4)
      → Layer 3 LLM fallback with iterative repair

Track: Solo (stdin/stdout JSON protocol).
       Adaptable to Marathon by swapping main() — see comment at bottom.

Sandbox compliance: stdlib only. No numpy, z3, networkx.
                    sympy 1.13.3 is available but not used in v0.1.

Size budget: ≤ 500 KB. Currently well under.

Reading order:
    1. PROMPT — what we ask the LLM
    2. Equation parsing (Var, Prod, parse_equation)
    3. Features (leaves, leftmost_leaf, etc.)
    4. Layer 1 templates (Lean code emitters)
    5. Affine probe library (verify-then-emit)
    6. Brute-force search
    7. Rule engine (lightweight v20 port)
    8. main() loop and protocol handling
"""

import json
import sys
import itertools
from typing import Optional


# ============================================================
# PROMPT — extracted by Solo proxy via AST parsing
# ============================================================

PROMPT = """You are a Lean 4 expert generating proofs for magma equation implications.

Question: Does {problem.equation1} (Eq1) imply {problem.equation2} (Eq2) over all magmas?

Solver's analysis:
{solver.analysis}

Previous attempts (round {history.round}):
{history.attempts}

Last error from judge: {history.last_error}

CRITICAL INSTRUCTIONS:

1. The wrapper code already runs `intro G _ h`. So h is the hypothesis Eq1.
2. The hypothesis h has type ∀ vars, EquationLHS = EquationRHS — i.e. it's UNIVERSALLY QUANTIFIED.
3. To use h, you must INSTANTIATE it: `h <var1> <var2> ...` gives a specific equality.
4. The variable order in h follows the variable order of Eq1 (alphabetical: w, x, y, z).
5. Read judge errors carefully — they tell you EXACTLY what type h instances have.

WORKED EXAMPLE for FALSE (counterexample):
  Goal: prove that hypothesis "x = x*y" does NOT imply "x*y = y*x" universally.
  Strategy: find a Fin n magma where x = x*y holds but x*y ≠ y*x somewhere.
  Output: {{"verdict": "false", "size": 2, "table": [[0,0],[1,1]]}}
  In this magma, op is left-projection (x*y = x always), so x = x*y holds, but
  x*y ≠ y*x for x=0, y=1 since 0*1=0 ≠ 1=1*0.

WORKED EXAMPLE for TRUE (proof):
  Goal: prove "x = y" implies "y = x".
  Output: {{"verdict": "true", "proof": "intro a b\\nexact (h a b).symm"}}

Respond with ONLY valid JSON, no markdown fences, no prose, no comments inside proof strings.

For TRUE: {{"verdict": "true", "proof": "<Lean tactic body>"}}
For FALSE: {{"verdict": "false", "size": <n>, "table": <n×n matrix>}}

If you provide FALSE, the solver will VERIFY your table locally before sending to judge.
Make sure your table actually satisfies Eq1 and refutes Eq2 — guessing wastes rounds.

If you don't have high confidence, output FALSE with a small table and let the local
verifier check it. Don't claim TRUE unless you can write the actual derivation."""


# ============================================================
# Equation parsing
# ============================================================

class Var:
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name

    def __repr__(self):
        return self.name

    def __eq__(self, other):
        return isinstance(other, Var) and self.name == other.name

    def __hash__(self):
        return hash(("var", self.name))


class Prod:
    __slots__ = ("left", "right")

    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __repr__(self):
        return f"({self.left}*{self.right})"

    def __eq__(self, other):
        return (
            isinstance(other, Prod)
            and self.left == other.left
            and self.right == other.right
        )

    def __hash__(self):
        return hash(("prod", self.left, self.right))


def _tokenize(s: str) -> list[str]:
    # Accept both ◇ and * as operator
    s = s.replace("◇", "*")
    import re
    return re.findall(r"[A-Za-z_][A-Za-z0-9_]*|\*|\(|\)", s)


def _parse_tokens(tokens: list[str]):
    pos = [0]

    def parse_atom():
        if pos[0] >= len(tokens):
            raise ValueError(f"unexpected end at {pos[0]}")
        tok = tokens[pos[0]]
        if tok == "(":
            pos[0] += 1
            e = parse_expr()
            assert tokens[pos[0]] == ")", f"expected ) got {tokens[pos[0]]}"
            pos[0] += 1
            return e
        else:
            pos[0] += 1
            return Var(tok)

    def parse_expr():
        left = parse_atom()
        while pos[0] < len(tokens) and tokens[pos[0]] == "*":
            pos[0] += 1
            right = parse_atom()
            left = Prod(left, right)
        return left

    return parse_expr()


def parse_equation(s: str) -> tuple:
    """Parse 'L = R' into (Tree, Tree)."""
    if "=" not in s:
        raise ValueError(f"no = in {s!r}")
    lhs_str, rhs_str = s.split("=", 1)
    return _parse_tokens(_tokenize(lhs_str)), _parse_tokens(_tokenize(rhs_str))


# ============================================================
# Features
# ============================================================

def leaves(t) -> list[Var]:
    if isinstance(t, Var):
        return [t]
    return leaves(t.left) + leaves(t.right)


def leftmost_leaf(t) -> Var:
    while isinstance(t, Prod):
        t = t.left
    return t


def rightmost_leaf(t) -> Var:
    while isinstance(t, Prod):
        t = t.right
    return t


def var_set(t) -> set:
    return {v.name for v in leaves(t)}


def var_counts(t) -> dict:
    counts = {}
    for v in leaves(t):
        counts[v.name] = counts.get(v.name, 0) + 1
    return counts


def is_bare(t) -> bool:
    return isinstance(t, Var)


def tree_eq(t1, t2) -> bool:
    """Syntactic equality of trees (same variable names)."""
    if isinstance(t1, Var) and isinstance(t2, Var):
        return t1.name == t2.name
    if isinstance(t1, Prod) and isinstance(t2, Prod):
        return tree_eq(t1.left, t2.left) and tree_eq(t1.right, t2.right)
    return False


def evaluate(t, assignment: dict, table: list[list[int]]) -> int:
    """Evaluate a tree under variable assignment using the magma table."""
    if isinstance(t, Var):
        return assignment[t.name]
    a = evaluate(t.left, assignment, table)
    b = evaluate(t.right, assignment, table)
    return table[a][b]


def equation_holds(L, R, table: list[list[int]]) -> bool:
    """Check if L = R holds for all variable assignments in the magma."""
    n = len(table)
    vars_used = sorted(var_set(L) | var_set(R))
    if not vars_used:
        return True
    for assignment_tuple in itertools.product(range(n), repeat=len(vars_used)):
        assignment = dict(zip(vars_used, assignment_tuple))
        if evaluate(L, assignment, table) != evaluate(R, assignment, table):
            return False
    return True


def equation_fails_witness(L, R, table: list[list[int]]) -> Optional[dict]:
    """Return a failing assignment if Eq fails somewhere; else None."""
    n = len(table)
    vars_used = sorted(var_set(L) | var_set(R))
    if not vars_used:
        return None
    for assignment_tuple in itertools.product(range(n), repeat=len(vars_used)):
        assignment = dict(zip(vars_used, assignment_tuple))
        if evaluate(L, assignment, table) != evaluate(R, assignment, table):
            return assignment
    return None


# ============================================================
# Lean certificate templates
# ============================================================

def emit_x1_certificate() -> str:
    """B.L = B.R syntactically — reflexivity proof."""
    return """import JudgeProblem

def submission : Goal := by
  intros
  rfl
"""


def emit_brute_force_false(size: int, table: list[list[int]]) -> str:
    """FALSE certificate: a finite magma satisfying Eq1 and refuting Eq2."""
    table_json = json.dumps(table).replace('"', '\\"')
    return f"""import JudgeProblem
import JudgeDecide.DecideBang
import JudgeFinOp.MemoFinOp
open MemoFinOp

def submission : Goal := by
  let m : Magma (Fin {size}) := {{ op := finOpTable "{table_json}" }}
  refine ⟨Fin {size}, m, ?_⟩
  decideFin!
"""


def emit_left_projection_false() -> str:
    return emit_brute_force_false(2, [[0, 0], [1, 1]])


def emit_right_projection_false() -> str:
    return emit_brute_force_false(2, [[0, 1], [0, 1]])


def emit_xor_false() -> str:
    return emit_brute_force_false(2, [[0, 1], [1, 0]])


def emit_llm_proof_certificate(proof_body: str) -> str:
    """Wrap an LLM-provided proof body in the Lean submission scaffolding.

    The body is what comes after `intro G _ h <vars>;` — i.e. just the tactics
    that introduce the variables of Eq2 and prove EquationRHS using h.
    Matches the SAIR baseline pattern (EQT02-S00001).
    """
    # Strip leading "by" if LLM included it
    body = proof_body.strip()
    if body.startswith("by\n"):
        body = body[3:]
    elif body.startswith("by "):
        body = body[3:]

    # Indent each line by 2 spaces
    indented_lines = []
    for line in body.split("\n"):
        if line.strip():
            indented_lines.append("  " + line)
        else:
            indented_lines.append("")
    indented = "\n".join(indented_lines)

    return f"""import JudgeProblem

def submission : Goal := by
  intro G _ h
{indented}
"""


# ============================================================
# Affine probe library (M1-M9 from Stage 1)
# ============================================================

# (p, q, c, m): u*v = p*u + q*v + c (mod m)
AFFINE_LIBRARY = [
    ("M1", 0, 1, 1, 3),  # v + 1 mod 3
    ("M2", 1, 0, 1, 3),  # u + 1 mod 3
    ("M3", 3, 2, 0, 4),  # 3u + 2v mod 4
    ("M4", 2, 3, 0, 4),  # 2u + 3v mod 4
    ("M5", 3, 3, 0, 5),  # 3u + 3v mod 5
    ("M6", 0, 1, 1, 4),  # v + 1 mod 4
    ("M7", 1, 0, 1, 4),  # u + 1 mod 4
    ("M8", 2, 2, 0, 3),  # 2u + 2v mod 3
    ("M9", 2, 2, 0, 4),  # 2u + 2v mod 4
]


def affine_table(p: int, q: int, c: int, m: int) -> list[list[int]]:
    return [[(p * i + q * j + c) % m for j in range(m)] for i in range(m)]


def try_affine_library(L1, R1, L2, R2) -> Optional[tuple[str, list[list[int]]]]:
    """
    Find an affine magma satisfying Eq1 but failing Eq2.
    Returns (magma_name, table) or None.
    """
    for name, p, q, c, m in AFFINE_LIBRARY:
        table = affine_table(p, q, c, m)
        if equation_holds(L1, R1, table) and equation_fails_witness(L2, R2, table):
            return (name, table)
    return None


# ============================================================
# Brute-force counterexample search
# ============================================================

def brute_force_search(L1, R1, L2, R2, max_size: int = 5, time_budget: float = 60.0):
    """
    Search for a finite magma counterexample by enumerating Cayley tables.
    Returns (size, table) or None.

    For size 2: 16 tables, trivial.
    For size 3: 19,683 tables. Tractable.
    For size 4-5: structured families only (affine, projection, constant, successor).
    """
    import time
    start = time.time()

    # Size 2: full enumeration
    for table in _enumerate_tables(2):
        if time.time() - start > time_budget:
            return None
        if equation_holds(L1, R1, table) and equation_fails_witness(L2, R2, table):
            return (2, table)

    if max_size < 3:
        return None

    # Size 3: full enumeration
    for table in _enumerate_tables(3):
        if time.time() - start > time_budget:
            return None
        if equation_holds(L1, R1, table) and equation_fails_witness(L2, R2, table):
            return (3, table)

    if max_size < 4:
        return None

    # Size 4-5: structured families
    for size in (4, 5):
        if size > max_size:
            break
        for table in _structured_families(size):
            if time.time() - start > time_budget:
                return None
            if equation_holds(L1, R1, table) and equation_fails_witness(L2, R2, table):
                return (size, table)

    return None


def _enumerate_tables(n: int):
    """Yield all n×n tables of values in [0, n)."""
    cells = n * n
    for values in itertools.product(range(n), repeat=cells):
        table = [list(values[i * n:(i + 1) * n]) for i in range(n)]
        yield table


def _structured_families(n: int):
    """Yield structured n×n tables: affine, constant, projection, successor."""
    # Affine: x*y = (p*x + q*y + c) mod n
    for p in range(n):
        for q in range(n):
            for c in range(n):
                yield [[(p * i + q * j + c) % n for j in range(n)] for i in range(n)]
    # Constants
    for c in range(n):
        yield [[c for _ in range(n)] for _ in range(n)]
    # Projections
    yield [[i for _ in range(n)] for i in range(n)]
    yield [[j for j in range(n)] for _ in range(n)]
    # Successor families
    yield [[(i + 1) % n for _ in range(n)] for i in range(n)]
    yield [[(j + 1) % n for j in range(n)] for _ in range(n)]


def _structured_size_4_families():
    """Backwards-compatible alias."""
    yield from _structured_families(4)


# ============================================================
# Lightweight rule classifier (subset of Stage 1's v20)
# ============================================================

class RuleResult:
    def __init__(self, verdict: Optional[bool], rule: str, certificate: Optional[str] = None):
        self.verdict = verdict
        self.rule = rule
        self.certificate = certificate  # Lean code if directly emitable


def try_x1(L1, R1, L2, R2) -> Optional[RuleResult]:
    """X1: B.L = B.R syntactically → TRUE via reflexivity."""
    if tree_eq(L2, R2):
        return RuleResult(True, "X1", emit_x1_certificate())
    return None


def emit_singleton_certificate(eq1_str: str, eq2_str: str) -> Optional[str]:
    """
    Build a TRUE certificate for X3 (collapse-to-singleton).

    Pattern from SAIR baseline EQT02-S00001: when Eq1 has form
    `x = <term not containing x>`, |M| must be 1, so any Eq2 holds via
    the universal-equality lemma.

    Returns Lean source, or None if the pattern doesn't apply cleanly.
    """
    import re
    # Split Eq1 to get LHS variable and RHS variables
    if "=" not in eq1_str:
        return None
    lhs1, rhs1 = eq1_str.split("=", 1)
    lhs1 = lhs1.strip()
    if lhs1 != "x":
        return None  # only handle the canonical "x = ..." case for now
    rhs_vars_in_eq1 = re.findall(r'\b([a-z])\b', rhs1)
    if "x" in rhs_vars_in_eq1:
        return None  # x appears on RHS — not a collapse case
    eq1_vars = []
    seen = set()
    for v in re.findall(r'\b([a-z])\b', eq1_str):
        if v not in seen:
            seen.add(v)
            eq1_vars.append(v)
    eq2_vars = []
    seen2 = set()
    for v in re.findall(r'\b([a-z])\b', eq2_str):
        if v not in seen2:
            seen2.add(v)
            eq2_vars.append(v)
    if "=" not in eq2_str:
        return None
    eq2_lhs, eq2_rhs = eq2_str.split("=", 1)
    filler = " ".join(["a"] * (len(eq1_vars) - 1)) if len(eq1_vars) > 1 else ""

    proof_body = (
        f"  intro {' '.join(eq2_vars)}\n"
        f"  have singleton : ∀ (a b : G), a = b := "
        f"fun a b => (h a {filler}).trans (h b {filler}).symm\n"
        f"  exact singleton ({eq2_lhs.strip()}) ({eq2_rhs.strip()})"
    )
    return f"""import JudgeProblem

def submission : Goal := by
  intro G _ h
{proof_body}
"""


def try_x3(L1, R1, L2, R2, eq1_str: str = "", eq2_str: str = "") -> Optional[RuleResult]:
    """X3: A has lone variable absent from other side → forces |M|=1."""
    if is_bare(L1) and not is_bare(R1):
        if L1.name not in var_set(R1):
            cert = emit_singleton_certificate(eq1_str, eq2_str) if eq1_str else None
            return RuleResult(True, "X3", cert)
    if is_bare(R1) and not is_bare(L1):
        if R1.name not in var_set(L1):
            # Could swap-and-emit, but for first version leave to LLM
            return RuleResult(True, "X3", None)
    return None


def try_separators(L1, R1, L2, R2) -> Optional[RuleResult]:
    """S1, S2, S4 separators → projection / XOR magma refutes."""
    # S1: LP(A) AND NOT LP(B)
    LP_A = leftmost_leaf(L1).name == leftmost_leaf(R1).name
    LP_B = leftmost_leaf(L2).name == leftmost_leaf(R2).name
    if LP_A and not LP_B:
        return RuleResult(False, "S1", emit_left_projection_false())

    # S2: RP(A) AND NOT RP(B)
    RP_A = rightmost_leaf(L1).name == rightmost_leaf(R1).name
    RP_B = rightmost_leaf(L2).name == rightmost_leaf(R2).name
    if RP_A and not RP_B:
        return RuleResult(False, "S2", emit_right_projection_false())

    # S4: XOR(A) AND NOT XOR(B) — every var has same parity both sides
    cA1, cA2 = var_counts(L1), var_counts(R1)
    cB1, cB2 = var_counts(L2), var_counts(R2)

    def xor_holds(c1, c2):
        all_v = set(c1) | set(c2)
        return all((c1.get(v, 0) % 2) == (c2.get(v, 0) % 2) for v in all_v)

    XOR_A = xor_holds(cA1, cA2)
    XOR_B = xor_holds(cB1, cB2)
    if XOR_A and not XOR_B:
        return RuleResult(False, "S4", emit_xor_false())

    return None


def try_affine_separator(L1, R1, L2, R2) -> Optional[RuleResult]:
    """Affine library M1-M9: a magma admits Eq1 and refutes Eq2."""
    result = try_affine_library(L1, R1, L2, R2)
    if result:
        name, table = result
        size = len(table)
        return RuleResult(False, name, emit_brute_force_false(size, table))
    return None


def classify(L1, R1, L2, R2, eq1_str: str = "", eq2_str: str = "") -> Optional[RuleResult]:
    """Run rule engine in priority order. Returns first firing rule."""
    # X1 first (cheap, exact)
    result = try_x1(L1, R1, L2, R2)
    if result is not None:
        return result
    # Separators (FALSE direct)
    result = try_separators(L1, R1, L2, R2)
    if result is not None:
        return result
    # Affine library (FALSE via verified probe)
    result = try_affine_separator(L1, R1, L2, R2)
    if result is not None:
        return result
    # X3 collapse (TRUE with constructed Lean proof if singleton case)
    result = try_x3(L1, R1, L2, R2, eq1_str, eq2_str)
    if result is not None:
        return result
    return None


# ============================================================
# Communication protocol
# ============================================================

def send(obj):
    """Write a JSON message to stdout (one line)."""
    sys.stdout.write(json.dumps(obj) + "\n")
    sys.stdout.flush()


def recv():
    """Read a JSON message from stdin."""
    line = sys.stdin.readline()
    if not line:
        sys.exit(0)
    return json.loads(line)


def call_judge(verdict: bool, code: str) -> dict:
    """Send a judge request, return the response."""
    send({
        "call": "judge",
        "verdict": "true" if verdict else "false",
        "code": code,
    })
    return recv()


def call_llm(context: dict) -> dict:
    """Send an LLM request, return the response."""
    send({"call": "llm", "context": context})
    return recv()


# ============================================================
# Analysis context for LLM
# ============================================================

def build_analysis(L1, R1, L2, R2, attempted_rules: list[str], witness_search_log: str) -> str:
    """Build a structured analysis string for the LLM context."""
    parts = []
    parts.append(f"Eq1: {L1} = {R1}")
    parts.append(f"Eq2: {L2} = {R2}")

    # Variable structure
    vA = sorted(var_set(L1) | var_set(R1))
    vB = sorted(var_set(L2) | var_set(R2))
    parts.append(f"Eq1 vars: {vA} ({len(vA)} distinct)")
    parts.append(f"Eq2 vars: {vB} ({len(vB)} distinct)")

    # Bare-side info
    if is_bare(L1):
        parts.append(f"Eq1 LHS is bare variable {L1.name}")
    if is_bare(L2):
        parts.append(f"Eq2 LHS is bare variable {L2.name}")

    # Leftmost/rightmost
    parts.append(f"Eq1 leftmost: L={leftmost_leaf(L1).name} R={leftmost_leaf(R1).name}")
    parts.append(f"Eq1 rightmost: L={rightmost_leaf(L1).name} R={rightmost_leaf(R1).name}")
    parts.append(f"Eq2 leftmost: L={leftmost_leaf(L2).name} R={leftmost_leaf(R2).name}")
    parts.append(f"Eq2 rightmost: L={rightmost_leaf(L2).name} R={rightmost_leaf(R2).name}")

    if attempted_rules:
        parts.append(f"Rules attempted (and failed): {', '.join(attempted_rules)}")

    if witness_search_log:
        parts.append(f"Witness search: {witness_search_log}")

    return "\n".join(parts)


# ============================================================
# LLM response handling
# ============================================================

def parse_llm_response(response_text: str) -> Optional[dict]:
    """Extract verdict and proof/table from LLM response."""
    # LLM is instructed to return ONLY JSON. Strip whitespace + try parse.
    text = response_text.strip()

    # Strip markdown fences if model added them despite instructions
    if text.startswith("```"):
        lines = text.split("\n")
        if lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines)

    try:
        return json.loads(text)
    except json.JSONDecodeError:
        # Try to extract JSON object from anywhere in text
        import re
        match = re.search(r'\{[^{}]*"verdict"[^{}]*\}', text, re.DOTALL)
        if match:
            try:
                return json.loads(match.group(0))
            except Exception:
                pass
        return None


def llm_response_to_certificate(response: dict, L1=None, R1=None, L2=None, R2=None) -> Optional[tuple[bool, str]]:
    """Convert LLM response to (verdict, lean_code) or None if malformed.

    For FALSE certificates, if L1/R1/L2/R2 trees are provided, locally verify
    that the proposed magma actually satisfies Eq1 and refutes Eq2 BEFORE
    we send it to the judge. This saves wasted judge calls on garbage tables.
    """
    if not isinstance(response, dict) or "verdict" not in response:
        return None

    verdict_str = str(response["verdict"]).lower()
    if verdict_str == "true":
        proof = response.get("proof", "")
        if not proof:
            return None
        return (True, emit_llm_proof_certificate(proof))

    elif verdict_str == "false":
        size = response.get("size")
        table = response.get("table")
        if size is None and isinstance(table, list):
            size = len(table)
        if not isinstance(size, int) or not isinstance(table, list):
            return None
        if len(table) != size or any(len(row) != size for row in table):
            return None
        if not all(isinstance(x, int) and 0 <= x < size for row in table for x in row):
            return None

        # Local verification — only emit certificate if magma is a valid counterexample
        if L1 is not None:
            if not equation_holds(L1, R1, table):
                return None  # Eq1 doesn't hold — invalid candidate
            if not equation_fails_witness(L2, R2, table):
                return None  # Eq2 also holds — not a counterexample

        return (False, emit_brute_force_false(size, table))

    return None


# ============================================================
# Main solver loop
# ============================================================

def solve_problem(eq1_str: str, eq2_str: str, send_judge_fn) -> Optional[bool]:
    """
    Run the full solver pipeline on one problem.

    Args:
        eq1_str, eq2_str: equation strings.
        send_judge_fn: callable(verdict: bool, code: str) -> dict with "status".
                       In Solo mode this calls the proxy via stdin/stdout.
                       In Marathon mode it can be a no-op that just emits to JSONL.

    Returns:
        True if accepted, False if all strategies exhausted, None if not attempted.
    """
    try:
        L1, R1 = parse_equation(eq1_str)
        L2, R2 = parse_equation(eq2_str)
    except Exception:
        return None

    # Layer 1 — rule engine
    rule_result = classify(L1, R1, L2, R2, eq1_str, eq2_str)
    if rule_result and rule_result.certificate:
        resp = send_judge_fn(rule_result.verdict, rule_result.certificate)
        if resp.get("status") == "accepted":
            return True

    # Layer 1.5 — brute-force search Fin 2-3 (matches SAIR baseline reach)
    witness = brute_force_search(L1, R1, L2, R2, max_size=3, time_budget=30.0)
    if witness:
        size, table = witness
        cert = emit_brute_force_false(size, table)
        resp = send_judge_fn(False, cert)
        if resp.get("status") == "accepted":
            return True

    return False


def run_solo():
    """Solo track: stdin/stdout JSON protocol, one process per problem."""
    startup = recv()
    problem = startup["problem"]
    eq1_str = problem["equation1"]
    eq2_str = problem["equation2"]

    L1, R1 = parse_equation(eq1_str)
    L2, R2 = parse_equation(eq2_str)
    attempted = []

    # Layer 1
    rule_result = classify(L1, R1, L2, R2, eq1_str, eq2_str)
    if rule_result and rule_result.certificate:
        attempted.append(rule_result.rule)
        resp = call_judge(rule_result.verdict, rule_result.certificate)
        if resp.get("status") == "accepted":
            return

    # Layer 1.5
    witness = brute_force_search(L1, R1, L2, R2, max_size=5, time_budget=120.0)
    if witness:
        size, table = witness
        attempted.append(f"brute_force_size_{size}")
        cert = emit_brute_force_false(size, table)
        resp = call_judge(False, cert)
        if resp.get("status") == "accepted":
            return

    # Layer 3 — LLM iterative repair
    if witness:
        witness_log = f"size {witness[0]} witness was rejected by judge — try a different magma"
    else:
        witness_log = (
            "BRUTE-FORCE SEARCH RESULT: exhaustive Fin 2-3 + structured Fin 4-5 "
            "(affine, projection, constant, successor) found no counterexample. "
            "This DOES NOT MEAN Eq1 implies Eq2 — many FALSE implications require "
            "non-affine magmas at sizes 4-7+. Consider both verdicts equally likely."
        )

    for round_num in range(8):
        analysis = build_analysis(L1, R1, L2, R2, attempted, witness_log)
        llm_resp = call_llm({"analysis": analysis})
        if "error" in llm_resp:
            break

        response_text = llm_resp.get("response", "")
        parsed = parse_llm_response(response_text)
        if not parsed:
            attempted.append(f"llm_round_{round_num}_unparseable")
            continue

        cert_pair = llm_response_to_certificate(parsed, L1, R1, L2, R2)
        if not cert_pair:
            attempted.append(f"llm_round_{round_num}_malformed_or_unverified")
            continue

        verdict, code = cert_pair
        attempted.append(f"llm_round_{round_num}")
        judge_resp = call_judge(verdict, code)
        if judge_resp.get("status") == "accepted":
            return


def run_marathon():
    """Marathon track: read manifest JSONL, append answer JSONL."""
    import os
    import time

    manifest_path = os.environ["JUDGE_MARATHON_MANIFEST"]
    output_path = os.environ["JUDGE_MARATHON_OUTPUT"]
    budget_seconds = float(os.environ.get("JUDGE_MARATHON_BUDGET_SECONDS", "3600"))
    deadline = time.monotonic() + budget_seconds

    # Load manifest
    problems = []
    with open(manifest_path, encoding="utf-8") as fh:
        for raw in fh:
            raw = raw.strip()
            if not raw:
                continue
            try:
                problems.append(json.loads(raw))
            except json.JSONDecodeError:
                continue

    if not problems:
        return

    tail_margin = 5.0
    per_problem_cap = max(2.0, (budget_seconds - tail_margin) / len(problems))

    def append_answer(entry):
        line = json.dumps(entry, ensure_ascii=False) + "\n"
        with open(output_path, "a", encoding="utf-8") as fh:
            fh.write(line)
            fh.flush()
            try:
                os.fsync(fh.fileno())
            except OSError:
                pass

    for prob in problems:
        if time.monotonic() + tail_margin >= deadline:
            break

        eq1_str = prob["equation1"]
        eq2_str = prob["equation2"]

        try:
            L1, R1 = parse_equation(eq1_str)
            L2, R2 = parse_equation(eq2_str)
        except Exception:
            continue

        # Layer 1 — rule engine, deterministic
        rule_result = classify(L1, R1, L2, R2, eq1_str, eq2_str)
        if rule_result and rule_result.certificate:
            append_answer({
                "id": prob["id"],
                "verdict": "true" if rule_result.verdict else "false",
                "code": rule_result.certificate,
            })
            continue

        # Layer 1.5 — brute force within per-problem cap
        try:
            witness = brute_force_search(
                L1, R1, L2, R2,
                max_size=3,
                time_budget=per_problem_cap,
            )
        except Exception:
            continue

        if witness:
            size, table = witness
            append_answer({
                "id": prob["id"],
                "verdict": "false",
                "code": emit_brute_force_false(size, table),
            })


def main():
    import os
    try:
        if "JUDGE_MARATHON_MANIFEST" in os.environ:
            run_marathon()
        else:
            run_solo()
    except Exception as e:
        sys.stderr.write(f"solver exception: {type(e).__name__}: {e}\n")
        raise


if __name__ == "__main__":
    main()

"""
Conservative Solo-track MVP solver.

Single-file submission. The solver first searches deterministic finite
magmas for counterexamples, then tries a few small true-proof patterns.
It intentionally avoids external cache files, the equational_theories
library, and unbounded LLM loops.
"""

import json
import re
import sys
import time
from itertools import product


PROMPT = ""

FALSE_SEARCH_SECONDS = 20.0
MAX_TRUE_JUDGE_CALLS_PER_STRATEGY = 4
MAX_DIRECT_SUBSTITUTION_COMPOUND_POOL_SIZE = 64
MAX_DIRECT_SUBSTITUTION_COMPOUND_JUDGE_CALLS = 3
MAX_ONE_CONGR_CALC_CANDIDATES = 3
MAX_ONE_CONGR_CALC_JUDGE_CALLS = 2
MAX_TERM_POOL_CONSTANCY_CANDIDATES = 3
MAX_TERM_POOL_CONSTANCY_JUDGE_CALLS = 2


# -- Protocol ---------------------------------------------------------------

def log(msg):
    print(msg, file=sys.stderr, flush=True)


def read_message():
    line = sys.stdin.readline()
    if not line:
        sys.exit(0)
    return json.loads(line.strip())


def send_message(msg):
    print(json.dumps(msg), flush=True)


def call_judge(verdict, code):
    send_message({"call": "judge", "verdict": verdict, "code": code})
    return read_message()


class Judge:
    def __init__(self):
        self.calls = 0

    def check(self, verdict, code, strategy):
        self.calls += 1
        log(f"judge call {self.calls}: {strategy} ({verdict})")
        result = call_judge(verdict, code)
        status = result.get("status")
        log(f"judge result {self.calls}: {status}")
        return result


# -- Parsing and local evaluation -----------------------------------------

def normalize_op_to_diamond(text):
    return text.replace("*", "◇") if isinstance(text, str) else text


def parse_variables(text):
    seen = set()
    variables = []
    for v in re.findall(r"\b([a-z])\b", text):
        if v not in seen:
            seen.add(v)
            variables.append(v)
    return variables


def strip_outer_parens(s):
    s = s.strip()
    while len(s) >= 2 and s[0] == "(" and s[-1] == ")":
        depth = 0
        matched = True
        for i, ch in enumerate(s):
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if depth == 0 and i < len(s) - 1:
                matched = False
                break
        if not matched:
            break
        s = s[1:-1].strip()
    return s


def parse_term(s, variables):
    s = strip_outer_parens(normalize_op_to_diamond(s))
    depth = 0
    last_op = -1
    for i, ch in enumerate(s):
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif ch == "◇" and depth == 0:
            last_op = i
    if last_op >= 0:
        left = parse_term(s[:last_op], variables)
        right = parse_term(s[last_op + 1:], variables)
        return ("op", left, right)
    if len(s) == 1 and s in variables:
        return ("var", s)
    raise ValueError(f"cannot parse term: {s!r}")


def parse_equation(text):
    text = normalize_op_to_diamond(text)
    variables = parse_variables(text)
    lhs, rhs = text.split("=", 1)
    return variables, parse_term(lhs, variables), parse_term(rhs, variables)


def eval_term(term, env, op):
    if term[0] == "var":
        return env[term[1]]
    return op(eval_term(term[1], env, op), eval_term(term[2], env, op))


def tree_to_lean(term):
    if term[0] == "var":
        return term[1]
    return f"({tree_to_lean(term[1])} ◇ {tree_to_lean(term[2])})"


def norm_tree(term):
    if term[0] == "var":
        return term[1]
    return f"({norm_tree(term[1])}◇{norm_tree(term[2])})"


def subst_tree(term, mapping):
    if term[0] == "var":
        return mapping[term[1]]
    return ("op", subst_tree(term[1], mapping), subst_tree(term[2], mapping))


def check_equation(variables, lhs, rhs, n, table):
    op = lambda a, b: table[a][b]
    for vals in product(range(n), repeat=len(variables)):
        env = dict(zip(variables, vals))
        if eval_term(lhs, env, op) != eval_term(rhs, env, op):
            return False
    return True


def verify_counterexample(eq1_text, eq2_text, n, table):
    if not valid_table(n, table):
        return False, False
    v1, l1, r1 = parse_equation(eq1_text)
    v2, l2, r2 = parse_equation(eq2_text)
    sat1 = check_equation(v1, l1, r1, n, table)
    sat2 = check_equation(v2, l2, r2, n, table)
    return sat1, sat2


def valid_table(n, table):
    if not isinstance(table, list) or len(table) != n:
        return False
    for row in table:
        if not isinstance(row, list) or len(row) != n:
            return False
        for value in row:
            if not isinstance(value, int) or value < 0 or value >= n:
                return False
    return True


# -- Lean code generation --------------------------------------------------

def make_false_code(problem, n, table):
    table_str = json.dumps(table, separators=(",", ":"))
    return (
        "import JudgeProblem\n"
        "import JudgeDecide.DecideBang\n"
        "import JudgeFinOp.MemoFinOp\n"
        "open MemoFinOp\n\n"
        "def submission : Goal := by\n"
        f"  let m : Magma (Fin {n}) := {{\n"
        f"    op := finOpTable \"{table_str}\"\n"
        f"  }}\n"
        f"  refine ⟨Fin {n}, m, ?_⟩\n"
        "  decideFin!\n"
    )


def make_true_code(problem, proof_body):
    lines = clean_proof_body(proof_body).splitlines()
    indented = "\n".join("  " + line if line.strip() else "" for line in lines)
    return (
        "import JudgeProblem\n\n"
        "def submission : Goal := by\n"
        "  intro G _ h\n"
        f"{indented}\n"
    )


def make_final_true_probe_code(problem):
    return (
        "import JudgeProblem\n\n"
        "def submission : Goal := by\n"
        "  intro G _ h\n"
        "  exact h\n"
    )


def final_reject_probe(problem, judge):
    return judge.check("true", make_final_true_probe_code(problem), "final_reject_probe")


def clean_proof_body(proof_body):
    proof_body = normalize_op_to_diamond(proof_body or "")
    proof_body = re.sub(r"<think>[\s\S]*?</think>", "", proof_body).strip()
    proof_body = re.sub(r"^```(?:lean)?\s*\n?", "", proof_body)
    proof_body = re.sub(r"\n?```\s*$", "", proof_body)
    proof_body = re.sub(r"^\s*import\s+.*\n?", "", proof_body, flags=re.MULTILINE)
    proof_body = re.sub(r"^\s*by\s+", "", proof_body)
    if re.match(r"^\s*(theorem|def)\s+", proof_body) and ":= by" in proof_body:
        proof_body = re.sub(r"^.*?:=\s*by\s*\n?", "", proof_body, count=1, flags=re.DOTALL)
    return proof_body.strip()


def proof_body_allowed(proof_body):
    banned = ["sorry", "admit", "sorryAx", "import ", "theorem ", "def submission"]
    lower = proof_body.lower()
    return not any(tok.lower() in lower for tok in banned)


# -- Deterministic false search -------------------------------------------

def table_key(table):
    return tuple(tuple(row) for row in table)


def exhaustive_tables(n):
    total = n ** (n * n)
    for enc in range(total):
        yield [[(enc // (n ** (i * n + j))) % n for j in range(n)] for i in range(n)]


def product_tables(n):
    for p in range(2, n):
        if n % p != 0:
            continue
        q = n // p
        for a1 in range(p):
            for b1 in range(p):
                for c1 in range(p):
                    for a2 in range(q):
                        for b2 in range(q):
                            for c2 in range(q):
                                if a1 == b1 == c1 == a2 == b2 == c2 == 0:
                                    continue
                                table = [[0] * n for _ in range(n)]
                                for i in range(n):
                                    for j in range(n):
                                        ix, iy = divmod(i, q)
                                        jx, jy = divmod(j, q)
                                        rx = (a1 * ix + b1 * jx + c1) % p
                                        ry = (a2 * iy + b2 * jy + c2) % q
                                        table[i][j] = rx * q + ry
                                yield table


def rectangular_band_tables(n):
    for p in range(2, n):
        if n % p != 0:
            continue
        q = n // p
        yield [[(i // q) * q + (j % q) for j in range(n)] for i in range(n)]
        yield [[(j // q) * q + (i % q) for j in range(n)] for i in range(n)]


def projection_exception_tables(n):
    base_left = [[i for _ in range(n)] for i in range(n)]
    base_right = [[j for j in range(n)] for _ in range(n)]
    for base in (base_left, base_right):
        for i in range(n):
            for j in range(n):
                for c in range(n):
                    if base[i][j] == c:
                        continue
                    t = [row[:] for row in base]
                    t[i][j] = c
                    yield t
        for row in range(n):
            for c in range(n):
                t = [r[:] for r in base]
                t[row] = [c] * n
                yield t
        for col in range(n):
            for c in range(n):
                t = [r[:] for r in base]
                for i in range(n):
                    t[i][col] = c
                yield t


def structured_tables(n):
    for c in range(n):
        yield [[c] * n for _ in range(n)]

    yield [[i for _ in range(n)] for i in range(n)]      # left projection
    yield [[j for j in range(n)] for _ in range(n)]      # right projection
    yield [[min(i, j) for j in range(n)] for i in range(n)]
    yield [[max(i, j) for j in range(n)] for i in range(n)]
    yield [[(i + j) % n for j in range(n)] for i in range(n)]
    yield [[(i - j) % n for j in range(n)] for i in range(n)]

    for a in range(n):
        for b in range(n):
            for c in range(n):
                yield [[(a * i + b * j + c) % n for j in range(n)] for i in range(n)]

    for c in range(n):
        yield [[i if i == j else c for j in range(n)] for i in range(n)]
        yield [[i if i == j else i for j in range(n)] for i in range(n)]
        yield [[i if i == j else j for j in range(n)] for i in range(n)]
        yield [[i if i == j else (i + j + c) % n for j in range(n)] for i in range(n)]

    yield from rectangular_band_tables(n)
    yield from product_tables(n)
    yield from projection_exception_tables(n)


def find_counterexample(eq1_text, eq2_text, deadline):
    v1, l1, r1 = parse_equation(eq1_text)
    v2, l2, r2 = parse_equation(eq2_text)
    tested = 0
    seen = set()

    def is_counterexample(n, table):
        nonlocal tested
        tested += 1
        if time.monotonic() > deadline:
            raise TimeoutError
        return (
            check_equation(v1, l1, r1, n, table)
            and not check_equation(v2, l2, r2, n, table)
        )

    for n in (2, 3):
        log(f"strategy false_exhaustive_fin_{n}: start")
        for table in exhaustive_tables(n):
            if is_counterexample(n, table):
                log(f"strategy false_exhaustive_fin_{n}: found after {tested} candidates")
                return n, table, f"false_exhaustive_fin_{n}", tested
        log(f"strategy false_exhaustive_fin_{n}: exhausted, tested={tested}")

    for n in range(4, 8):
        log(f"strategy false_structured_fin_{n}: start")
        for table in structured_tables(n):
            key = (n, table_key(table))
            if key in seen:
                continue
            seen.add(key)
            if is_counterexample(n, table):
                log(f"strategy false_structured_fin_{n}: found after {tested} candidates")
                return n, table, f"false_structured_fin_{n}", tested
        log(f"strategy false_structured_fin_{n}: finished, tested={tested}")

    return None, None, "false_search_none", tested


# -- Deterministic true proof strategies ----------------------------------

def try_judged_true(problem, proof_body, judge, strategy):
    if not proof_body_allowed(proof_body):
        log(f"strategy {strategy}: rejected locally by proof filter")
        return False
    result = judge.check("true", make_true_code(problem, proof_body), strategy)
    return result.get("status") == "accepted"


def try_singleton(problem, eq1_text, eq2_text, judge):
    log("strategy true_singleton: start")
    eq1_vars = parse_variables(eq1_text)
    eq2_vars = parse_variables(eq2_text)
    if len(eq1_vars) < 2 or "=" not in eq1_text or "=" not in eq2_text:
        return False
    lhs, rhs = [part.strip() for part in eq1_text.split("=", 1)]
    if len(lhs) != 1 or lhs not in eq1_vars:
        return False
    if lhs in set(parse_variables(rhs)):
        return False

    goal_lhs, goal_rhs = [part.strip() for part in eq2_text.split("=", 1)]
    filler_count = max(len(eq1_vars) - 1, 0)
    filler = " ".join(["a"] * filler_count)
    h_a = f"h a {filler}" if filler else "h a"
    h_b = f"h b {filler}" if filler else "h b"
    proof = (
        f"intro {' '.join(eq2_vars)}\n"
        f"have singleton : ∀ (a b : G), a = b := "
        f"fun a b => ({h_a}).trans ({h_b}).symm\n"
        f"exact singleton ({goal_lhs}) ({goal_rhs})"
    )
    return try_judged_true(problem, proof, judge, "true_singleton")


def h_instances(eq1_text, eq2_vars, max_compound=False):
    eq1_vars, eq1_lhs, eq1_rhs = parse_equation(eq1_text)
    terms = [("var", v) for v in eq2_vars]
    if max_compound:
        terms += [("op", ("var", a), ("var", b)) for a in eq2_vars for b in eq2_vars]
    for combo in product(terms, repeat=len(eq1_vars)):
        mapping = dict(zip(eq1_vars, combo))
        lhs = subst_tree(eq1_lhs, mapping)
        rhs = subst_tree(eq1_rhs, mapping)
        if norm_tree(lhs) == norm_tree(rhs):
            continue
        args = " ".join(tree_to_lean(t) for t in combo)
        yield lhs, rhs, args


def try_direct_substitution(problem, eq1_text, eq2_text, judge):
    log("strategy true_direct_substitution: start")
    eq2_vars, goal_lhs, goal_rhs = parse_equation(eq2_text)
    target_l = norm_tree(goal_lhs)
    target_r = norm_tree(goal_rhs)
    calls = 0
    for lhs, rhs, args in h_instances(eq1_text, eq2_vars, max_compound=False):
        proof_term = None
        if norm_tree(lhs) == target_l and norm_tree(rhs) == target_r:
            proof_term = f"h {args}"
        elif norm_tree(lhs) == target_r and norm_tree(rhs) == target_l:
            proof_term = f"(h {args}).symm"
        if proof_term:
            proof = f"intro {' '.join(eq2_vars)}\nexact {proof_term}"
            calls += 1
            if try_judged_true(problem, proof, judge, "true_direct_substitution"):
                return True
            if calls >= MAX_TRUE_JUDGE_CALLS_PER_STRATEGY:
                return False
    return False


def term_size(term):
    if term[0] == "var":
        return 1
    return 1 + term_size(term[1]) + term_size(term[2])


def subterms(term):
    yield term
    if term[0] == "op":
        yield from subterms(term[1])
        yield from subterms(term[2])


def term_pool(goal_vars, goal_lhs=None, goal_rhs=None):
    terms = [("var", v) for v in goal_vars]
    terms += [("op", ("var", a), ("var", b)) for a in goal_vars for b in goal_vars]
    for root in (goal_lhs, goal_rhs):
        if root is None:
            continue
        terms += [t for t in subterms(root) if term_size(t) <= 5]

    deduped = {}
    for t in terms:
        deduped.setdefault(norm_tree(t), t)
    return sorted(deduped.values(), key=lambda t: (term_size(t), norm_tree(t)))


def match_pattern(pattern, target, mapping):
    if pattern[0] == "var":
        v = pattern[1]
        current = mapping.get(v)
        if current is None:
            mapping = dict(mapping)
            mapping[v] = target
            return mapping
        return mapping if norm_tree(current) == norm_tree(target) else None
    if target[0] != "op":
        return None
    mapping = match_pattern(pattern[1], target[1], mapping)
    if mapping is None:
        return None
    return match_pattern(pattern[2], target[2], mapping)


def mapping_uses_term_pool(mapping, allowed):
    return all(norm_tree(t) in allowed for t in mapping.values())


def direct_term_pool_candidate(eq1_vars, eq1_lhs, eq1_rhs, goal_lhs, goal_rhs, allowed):
    mapping = match_pattern(eq1_lhs, goal_lhs, {})
    if mapping is None:
        return None
    mapping = match_pattern(eq1_rhs, goal_rhs, mapping)
    if mapping is None:
        return None
    if not all(v in mapping for v in eq1_vars):
        return None
    if not mapping_uses_term_pool(mapping, allowed):
        return None
    args = " ".join(tree_to_lean(mapping[v]) for v in eq1_vars)
    return f"h {args}"


def try_direct_substitution_compound(problem, eq1_text, eq2_text, judge):
    log("strategy true_direct_substitution_compound: start")
    eq2_vars, goal_lhs, goal_rhs = parse_equation(eq2_text)
    eq1_vars, eq1_lhs, eq1_rhs = parse_equation(eq1_text)
    pool = term_pool(eq2_vars, goal_lhs, goal_rhs)
    if len(pool) > MAX_DIRECT_SUBSTITUTION_COMPOUND_POOL_SIZE:
        pool = pool[:MAX_DIRECT_SUBSTITUTION_COMPOUND_POOL_SIZE]
    allowed = {norm_tree(t) for t in pool}

    candidates = []
    checked = 0

    checked += 1
    direct = direct_term_pool_candidate(eq1_vars, eq1_lhs, eq1_rhs, goal_lhs, goal_rhs, allowed)
    if direct is not None:
        candidates.append((direct, "direct"))

    checked += 1
    reverse = direct_term_pool_candidate(eq1_vars, eq1_lhs, eq1_rhs, goal_rhs, goal_lhs, allowed)
    if reverse is not None:
        candidates.append((f"({reverse}).symm", "symm"))

    log(
        "strategy true_direct_substitution_compound: "
        f"pool={len(pool)} checked={checked} candidates={len(candidates)}"
    )
    calls = 0
    seen = set()
    for proof_term, kind in candidates:
        if proof_term in seen:
            continue
        seen.add(proof_term)
        proof = f"intro {' '.join(eq2_vars)}\nexact {proof_term}"
        calls += 1
        if try_judged_true(problem, proof, judge, "true_direct_substitution_compound"):
            log(f"strategy true_direct_substitution_compound: accepted {kind}; judge_calls={calls}")
            return True
        if calls >= MAX_DIRECT_SUBSTITUTION_COMPOUND_JUDGE_CALLS:
            break
    log(f"strategy true_direct_substitution_compound: judge_calls={calls}; no acceptance")
    return False


def try_calc_chain(problem, eq1_text, eq2_text, judge):
    log("strategy true_calc_chain: start")
    eq2_vars, goal_lhs, goal_rhs = parse_equation(eq2_text)
    target_l = norm_tree(goal_lhs)
    target_r = norm_tree(goal_rhs)
    nodes = {target_l: goal_lhs, target_r: goal_rhs}
    edges = {}

    for lhs, rhs, args in h_instances(eq1_text, eq2_vars, max_compound=False):
        nl = norm_tree(lhs)
        nr = norm_tree(rhs)
        nodes.setdefault(nl, lhs)
        nodes.setdefault(nr, rhs)
        edges.setdefault(nl, []).append((nr, f"h {args}"))
        edges.setdefault(nr, []).append((nl, f"(h {args}).symm"))

    calls = 0
    for mid, proof1 in edges.get(target_l, []):
        if mid == target_r:
            proof = (
                f"intro {' '.join(eq2_vars)}\n"
                "calc\n"
                f"  {tree_to_lean(goal_lhs)} = {tree_to_lean(goal_rhs)} := {proof1}"
            )
            calls += 1
            if try_judged_true(problem, proof, judge, "true_calc_chain_1"):
                return True
            if calls >= MAX_TRUE_JUDGE_CALLS_PER_STRATEGY:
                return False

    for mid, proof1 in edges.get(target_l, []):
        for end, proof2 in edges.get(mid, []):
            if end != target_r:
                continue
            proof = (
                f"intro {' '.join(eq2_vars)}\n"
                "calc\n"
                f"  {tree_to_lean(goal_lhs)} = {tree_to_lean(nodes[mid])} := {proof1}\n"
                f"  _ = {tree_to_lean(goal_rhs)} := {proof2}"
            )
            calls += 1
            if try_judged_true(problem, proof, judge, "true_calc_chain_2"):
                return True
            if calls >= MAX_TRUE_JUDGE_CALLS_PER_STRATEGY:
                return False
    return False


def h_proof_between(eq1_vars, eq1_lhs, eq1_rhs, left, right, allowed):
    direct = direct_term_pool_candidate(eq1_vars, eq1_lhs, eq1_rhs, left, right, allowed)
    if direct is not None:
        return direct
    reverse = direct_term_pool_candidate(eq1_vars, eq1_lhs, eq1_rhs, right, left, allowed)
    if reverse is not None:
        return f"({reverse}).symm"
    return None


def h_edges_from_left(eq1_vars, eq1_lhs, eq1_rhs, left, pool, allowed, limit=16):
    edges = []

    def add_edges(pattern, result, wrapper):
        nonlocal edges
        mapping = match_pattern(pattern, left, {})
        if mapping is None or not mapping_uses_term_pool(mapping, allowed):
            return
        missing = [v for v in eq1_vars if v not in mapping]
        for combo in product(pool, repeat=len(missing)):
            full = dict(mapping)
            full.update(dict(zip(missing, combo)))
            if not mapping_uses_term_pool(full, allowed):
                continue
            right = subst_tree(result, full)
            if norm_tree(right) == norm_tree(left):
                continue
            args = " ".join(tree_to_lean(full[v]) for v in eq1_vars)
            edges.append((right, wrapper(args)))
            if len(edges) >= limit:
                return

    add_edges(eq1_lhs, eq1_rhs, lambda args: f"h {args}")
    if len(edges) < limit:
        add_edges(eq1_rhs, eq1_lhs, lambda args: f"(h {args}).symm")
    return edges[:limit]


def congr_arg_between(eq1_vars, eq1_lhs, eq1_rhs, left, right, allowed):
    if left[0] != "op" or right[0] != "op":
        return None
    if norm_tree(left[2]) == norm_tree(right[2]):
        inner = h_proof_between(eq1_vars, eq1_lhs, eq1_rhs, left[1], right[1], allowed)
        if inner is not None:
            return f"congrArg (fun t : G => t ◇ {tree_to_lean(left[2])}) ({inner})"
    if norm_tree(left[1]) == norm_tree(right[1]):
        inner = h_proof_between(eq1_vars, eq1_lhs, eq1_rhs, left[2], right[2], allowed)
        if inner is not None:
            return f"congrArg (fun t : G => {tree_to_lean(left[1])} ◇ t) ({inner})"
    return None


def try_one_congr_calc_chain(problem, eq1_text, eq2_text, judge):
    log("strategy true_one_congr_calc_chain: start")
    eq2_vars, goal_lhs, goal_rhs = parse_equation(eq2_text)
    eq1_vars, eq1_lhs, eq1_rhs = parse_equation(eq1_text)
    pool = term_pool(eq2_vars, goal_lhs, goal_rhs)
    if len(pool) > MAX_DIRECT_SUBSTITUTION_COMPOUND_POOL_SIZE:
        pool = pool[:MAX_DIRECT_SUBSTITUTION_COMPOUND_POOL_SIZE]
    allowed = {norm_tree(t) for t in pool}
    candidates = []
    seen = set()

    for mid, proof1 in h_edges_from_left(eq1_vars, eq1_lhs, eq1_rhs, goal_lhs, pool, allowed):
        proof2 = congr_arg_between(eq1_vars, eq1_lhs, eq1_rhs, mid, goal_rhs, allowed)
        if proof2 is None:
            continue
        proof = (
            f"intro {' '.join(eq2_vars)}\n"
            "calc\n"
            f"  {tree_to_lean(goal_lhs)} = {tree_to_lean(mid)} := {proof1}\n"
            f"  _ = {tree_to_lean(goal_rhs)} := {proof2}"
        )
        if proof in seen:
            continue
        seen.add(proof)
        candidates.append(proof)
        if len(candidates) >= MAX_ONE_CONGR_CALC_CANDIDATES:
            break

    log(f"strategy true_one_congr_calc_chain: candidates={len(candidates)}")
    calls = 0
    for proof in candidates[:MAX_ONE_CONGR_CALC_JUDGE_CALLS]:
        calls += 1
        if try_judged_true(problem, proof, judge, "true_one_congr_calc_chain"):
            log(
                "strategy true_one_congr_calc_chain: "
                f"accepted {problem.get('id', '?')}; judge_calls={calls}"
            )
            return True
    log(f"strategy true_one_congr_calc_chain: judge_calls={calls}; no acceptance")
    return False


def combo_side_terms(eq1_text, eq2_vars):
    eq1_vars, eq1_lhs, eq1_rhs = parse_equation(eq1_text)
    term_vars = [("var", v) for v in eq2_vars]
    for combo in product(term_vars, repeat=len(eq1_vars)):
        mapping = dict(zip(eq1_vars, combo))
        args = " ".join(tree_to_lean(t) for t in combo)
        yield eq1_vars, combo, args, subst_tree(eq1_lhs, mapping), subst_tree(eq1_rhs, mapping)


def try_simple_constancy(problem, eq1_text, eq2_text, judge):
    log("strategy true_simple_constancy: start")
    eq2_vars, goal_lhs, goal_rhs = parse_equation(eq2_text)
    target_l = norm_tree(goal_lhs)
    target_r = norm_tree(goal_rhs)
    eq1_vars, raw_lhs, raw_rhs = parse_equation(eq1_text)
    lhs_vars = set(re.findall(r"\b([a-z])\b", eq1_text.split("=", 1)[0]))
    rhs_vars = set(re.findall(r"\b([a-z])\b", eq1_text.split("=", 1)[1]))
    calls = 0

    for pos, var in enumerate(eq1_vars):
        lhs_only = var in lhs_vars and var not in rhs_vars
        rhs_only = var in rhs_vars and var not in lhs_vars
        if not lhs_only and not rhs_only:
            continue

        combos = list(combo_side_terms(eq1_text, eq2_vars))
        for _, combo_a, args_a, lhs_a, rhs_a in combos:
            for _, combo_b, args_b, lhs_b, rhs_b in combos:
                if all(i == pos or norm_tree(combo_a[i]) == norm_tree(combo_b[i]) for i in range(len(eq1_vars))):
                    if norm_tree(combo_a[pos]) == norm_tree(combo_b[pos]):
                        continue
                    if rhs_only:
                        left, right = rhs_a, rhs_b
                        term = f"(h {args_a}).symm.trans (h {args_b})"
                    else:
                        left, right = lhs_a, lhs_b
                        term = f"(h {args_a}).trans (h {args_b}).symm"

                    if norm_tree(left) == target_l and norm_tree(right) == target_r:
                        proof_term = term
                    elif norm_tree(left) == target_r and norm_tree(right) == target_l:
                        proof_term = f"({term}).symm"
                    else:
                        continue

                    proof = f"intro {' '.join(eq2_vars)}\nexact {proof_term}"
                    calls += 1
                    if try_judged_true(problem, proof, judge, "true_simple_constancy"):
                        return True
                    if calls >= MAX_TRUE_JUDGE_CALLS_PER_STRATEGY:
                        return False
    return False


def constancy_proof_for(eq1_vars, side_term, lhs_only, target_l, target_r, allowed, default_term):
    m_a = match_pattern(side_term, target_l, {})
    m_b = match_pattern(side_term, target_r, {})
    if m_a is None or m_b is None:
        return None
    if not mapping_uses_term_pool(m_a, allowed) or not mapping_uses_term_pool(m_b, allowed):
        return None

    diff_positions = []
    args_a = []
    args_b = []
    for i, v in enumerate(eq1_vars):
        a = m_a.get(v, default_term)
        b = m_b.get(v, default_term)
        args_a.append(tree_to_lean(a))
        args_b.append(tree_to_lean(b))
        if norm_tree(a) != norm_tree(b):
            diff_positions.append(i)

    if len(diff_positions) != 1:
        return None
    args_a = " ".join(args_a)
    args_b = " ".join(args_b)
    if lhs_only:
        return f"(h {args_a}).trans (h {args_b}).symm", diff_positions[0]
    return f"(h {args_a}).symm.trans (h {args_b})", diff_positions[0]


def congr_arg_candidate(eq1_vars, side_term, lhs_only, goal_lhs, goal_rhs, allowed, default_term):
    if goal_lhs[0] != "op" or goal_rhs[0] != "op":
        return None
    if norm_tree(goal_lhs[2]) == norm_tree(goal_rhs[2]):
        proof = constancy_proof_for(
            eq1_vars, side_term, lhs_only, goal_lhs[1], goal_rhs[1], allowed, default_term
        )
        if proof is not None:
            return f"congr_arg (fun t : G => t ◇ {tree_to_lean(goal_lhs[2])}) ({proof[0]})"
    if norm_tree(goal_lhs[1]) == norm_tree(goal_rhs[1]):
        proof = constancy_proof_for(
            eq1_vars, side_term, lhs_only, goal_lhs[2], goal_rhs[2], allowed, default_term
        )
        if proof is not None:
            return f"congr_arg (fun t : G => {tree_to_lean(goal_lhs[1])} ◇ t) ({proof[0]})"
    return None


def try_constancy_term_pool(problem, eq1_text, eq2_text, judge):
    log("strategy true_constancy_term_pool: start")
    eq2_vars, goal_lhs, goal_rhs = parse_equation(eq2_text)
    eq1_vars, eq1_lhs, eq1_rhs = parse_equation(eq1_text)
    lhs_vars = set(re.findall(r"\b([a-z])\b", eq1_text.split("=", 1)[0]))
    rhs_vars = set(re.findall(r"\b([a-z])\b", eq1_text.split("=", 1)[1]))
    pool = term_pool(eq2_vars)
    if not pool:
        return False
    default_term = pool[0]
    allowed = {norm_tree(t) for t in pool}
    candidates = []
    seen = set()

    def add_candidate(proof_term, kind):
        if proof_term is None:
            return
        key = (kind, proof_term)
        if key in seen or len(candidates) >= MAX_TERM_POOL_CONSTANCY_CANDIDATES:
            return
        seen.add(key)
        candidates.append((proof_term, kind))

    for pos, var in enumerate(eq1_vars):
        lhs_only = var in lhs_vars and var not in rhs_vars
        rhs_only = var in rhs_vars and var not in lhs_vars
        if not lhs_only and not rhs_only:
            continue
        side_term = eq1_lhs if lhs_only else eq1_rhs

        direct = constancy_proof_for(
            eq1_vars, side_term, lhs_only, goal_lhs, goal_rhs, allowed, default_term
        )
        if direct is not None and direct[1] == pos:
            add_candidate(direct[0], "direct")
        direct_rev = constancy_proof_for(
            eq1_vars, side_term, lhs_only, goal_rhs, goal_lhs, allowed, default_term
        )
        if direct_rev is not None and direct_rev[1] == pos:
            add_candidate(f"({direct_rev[0]}).symm", "direct")

        add_candidate(
            congr_arg_candidate(
                eq1_vars, side_term, lhs_only, goal_lhs, goal_rhs, allowed, default_term
            ),
            "congr_arg",
        )
        rev = congr_arg_candidate(
            eq1_vars, side_term, lhs_only, goal_rhs, goal_lhs, allowed, default_term
        )
        if rev is not None:
            add_candidate(f"({rev}).symm", "congr_arg")

    log(f"strategy true_constancy_term_pool: candidates={len(candidates)}")
    calls = 0
    for proof_term, kind in candidates[:MAX_TERM_POOL_CONSTANCY_JUDGE_CALLS]:
        proof = f"intro {' '.join(eq2_vars)}\nexact {proof_term}"
        calls += 1
        if try_judged_true(problem, proof, judge, "true_constancy_term_pool"):
            log(f"strategy true_constancy_term_pool: accepted {kind}; judge_calls={calls}")
            return True
    log(f"strategy true_constancy_term_pool: judge_calls={calls}; no acceptance")
    return False


def run_true_strategies(problem, eq1_text, eq2_text, judge):
    strategies = [
        try_singleton,
        try_direct_substitution,
        try_direct_substitution_compound,
        try_calc_chain,
        try_one_congr_calc_chain,
        try_simple_constancy,
        try_constancy_term_pool,
    ]
    for strategy in strategies:
        if strategy(problem, eq1_text, eq2_text, judge):
            log(f"accepted strategy: {strategy.__name__}")
            return True
    return False


# -- Main ------------------------------------------------------------------

def main():
    startup = read_message()
    problem = startup["problem"]
    problem["equation1"] = normalize_op_to_diamond(problem["equation1"])
    problem["equation2"] = normalize_op_to_diamond(problem["equation2"])
    eq1_text = problem["equation1"]
    eq2_text = problem["equation2"]
    problem_id = problem.get("id", "?")
    log(f"problem {problem_id}: Equation{problem.get('eq1_id')} -> Equation{problem.get('eq2_id')}")
    judge = Judge()

    false_deadline = time.monotonic() + FALSE_SEARCH_SECONDS
    try:
        n, table, strategy, tested = find_counterexample(eq1_text, eq2_text, false_deadline)
    except TimeoutError:
        n, table, strategy, tested = None, None, "false_search_timeout", 0
        log("strategy false_search: timeout")

    if n is not None:
        sat1, sat2 = verify_counterexample(eq1_text, eq2_text, n, table)
        log(f"strategy {strategy}: local verify hypothesis={sat1} goal={sat2}")
        if sat1 and not sat2:
            result = judge.check("false", make_false_code(problem, n, table), strategy)
            if result.get("status") == "accepted":
                log(f"accepted strategy: {strategy}; tested_tables={tested}; judge_calls={judge.calls}")
                return
        else:
            log(f"strategy {strategy}: rejected locally despite search hit")

    if run_true_strategies(problem, eq1_text, eq2_text, judge):
        log(f"problem {problem_id}: solved; judge_calls={judge.calls}")
        return

    log(f"problem {problem_id}: no accepted certificate; judge_calls={judge.calls}; last_false_strategy={strategy}")
    if judge.calls == 0:
        result = final_reject_probe(problem, judge)
        log(f"problem {problem_id}: final_reject_probe result={result.get('status')}; judge_calls={judge.calls}")


if __name__ == "__main__":
    main()

import json
import os
import re
import sys
import urllib.request


API_BASE = os.environ.get("PIPELINE_API_BASE", "http://localhost:8000")

PROMPT = """You are solving a Lean 4 equational-theories problem over magmas.
The problem contains a hypothesis equation and a target equation.

Return exactly one JSON object and no Markdown.

For a true implication:
{"verdict":"true","proof":"<Lean tactic proof body only>"}

For a false implication:
{"verdict":"false","counterexample_table":[[0,1],[1,0]]}

Rules:
- The operation is an arbitrary binary operation. Do not assume associativity, commutativity, identity, or inverses.
- Keep Lean code minimal and compatible with the judge wrapper.
- Never use incomplete proof placeholders or unsafe mechanisms.
- If judge feedback is provided, revise the previous candidate instead of repeating it."""


def api_request(method: str, path: str, body: dict[str, object] | None = None) -> dict[str, object]:
    data = json.dumps(body).encode("utf-8") if body is not None else None
    request = urllib.request.Request(
        f"{API_BASE}{path}",
        data=data,
        method=method,
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(request, timeout=300) as response:
        payload = json.loads(response.read())
    data_payload = payload.get("data")
    if not isinstance(data_payload, dict):
        raise RuntimeError("API response is missing data object")
    return data_payload


def read_problem() -> dict[str, object]:
    raw_problem = os.environ.get("PROBLEM_JSON")
    if raw_problem:
        problem = json.loads(raw_problem)
    else:
        startup = json.loads(sys.stdin.readline())
        problem = startup.get("problem")
    if not isinstance(problem, dict):
        raise RuntimeError("Problem payload is missing")
    return problem


def create_session(problem: dict[str, object]) -> str:
    result = api_request("POST", "/api/stage2/pipeline/sessions", {"problem": problem})
    session_id = result.get("session_id")
    if not isinstance(session_id, str) or not session_id:
        raise RuntimeError("API response is missing session_id")
    return session_id


def close_session(session_id: str) -> None:
    api_request("DELETE", f"/api/stage2/pipeline/sessions/{session_id}")


def llm_chat(session_id: str, context: dict[str, object]) -> str:
    result = api_request("POST", f"/api/stage2/pipeline/sessions/{session_id}/llm", {"context": context})
    response = result.get("response")
    if not isinstance(response, str):
        raise RuntimeError("LLM response is missing")
    return response


def judge_answer(session_id: str, answer: dict[str, object]) -> dict[str, object]:
    verdict = answer.get("verdict")
    if verdict not in ("true", "false"):
        raise ValueError("answer verdict must be true or false")
    proof = answer.get("proof")
    code = proof if isinstance(proof, str) else answer.get("code")
    if verdict == "false" and isinstance(answer.get("counterexample_table"), list):
        code = json.dumps(answer["counterexample_table"])
    if not isinstance(code, str):
        raise ValueError("answer code is missing")
    return api_request("POST", f"/api/stage2/pipeline/sessions/{session_id}/judge", {"verdict": verdict, "code": code})


def parse_answer(response: str) -> dict[str, object] | None:
    stripped = response.strip()
    candidates = [stripped]
    candidates.extend(match.group(0) for match in re.finditer(r"\{[\s\S]*?\}", response))
    for candidate in candidates:
        try:
            parsed = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            return parsed
    return None


def compact_judge_feedback(result: dict[str, object]) -> dict[str, object]:
    return {
        "status": result.get("status"),
        "error_code": result.get("error_code"),
        "message": result.get("message"),
        "lean_stdout": result.get("lean_stdout"),
        "lean_stderr": result.get("lean_stderr"),
    }


def main() -> None:
    session_id = ""
    best_answer: dict[str, object] | None = None
    feedback: dict[str, object] | None = None
    try:
        problem = read_problem()
        session_id = create_session(problem)
        for round_index in range(8):
            context: dict[str, object] = {"round": round_index, "problem": problem}
            if feedback is not None:
                context["judge_feedback"] = feedback
            response = llm_chat(session_id, context)
            answer = parse_answer(response)
            if answer is None:
                feedback = {"status": "unparsed", "message": "Model did not return JSON"}
                continue
            best_answer = answer
            try:
                result = judge_answer(session_id, answer)
            except Exception as exc:
                feedback = {"status": "malformed", "message": str(exc), "answer": answer}
                continue
            if result.get("status") == "accepted":
                print(json.dumps({"solved": True, "verdict": answer.get("verdict"), "answer": answer, "judge": result}))
                return
            feedback = compact_judge_feedback(result)
        print(json.dumps({"solved": False, "answer": best_answer, "feedback": feedback}))
    except Exception as exc:
        print(json.dumps({"solved": False, "error": str(exc)}))
    finally:
        if session_id:
            try:
                close_session(session_id)
            except Exception:
                pass


if __name__ == "__main__":
    main()

