@lru_cache(maxsize=None)
def commutative_term_key(term: Term) -> Term:
    if term[0] == "var":
        return term
    left = commutative_term_key(term[1])
    right = commutative_term_key(term[2])
    if repr(right) < repr(left):
        left, right = right, left
    return "op", left, right


