SYMBOLIC_MODEL_PLAN_VERSION = 'sair-symbolic-model-plan-v1'
SYMBOLIC_MODEL_PLAN_KINDS = {'symbolic_model_plan', 'type_model_plan', 'infinite_model_plan', 'structured_infinite_model'}
SYMBOLIC_MODEL_PATCH_KINDS = {'symbolic_model_patch', 'type_model_patch', 'infinite_model_patch', 'structured_infinite_model_patch'}
SYMBOLIC_MODEL_PART_FIELDS = ('carrier', 'definitions', 'operation', 'setup', 'hypothesis_proof', 'counterexample_proof')
_SYMBOLIC_MODEL_NAME_RE = re.compile("^[A-Za-z_][A-Za-z0-9_']*$")
_SYMBOLIC_MODEL_IMPORT_RE = re.compile("^[A-Za-z_][A-Za-z0-9_'.]*$")
_SYMBOLIC_MODEL_BANNED_RE = re.compile('\\b(?:sorry|admit|axiom|unsafe|def\\s+submission)\\b|<(?!;>)[A-Za-z][^>\\n]{0,79}>', re.IGNORECASE)

def is_symbolic_model_plan_payload(data: Any) -> bool:
    return isinstance(data, dict) and str(data.get('kind') or '') in SYMBOLIC_MODEL_PLAN_KINDS

def is_symbolic_model_patch_payload(data: Any) -> bool:
