    initial_feedback = [{'kind': 'initial_direct_graph_state', 'status': 'direct_mechanical_routes_available_for_feedback', 'search_state': graph_search_state(h_eq, g_eq, status='direct_goal_not_connected'), 'need_hint': 'Use frontier/closest_pairs to propose a bridge midpoint, or choose the top ranked trusted tool.'}, *early_true_feedback[-2:]]
