            completion_failure_feedback.append(protocol_state('MechanicalResponse', 'judge_rejected_true_body', 'ordered_completion', tool_state=completion_state, judge_status=result.get('status'), need_hint='Completion built a proof plan but Lean rejected the final body; inspect the blocked replay edge or propose its equation as a smaller midpoint.'))
        elif isinstance(completion_state, dict):
            completion_failure_feedback.append(protocolize_state(completion_state, 'ordered_completion', status=completion_state.get('status', 'stuck')))
    remaining = max(0.0, budget - (time.monotonic() - solve_started))
    late_llm_feedback: list[dict[str, Any]] = []
    late_failed_signatures: set[str] = set()
    status = try_llm_collaboration(h_eq, g_eq, remaining, max_rounds=2, collaboration_goal='Late collaboration pass after native deterministic tools failed. Broad finite-model routes have already failed in this solve. Prefer a real bridge midpoint/lemma_chain or a true-side tool that acts on the reported frontier. Use a false artifact only when you can provide a concrete construction rather than another routine carrier retry. A useful midpoint will be proved as H=>M and then consumed as H+M=>G.', initial_feedback=[{'kind': 'late_system2_state', 'status': 'native_deep_tools_failed', 'search_state': graph_search_state(h_eq, g_eq, status='native_deep_goal_not_connected'), 'native_false_failed_attempts': false_failure_feedback[-3:], 'native_deep_failed_attempts': deep_failure_feedback, 'completion_failed_attempts': completion_failure_feedback, 'need_hint': 'Propose a small midpoint with seed_h_args, or a concrete false_model_hint route not already covered by default search.'}], prefer_false=False, feedback_sink=late_llm_feedback, semantic_context=semantic_context, failed_signatures=late_failed_signatures, candidate_blackboard=candidate_blackboard)
    if status:
        return status
    status = try_llm_collaboration(h_eq, g_eq, budget, max_rounds=3, collaboration_goal='True-recovery collaboration pass after deterministic and broad finite-model routes failed. Use the preserved mechanical feedback to repair prior midpoint/tool actions. Propose a bridge midpoint, lemma_chain, seed_terms, or direct proof; return a false artifact only when it is concrete and not another routine carrier retry.', initial_feedback=[{'kind': 'initial_direct_graph_state', 'status': 'direct_mechanical_routes_exhausted', 'search_state': graph_search_state(h_eq, g_eq, status='direct_goal_not_connected'), 'need_hint': 'Use the frontier/closest_pairs to propose a bridge midpoint, or choose a different bounded tool route.'}, *false_failure_feedback[-3:], *deep_failure_feedback[-4:], *completion_failure_feedback[-2:], *late_llm_feedback[-6:]], prefer_false=False, semantic_context=semantic_context, failed_signatures=late_failed_signatures, candidate_blackboard=candidate_blackboard)
    return status or 'unsolved'

def main() -> None:
    startup = read_msg()
    problem = startup.get('problem', startup)
    budget = float(startup.get('budget', {}).get('timeout_seconds', 3600))
    status = solve(problem, budget)
    print(f"[baby_solver] {problem.get('id')}: {status}", file=sys.stderr)
if __name__ == '__main__':
    main()

