@dataclass(frozen=True)
class ProtocolIssue:
    code: str
    message: str
    field: str | None = None

    def to_dict(self) -> dict[str, Any]:
        out = {'code': self.code, 'message': self.message}
        if self.field:
            out['field'] = self.field
        return out

def protocol_state(kind: str, status: str, source: str, **extra: Any) -> dict[str, Any]:
    out: dict[str, Any] = {'protocol_version': PROTOCOL_VERSION, 'kind': kind, 'status': status, 'source': source}
    contract = tool_contract(extra.get('tool') or source) if 'tool_contract' not in extra else None
    if contract:
        out['tool_contract'] = contract
    for key, value in extra.items():
        if value is not None:
            out[key] = value
    return out

def protocolize_state(state: dict[str, Any] | None, source: str, *, status: str | None=None, suggested_next_actions: list[dict[str, Any]] | None=None, errors: list[dict[str, Any]] | None=None, **extra: Any) -> dict[str, Any]:
    out = dict(state or {})
    out.setdefault('protocol_version', PROTOCOL_VERSION)
    out.setdefault('kind', 'MechanicalState')
    if 'source' in out and out['source'] != source:
        out.setdefault('artifact_source', out['source'])
    out['source'] = source
    contract = tool_contract(out.get('tool') or source)
    if contract:
        out.setdefault('tool_contract', contract)
    if status is not None:
        out['status'] = status
    else:
        out.setdefault('status', 'unknown')
    if suggested_next_actions:
        out['suggested_next_actions'] = suggested_next_actions
    if errors:
        out['errors'] = errors
    for key, value in extra.items():
        if value is not None:
            out[key] = value
    return out

def _finite_float(value: Any, default: float) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return default
    if parsed != parsed or parsed in (float('inf'), float('-inf')):
        return default
    return parsed

def _clamped_float(value: Any, default: float, low: float, high: float) -> float:
    return max(low, min(high, _finite_float(value, default)))

def _clamped_int(value: Any, default: int, low: int, high: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return default
    return max(low, min(high, parsed))

@dataclass(frozen=True)
class MidpointBudgetPolicy:
    total_budget: float
    initial_grant: float = 2.5
    grant_growth: float = 2.0
    max_grant: float = 10.0
    max_grants_per_task: int = 3
    attain_priority: float = 1.0
    consume_priority: float = 1.2
    goal_priority: float = 1.1
    relevance_weight: float = 0.35
    reuse_weight: float = 0.25
    exploration_weight: float = 0.3
    progress_weight: float = 0.4
    companion_success_weight: float = 1.25
    failure_penalty: float = 0.15
    tie_break_weight: float = 0.001
    seed: int = 0

    @classmethod
    def from_mapping(cls, value: Any=None, *, candidate_count: int=1, requested_total: Any=None) -> 'MidpointBudgetPolicy':
        raw = dict(value) if isinstance(value, dict) else {}
        default_total = max(10.0, 10.0 * (max(1, min(5, candidate_count)) + 1))
        total = raw.get('total_budget', raw.get('total', requested_total))
        total_budget = _clamped_float(total, default_total, 1.0, 600.0)
        initial = _clamped_float(raw.get('initial_grant', raw.get('minimum_grant')), 2.5, 0.1, min(60.0, total_budget))
        max_grant = _clamped_float(raw.get('max_grant'), 10.0, initial, min(120.0, total_budget))
        return cls(total_budget=total_budget, initial_grant=initial, grant_growth=_clamped_float(raw.get('grant_growth', raw.get('growth_factor')), 2.0, 1.0, 4.0), max_grant=max_grant, max_grants_per_task=_clamped_int(raw.get('max_grants_per_task'), 3, 1, 8), attain_priority=_clamped_float(raw.get('attain_priority'), 1.0, 0.0, 10.0), consume_priority=_clamped_float(raw.get('consume_priority'), 1.2, 0.0, 10.0), goal_priority=_clamped_float(raw.get('goal_priority'), 1.1, 0.0, 10.0), relevance_weight=_clamped_float(raw.get('relevance_weight'), 0.35, 0.0, 10.0), reuse_weight=_clamped_float(raw.get('reuse_weight'), 0.25, 0.0, 10.0), exploration_weight=_clamped_float(raw.get('exploration_weight'), 0.3, 0.0, 10.0), progress_weight=_clamped_float(raw.get('progress_weight'), 0.4, 0.0, 10.0), companion_success_weight=_clamped_float(raw.get('companion_success_weight'), 1.25, 0.0, 10.0), failure_penalty=_clamped_float(raw.get('failure_penalty'), 0.15, 0.0, 10.0), tie_break_weight=_clamped_float(raw.get('tie_break_weight'), 0.001, 0.0, 1.0), seed=_clamped_int(raw.get('seed'), 0, 0, 2 ** 31 - 1))

    def to_mapping(self) -> dict[str, Any]:
        return {'total_budget': self.total_budget, 'initial_grant': self.initial_grant, 'grant_growth': self.grant_growth, 'max_grant': self.max_grant, 'max_grants_per_task': self.max_grants_per_task, 'attain_priority': self.attain_priority, 'consume_priority': self.consume_priority, 'goal_priority': self.goal_priority, 'relevance_weight': self.relevance_weight, 'reuse_weight': self.reuse_weight, 'exploration_weight': self.exploration_weight, 'progress_weight': self.progress_weight, 'companion_success_weight': self.companion_success_weight, 'failure_penalty': self.failure_penalty, 'tie_break_weight': self.tie_break_weight, 'seed': self.seed}

    @property
    def policy_id(self) -> str:
        encoded = json.dumps(self.to_mapping(), sort_keys=True, separators=(',', ':')).encode('utf-8')
        return f'midpoint_budget_v1_{zlib.crc32(encoded) & 4294967295:08x}'

@dataclass
class BudgetWorkItem:
