def compact_proof_state(state: dict[str, Any] | None) -> dict[str, Any]:
    source = state if isinstance(state, dict) else {}
    superposition = source.get('superposition_state')
    if not isinstance(superposition, dict) and source.get('kind') == 'SuperpositionState':
        superposition = source
    superposition = superposition if isinstance(superposition, dict) else {}
    return {'kind': source.get('kind'), 'status': source.get('status'), 'stop_reason': superposition.get('stop_reason'), 'records_generated': superposition.get('records_generated') or superposition.get('equations_generated') or superposition.get('record_count'), 'derivation_length': superposition.get('derivation_length'), 'need_hint': source.get('need_hint') or superposition.get('need_hint')}

