        rung_state = {'index': index, 'name': name, 'equation': equation['text'], 'status': 'proved' if proof_body else 'stuck', 'elapsed_seconds': round(time.monotonic() - rung_started, 3), 'budget_clock': 'cpu_with_wall_cap' if cpu_budgeted else 'wall', 'proof_state': compact_proof_state(proof_state)}
        attempts.append(rung_state)
