def collapse_witness_vars(t: Term, acc: set[str] | None=None) -> set[str]:
    acc = acc if acc is not None else set()
    if t[0] == 'var':
        acc.add(str(t[1]))
    else:
        collapse_witness_vars(t[1], acc)
        collapse_witness_vars(t[2], acc)
    return acc

def is_collapse_witness(l: Term, r: Term) -> bool:
    if l[0] == 'var' and l[1] not in collapse_witness_vars(r):
        return True
    if r[0] == 'var' and r[1] not in collapse_witness_vars(l):
        return True
    return False
COLLAPSE_CERT_DEPTH = 4
COLLAPSE_CERT_MAX_TERM = 24
COLLAPSE_CERT_MAX_DERIVED = 600

def collapse_cert_vars(t: Term, acc: list[str] | None=None) -> list[str]:
    acc = acc if acc is not None else []
    if t[0] == 'var':
        if not str(t[1]).startswith('#') and t[1] not in acc:
            acc.append(t[1])
    else:
        collapse_cert_vars(t[1], acc)
        collapse_cert_vars(t[2], acc)
    return acc

def collapse_cert_size(t: Term) -> int:
    return 1 if t[0] == 'var' else 1 + collapse_cert_size(t[1]) + collapse_cert_size(t[2])

def collapse_cert_term(t: Term) -> str:
    if t[0] == 'var':
        return str(t[1])
    return f'({collapse_cert_term(t[1])} ◇ {collapse_cert_term(t[2])})'

def collapse_cert_rename(eq: tuple[Term, Term], prefix: str, counter: list[int], mapping: dict[str, Term]) -> tuple[Term, Term]:

    def go(t: Term) -> Term:
        if t[0] == 'var':
            name = str(t[1])
            if name.startswith('#'):
                return t
            if name not in mapping:
                mapping[name] = ('var', f'{prefix}{counter[0]}')
                counter[0] += 1
            return mapping[name]
        return ('op', go(t[1]), go(t[2]))
    return (go(eq[0]), go(eq[1]))

class CollapseCertRule:
    __slots__ = ('name', 'vars', 'l', 'r', 'proof_lines', 'parents')

    def __init__(self, name: str, vars: list[str], l: Term, r: Term, proof_lines: list[str], parents: list[Any] | None=None) -> None:
        self.name = name
        self.vars = vars
        self.l = l
        self.r = r
        self.proof_lines = proof_lines
        self.parents = list(parents or [])

def collapse_cert_overlap(rule_a: CollapseCertRule, rule_b: CollapseCertRule, fresh: list[int]) -> list[tuple[Term, Term, dict[str, Term], dict[str, Term], dict[str, Term]]]:
    map_a: dict[str, Term] = {}
    map_b: dict[str, Term] = {}
    lhs_a, rhs_a = collapse_cert_rename((rule_a.l, rule_a.r), f'p{fresh[0]}_', fresh, map_a)
    lhs_b, rhs_b = collapse_cert_rename((rule_b.l, rule_b.r), f'q{fresh[0]}_', fresh, map_b)
    out = []
    for pos, subterm in pc_positions(lhs_a):
        if pos == () or subterm[0] == 'var':
            continue
        subst = pc_unify(subterm, lhs_b, {})
        if subst is None:
            continue
        cp_l = pc_apply(pc_replace_at(lhs_a, pos, rhs_b), subst)
        cp_r = pc_apply(rhs_a, subst)
        if cp_l == cp_r:
            continue
        out.append((cp_l, cp_r, map_a, map_b, subst))
    return out

def collapse_cert_subst_unbound(t: Term, bound: set[str], witness: str) -> Term:
    if t[0] == 'var':
        name = str(t[1])
        if name.startswith('#'):
            return t
        return t if name in bound else ('var', witness)
    return ('op', collapse_cert_subst_unbound(t[1], bound, witness), collapse_cert_subst_unbound(t[2], bound, witness))

def collapse_cert_emit_rule(rule_a: CollapseCertRule, rule_b: CollapseCertRule, map_a: dict[str, Term], map_b: dict[str, Term], subst: dict[str, Term], cp_l: Term, cp_r: Term, name: str) -> CollapseCertRule:
    vars_out = collapse_cert_vars(cp_l)
    collapse_cert_vars(cp_r, vars_out)
    bound = set(vars_out)
    witness = vars_out[0] if vars_out else 'w'

    def argstr(rule: CollapseCertRule, mapping: dict[str, Term]) -> str:
        parts: list[str] = []
        for var in rule.vars:
            if var not in mapping:
                parts.append(witness)
                continue
            arg = pc_apply(mapping[var], subst)
            arg = collapse_cert_subst_unbound(arg, bound, witness)
            parts.append(collapse_cert_term(arg))
        return ' '.join(parts)
    proof = [f'have _iA := {rule_a.name} {argstr(rule_a, map_a)}'.rstrip(), f'have _iB := {rule_b.name} {argstr(rule_b, map_b)}'.rstrip(), 'grind']
    parents = [rule for rule in (rule_a, rule_b) if rule.name != 'h']
    return CollapseCertRule(name, vars_out, cp_l, cp_r, proof, parents=parents)

def collapse_cert_mk_rule(rule_a: CollapseCertRule, rule_b: CollapseCertRule, fresh: list[int], name: str) -> CollapseCertRule | None:
    best: tuple[int, Term, Term, dict[str, Term], dict[str, Term], dict[str, Term]] | None = None
    for cp_l, cp_r, map_a, map_b, subst in collapse_cert_overlap(rule_a, rule_b, fresh):
        canon_l, canon_r = pc_canon(cp_l, cp_r)
        if not is_collapse_witness(canon_l, canon_r):
            continue
        total_size = collapse_cert_size(cp_l) + collapse_cert_size(cp_r)
        if total_size > COLLAPSE_CERT_MAX_TERM:
            continue
        if best is None or total_size < best[0]:
            best = (total_size, cp_l, cp_r, map_a, map_b, subst)
    if best is None:
        return None
    _, cp_l, cp_r, map_a, map_b, subst = best
    return collapse_cert_emit_rule(rule_a, rule_b, map_a, map_b, subst, cp_l, cp_r, name)

def collapse_cert_path(collapse_rule: CollapseCertRule) -> list[CollapseCertRule]:
    order: list[CollapseCertRule] = []
    visited: set[int] = set()

    def visit(rule: CollapseCertRule) -> None:
        if id(rule) in visited:
            return
        visited.add(id(rule))
        for parent in rule.parents:
            visit(parent)
        order.append(rule)
    visit(collapse_rule)
    remap: dict[str, str] = {}
    idx = 0
    for rule in order:
        if rule is collapse_rule:
            continue
        remap[rule.name] = f'M{idx}'
        idx += 1
    for rule in order:
        if rule.name in remap:
            rule.name = remap[rule.name]
        patched: list[str] = []
        for line in rule.proof_lines:
            for old, new in remap.items():
                line = line.replace(f':= {old} ', f':= {new} ')
            patched.append(line)
        rule.proof_lines = patched
    return order

def collapse_cert_derive(h_rule: CollapseCertRule) -> tuple[list[CollapseCertRule], CollapseCertRule] | None:
    fresh = [0]
    direct = collapse_cert_mk_rule(h_rule, h_rule, fresh, 'magic')
    if direct is not None:
        return ([direct], direct)
    derived = [h_rule]
    seen = {pc_canon(h_rule.l, h_rule.r)}
    frontier = [h_rule]
    lemma_index = 0
    for _depth in range(COLLAPSE_CERT_DEPTH):
        new_frontier: list[CollapseCertRule] = []
        for rule_a in frontier:
            for rule_b in derived:
                for cp_l, cp_r, map_a, map_b, subst in collapse_cert_overlap(rule_a, rule_b, fresh):
                    if collapse_cert_size(cp_l) + collapse_cert_size(cp_r) > COLLAPSE_CERT_MAX_TERM:
                        continue
                    canon_l, canon_r = pc_canon(cp_l, cp_r)
                    if is_collapse_witness(canon_l, canon_r):
                        collapse = collapse_cert_emit_rule(rule_a, rule_b, map_a, map_b, subst, cp_l, cp_r, 'magic')
                        return (collapse_cert_path(collapse), collapse)
                    key = pc_canon(cp_l, cp_r)
                    if key in seen:
                        continue
                    if collapse_cert_size(cp_l) >= collapse_cert_size(cp_r):
                        new_l, new_r = (cp_l, cp_r)
                    else:
                        new_l, new_r = (cp_r, cp_l)
                    if new_l[0] == 'var':
                        continue
                    seen.add(key)
                    name = f'L{lemma_index}'
                    lemma_index += 1
                    rule = collapse_cert_emit_rule(rule_a, rule_b, map_a, map_b, subst, new_l, new_r, name)
                    derived.append(rule)
                    new_frontier.append(rule)
                    if len(derived) > COLLAPSE_CERT_MAX_DERIVED:
                        return None
        frontier = new_frontier
        if not frontier:
            break
    return None

def collapse_cert_all_subterms(t: Term):
    yield t
    if t[0] == 'op':
        yield from collapse_cert_all_subterms(t[1])
        yield from collapse_cert_all_subterms(t[2])

def collapse_cert_match(pat: Term, term: Term, subst: dict[str, Term]) -> dict[str, Term] | None:
    if pat[0] == 'var' and (not str(pat[1]).startswith('#')):
        name = str(pat[1])
        if name in subst:
            return subst if subst[name] == term else None
        subst = dict(subst)
        subst[name] = term
        return subst
    if pat[0] == 'var':
        return subst if term == pat else None
    if term[0] != 'op':
        return None
    subst_left = collapse_cert_match(pat[1], term[1], subst)
    if subst_left is None:
        return None
    return collapse_cert_match(pat[2], term[2], subst_left)

def collapse_cert_goal_instance(cp_l: Term, cp_r: Term, all_vars: list[str], goal_l: Term, goal_r: Term) -> str | None:
    if cp_r[0] != 'var':
        return None
    for product_side, other_side in ((goal_l, goal_r), (goal_r, goal_l)):
        for subterm in collapse_cert_all_subterms(product_side):
            if subterm[0] != 'op':
                continue
            subst = collapse_cert_match(cp_l, subterm, {})
            if subst is None:
                continue
            subst = dict(subst)
            subst.setdefault(str(cp_r[1]), other_side)
            other = collapse_cert_term(other_side)
            args = [collapse_cert_term(subst[var]) if var in subst else other for var in all_vars]
            return ' '.join(args)
    return None

def collapse_certificate_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    h_lhs, h_rhs = (h_eq['lhs'], h_eq['rhs'])
    if is_collapse_witness(h_lhs, h_rhs) and len(h_eq['variables']) >= 2:
        if h_lhs[0] == 'var' and h_lhs[1] not in collapse_witness_vars(h_rhs):
            collapse_var = str(h_lhs[1])
        elif h_rhs[0] == 'var' and h_rhs[1] not in collapse_witness_vars(h_lhs):
            collapse_var = str(h_rhs[1])
        else:
            collapse_var = h_eq['variables'][0]

        def direct_args(value: str) -> str:
            return ' '.join((value if var == collapse_var else 'u' for var in h_eq['variables']))
        goal_vars = list(g_eq['variables'])
        lines = []
        if goal_vars:
            lines.append('intro ' + ' '.join(goal_vars))
        lines.extend(['have triv : ∀ u v : G, u = v := by', '  intro u v', f"  have hu := h {direct_args('u')}", f"  have hv := h {direct_args('v')}", '  grind', f"exact triv ({collapse_cert_term(g_eq['lhs'])}) ({collapse_cert_term(g_eq['rhs'])})"])
        return '\n'.join(lines)
    if h_lhs[0] != 'var' and h_rhs[0] != 'var':
        return None
    if h_lhs[0] == 'var':
        big, lone = (h_rhs, h_lhs)
    elif h_rhs[0] == 'var':
        big, lone = (h_lhs, h_rhs)
    else:
        return None
    h_rule = CollapseCertRule('h', list(h_eq['variables']), big, lone, [])
    derived = collapse_cert_derive(h_rule)
    if derived is None:
        return None
    lemmas, collapse = derived
    goal_vars = list(g_eq['variables'])
    goal_l, goal_r = (g_eq['lhs'], g_eq['rhs'])
    cp_l, cp_r, all_vars = (collapse.l, collapse.r, collapse.vars)
    collapse_slot = str(cp_r[1]) if cp_r[0] == 'var' else None
    lines: list[str] = []
    if goal_vars:
        lines.append('intro ' + ' '.join(goal_vars))
    for rule in lemmas:
        binders = ' '.join(rule.vars)
        lines.append(f'have {rule.name} : ∀ {binders} : G, {collapse_cert_term(rule.l)} = {collapse_cert_term(rule.r)} := by')
        lines.append('  intro ' + binders)
        for proof_line in rule.proof_lines:
            lines.append('  ' + proof_line)
    if collapse_slot is not None and collapse_slot in all_vars and goal_vars:
        witness = goal_vars[0]

        def margs(slot_value: str) -> str:
            return ' '.join((slot_value if var == collapse_slot else witness for var in all_vars))
        lines.extend(['have triv : ∀ u v : G, u = v := by', '  intro u v', f"  have eu := {collapse.name} {margs('u')}", f"  have ev := {collapse.name} {margs('v')}", '  grind', f'exact triv ({collapse_cert_term(goal_l)}) ({collapse_cert_term(goal_r)})'])
        return '\n'.join(lines)
    inst = collapse_cert_goal_instance(cp_l, cp_r, all_vars, goal_l, goal_r)
    if inst is not None:
        lines.append(f'have hgoal := {collapse.name} ' + inst)
    lines.append('grind')
    return '\n'.join(lines)

def collapse_certificate_bodies(h_eq: dict[str, Any], g_eq: dict[str, Any]):
    body = collapse_certificate_body(h_eq, g_eq)
    if body:
        yield ('collapse_certificates', body)

def broad_grounding_vars(term: Term, acc: list[str] | None=None) -> list[str]:
    acc = acc if acc is not None else []
    if term[0] == 'var':
        if term[1] not in acc:
            acc.append(term[1])
    else:
        broad_grounding_vars(term[1], acc)
        broad_grounding_vars(term[2], acc)
    return acc

def broad_grounding_orientable(lhs: Term, rhs: Term) -> bool:
    left_vars = set(broad_grounding_vars(lhs))
    right_vars = set(broad_grounding_vars(rhs))
    return left_vars <= right_vars or right_vars <= left_vars

def broad_grounding_target_collapse(eq: tuple[Term, Term]) -> bool:
    lhs, rhs = eq
    return is_collapse_witness(lhs, rhs)

def broad_grounding_target_right_irrel(eq: tuple[Term, Term]) -> bool:
    lhs, rhs = eq
    return lhs[0] == 'op' and rhs[0] == 'op' and (lhs[1] == rhs[1]) and (lhs[2][0] == 'var') and (rhs[2][0] == 'var') and (lhs[2] != rhs[2])

def broad_grounding_target_left_irrel(eq: tuple[Term, Term]) -> bool:
    lhs, rhs = eq
    return lhs[0] == 'op' and rhs[0] == 'op' and (lhs[2] == rhs[2]) and (lhs[1][0] == 'var') and (rhs[1][0] == 'var') and (lhs[1] != rhs[1])
BROAD_GROUNDING_TARGETS = [('right_irrel', broad_grounding_target_right_irrel), ('left_irrel', broad_grounding_target_left_irrel), ('collapse', broad_grounding_target_collapse)]

def self_root_absorption_h(h_eq: dict[str, Any]) -> bool:
    for lone, other in ((h_eq['lhs'], h_eq['rhs']), (h_eq['rhs'], h_eq['lhs'])):
        if lone[0] == 'var' and other[0] == 'op' and (other[1] == lone or other[2] == lone):
            return True
    return False

def repeated_self_absorption_h(h_eq: dict[str, Any], g_eq: dict[str, Any] | None=None) -> bool:
    for lone, other in ((h_eq['lhs'], h_eq['rhs']), (h_eq['rhs'], h_eq['lhs'])):
        if lone[0] != 'var' or other[0] != 'op':
            continue
        var = str(lone[1])
        if term_var_count(other, var) < 2:
            continue
        if g_eq is None:
            return True
        goal_pairs = ((g_eq['lhs'], g_eq['rhs']), (g_eq['rhs'], g_eq['lhs']))
        if any((side[0] == 'var' and side[1] == var and (other_side[0] == 'op') for side, other_side in goal_pairs)):
            return True
    return False

def nested_tail_absorption_h(h_eq: dict[str, Any], g_eq: dict[str, Any] | None=None) -> bool:
    for lone, other in ((h_eq['lhs'], h_eq['rhs']), (h_eq['rhs'], h_eq['lhs'])):
        if lone[0] != 'var' or other[0] != 'op':
            continue
        left, right = (other[1], other[2])
        if left[0] != 'op' or right[0] != 'op':
            continue
        left_tail = left[2]
        if left_tail[0] != 'op':
            continue
        if left_tail[2] != lone or right[2] != lone:
            continue
        if left_tail[1] == lone:
            continue
        if g_eq is None:
            return True
        goal_pairs = ((g_eq['lhs'], g_eq['rhs']), (g_eq['rhs'], g_eq['lhs']))
        if any((side == lone and other_side[0] == 'op' for side, other_side in goal_pairs)):
            return True
    return False

def broad_grounding_derived_body(h_eq: dict[str, Any], g_eq: dict[str, Any], budget: float=12.0, *, full_budget_per_target: bool=False) -> tuple[str | None, dict[str, Any]]:
    if not broad_grounding_orientable(h_eq['lhs'], h_eq['rhs']):
        return (None, {'kind': 'broad_grounding_derived_state', 'status': 'not_applicable', 'reason': 'H is non-orientable; grounding_h is the matching certificate family.'})
    attempts: list[dict[str, Any]] = []
    per_target_budget = max(1.0, float(budget)) if full_budget_per_target else max(1.0, float(budget) / max(1, len(BROAD_GROUNDING_TARGETS)))
    for name, predicate in BROAD_GROUNDING_TARGETS:
        tid, recs, meta = pc_saturate([(h_eq['lhs'], h_eq['rhs'])], predicate, max_rounds=6, max_eqs=2000, max_size=26, time_budget=per_target_budget)
        attempts.append({'target_helper': name, 'status': 'derived' if tid is not None else 'stuck', 'generated_equations': len(recs), 'rounds': meta.get('rounds'), 'stop_reason': meta.get('stop_reason')})
        if tid is not None:
            body = pc_render(tid, recs, list(g_eq['variables']), goal_lhs=g_eq['lhs'], goal_rhs=g_eq['rhs'])
            return (body, {'kind': 'broad_grounding_derived_state', 'status': 'body_built', 'derived_helper': name, 'full_budget_per_target': full_budget_per_target, 'attempts': attempts})
    return (None, {'kind': 'broad_grounding_derived_state', 'status': 'stuck', 'full_budget_per_target': full_budget_per_target, 'attempts': attempts, 'need_hint': 'No collapse or factor-irrelevance helper was derived; try goal_superposition, collapse_certificates, or a midpoint close to the best superposition frontier.'})

def equation_shape_tags(lhs: Term, rhs: Term) -> list[str]:
    tags: list[str] = []
    for l, r in ((lhs, rhs), (rhs, lhs)):
        if l[0] == 'var' and r[0] == 'var' and (l != r):
            tags.append('const')
        if l[0] == 'op' and r[0] == 'var':
            if l[1] == r:
                tags.append('proj_l')
            if l[2] == r:
                tags.append('proj_r')
        if l[0] == 'op' and r[0] == 'op':
            if l[1] == r[1] and l[2] != r[2]:
                tags.append('rowconst')
            if l[2] == r[2] and l[1] != r[1]:
                tags.append('colconst')
            if l[1] != r[1] and l[2] != r[2]:
                tags.append('opconst_like')
            if is_square(l) is not None and is_square(r) is not None and (l != r):
                tags.append('square_const')
    return unique(tags)

def target_aux_shape(target_eq: dict[str, Any]) -> str | None:
    lhs, rhs = (target_eq['lhs'], target_eq['rhs'])
    tags = equation_shape_tags(lhs, rhs)
    if 'const' in tags and lhs[0] == 'var' and (rhs[0] == 'var'):
        return 'const'
    if 'proj_l' in tags:
        return 'proj_l'
    if 'proj_r' in tags:
        return 'proj_r'
    if 'rowconst' in tags:
        return 'rowconst'
    if 'opconst_like' in tags:
        return 'opconst'
    if 'square_const' in tags:
        return 'square_const'
    return None

def superposition_state(h_eq: dict[str, Any], target_eq: dict[str, Any], recs: list[dict[str, Any]], meta: dict[str, Any], status: str, base_names: list[str]) -> dict[str, Any]:
    goal_l = term_to_str(target_eq['lhs'])
    goal_r = term_to_str(target_eq['rhs'])
    scored: list[dict[str, Any]] = []
    derived_scored: list[dict[str, Any]] = []
    shape_rows: list[dict[str, Any]] = []
    for rid, rec in enumerate(recs[:2000]):
        lhs = term_to_str(rec['lhs'])
        rhs = term_to_str(rec['rhs'])
        text = f'{lhs} = {rhs}'
        score = max(difflib.SequenceMatcher(None, lhs, goal_l).ratio(), difflib.SequenceMatcher(None, lhs, goal_r).ratio(), difflib.SequenceMatcher(None, rhs, goal_l).ratio(), difflib.SequenceMatcher(None, rhs, goal_r).ratio(), difflib.SequenceMatcher(None, text, target_eq['text']).ratio())
        row = {'rid': rid, 'similarity': round(score, 3), **pc_rec_summary(rec)}
        scored.append(row)
        if rec.get('deriv') is not None:
            derived_scored.append(row)
            tags = equation_shape_tags(rec['lhs'], rec['rhs'])
            if tags:
                shape_rows.append({**row, 'shape_tags': tags})
    scored.sort(key=lambda item: item['similarity'], reverse=True)
    derived_scored.sort(key=lambda item: item['similarity'], reverse=True)
    shape_rows.sort(key=lambda item: (len(item.get('shape_tags', [])), item['similarity']), reverse=True)
    target_shape = target_aux_shape(target_eq)
    frontier_action = None
    if status != 'proved' and target_shape == 'const' and derived_scored:
        frontier = derived_scored[0]
        frontier_action = {'kind': 'midpoint', 'lemma': f"{frontier['lhs']} = {frontier['rhs']}", 'why': 'proof-carrying frontier equation is an easier first rung toward collapse'}
    state = {'kind': 'SuperpositionState', 'status': status, 'target': target_eq['text'], 'target_shape': target_shape, 'base_names': base_names, 'generated_equations': len(recs), 'rounds': meta.get('rounds'), 'stop_reason': meta.get('stop_reason'), 'limits': {'max_rounds': meta.get('max_rounds'), 'max_eqs': meta.get('max_eqs'), 'max_size': meta.get('max_size')}, 'closest_equations': scored[:5], 'derived_closest_equations': derived_scored[:5], 'shape_diagnostics': shape_rows[:8], 'need_hint': None if status == 'proved' else {'kind': 'superposition_subgoal', 'reason': 'proof-carrying superposition did not reach the target; propose a smaller universal midpoint near a closest_equations row', 'target': target_eq['text'], 'closest_equation': (derived_scored[0] if derived_scored else scored[0]) if scored else None, 'recommended_next_action': frontier_action}, 'suggested_next_actions': [frontier_action] if frontier_action else []}
    if target_shape == 'rowconst':
        opconst_like = next((row for row in shape_rows if 'opconst_like' in row.get('shape_tags', [])), None)
        recommended_next_action = None
        rejected_recommendations: list[dict[str, Any]] = []
        if opconst_like:
            opconst_eq = parse_equation('a ◇ b = c ◇ d')
            opconst_refutation = hint_refutation(h_eq, opconst_eq)
            if opconst_refutation is None:
                recommended_next_action = {'kind': 'midpoint', 'lemma': 'a ◇ b = c ◇ d', 'why': 'rowconst target is stuck but superposition derived an opconst-like product bridge', 'source': opconst_like}
            else:
                rejected_recommendations.append({'kind': 'midpoint', 'lemma': 'a ◇ b = c ◇ d', 'status': 'refuted_by_small_model', 'refutation': opconst_refutation, 'source': opconst_like})
        state['rowconst_diagnostics'] = {'kind': 'rowconst_superposition_diagnostics', 'best_derived_equations': derived_scored[:5], 'near_aux_shapes': shape_rows[:8], 'recommended_next_action': recommended_next_action, 'rejected_recommendations': rejected_recommendations, 'secondary_bridge_candidates': ['a ◇ b = c ◇ d', 'a ◇ a = b ◇ b', 'a ◇ b = a', 'a ◇ b = b'], 'reason': 'If rowconst itself is hard to prove or insufficient, these derived shapes are useful follow-up bridge candidates.'}
        if recommended_next_action and isinstance(state.get('need_hint'), dict):
            state['need_hint']['recommended_next_action'] = recommended_next_action
    return state

def superposition_prove_detailed(h_eq: dict[str, Any], target_eq: dict[str, Any], assumptions: list[UniversalEquation] | None=None, *, budget: float=6.0, allow_var_overlap: bool=False, cpu_budgeted: bool=False, wall_budget: float | None=None) -> tuple[str | None, dict[str, Any]]:
    assumptions = assumptions or []
    start = [(h_eq['lhs'], h_eq['rhs'])] + [(a.eq['lhs'], a.eq['rhs']) for a in assumptions]
    base_names = ['h'] + [a.name for a in assumptions]
    target_sig = pc_canon(target_eq['lhs'], target_eq['rhs'])
    last_state: dict[str, Any] | None = None
    configs = [(3, 360, 14), (4, 650, 16), (5, 900, 20), (5, 1400, 22), (6, 1800, 24)]
    wall_allowance = max(1.0, wall_budget) if cpu_budgeted and wall_budget is not None else max(2.0, budget * 6.0) if cpu_budgeted else max(1.0, budget)
    deadline = time.monotonic() + wall_allowance
    cpu_deadline = time.process_time() + max(0.1, budget) if cpu_budgeted else None
    for max_rounds, max_eqs, max_size in configs:
        rem = deadline - time.monotonic()
        cpu_rem = cpu_deadline - time.process_time() if cpu_deadline is not None else None
        if rem <= 0.25 or (cpu_rem is not None and cpu_rem <= 0.1):
            break
        tid, recs, meta = pc_saturate(start, lambda eq: pc_canon(eq[0], eq[1]) == target_sig, max_rounds=max_rounds, max_eqs=max_eqs, max_size=max_size, time_budget=rem, cpu_budget=cpu_rem, allow_var_overlap=allow_var_overlap)
        if tid is not None:
            body = pc_render(tid, recs, target_eq['variables'], goal_lhs=target_eq['lhs'], goal_rhs=target_eq['rhs'], base_names=base_names)
            return (body, superposition_state(h_eq, target_eq, recs, meta, 'proved', base_names))
        last_state = superposition_state(h_eq, target_eq, recs, meta, 'stuck', base_names)
        if meta.get('stop_reason') == 'time_budget':
            break
    return (None, last_state or {'kind': 'SuperpositionState', 'status': 'stuck', 'target': target_eq['text'], 'base_names': base_names, 'generated_equations': 0, 'need_hint': {'kind': 'superposition_subgoal', 'reason': 'no equations generated before budget expired'}})
STANDARD_AUX_EQUATIONS = {'const': 'a = b', 'proj_l': 'a ◇ b = a', 'proj_r': 'a ◇ b = b', 'rowconst': 'a ◇ b = a ◇ c'}
SECONDARY_BRIDGE_EQUATIONS = {'opconst': 'a ◇ b = c ◇ d', 'square_const': 'a ◇ a = b ◇ b', 'proj_l': 'a ◇ b = a', 'proj_r': 'a ◇ b = b', 'const': 'a = b', 'colconst': 'a ◇ b = c ◇ b'}

def standard_aux_order(call: dict[str, Any] | None=None) -> list[str]:
    raw = []
    if call:
        for key in ('lemmas', 'aux', 'kinds', 'targets'):
            val = call.get(key)
            if isinstance(val, str):
                raw.extend((part.strip() for part in val.split(',')))
            elif isinstance(val, list):
                raw.extend((str(part).strip() for part in val))
    if not raw:
        raw = ['const', 'proj_l', 'proj_r', 'rowconst']
    out: list[str] = []
    for item in raw:
        item = item.lower()
        item = {'projection_left': 'proj_l', 'left_projection': 'proj_l', 'projection_right': 'proj_r', 'right_projection': 'proj_r', 'row_constant': 'rowconst', 'row_const': 'rowconst'}.get(item, item)
        if item in STANDARD_AUX_EQUATIONS and item not in out:
            out.append(item)
    return out

def implied_standard_aux_lemmas(h_eq: dict[str, Any]) -> list[str]:
    plausible = [kind for kind in ('const', 'proj_l', 'proj_r', 'rowconst') if hint_refutation(h_eq, standard_aux_equation(kind)) is None]
    if 'const' in plausible:
        return ['const']
    return [kind for kind in ('proj_l', 'proj_r', 'rowconst') if kind in plausible]

def standard_aux_equation(kind: str) -> dict[str, Any]:
    return parse_equation(STANDARD_AUX_EQUATIONS[kind])

def secondary_bridge_order(aux_kind: str) -> list[str]:
    if aux_kind == 'rowconst':
        return ['opconst', 'square_const', 'proj_l', 'proj_r', 'const']
    if aux_kind == 'proj_l':
        return ['proj_r', 'const', 'opconst', 'square_const']
    if aux_kind == 'proj_r':
        return ['proj_l', 'const', 'opconst', 'square_const']
    if aux_kind == 'const':
        return []
    return ['opconst', 'square_const', 'proj_l', 'proj_r', 'const']

def secondary_bridge_equation(kind: str) -> dict[str, Any]:
    return parse_equation(SECONDARY_BRIDGE_EQUATIONS[kind])

def secondary_bridge_attempt(h_eq: dict[str, Any], g_eq: dict[str, Any], aux: UniversalEquation, aux_kind: str, deadline: float) -> tuple[str | None, dict[str, Any]]:
    attempts: list[dict[str, Any]] = []
    for bridge_kind in secondary_bridge_order(aux_kind):
        if time.monotonic() > deadline - 0.5:
            attempts.append({'kind': bridge_kind, 'status': 'skipped_budget_exhausted', 'equation': SECONDARY_BRIDGE_EQUATIONS[bridge_kind]})
            continue
        eq = secondary_bridge_equation(bridge_kind)
        if pc_canon(eq['lhs'], eq['rhs']) == pc_canon(aux.eq['lhs'], aux.eq['rhs']):
            continue
        refutation = hint_refutation(h_eq, eq)
        if refutation is not None:
            attempts.append({'kind': bridge_kind, 'status': 'refuted_by_small_model', 'equation': eq['text'], 'refutation': refutation})
            continue
        bridge = UniversalEquation(name=bridge_kind, eq=eq, extra_args=[])
        proof_body, proof_state = prove_with_assumptions_detailed(h_eq, eq, [aux])
        if proof_body is None:
            attempts.append({'kind': bridge_kind, 'status': 'not_proved', 'equation': eq['text'], 'proof_state': proof_state})
            continue
        goal_body, goal_state = prove_with_assumptions_detailed(h_eq, g_eq, [aux, bridge])
        attempts.append({'kind': bridge_kind, 'status': 'proved' if goal_body else 'proved_not_consumed', 'equation': eq['text'], 'proof_state': proof_state, 'consume_state': goal_state})
        if goal_body:
            return ('\n'.join([f'have {bridge_kind} : {lemma_statement(eq)} := by', indent(proof_body, 2), goal_body]), {'kind': 'SecondaryBridgeState', 'status': 'body_built', 'aux': aux_kind, 'bridge': bridge_kind, 'bridge_equation': eq['text'], 'attempts': attempts})
    need_hint = None
    for attempt in attempts:
        state = attempt.get('consume_state') or attempt.get('proof_state') or {}
        if isinstance(state, dict) and state.get('need_hint'):
            need_hint = state.get('need_hint')
            break
    return (None, {'kind': 'SecondaryBridgeState', 'status': 'stuck', 'aux': aux_kind, 'attempts': attempts[:5], 'need_hint': need_hint or {'kind': 'secondary_bridge_failed', 'reason': 'A proved auxiliary lemma did not close the goal, and bounded secondary bridges did not close either.'}})

def standard_aux_tail(kind: str, g_eq: dict[str, Any], h_eq: dict[str, Any], aux: UniversalEquation) -> tuple[str | None, dict[str, Any]]:
    intro = 'intro ' + ' '.join(g_eq['variables']) if g_eq['variables'] else ''

    def close_with(proof: str, status: str) -> tuple[str, dict[str, Any]]:
        return ('\n'.join([intro, proof] if intro else [proof]), {'kind': 'AuxConsumeState', 'status': status, 'used_aux': aux.name, 'need_hint': None})
    if kind == 'const':
        lhs = lean_arg(term_to_str(g_eq['lhs']))
        rhs = lean_arg(term_to_str(g_eq['rhs']))
        return close_with(f'exact {aux.name} {lhs} {rhs}', 'consumed_by_const')
    aux_eq = aux.eq
    exact_line = pc_target_exact_line(aux.name, aux_eq['lhs'], aux_eq['rhs'], aux_eq['variables'], g_eq['lhs'], g_eq['rhs'])
    if exact_line is not None:
        return close_with(exact_line, 'consumed_directly')
    hrec = {'binders': h_eq['variables'], 'lhs': h_eq['lhs'], 'rhs': h_eq['rhs']}
    calc_line = pc_one_h_target_calc(hrec, aux_eq['lhs'], aux_eq['rhs'], aux_eq['variables'], g_eq['lhs'], g_eq['rhs'], target_name=aux.name)
    if calc_line is not None:
        return close_with(calc_line, 'consumed_by_one_h_aux')
    calc_line = pc_path_target_calc(hrec, aux_eq['lhs'], aux_eq['rhs'], aux_eq['variables'], g_eq['lhs'], g_eq['rhs'], target_name=aux.name)
    if calc_line is not None:
        return close_with(calc_line, 'consumed_by_h_aux_path')
    goal_body, goal_state = prove_with_assumptions_detailed(h_eq, g_eq, [aux])
    return (goal_body, goal_state)

def grounded_assumption_grind_body(h_eq: dict[str, Any], g_eq: dict[str, Any], assumptions: list[UniversalEquation], h_limit: int=16, lemma_limit: int=32) -> tuple[str | None, dict[str, Any]]:
    if not g_eq['variables']:
        return (None, {'kind': 'GroundedConsumeState', 'status': 'no_goal_variables'})
    lines = ['intro ' + ' '.join(g_eq['variables'])]
    h_rows = candidate_h_args(h_eq, g_eq, h_limit)
    lines.extend((f'have gh{i} := h ' + ' '.join(map(lean_arg, args)) for i, args in enumerate(h_rows, 1)))
    lemma_instances = 0
    for j, assumption in enumerate(assumptions, 1):
        for i, args in enumerate(candidate_lemma_args(assumption.eq, g_eq, lemma_limit), 1):
            lines.append(f'have gl{j}_{i} := {assumption.name} ' + ' '.join(map(lean_arg, args)))
            lemma_instances += 1
    lines.append('grind')
    return ('\n'.join(lines), {'kind': 'GroundedConsumeState', 'status': 'candidate_built', 'h_instances': len(h_rows), 'lemma_instances': lemma_instances})

def standard_aux_superposition_attempt(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any] | None=None) -> tuple[str | None, dict[str, Any]]:
    call = call or {}
    kinds = standard_aux_order(call)
    implied_kinds = implied_standard_aux_lemmas(h_eq)
    prefer_implied = call.get('prefer_implied', True) is not False
    if prefer_implied and implied_kinds:
        preferred = [kind for kind in implied_kinds if kind in kinds]
        remainder = [kind for kind in kinds if kind not in preferred]
        kinds = preferred + remainder
    total_budget = float(call.get('budget') or call.get('time_budget') or 10.0)
    cpu_budgeted = bool(call.get('cpu_budgeted'))
    wall_allowance = float(call.get('wall_budget')) if cpu_budgeted and call.get('wall_budget') is not None else max(2.0, total_budget * 6.0) if cpu_budgeted else total_budget
    deadline = time.monotonic() + max(1.0, wall_allowance)
    cpu_started = time.process_time()
    allow_overlap_fallback = bool(call.get('allow_var_overlap', True))
    attempts: list[dict[str, Any]] = []
    for idx, kind in enumerate(kinds):
        rem = deadline - time.monotonic()
        if rem <= 0.25:
            attempts.append({'kind': kind, 'status': 'skipped_budget_exhausted', 'equation': STANDARD_AUX_EQUATIONS[kind]})
            continue
        eq = standard_aux_equation(kind)
        refutation = hint_refutation(h_eq, eq)
        if refutation is not None:
            attempts.append({'kind': kind, 'status': 'refuted_by_small_model', 'equation': eq['text'], 'refutation': refutation})
            continue
        remaining = max(1, len(kinds) - idx)
        focused_floor = 1.0
        if kind in implied_kinds:
            focused_floor = 8.0 if kind in {'proj_l', 'proj_r'} else 5.0
        if cpu_budgeted:
            cpu_rem = max(0.0, total_budget - (time.process_time() - cpu_started))
            if cpu_rem <= 0.1:
                attempts.append({'kind': kind, 'status': 'skipped_budget_exhausted', 'equation': eq['text'], 'budget_clock': 'cpu_with_wall_cap'})
                continue
            attempt_budget = min(cpu_rem, max(1.0, cpu_rem / remaining, focused_floor))
        else:
            attempt_budget = min(rem, max(1.0, rem / remaining, focused_floor))
        proof_body, proof_state = superposition_prove_detailed(h_eq, eq, budget=attempt_budget, allow_var_overlap=False, cpu_budgeted=cpu_budgeted, wall_budget=rem if cpu_budgeted else None)
        if proof_body is None and allow_overlap_fallback:
            overlap_rem = deadline - time.monotonic()
            overlap_cpu_rem = max(0.0, total_budget - (time.process_time() - cpu_started))
            if overlap_rem > 0.75 and (not cpu_budgeted or overlap_cpu_rem > 0.25):
                overlap_budget = min(overlap_cpu_rem if cpu_budgeted else overlap_rem, max(1.0, attempt_budget * 0.5))
                overlap_body, overlap_state = superposition_prove_detailed(h_eq, eq, budget=overlap_budget, allow_var_overlap=True, cpu_budgeted=cpu_budgeted, wall_budget=overlap_rem if cpu_budgeted else None)
                if isinstance(proof_state, dict):
                    proof_state = dict(proof_state)
                    proof_state['overlap_fallback_state'] = overlap_state
                else:
                    proof_state = {'overlap_fallback_state': overlap_state}
                if overlap_body is not None:
                    proof_body = overlap_body
                    proof_state['used_overlap_fallback'] = True
        if proof_body is None:
            budget_starved = isinstance(proof_state, dict) and (proof_state.get('stop_reason') == 'time_budget' or (isinstance(proof_state.get('superposition_state'), dict) and proof_state['superposition_state'].get('stop_reason') == 'time_budget') or (isinstance(proof_state.get('overlap_fallback_state'), dict) and proof_state['overlap_fallback_state'].get('stop_reason') == 'time_budget'))
            attempts.append({'kind': kind, 'status': 'budget_starved' if budget_starved else 'not_proved', 'equation': eq['text'], 'attempt_budget': round(attempt_budget, 3), 'budget_clock': 'cpu_with_wall_cap' if cpu_budgeted else 'wall', 'implied_by_scout': kind in implied_kinds, 'proof_state': proof_state})
            continue
        aux = UniversalEquation(name=kind, eq=eq, extra_args=[])
        tail, consume_state = standard_aux_tail(kind, g_eq, h_eq, aux)
        secondary_tail = None
        secondary_state = None
        if tail is None:
            secondary_tail, secondary_state = secondary_bridge_attempt(h_eq, g_eq, aux, kind, deadline)
        grounded_tail = None
        grounded_state = None
        if tail is None and secondary_tail is None:
            grounded_tail, grounded_state = grounded_assumption_grind_body(h_eq, g_eq, [aux])
        built_tail = tail or secondary_tail or grounded_tail
        attempts.append({'kind': kind, 'status': 'grounded_candidate_built' if grounded_tail else 'proved' if built_tail else 'proved_not_consumed', 'equation': eq['text'], 'attempt_budget': round(attempt_budget, 3), 'budget_clock': 'cpu_with_wall_cap' if cpu_budgeted else 'wall', 'implied_by_scout': kind in implied_kinds, 'proof_state': proof_state, 'consume_state': consume_state, 'secondary_state': secondary_state, 'grounded_state': grounded_state})
        if built_tail:
            body = '\n'.join([f'have {kind} : {lemma_statement(eq)} := by', indent(proof_body, 2), built_tail])
            return (body, {'kind': 'StandardAuxSuperpositionState', 'status': 'body_built', 'used_aux': kind, 'implied_aux': implied_kinds, 'used_secondary_bridge': secondary_state.get('bridge') if isinstance(secondary_state, dict) else None, 'used_grounded_consumer': grounded_tail is not None, 'attempts': attempts})
    need_hint = None
    for attempt in attempts:
        states = []
        if attempt.get('status') == 'proved_not_consumed':
            states = [attempt.get('secondary_state'), attempt.get('consume_state'), attempt.get('proof_state')]
        else:
            states = [attempt.get('proof_state'), attempt.get('consume_state')]
        for state in states:
            if isinstance(state, dict) and state.get('need_hint'):
                if attempt.get('status') == 'proved_not_consumed':
                    need_hint = {'kind': 'standard_aux_followup', 'proved_aux': attempt.get('kind'), 'proved_aux_equation': attempt.get('equation'), 'reason': 'The auxiliary lemma was proved from H, but the goal did not close with current bounded consumers.', 'next': state.get('need_hint')}
                else:
                    need_hint = state.get('need_hint')
                break
        if need_hint is not None:
            break
    return (None, {'kind': 'StandardAuxSuperpositionState', 'status': 'stuck', 'attempted_aux': kinds, 'implied_aux': implied_kinds, 'attempts': attempts[:5], 'need_hint': need_hint or {'kind': 'standard_aux_failed', 'reason': 'No standard auxiliary lemma was both proved from H and useful for the goal.', 'next_action': 'Propose a custom midpoint/lemma_chain or try a different tool.'}})

def rigidity_collapse_portfolio_attempt(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any] | None=None) -> tuple[str | None, dict[str, Any]]:
    call = call or {}
    total_wall_budget = float(call.get('budget') or call.get('time_budget') or 60.0)
    started = time.monotonic()
    cpu_started = time.process_time()
    deadline = started + max(1.0, total_wall_budget)
    family_states: list[dict[str, Any]] = []
    ranked: list[tuple[int, str]] = []
    seeded_square: dict[str, Any] | None = None
    aux_entry_state: dict[str, Any] | None = None
    square_spec, aux_spec = RIGIDITY_COLLAPSE_FAMILIES
    square_eq = parse_equation(str(square_spec['entry_equation']))
    remaining = deadline - time.monotonic()
    if remaining > 1.0:
        entry_started = time.monotonic()
        square_body, square_state = prove_with_assumptions_detailed(h_eq, square_eq, superposition_budget=float(square_spec['entry_cpu_budget']), superposition_cpu_budgeted=True, superposition_wall_budget=remaining)
        square_row = {'family': square_spec['name'], 'entry_equation': square_eq['text'], 'entry_status': 'proved' if square_body else 'stuck', 'entry_elapsed_seconds': round(time.monotonic() - entry_started, 3), 'entry_state': compact_proof_state(square_state)}
        family_states.append(square_row)
        if square_body:
            ranked.append((3, str(square_spec['name'])))
            seeded_square = {'equation': square_eq['text'], 'proof_body': square_body, 'proof_state': square_state}
    remaining = deadline - time.monotonic()
    if remaining > 1.0:
        entry_started = time.monotonic()
        aux_body, aux_entry_state = standard_aux_superposition_attempt(h_eq, g_eq, {'lemmas': ['const'], 'budget': float(aux_spec['entry_cpu_budget']), 'wall_budget': remaining, 'cpu_budgeted': True})
        frontier = latest_midpoint_recommendation([aux_entry_state])
        frontier_advice = None
        if frontier is not None:
            frontier_advice, _directive = frontier_prompt_advice(frontier, h_eq)
        frontier_supported = bool(isinstance(frontier_advice, dict) and frontier_advice.get('kind') == 'proof_carrying_collapse_ladder_recommendation')
        aux_row = {'family': aux_spec['name'], 'entry_equation': aux_spec['entry_equation'], 'entry_status': 'proved' if aux_body else 'frontier_supported' if frontier_supported else 'stuck', 'entry_elapsed_seconds': round(time.monotonic() - entry_started, 3), 'entry_state': compact_proof_state(aux_entry_state), 'frontier_advice': frontier_advice}
        family_states.append(aux_row)
        if aux_body:
            return (aux_body, protocol_state('RigidityCollapsePortfolioState', 'body_built', 'rigidity_collapse_portfolio', winning_family=aux_spec['name'], family_states=family_states, elapsed_seconds=round(time.monotonic() - started, 3), cpu_seconds=round(time.process_time() - cpu_started, 3)))
        if frontier_supported:
            ranked.append((2, str(aux_spec['name'])))
    ranked.sort(reverse=True)
    continuation_states: list[dict[str, Any]] = []
    for _score, family_name in ranked:
        remaining = deadline - time.monotonic()
        if remaining <= 1.0:
            break
        if family_name == square_spec['name'] and seeded_square is not None:
            body, state = rigidity_collapse_ladder_attempt(h_eq, g_eq, {'budget': remaining, 'cpu_budgeted': True, '_seeded_entry': seeded_square})
        elif family_name == aux_spec['name'] and aux_entry_state is not None:
            body, state = standard_aux_superposition_attempt(h_eq, g_eq, {'lemmas': ['const'], 'budget': float(aux_spec['renewal_cpu_budget']), 'wall_budget': remaining, 'cpu_budgeted': True})
        else:
            continue
        continuation_states.append({'family': family_name, 'status': 'body_built' if body else 'stuck', 'state': state})
        if body:
            return (body, protocol_state('RigidityCollapsePortfolioState', 'body_built', 'rigidity_collapse_portfolio', winning_family=family_name, family_states=family_states, continuations=continuation_states, elapsed_seconds=round(time.monotonic() - started, 3), cpu_seconds=round(time.process_time() - cpu_started, 3), trust_boundary='The no-small-model signal only schedules the portfolio; the winning collapse family is fully represented in the Lean body.'))
    return (None, protocol_state('RigidityCollapsePortfolioState', 'stuck', 'rigidity_collapse_portfolio', family_states=family_states, ranked_families=[name for _score, name in ranked], continuations=continuation_states, elapsed_seconds=round(time.monotonic() - started, 3), cpu_seconds=round(time.process_time() - cpu_started, 3), need_hint={'kind': 'collapse_portfolio_exhausted', 'reason': 'No registered collapse family produced a complete proof-carrying certificate within its CPU/work lease and the global wall cap.', 'next_action': 'Propose a new first rung from the strongest family frontier; keep proved rungs and do not infer truth from the rigidity signal.'}))

def native_deep_true_candidates(h_eq: dict[str, Any], g_eq: dict[str, Any], budget: float):
    deadline = time.monotonic() + max(1.0, budget)
    for route, body in collapse_certificate_bodies(h_eq, g_eq):
        if time.monotonic() >= deadline:
            return
        yield (route, body, {'family': 'collapse_certificates'})
    for route, body in grounding_h_certificate_bodies(h_eq, g_eq):
        if time.monotonic() >= deadline:
            return
        yield (route, body, {'family': 'grounding_h'})
    remaining = deadline - time.monotonic()
    if remaining > 1.0:
        body, state = broad_grounding_derived_body(h_eq, g_eq, budget=min(12.0, max(1.0, remaining * 0.45)))
        if body:
            yield ('broad_grounding_derived', body, state)
    remaining = deadline - time.monotonic()
    if remaining > 1.0:
        body, state = standard_aux_superposition_attempt(h_eq, g_eq, {'lemmas': ['const', 'proj_l', 'proj_r', 'rowconst'], 'budget': min(12.0, max(1.0, remaining * 0.35))})
        if body:
            yield ('standard_aux_superposition', body, state)
    for route, body in native_saturation_bodies(h_eq, g_eq):
        if time.monotonic() >= deadline:
            return
        yield (route, body, {'family': 'deep_saturation'})
    remaining = deadline - time.monotonic()
    if remaining > 1.0:
        body, state = superposition_prove_detailed(h_eq, g_eq, budget=min(12.0, max(1.0, remaining)), allow_var_overlap=True)
        if body:
            yield ('goal_superposition:overlap', body, state)

def prove_with_assumptions_detailed(h_eq: dict[str, Any], target_eq: dict[str, Any], assumptions: list[UniversalEquation] | None=None, *, extra_h_args: list[tuple[str, ...]] | None=None, superposition_budget: float=5.0, superposition_cpu_budgeted: bool=False, superposition_wall_budget: float | None=None) -> tuple[str | None, dict[str, Any]]:
    last_state: dict[str, Any] | None = None
    tiers = [(48, 96, 0), (64, 128, 600), (80, 180, 1600)]
    if assumptions:
        tiers.append((140, 320, 4000))
    for h_limit, lemma_limit, congruence_cap in tiers:
        body = h_graph_body(h_eq, target_eq, h_limit, lemmas=[assumption.as_lemma() for assumption in assumptions or []], lemma_limit=lemma_limit, congruence_cap=congruence_cap, extra_args=extra_h_args)
        state = graph_search_state(h_eq, target_eq, assumptions, h_limit=h_limit, lemma_limit=lemma_limit, congruence_cap=congruence_cap, extra_args=extra_h_args, status='proved' if body else 'stuck')
        if body:
            return (body, state)
        last_state = state
    pc_body, pc_state = superposition_prove_detailed(h_eq, target_eq, assumptions, budget=superposition_budget, cpu_budgeted=superposition_cpu_budgeted, wall_budget=superposition_wall_budget)
    if pc_body is None and (assumptions or target_aux_shape(target_eq)):
        overlap_budget = max(1.0, min(3.0, superposition_budget / 3.0))
        pc_body, pc_state = superposition_prove_detailed(h_eq, target_eq, assumptions, budget=overlap_budget, allow_var_overlap=True, cpu_budgeted=superposition_cpu_budgeted, wall_budget=superposition_wall_budget)
    if pc_body:
        return (pc_body, pc_state)
    if last_state is not None:
        last_state = dict(last_state)
        last_state['superposition_state'] = pc_state
        last_state['need_hint'] = pc_state.get('need_hint') or last_state.get('need_hint')
        return (None, last_state)
    return (None, last_state or {'kind': 'SearchState', 'status': 'stuck', 'target': target_eq['text']})

def prove_with_assumptions(h_eq: dict[str, Any], target_eq: dict[str, Any], assumptions: list[UniversalEquation] | None=None) -> str | None:
    body, _state = prove_with_assumptions_detailed(h_eq, target_eq, assumptions)
    return body

def midpoint_progress_signal(state: dict[str, Any] | None) -> float:
    source = state if isinstance(state, dict) else {}
    score = 0.0
    if source.get('closest_pairs'):
        score += 0.2
    if source.get('suggested_next_actions') or source.get('need_hint'):
        score += 0.1
    superposition = source.get('superposition_state')
    if isinstance(superposition, dict):
        if superposition.get('derived_closest_equations'):
            score += 0.35
        if superposition.get('shape_diagnostics'):
            score += 0.2
        if superposition.get('stop_reason') not in {None, 'time_budget'}:
            score += 0.05
    return min(1.0, score)

def generic_midpoint_chain_attempt(h_eq: dict[str, Any], g_eq: dict[str, Any], hints: list[UniversalEquation], *, budget_policy: dict[str, Any] | MidpointBudgetPolicy | None=None, total_budget: float | None=None, ordered_chain: bool=False) -> tuple[str | None, dict[str, Any]]:
    limited_hints = hints[:10]
    if isinstance(budget_policy, MidpointBudgetPolicy):
        policy = budget_policy
    else:
        raw_policy = dict(budget_policy) if isinstance(budget_policy, dict) else {}
        if ordered_chain:
            total_hint = raw_policy.get('total_budget', raw_policy.get('total', total_budget))
            default_total = max(10.0, 10.0 * (max(1, min(5, len(limited_hints))) + 1))
            chain_total = _clamped_float(total_hint, default_total, 1.0, 600.0)
            first_pass_grant = chain_total / max(2, len(limited_hints) + 1)
            raw_policy.setdefault('initial_grant', min(8.0, first_pass_grant))
            raw_policy.setdefault('max_grant', 12.0)
            raw_policy.setdefault('max_grants_per_task', 2)
        policy = MidpointBudgetPolicy.from_mapping(raw_policy, candidate_count=len(limited_hints), requested_total=total_budget)
    broker = RenewableBudgetBroker(policy)
    proof_lines: list[str] = []
    proved: list[UniversalEquation] = []
    proved_indices: set[int] = set()
    failed: list[dict[str, Any]] = []
    candidate_statuses: list[dict[str, Any]] = []
    candidates: dict[int, dict[str, Any]] = {}
    for index, hint in enumerate(limited_hints):
        same_as_goal = hint.eq['lhs'] == g_eq['lhs'] and hint.eq['rhs'] == g_eq['rhs'] or (hint.eq['lhs'] == g_eq['rhs'] and hint.eq['rhs'] == g_eq['lhs'])
        if same_as_goal:
            failed.append({'stage': 'goal_as_midpoint', 'name': hint.name, 'equation': hint.eq['text'], 'failure': {'reason': 'The proposed midpoint is the goal itself, so it does not split H=>G into easier subgoals.', 'repair': 'Return a smaller reusable helper equation or a false_model_search route instead.'}})
            candidate_statuses.append({'name': hint.name, 'equation': hint.eq['text'], 'status': 'invalid_goal_repetition', 'variant_kind': hint.variant_kind, 'leg_1': {'status': 'not_attempted'}, 'leg_2': {'status': 'same_as_original_goal'}, 'need_hint': 'Generalize or shrink the goal into a reusable bridge.'})
            continue
        refutation = hint_refutation(h_eq, hint.eq)
        if refutation is not None:
            failed.append({'stage': 'plausibility_filter', 'name': hint.name, 'equation': hint.eq['text'], 'failure': refutation})
            candidate_statuses.append({'name': hint.name, 'equation': hint.eq['text'], 'status': 'counterexample_found', 'variant_kind': hint.variant_kind, 'leg_1': {'status': 'counterexample_found', 'carrier_size': refutation.get('n')}, 'leg_2': {'status': 'not_attempted'}, 'need_hint': 'Replace this equation; a checked model of H refutes it.'})
            continue
        relevance = min(1.0, max(0.0, float(-hint_score(hint, g_eq)[0])) / 24.0)
        reusable = 1.0 if helper_kind(hint.eq['text']) else 0.0
        common_score = policy.relevance_weight * relevance + policy.reuse_weight * reusable
        candidates[index] = {'index': index, 'hint': hint, 'relevance': relevance, 'reusable': reusable, 'proof_body': None, 'proof_state': None, 'consume_body': None, 'consume_state': None, 'variant_kind': hint.variant_kind, 'origin_signature': hint.origin_signature}
        metadata = {'candidate_index': index, 'candidate': hint.name, 'equation': hint.eq['text']}
        broker.register(f'candidate:{index}:consume', base_score=policy.consume_priority + common_score, metadata={**metadata, 'leg': 'consume'}, enabled=not ordered_chain)
        broker.register(f'candidate:{index}:attain', base_score=policy.attain_priority + common_score, metadata={**metadata, 'leg': 'attain'}, enabled=not ordered_chain)
    if ordered_chain and candidates:
        broker.update(f'candidate:{min(candidates)}:attain', enabled=True)
    broker.register('root:consume', base_score=policy.goal_priority, metadata={'candidate': 'root', 'leg': 'consume_proved_set'}, enabled=False)
    solution_body: str | None = None
    last_goal_state: dict[str, Any] | None = None
    while solution_body is None:
        lease = broker.next_grant()
        if lease is None:
            break
        task, grant = lease
        started = time.monotonic()
        leg = task.metadata.get('leg')
        index = task.metadata.get('candidate_index')
        candidate = candidates.get(index) if isinstance(index, int) else None
        body: str | None = None
        state: dict[str, Any] = {}
        if leg == 'attain' and candidate is not None:
            hint = candidate['hint']
            body, state = prove_with_assumptions_detailed(h_eq, hint.eq, list(proved), extra_h_args=hint.proof_extra_args(), superposition_budget=grant)
            candidate['proof_state'] = state
            if body is not None and index not in proved_indices:
                candidate['proof_body'] = body
                proof_lines.append(f'have {hint.name} : {lemma_statement(hint.eq)} := by\n{indent(body, 2)}')
                proved.append(hint)
                proved_indices.add(index)
                broker.report(task.task_id, 'succeeded', progress=1.0, elapsed_seconds=time.monotonic() - started, detail={'proved_lemma': hint.name})
                broker.advance_context()
                if ordered_chain:
                    remaining = [i for i in sorted(candidates) if i not in proved_indices]
                    if remaining:
                        broker.update(f'candidate:{remaining[0]}:attain', enabled=True)
                    else:
                        broker.update('root:consume', enabled=True)
                else:
                    broker.update('root:consume', enabled=True)
                    broker.update(f'candidate:{index}:consume', companion_succeeded=True)
                    if candidate.get('consume_body'):
                        solution_body = '\n'.join([*proof_lines, candidate['consume_body']])
                continue
        elif leg == 'consume' and candidate is not None:
            hint = candidate['hint']
            assumptions = list(proved)
            if index not in proved_indices:
                assumptions.append(hint)
            body, state = prove_with_assumptions_detailed(h_eq, g_eq, assumptions, superposition_budget=grant)
            candidate['consume_state'] = state
            last_goal_state = state
            if body is not None:
                candidate['consume_body'] = body
                broker.report(task.task_id, 'succeeded', progress=1.0, elapsed_seconds=time.monotonic() - started, detail={'candidate_is_attained': index in proved_indices})
                broker.update(f'candidate:{index}:attain', companion_succeeded=True)
                if index in proved_indices:
                    solution_body = '\n'.join([*proof_lines, body])
                continue
        elif leg == 'consume_proved_set' and proved:
            body, state = prove_with_assumptions_detailed(h_eq, g_eq, list(proved), superposition_budget=grant)
            last_goal_state = state
            if body is not None:
                broker.report(task.task_id, 'succeeded', progress=1.0, elapsed_seconds=time.monotonic() - started, detail={'proved_lemma_count': len(proved)})
                solution_body = '\n'.join([*proof_lines, body])
                continue
        else:
            state = {'kind': 'BudgetTaskState', 'status': 'not_runnable', 'leg': leg}
        broker.report(task.task_id, 'retryable', progress=midpoint_progress_signal(state), elapsed_seconds=time.monotonic() - started, detail={'search_status': state.get('status'), 'stop_reason': (state.get('superposition_state') or {}).get('stop_reason') if isinstance(state.get('superposition_state'), dict) else None})
    for index, candidate in candidates.items():
        hint = candidate['hint']
        proof_state = candidate.get('proof_state') or {'kind': 'SearchState', 'status': 'not_started_before_budget_exhausted'}
        consume_state = candidate.get('consume_state') or {'kind': 'SearchState', 'status': 'not_started_before_budget_exhausted'}
        proved_here = index in proved_indices
        consumed = bool(candidate.get('consume_body'))
        if proved_here and consumed:
            lifecycle_status = 'proved_and_helpful'
        elif proved_here:
            lifecycle_status = 'proved_but_not_connected'
        elif consumed:
            lifecycle_status = 'second_leg_proved_first_leg_unproved'
        else:
            lifecycle_status = 'unproved_with_budget'

        def compact_leg(state: dict[str, Any], status: str) -> dict[str, Any]:
            superposition = state.get('superposition_state')
            need_hint = state.get('need_hint')
            if need_hint is None and isinstance(superposition, dict):
                need_hint = superposition.get('need_hint')
            out = {'status': status, 'search_status': state.get('status')}
            if need_hint is not None and status != 'proved':
                out['need_hint'] = need_hint
            closest = state.get('closest_pairs')
            if status != 'proved' and isinstance(closest, list) and closest:
                out['closest_pairs'] = closest[:2]
            return out
        leg_1 = compact_leg(proof_state, 'proved' if proved_here else 'unproved_with_budget')
        leg_2 = compact_leg(consume_state, 'proved' if consumed else 'stuck')
        need_hint = leg_2.get('need_hint') if proved_here else leg_1.get('need_hint')
        candidate_statuses.append({'name': hint.name, 'equation': hint.eq['text'], 'status': lifecycle_status, 'variant_kind': candidate.get('variant_kind'), 'origin_signature': candidate.get('origin_signature'), 'leg_1': leg_1, 'leg_2': leg_2, 'need_hint': need_hint})
        if not proved_here:
            failed.append({'stage': 'prove_midpoint', 'name': hint.name, 'equation': hint.eq['text'], 'search_state': proof_state})
    summary: dict[str, Any] = {'protocol_version': PROTOCOL_VERSION, 'kind': 'midpoint_chain_attempt', 'status': 'stuck', 'source': 'generic_midpoint_chain', 'ordered_chain': ordered_chain, 'proposed_lemmas': [{'name': hint.name, 'equation': hint.eq['text'], 'score': -hint_score(hint, g_eq)[0]} for hint in limited_hints], 'proved_lemmas': [{'name': hint.name, 'equation': hint.eq['text']} for hint in proved], 'candidate_statuses': candidate_statuses, 'failed_midpoints': failed[:3], 'budget_allocation': broker.snapshot()}
    if not hints:
        summary['status'] = 'no_parseable_midpoints'
        summary['need_hint'] = {'kind': 'midpoint', 'reason': 'return one small universal equation, e.g. a ◇ b = b'}
        summary['suggested_next_actions'] = [{'kind': 'midpoint', 'lemma': 'a ◇ b = b', 'why': 'example shape only; replace with a problem-specific bridge'}]
        return (None, summary)
    if not proved:
        summary['status'] = 'no_midpoint_proved'
        bridge_failures = [item for item in failed if 'search_state' in item]
        goal_as_midpoint_failures = [item for item in failed if item.get('stage') == 'goal_as_midpoint']
        if goal_as_midpoint_failures:
            summary['need_hint'] = {'kind': 'replace_goal_as_midpoint', 'reason': 'The proposed midpoint repeated the target goal and did not reduce the proof obligation.', 'bad_midpoint': goal_as_midpoint_failures[0].get('equation'), 'next_action': 'Propose a smaller universal midpoint/lemma_chain that would imply the goal, or switch to a concrete false_model_search route.'}
        elif bridge_failures:
            summary['need_hint'] = bridge_failures[0]['search_state'].get('need_hint')
        elif failed:
            summary['need_hint'] = {'kind': 'replace_midpoint', 'reason': 'proposed midpoint was refuted by a small model of H'}
        if summary.get('need_hint'):
            summary['suggested_next_actions'] = [summary['need_hint']]
        return (None, summary)
    if solution_body is None:
        summary['status'] = 'proved_midpoints_not_consumed'
        goal_state = last_goal_state or {'kind': 'SearchState', 'status': 'budget_exhausted', 'need_hint': 'The shared midpoint budget was exhausted before a proved helper set closed the goal.'}
        summary['goal_search_state'] = goal_state
        summary['need_hint'] = goal_state.get('need_hint')
        if goal_state.get('suggested_next_actions'):
            summary['suggested_next_actions'] = goal_state.get('suggested_next_actions')
        return (None, summary)
    summary['status'] = 'body_built'
    summary['goal_search_state'] = last_goal_state
    return (solution_body, summary)

def generic_midpoint_chain_body(h_eq: dict[str, Any], g_eq: dict[str, Any], hints: list[UniversalEquation]) -> str | None:
    body, _state = generic_midpoint_chain_attempt(h_eq, g_eq, hints, ordered_chain=True)
    return body

def hint_payload_attempt(payload: dict[str, Any], h_eq: dict[str, Any], g_eq: dict[str, Any], *, capability_mask: Any=None) -> tuple[str | None, dict[str, Any]]:
    ordered_chain = payload.get('_ordered_chain')
    if ordered_chain is None:
        action_kind = payload.get('tool') if payload.get('kind') == 'tool_call' else payload.get('kind')
        ordered_chain = action_kind in {'midpoint_chain', 'lemma_chain'}
    hints = parse_universal_equations(payload)
    if not payload.get('_variants_expanded') and (not ordered_chain):
        hints = expand_hint_variants(hints, g_eq)
    hints = ordered_hints_for_payload(payload, hints, g_eq)
    body, state = generic_midpoint_chain_attempt(h_eq, g_eq, hints, budget_policy=payload.get('budget_policy'), total_budget=payload.get('budget') or payload.get('time_budget'), ordered_chain=bool(ordered_chain))
    if body:
        return (body, state)
    kinds = {helper_kind(hint.eq['text']) for hint in hints}
    focused_fallbacks_withheld: list[str] = []
    right_square_gate = capability_gate_state('right_square_chain', capability_mask)
    if {'square_absorb', 'right_square'} <= kinds and right_square_gate is None:
        body = generic_right_square_chain_body(h_eq, g_eq)
        if body:
            state['status'] = 'body_built_by_focused_right_square_fallback'
            return (body, state)
    elif {'square_absorb', 'right_square'} <= kinds:
        focused_fallbacks_withheld.append('tool:right_square_chain')
    square_sandwich_gate = capability_gate_state('square_sandwich_chain', capability_mask)
    if {'square_const', 'right_id_square', 'sandwich'} <= kinds and square_sandwich_gate is None:
        body = square_sandwich_chain_body(h_eq, g_eq)
        if body:
            state['status'] = 'body_built_by_focused_square_sandwich_fallback'
            return (body, state)
    elif {'square_const', 'right_id_square', 'sandwich'} <= kinds:
        focused_fallbacks_withheld.append('tool:square_sandwich_chain')
    if focused_fallbacks_withheld:
        state['focused_fallbacks_withheld'] = focused_fallbacks_withheld
    return (None, state)

def body_from_hint_payload(payload: dict[str, Any], h_eq: dict[str, Any], g_eq: dict[str, Any], *, capability_mask: Any=None) -> str | None:
    body, _state = hint_payload_attempt(payload, h_eq, g_eq, capability_mask=capability_mask)
    return body

def op(left: Term, right: Term) -> Term:
    return ('op', left, right)

def sq(t: Term) -> Term:
    return ('op', t, t)

def is_square(t: Term):
    return t[1] if t[0] == 'op' and t[1] == t[2] else None

def right_square_h_roles(h_eq: dict[str, Any]) -> dict[str, Any] | None:
    for reversed_eq, lone, body in ((False, h_eq['lhs'], h_eq['rhs']), (True, h_eq['rhs'], h_eq['lhs'])):
        if lone[0] != 'var' or body[0] != 'op':
            continue
        x = lone[1]
        if body[2] != sq(('var', x)):
            continue
        left = body[1]
        if left[0] != 'op' or left[1][0] != 'var' or left[2][0] != 'op':
            continue
        y = left[1][1]
        yz = left[2]
        if yz[1] != ('var', y) or yz[2][0] != 'var':
            continue
        z = yz[2][1]
        if len({x, y, z}) == 3:
            return {'x': x, 'y': y, 'z': z, 'reversed': reversed_eq}
    return None

def right_square_goal_roles(g_eq: dict[str, Any]) -> dict[str, Any] | None:
    for reversed_eq, lone, body in ((False, g_eq['lhs'], g_eq['rhs']), (True, g_eq['rhs'], g_eq['lhs'])):
        if lone[0] != 'var' or body[0] != 'op' or body[1] != lone:
            continue
        inner = body[2]
        if inner[0] != 'op' or inner[2] != lone or inner[1][0] != 'op':
            continue
        b = inner[1][1]
        if inner[1][2] != op(lone, b):
            continue
        return {'x': term_to_str(lone), 'b': term_to_str(b), 'reversed': reversed_eq}
    return None

def right_square_helper_lines(h_eq: dict[str, Any]) -> list[str] | None:
    roles = right_square_h_roles(h_eq)
    if roles is None:
        return None
    hx, hy, hz = (roles['x'], roles['y'], roles['z'])

    def h_call(x: str, y: str, z: str) -> str:
        mp = {hx: x, hy: y, hz: z}
        proof = 'h ' + ' '.join((lean_arg(mp[v]) for v in h_eq['variables']))
        return f'({proof}).symm' if roles['reversed'] else proof
    return ['have E4 : ∀ (v0 v1 v2 v3 v4 : G), ((v0 ◇ (v0 ◇ v1)) ◇ ((v2 ◇ (v2 ◇ v3)) ◇ ((v4 ◇ v4) ◇ (v4 ◇ v4)))) = v4 := by', '  intro v0 v1 v2 v3 v4', f"  have ia : v4 = ((v0 ◇ (v0 ◇ v1)) ◇ (v4 ◇ v4)) := {h_call('v4', 'v0', 'v1')}", f"  have ib : (v4 ◇ v4) = ((v2 ◇ (v2 ◇ v3)) ◇ ((v4 ◇ v4) ◇ (v4 ◇ v4))) := {h_call('(v4 ◇ v4)', 'v2', 'v3')}", '  have ic : ((v0 ◇ (v0 ◇ v1)) ◇ (v4 ◇ v4)) = ((v0 ◇ (v0 ◇ v1)) ◇ ((v2 ◇ (v2 ◇ v3)) ◇ ((v4 ◇ v4) ◇ (v4 ◇ v4)))) := congrArg (fun t => ((v0 ◇ (v0 ◇ v1)) ◇ t)) ib', '  exact (ia.trans ic).symm', 'have raw_square_absorb : ∀ (v0 v1 v2 v3 : G), (v0 ◇ (v1 ◇ v1)) = v1 := by', '  intro v0 v1 v2 v3', f"  have ia : v1 = (((v2 ◇ (v2 ◇ v3)) ◇ ((v2 ◇ (v2 ◇ v3)) ◇ ((v0 ◇ v0) ◇ (v0 ◇ v0)))) ◇ (v1 ◇ v1)) := {h_call('v1', '(v2 ◇ (v2 ◇ v3))', '((v0 ◇ v0) ◇ (v0 ◇ v0))')}", '  have ib : ((v2 ◇ (v2 ◇ v3)) ◇ ((v2 ◇ (v2 ◇ v3)) ◇ ((v0 ◇ v0) ◇ (v0 ◇ v0)))) = v0 := E4 v2 v3 v2 v3 v0', '  have ic : (((v2 ◇ (v2 ◇ v3)) ◇ ((v2 ◇ (v2 ◇ v3)) ◇ ((v0 ◇ v0) ◇ (v0 ◇ v0)))) ◇ (v1 ◇ v1)) = (v0 ◇ (v1 ◇ v1)) := congrArg (fun t => t ◇ (v1 ◇ v1)) ib', '  exact (ia.trans ic).symm', 'have square_absorb : ∀ (v0 v1 : G), (v0 ◇ (v1 ◇ v1)) = v1 := by', '  intro v0 v1', '  exact raw_square_absorb v0 v1 v0 v0', 'have raw_right_square : ∀ (v0 v1 v2 v3 v4 v5 : G), (v0 ◇ v1) = (v1 ◇ v1) := by', '  intro v0 v1 v2 v3 v4 v5', '  have ia : v0 ◇ ((v1 ◇ v1) ◇ (v1 ◇ v1)) = (v1 ◇ v1) := square_absorb v0 (v1 ◇ v1)', '  have ib : ((v1 ◇ v1) ◇ (v1 ◇ v1)) = v1 := square_absorb (v1 ◇ v1) v1', '  have ic : v0 ◇ ((v1 ◇ v1) ◇ (v1 ◇ v1)) = v0 ◇ v1 := congrArg (fun t => v0 ◇ t) ib', '  exact ic.symm.trans ia', 'have right_square : ∀ (v0 v1 : G), (v0 ◇ v1) = (v1 ◇ v1) := by', '  intro v0 v1', '  exact raw_right_square v0 v1 v0 v0 v0 v0']

def right_square_chain_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    helper = right_square_helper_lines(h_eq)
    goal = right_square_goal_roles(g_eq)
    if helper is None or goal is None:
        return None
    x, y = (goal['x'], goal['b'])
    xy = f'({x} ◇ {y})'
    yxy = f'({y} ◇ {xy})'
    inner = f'({yxy} ◇ {x})'
    used_names = set(h_eq['variables']) | set(g_eq['variables']) | {'h'}

    def fresh(base: str) -> str:
        candidate = base
        while candidate in used_names:
            candidate += '_'
        used_names.add(candidate)
        return candidate
    eq1 = fresh('rs_eq1')
    eq2 = fresh('rs_eq2')
    eq3 = fresh('rs_eq3')
    eq4 = fresh('rs_eq4')
    bridge_left = fresh('rs_bridge_left')
    bridge_right = fresh('rs_bridge_right')
    lines = ['intro ' + ' '.join(g_eq['variables'])] + helper + [f'have {eq1} : {yxy} = ({xy} ◇ {xy}) := right_square {y} {xy}', f'have {eq2} : {inner} = ({x} ◇ {x}) := by', f'  have {bridge_left} : {inner} = (({xy} ◇ {xy}) ◇ {x}) := congrArg (fun t => t ◇ {x}) {eq1}', f'  have {bridge_right} : (({xy} ◇ {xy}) ◇ {x}) = ({x} ◇ {x}) := right_square ({xy} ◇ {xy}) {x}', f'  exact {bridge_left}.trans {bridge_right}', f'have {eq3} : {x} ◇ {inner} = {x} ◇ ({x} ◇ {x}) := congrArg (fun u => {x} ◇ u) {eq2}', f'have {eq4} : {x} ◇ ({x} ◇ {x}) = {x} := square_absorb {x} {x}', f'exact {eq3}.trans {eq4}' if goal['reversed'] else f'exact ({eq3}.trans {eq4}).symm']
    return '\n'.join(lines)

def generic_right_square_chain_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    helper = right_square_helper_lines(h_eq)
    if helper is None:
        return None
    lemmas = [{'name': 'square_absorb', 'eq': parse_equation('u ◇ (v ◇ v) = v')}, {'name': 'right_square', 'eq': parse_equation('u ◇ v = v ◇ v')}]
    goal_body = h_graph_body(h_eq, g_eq, 64, lemmas=lemmas, lemma_limit=160, congruence_cap=1600)
    if goal_body is None:
        return None
    parts = goal_body.splitlines()
    if parts and parts[0].startswith('intro '):
        return '\n'.join([parts[0], *helper, *parts[1:]])
    return '\n'.join(helper + [goal_body])

def square_sandwich_h_roles(h_eq: dict[str, Any]) -> dict[str, Any] | None:
    for reversed_eq, lone, body in ((False, h_eq['lhs'], h_eq['rhs']), (True, h_eq['rhs'], h_eq['lhs'])):
        if lone[0] != 'var' or body[0] != 'op':
            continue
        x = lone[1]
        left, square = (body[1], body[2])
        if left[0] != 'op' or square[0] != 'op':
            continue
        yx, y2 = (left[1], left[2])
        if yx[0] != 'op' or yx[1][0] != 'var' or yx[2] != ('var', x) or (y2[0] != 'var'):
            continue
        y = yx[1][1]
        if y2[1] != y or square[1][0] != 'var' or square[2] != square[1]:
            continue
        z = square[1][1]
        if len({x, y, z}) == 3:
            return {'x': x, 'y': y, 'z': z, 'reversed': reversed_eq}
    return None

def square_sandwich_helper_lines(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> list[str] | None:
    roles = square_sandwich_h_roles(h_eq)
    if roles is None or not g_eq['variables']:
        return None
    hx, hy, hz = (roles['x'], roles['y'], roles['z'])

    def h_call(x: str, y: str, z: str) -> str:
        mp = {hx: x, hy: y, hz: z}
        proof = 'h ' + ' '.join((lean_arg(mp[v]) for v in h_eq['variables']))
        return f'({proof}).symm' if roles['reversed'] else proof
    return ['intro ' + ' '.join(g_eq['variables']), 'have square_const : ∀ v w : G, v ◇ v = w ◇ w := by', '  intro v w', '  let A : G := (v ◇ (v ◇ v)) ◇ v', '  have hvA : v ◇ v = A ◇ (v ◇ v) := by', f"    simpa [A] using {h_call('v ◇ v', 'v', 'v')}", '  have hwA : v ◇ v = A ◇ (w ◇ w) := by', f"    simpa [A] using {h_call('v ◇ v', 'v', 'w')}", '  have ev : v ◇ v = ((v ◇ v) ◇ A) ◇ (v ◇ v) := by', '    calc', f"      v ◇ v = ((A ◇ (v ◇ v)) ◇ A) ◇ (v ◇ v) := {h_call('v ◇ v', 'A', 'v')}", '      _ = ((v ◇ v) ◇ A) ◇ (v ◇ v) := by rw [← hvA]', '  have ew : w ◇ w = ((v ◇ v) ◇ A) ◇ (v ◇ v) := by', '    calc', f"      w ◇ w = ((A ◇ (w ◇ w)) ◇ A) ◇ (v ◇ v) := {h_call('w ◇ w', 'A', 'v')}", '      _ = ((v ◇ v) ◇ A) ◇ (v ◇ v) := by rw [← hwA]', '  exact ev.trans ew.symm', 'have right_id_square : ∀ a b : G, a ◇ (b ◇ b) = a := by', '  intro a b', '  have sqv : a ◇ a = b ◇ b := square_const a b', '  have step1 : ((b ◇ b) ◇ a) ◇ (b ◇ b) = a := by', '    calc', '      ((b ◇ b) ◇ a) ◇ (b ◇ b) = ((a ◇ a) ◇ a) ◇ (b ◇ b) := by rw [← sqv]', f"      _ = a := ({h_call('a', 'a', 'b')}).symm", '  have step2 : a = a ◇ (b ◇ b) := by', '    calc', f"      a = (((b ◇ b) ◇ a) ◇ (b ◇ b)) ◇ (b ◇ b) := {h_call('a', 'b ◇ b', 'b')}", '      _ = a ◇ (b ◇ b) := by rw [step1]', '  exact step2.symm', 'have sandwich : ∀ a b : G, (b ◇ a) ◇ b = a := by', '  intro a b', '  calc', '    (b ◇ a) ◇ b = ((b ◇ a) ◇ b) ◇ (a ◇ a) := (right_id_square ((b ◇ a) ◇ b) a).symm', f"    _ = a := ({h_call('a', 'b', 'a')}).symm", 'have left_sandwich : ∀ a b : G, b ◇ (a ◇ b) = a := by', '  intro a b', '  have d_eq_a : (((a ◇ b) ◇ a) ◇ (a ◇ b)) = a := by', '    calc', '      (((a ◇ b) ◇ a) ◇ (a ◇ b)) = (((a ◇ b) ◇ a) ◇ (a ◇ b)) ◇ (a ◇ a) := (right_id_square (((a ◇ b) ◇ a) ◇ (a ◇ b)) a).symm', f"      _ = a := ({h_call('a', 'a ◇ b', 'a')}).symm", '  calc', '    b ◇ (a ◇ b) = (((a ◇ b) ◇ a) ◇ (a ◇ b)) := congrArg (fun u => u ◇ (a ◇ b)) (sandwich b a).symm', '    _ = a := d_eq_a']

class SquareReducer:

    def __init__(self, witness: str):
        self.witness_var = witness
        self.witness = sq(('var', witness))
        self.lines: list[str] = []
        self.count = 0

    def fresh(self) -> str:
        self.count += 1
        return f'sq_chain_{self.count}'

    def add_calc(self, start: Term, steps: list[tuple[Term, str]]) -> str:
        name = self.fresh()
        self.lines.append(f'have {name} : {term_to_str(start)} = {term_to_str(steps[-1][0])} := by')
        if len(steps) == 1:
            self.lines.append(f'  exact {steps[0][1]}')
        else:
            self.lines.append('  calc')
            for i, (to_term, proof) in enumerate(steps):
                self.lines.append(f"    {(term_to_str(start) if i == 0 else '_')} = {term_to_str(to_term)} := {proof}")
        return name

    def reduce(self, t: Term) -> tuple[Term, str | None]:
        if t[0] == 'var':
            return (t, None)
        ln, lp = self.reduce(t[1])
        rn, rp = self.reduce(t[2])
        cur = op(ln, rn)
        steps: list[tuple[Term, str]] = []
        if lp:
            steps.append((op(ln, t[2]), f'congrArg (fun u => u ◇ {term_to_str(t[2])}) {lp}'))
        if rp:
            steps.append((cur, f'congrArg (fun u => {term_to_str(ln)} ◇ u) {rp}'))
        while cur[0] == 'op':
            l, r = (cur[1], cur[2])
            if r[0] == 'op' and r[1] == r[2]:
                cur = l
                steps.append((cur, f'right_id_square {term_to_str(l)} {term_to_str(r[1])}'))
            elif l[0] == 'op' and l[1] == r:
                cur = l[2]
                steps.append((cur, f'sandwich {term_to_str(cur)} {term_to_str(r)}'))
            elif r[0] == 'op' and r[2] == l:
                cur = r[1]
                steps.append((cur, f'left_sandwich {term_to_str(cur)} {term_to_str(l)}'))
            else:
                base = is_square(cur)
                if base is not None and cur != self.witness:
                    cur = self.witness
                    steps.append((cur, f'square_const {term_to_str(base)} {self.witness_var}'))
                else:
                    break
        if not steps:
            return (t, None)
        return (cur, self.add_calc(t, steps))

def square_sandwich_chain_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    helper = square_sandwich_helper_lines(h_eq, g_eq)
    if helper is None:
        return None
    reducer = SquareReducer(g_eq['variables'][0])
    lhs_norm, lhs_pf = reducer.reduce(g_eq['lhs'])
    rhs_norm, rhs_pf = reducer.reduce(g_eq['rhs'])
    if lhs_norm != rhs_norm:
        return None
    lines = helper + reducer.lines
    if lhs_pf is None and rhs_pf is None:
        lines.append('rfl')
    elif lhs_pf is None:
        lines.append(f'exact {rhs_pf}.symm')
    elif rhs_pf is None:
        lines.append(f'exact {lhs_pf}')
    else:
        lines.append(f'exact {lhs_pf}.trans {rhs_pf}.symm')
    return '\n'.join(lines)

def rowconst_h_roles(h_eq: dict[str, Any]) -> dict[str, Any] | None:
    for reversed_eq, lhs, rhs in ((False, h_eq['lhs'], h_eq['rhs']), (True, h_eq['rhs'], h_eq['lhs'])):
        if lhs[0] != 'op' or rhs[0] != 'op':
            continue
        if lhs[1][0] != 'var' or lhs[2][0] != 'var' or rhs[1][0] != 'var':
            continue
        x, y = (lhs[1][1], lhs[2][1])
        if rhs[1][1] != y or rhs[2][0] != 'op' or rhs[2][1][0] != 'var' or (rhs[2][2][0] != 'op'):
            continue
        z = rhs[2][1][1]
        if rhs[2][2] != op(('var', y), ('var', z)):
            continue
        if len({x, y, z}) == 3:
            return {'x': x, 'y': y, 'z': z, 'reversed': reversed_eq}
    return None

def rowconst_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    roles = rowconst_h_roles(h_eq)
    if roles is None or g_eq['lhs'][0] != 'op' or g_eq['rhs'][0] != 'op':
        return None
    hx, hy, hz = (roles['x'], roles['y'], roles['z'])

    def h_call(x: str, y: str, z: str) -> str:
        mp = {hx: x, hy: y, hz: z}
        proof = 'h ' + ' '.join((lean_arg(mp[v]) for v in h_eq['variables']))
        return f'({proof}).symm' if roles['reversed'] else proof
    lhs_l, lhs_r = (term_to_str(g_eq['lhs'][1]), term_to_str(g_eq['lhs'][2]))
    rhs_l, rhs_r = (term_to_str(g_eq['rhs'][1]), term_to_str(g_eq['rhs'][2]))
    return '\n'.join(['intro ' + ' '.join(g_eq['variables']), 'have col : ∀ p q r : G, p ◇ q = r ◇ q := by', '  intro p q r', '  calc', f"    p ◇ q = q ◇ (q ◇ (q ◇ q)) := {h_call('p', 'q', 'q')}", f"    _ = r ◇ q := ({h_call('r', 'q', 'q')}).symm", 'have rowconst : ∀ a b c : G, a ◇ b = a ◇ c := by', '  intro a b c', '  have hbcc : b ◇ c = c ◇ c := col b c c', '  calc', f"    a ◇ b = b ◇ (c ◇ (b ◇ c)) := {h_call('a', 'b', 'c')}", '    _ = c ◇ (c ◇ (b ◇ c)) := col b (c ◇ (b ◇ c)) c', '    _ = c ◇ (c ◇ (c ◇ c)) := by exact congrArg (fun u => c ◇ (c ◇ u)) hbcc', f"    _ = a ◇ c := ({h_call('a', 'c', 'c')}).symm", 'calc', f"  {term_to_str(g_eq['lhs'])} = {rhs_l} ◇ {lhs_r} := col {lhs_l} {lhs_r} {rhs_l}", f"  _ = {term_to_str(g_eq['rhs'])} := rowconst {rhs_l} {lhs_r} {rhs_r}"])

def square_rowconst_h_roles(h_eq: dict[str, Any]) -> dict[str, Any] | None:
    for reversed_eq, lone, body in ((False, h_eq['lhs'], h_eq['rhs']), (True, h_eq['rhs'], h_eq['lhs'])):
        if lone[0] != 'var' or body[0] != 'op':
            continue
        x = lone[1]
        left, right = (body[1], body[2])
        if left != sq(('var', x)):
            continue
        if right[0] != 'op' or right[2][0] != 'var':
            continue
        yz = right[1]
        z = right[2][1]
        if yz[0] != 'op' or yz[1][0] != 'var' or yz[2] != ('var', z):
            continue
        y = yz[1][1]
        if len({x, y, z}) == 3:
            return {'x': x, 'y': y, 'z': z, 'reversed': reversed_eq}
    return None

def grounding_derived_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    roles = square_rowconst_h_roles(h_eq)
    if roles is None:
        return None
    hx, hy, hz = (roles['x'], roles['y'], roles['z'])
    goal_match = None
    for reversed_eq, lone, body in ((False, g_eq['lhs'], g_eq['rhs']), (True, g_eq['rhs'], g_eq['lhs'])):
        if lone[0] == 'var' and body[0] == 'op' and (body[1] == sq(lone)):
            goal_match = (reversed_eq, lone, body)
            break
    if goal_match is None:
        return None
    goal_reversed, lhs, rhs = goal_match
    goal_x = term_to_str(lhs)
    rhs_inner = term_to_str(rhs[2])
    rhs_s = term_to_str(rhs)
    xx = f'({goal_x} ◇ {goal_x})'
    xxx = f'(({goal_x} ◇ {goal_x}) ◇ {goal_x})'

    def h_call(x: str, y: str, z: str) -> str:
        mp = {hx: x, hy: y, hz: z}
        proof = 'h ' + ' '.join((lean_arg(mp[v]) for v in h_eq['variables']))
        return f'({proof}).symm' if roles['reversed'] else proof
    lines = []
    if g_eq['variables']:
        lines.append('intro ' + ' '.join(g_eq['variables']))
    if goal_reversed:
        lines.append('symm')
    lines.extend(['have E1 : ∀ v0 v1 v2 v3 : G, (v0 ◇ v0) ◇ (v1 ◇ ((v2 ◇ v3) ◇ v3)) = v0 := by', '  intro v0 v1 v2 v3', f"  have ia := {h_call('v0', '(v1 ◇ v1)', '((v2 ◇ v3) ◇ v3)')}", f"  have ib := {h_call('v1', 'v2', 'v3')}", '  calc', '    (v0 ◇ v0) ◇ (v1 ◇ ((v2 ◇ v3) ◇ v3)) = (v0 ◇ v0) ◇ (((v1 ◇ v1) ◇ ((v2 ◇ v3) ◇ v3)) ◇ ((v2 ◇ v3) ◇ v3)) := by', '      exact congrArg (fun u => (v0 ◇ v0) ◇ (u ◇ ((v2 ◇ v3) ◇ v3))) ib', '    _ = v0 := ia.symm', 'have E3 : ∀ v0 v1 v2 v3 : G, (v0 ◇ v0) ◇ v1 = v0 := by', '  intro v0 v1 v2 v3', '  have ia := E1 v0 (v1 ◇ v1) v2 v3', f"  have ib := {h_call('v1', 'v2', 'v3')}", '  calc', '    (v0 ◇ v0) ◇ v1 = (v0 ◇ v0) ◇ ((v1 ◇ v1) ◇ ((v2 ◇ v3) ◇ v3)) := by', '      exact congrArg (fun u => (v0 ◇ v0) ◇ u) ib', '    _ = v0 := ia', 'have target : ∀ a b : G, a ◇ b = a ◇ a := by', '  intro a b', '  have ia := E3 (a ◇ a) b a a', '  have ib := E3 a (a ◇ a) a a', '  have bridge : ((a ◇ a) ◇ (a ◇ a)) ◇ b = a ◇ b := by', '    exact congrArg (fun u => u ◇ b) ib', '  exact bridge.symm.trans ia', 'calc', f'  {goal_x} = {xx} ◇ {xxx} := {h_call(goal_x, goal_x, goal_x)}', f'  _ = {xx} ◇ {xx} := target {xx} {xxx}', f'  _ = {rhs_s} := (target {xx} {rhs_inner}).symm'])
    return '\n'.join(lines)

def battery_arg_layers(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> list[dict[str, Any]]:
    nargs = len(h_eq['variables'])
    if nargs == 0:
        return []
    pad = (g_eq['variables'] or ['x'])[0]
    terms = goal_terms(g_eq, 12)
    compounds = [term for term in terms if '◇' in term]
    diag = tuple([pad] * nargs)

    def slot(i: int, term_list: list[str]) -> list[tuple[str, ...]]:
        rows = []
        for term in term_list:
            args = [pad] * nargs
            if i < nargs:
                args[i] = term
            rows.append(tuple(args))
        return rows
    layers: list[dict[str, Any]] = [{'name': 'diag', 'args': [diag]}]
    slot0 = unique_arg_rows([diag] + slot(0, terms))
    layers.append({'name': 'slot0_terms', 'args': slot0})
    slot1 = unique_arg_rows(slot0 + slot(1, compounds))
    layers.append({'name': 'slot1_compounds', 'args': slot1})
    if nargs >= 3:
        slot2 = unique_arg_rows(slot1 + slot(2, compounds))
        layers.append({'name': 'slot2_compounds', 'args': slot2})
    return layers

def proof_battery_graph_body(h_eq: dict[str, Any], g_eq: dict[str, Any], max_layers: int=3) -> tuple[str | None, dict[str, Any]]:
    considered = []
    for layer in battery_arg_layers(h_eq, g_eq)[:max_layers]:
        rows = list(layer['args'])
        considered.append({'name': layer['name'], 'arg_count': len(rows)})
        body = h_graph_body(h_eq, g_eq, limit=0, extra_args=rows)
        if body:
            return (body, {'kind': 'proof_battery_state', 'status': 'body_built', 'winning_consumer': 'battery_h_fact_graph', 'graph_layers_considered': considered})
    return (None, {'kind': 'proof_battery_state', 'status': 'no_graph_path', 'graph_layers_considered': considered, 'need_hint': 'Old battery h-instance layers did not connect the goal; try forward_saturation, goal_superposition, or a midpoint.'})

def old_haves_grind_bodies(h_eq: dict[str, Any], g_eq: dict[str, Any]):
    intro = 'intro ' + ' '.join(g_eq['variables']) if g_eq['variables'] else ''
    for limit in (24, 48, 64):
        haves = []
        rows = candidate_h_args(h_eq, g_eq, limit)
        for i, args in enumerate(rows, start=1):
            haves.append(f'have h{i} := h ' + ' '.join(map(lean_arg, args)))
        if intro and haves:
            yield (f'old_haves_grind_{len(rows)}', '\n'.join([intro, *haves, 'grind']))

def proof_candidates_with_sources(h_eq: dict[str, Any], g_eq: dict[str, Any]):
    if g_eq['lhs'] == g_eq['rhs']:
        yield ('rfl_goal', 'intro ' + ' '.join(g_eq['variables']) + '\nrfl')
    for route, body in collapse_certificate_bodies(h_eq, g_eq):
        yield (route, body)
    for route, body in grounding_h_certificate_bodies(h_eq, g_eq):
        yield (route, body)
    for maker in (right_square_chain_body, generic_right_square_chain_body, square_sandwich_chain_body, rowconst_body, grounding_derived_body):
        try:
            body = maker(h_eq, g_eq)
        except Exception:
            body = None
        if body:
            yield (maker.__name__.removesuffix('_body'), body)
    body, _state = proof_battery_graph_body(h_eq, g_eq)
    if body:
        yield ('proof_battery_graph', body)
    for cfg in [(48, 0), (64, 0), (64, 600)]:
        body = h_graph_body(h_eq, g_eq, cfg[0], congruence_cap=cfg[1])
        if body:
            yield (f'h_graph_limit_{cfg[0]}_cong_{cfg[1]}', body)
    for i, action in enumerate(right_context_contraction_actions(h_eq, g_eq), 1):
        body, _ = hint_payload_attempt(action, h_eq, g_eq)
        if body:
            yield (f'structured_continuation_{i}', body)
    yield from native_saturation_bodies(h_eq, g_eq)
    yield from old_haves_grind_bodies(h_eq, g_eq)

def proof_candidates(h_eq: dict[str, Any], g_eq: dict[str, Any]):
    for _source, body in proof_candidates_with_sources(h_eq, g_eq):
        yield body

def extract_json(text: str) -> dict[str, Any] | None:
    text = re.sub('<think>[\\s\\S]*?</think>', '', text or '').strip()
    text = re.sub('^```(?:json)?\\s*\\n?', '', text)
    text = re.sub('\\n?```\\s*$', '', text)
    try:
        data = json.loads(text)
        return data if isinstance(data, dict) else None
    except Exception:
        pass
    m = re.search('\\{[\\s\\S]*\\}', text)
    if m:
        try:
            data = json.loads(m.group())
            return data if isinstance(data, dict) else None
        except Exception:
            return None
    return None

def helper_kind(eq_text: str) -> str | None:
    try:
        eq = parse_equation(eq_text)
    except Exception:
        return None
    lhs, rhs = (eq['lhs'], eq['rhs'])
    pairs = [(lhs, rhs), (rhs, lhs)]
    for l, r in pairs:
        if l[0] == 'op' and r[0] == 'var' and (l[2] == sq(r)):
            return 'square_absorb'
        if l[0] == 'op' and r[0] == 'op' and (r[1] == r[2]) and (l[2] == r[1]):
            return 'right_square'
        if l[0] == 'op' and r[0] == 'op' and (is_square(l) is not None) and (is_square(r) is not None) and (l != r):
            return 'square_const'
        if l[0] == 'op' and r[0] == 'var':
            if l[2][0] == 'op' and l[2][1] == l[2][2] and (l[1] == r):
                return 'right_id_square'
            if l[1][0] == 'op' and l[1][2] == r and (l[1][1] == l[2]):
                return 'sandwich'
            if l[2][0] == 'op' and l[2][1] == r and (l[2][2] == l[1]):
                return 'left_sandwich'
    return None
STANDARD_HELPER_CHAIN_SPECS: list[dict[str, Any]] = [{'name': 'nested_tail_absorption', 'trigger': 'nested_tail_absorption', 'budget_floor': 32.0, 'budget_policy': {'initial_grant': 3.0, 'max_grant': 15.0, 'max_grants_per_task': 4}, 'lemmas': [('nested_absorb', 'u ◇ (v ◇ u) = u'), ('tail_any', '((u ◇ v) ◇ v) ◇ (w ◇ t) = t')], 'why': 'For H of the form x = (y ◇ (z ◇ x)) ◇ (w ◇ x), first prove `u ◇ (v ◇ u) = u`; with that helper, prove the broad tail law `((u ◇ v) ◇ v) ◇ (w ◇ t) = t`, which directly instantiates the goal.'}, {'name': 'generic_right_square_absorption', 'trigger': 'repeated_self_absorption', 'budget_floor': 12.0, 'lemmas': [('square_absorb', 'u ◇ (v ◇ v) = v'), ('right_square', 'u ◇ v = v ◇ v')], 'why': 'A repeated self-absorption H can sometimes first prove `u ◇ (v ◇ v) = v`, then use it to prove `u ◇ v = v ◇ v`, and only then consume the pair toward a goal.'}]

def helper_chain_trigger_flags(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> list[str]:
    flags: list[str] = []
    if nested_tail_absorption_h(h_eq, g_eq):
        flags.append('nested_tail_absorption')
    if repeated_self_absorption_h(h_eq, g_eq):
        flags.append('repeated_self_absorption')
    if right_square_h_roles(h_eq):
        flags.append('focused_right_square_shape')
    if square_sandwich_h_roles(h_eq):
        flags.append('focused_square_sandwich_shape')
    return flags

def selected_helper_chain_specs(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any] | None=None) -> tuple[list[dict[str, Any]], list[str]]:
    call = call or {}
    requested_raw = call.get('chains') or call.get('chain') or call.get('families') or call.get('family')
    requested: set[str] = set()
    if isinstance(requested_raw, str):
        requested = {part.strip() for part in requested_raw.split(',') if part.strip()}
    elif isinstance(requested_raw, list):
        requested = {str(part).strip() for part in requested_raw if str(part).strip()}
    flags = helper_chain_trigger_flags(h_eq, g_eq)
    specs: list[dict[str, Any]] = []
    for spec in STANDARD_HELPER_CHAIN_SPECS:
        if requested and spec['name'] not in requested:
            continue
        if spec.get('trigger') in flags or requested:
            specs.append(spec)
    return (specs, flags)

def helper_chain_hints(spec: dict[str, Any]) -> list[UniversalEquation]:
    hints = []
    for name, equation in spec.get('lemmas', []):
        hints.append(UniversalEquation(name=name, eq=parse_equation(equation), extra_args=[]))
    return hints

def helper_chain_portfolio_attempt(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any] | None=None, *, budget: float | None=None) -> tuple[str | None, dict[str, Any]]:
    call = call or {}
    specs, flags = selected_helper_chain_specs(h_eq, g_eq, call)
    total_budget = float(budget if budget is not None else call.get('budget') or call.get('time_budget') or 12.0)
    deadline = time.monotonic() + max(1.0, total_budget)
    attempts: list[dict[str, Any]] = []
    if not specs:
        return (None, {'protocol_version': PROTOCOL_VERSION, 'kind': 'helper_chain_portfolio_state', 'status': 'not_applicable', 'trigger_flags': flags, 'available_chains': [spec['name'] for spec in STANDARD_HELPER_CHAIN_SPECS], 'need_hint': 'No standard helper-chain trigger fired; use lemma_chain with a problem-specific midpoint, goal_superposition, or false_model_search.'})
    for index, spec in enumerate(specs):
        rem = deadline - time.monotonic()
        if rem <= 0.5:
            attempts.append({'chain': spec['name'], 'status': 'skipped_budget_exhausted', 'lemmas': [equation for _name, equation in spec.get('lemmas', [])]})
            continue
        hints = helper_chain_hints(spec)
        refuted = []
        for hint in hints:
            refutation = hint_refutation(h_eq, hint.eq)
            if refutation is not None:
                refuted.append({'name': hint.name, 'equation': hint.eq['text'], 'refutation': refutation})
        if refuted:
            attempts.append({'chain': spec['name'], 'status': 'refuted_by_small_model', 'lemmas': [{'name': hint.name, 'equation': hint.eq['text']} for hint in hints], 'refuted_lemmas': refuted})
            continue
        remaining_specs = max(1, len(specs) - index)
        attempt_budget = min(rem, max(float(spec.get('budget_floor', 8.0)), rem / remaining_specs))
        raw_policy = dict(spec.get('budget_policy') or {})
        raw_policy['total_budget'] = attempt_budget
        body, state = generic_midpoint_chain_attempt(h_eq, g_eq, hints, budget_policy=raw_policy, total_budget=attempt_budget, ordered_chain=True)
        attempts.append({'chain': spec['name'], 'status': 'body_built' if body else state.get('status', 'stuck'), 'why': spec.get('why'), 'budget': round(attempt_budget, 3), 'lemmas': [{'name': hint.name, 'equation': hint.eq['text']} for hint in hints], 'chain_state': state})
        if body:
            return (body, {'protocol_version': PROTOCOL_VERSION, 'kind': 'helper_chain_portfolio_state', 'status': 'body_built', 'trigger_flags': flags, 'winning_chain': spec['name'], 'proved_lemmas': state.get('proved_lemmas', []), 'attempts': attempts})
    need_hint: Any = None
    for attempt in attempts:
        chain_state = attempt.get('chain_state')
        if isinstance(chain_state, dict) and chain_state.get('need_hint'):
            need_hint = chain_state.get('need_hint')
            break
    return (None, {'protocol_version': PROTOCOL_VERSION, 'kind': 'helper_chain_portfolio_state', 'status': 'stuck', 'trigger_flags': flags, 'attempts': attempts, 'need_hint': need_hint or {'kind': 'helper_chain_repair', 'reason': 'Standard helper chains were plausible but did not close; propose a problem-specific lemma_chain using the closest proof/consume feedback.'}})

def helper_chain_portfolio_body(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str | None:
    body, _state = helper_chain_portfolio_attempt(h_eq, g_eq, budget=12.0)
    return body

def run_tool_call_detailed(call: dict[str, Any], h_eq: dict[str, Any], g_eq: dict[str, Any], *, capability_mask: Any=None, verify_candidates: bool=False) -> tuple[str | None, dict[str, Any] | None]:
    raw_tool = str(call.get('tool') or '').strip()
    tool = TOOL_ALIASES.get(raw_tool, raw_tool)
    gate_state = capability_gate_state(tool, capability_mask)
    if gate_state is not None:
        return (None, gate_state)
    if tool == 'forward_saturation':
        bodies = list(native_saturation_bodies(h_eq, g_eq))
        attempts: list[dict[str, Any]] = []
        if verify_candidates:
            for idx, (route, body) in enumerate(bodies, start=1):
                result = judge_true_attributed(f'llm:tool:forward_saturation:{route}', body, source='llm_tool_call', detail={'tool': 'forward_saturation', 'candidate_index': idx, 'candidate_count': len(bodies)})
                attempts.append({'route': route, 'status': result.get('status'), 'message': short_text(result.get('message') or result.get('stderr') or '', 300)})
                if result.get('status') == 'accepted':
                    return (body, protocol_state('MechanicalResponse', 'proved', 'forward_saturation', tool=tool, candidate_count=len(bodies), accepted_route=route, judge_attempts=attempts, already_judged_accepted=True))
            return (None, protocol_state('MechanicalResponse', 'stuck', 'forward_saturation', tool=tool, candidate_count=len(bodies), judge_attempts=attempts, need_hint='Forward saturation tried every generated body cheapest-first and none closed; use closest_pairs to propose a midpoint, or switch to goal_superposition.'))
        body = bodies[0][1] if bodies else None
        route = bodies[0][0] if bodies else None
        return (body, protocol_state('MechanicalResponse', 'candidate_generated' if body else 'not_applicable', 'forward_saturation', tool=tool, candidate_count=len(bodies), selected_route=route, need_hint=None if body else 'No bounded saturation body was generated; try goal_superposition or a midpoint.'))
    if tool == 'right_square_chain':
        body = right_square_chain_body(h_eq, g_eq)
        return (body, protocol_state('MechanicalResponse', 'proved' if body else 'not_applicable', 'right_square_chain', tool=tool, need_hint=None if body else 'Right-square focused renderer did not match; try lemma_chain or goal_superposition.'))
    if tool == 'square_sandwich_chain':
        body = square_sandwich_chain_body(h_eq, g_eq)
        return (body, protocol_state('MechanicalResponse', 'proved' if body else 'not_applicable', 'square_sandwich_chain', tool=tool, need_hint=None if body else 'Square-sandwich renderer did not match; try lemma_chain with square_const/right_id/sandwich helpers.'))
    if tool == 'helper_chain_portfolio':
        body, state = helper_chain_portfolio_attempt(h_eq, g_eq, call, budget=float(call.get('budget') or call.get('time_budget') or 12.0))
        state = state or {}
        return (body, protocolize_state(state, 'helper_chain_portfolio', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'rowconst_certificates':
        body = rowconst_body(h_eq, g_eq)
        return (body, protocol_state('MechanicalResponse', 'proved' if body else 'not_applicable', 'rowconst_certificates', tool=tool, need_hint=None if body else 'Row-constant certificates did not apply; try standard_aux_superposition or a non-refuted midpoint from closest-equation feedback.'))
    if tool == 'grounding_derived':
        body = grounding_derived_body(h_eq, g_eq)
        return (body, protocolize_state({'kind': 'grounding_derived_state', 'status': 'body_built' if body else 'not_applicable', 'derived_helper': 'target : ∀ a b : G, a ◇ b = a ◇ a' if body else None, 'need_hint': None if body else 'Square-rowconst grounding closer did not apply; try certificates/rowconst/standard_aux or a midpoint.'}, 'grounding_derived'))
    if tool == 'broad_grounding_derived':
        body, state = broad_grounding_derived_body(h_eq, g_eq, budget=float(call.get('budget') or call.get('time_budget') or 12.0), full_budget_per_target=bool(call.get('full_budget_per_target', False)))
        state = state or {}
        return (body, protocolize_state(state, 'broad_grounding_derived', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'collapse_certificates':
        bodies = list(collapse_certificate_bodies(h_eq, g_eq))
        body = bodies[0][1] if bodies else None
        return (body, protocol_state('MechanicalResponse', 'proved' if body else 'not_applicable', 'collapse_certificates', tool=tool, candidate_count=len(bodies), need_hint=None if body else 'No carrier-collapse witness was derived within the bounded certificate search; try standard_aux_superposition, goal_superposition, or a midpoint.'))
    if tool == 'rigidity_collapse_ladder':
        body, state = rigidity_collapse_ladder_attempt(h_eq, g_eq, call)
        return (body, protocolize_state(state, 'rigidity_collapse_ladder', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'grounding_h':
        bodies = list(grounding_h_certificate_bodies(h_eq, g_eq))
        body = bodies[-1][1] if bodies else None
        return (body, protocol_state('MechanicalResponse', 'proved' if body else 'not_applicable', 'grounding_h', tool=tool, candidate_count=len(bodies), need_hint=None if body else 'H is not non-orientable, or the goal has no variables; try standard_aux_superposition or a midpoint.'))
    if tool == 'deep_saturation':
        bodies = list(native_saturation_bodies(h_eq, g_eq))
        body = bodies[-1][1] if bodies else None
        route = bodies[-1][0] if bodies else None
        if verify_candidates and body and route:
            search_state = graph_search_state(h_eq, g_eq, status='deep_saturation_pending')
            suggested = search_state.get('suggested_next_actions') or []
            continuation = suggested[0] if suggested else None
            if isinstance(continuation, dict) and is_hint_payload(continuation):
                continuation_body, _ = hint_payload_attempt(continuation, h_eq, g_eq, capability_mask=capability_mask)
                if continuation_body:
                    continuation_result = judge_true_attributed('llm:tool:deep_saturation:structured_continuation', continuation_body, source='mechanical_feedback_continuation')
                    if continuation_result.get('status') == 'accepted':
                        return (continuation_body, protocol_state('MechanicalResponse', 'proved', 'deep_saturation', tool=tool, accepted_route='structured_continuation', already_judged_accepted=True))
                    search_state['continuation_status'] = continuation_result.get('status')
            result = judge_true_attributed(f'llm:tool:deep_saturation:{route}', body, source='llm_tool_call')
            judge_attempt = {'route': route, 'status': result.get('status'), 'diagnostic': compact_judge_diagnostic(result, 500)}
            if result.get('status') == 'accepted':
                return (body, protocol_state('MechanicalResponse', 'proved', 'deep_saturation', tool=tool, accepted_route=route, judge_attempts=[judge_attempt], already_judged_accepted=True))
            return (None, protocol_state('MechanicalResponse', 'stuck', 'deep_saturation', tool=tool, selected_route=route, judge_attempts=[judge_attempt], search_state=search_state, recommended_next_call=continuation, need_hint='Saturation was rejected; repair from the continuation or closest_pairs.'))
        return (body, protocol_state('MechanicalResponse', 'candidate_generated' if body else 'not_applicable', 'deep_saturation', need_hint='Generated but not judge-verified.' if body else 'No bounded saturation body was generated; try goal_superposition or a midpoint.'))
    if tool == 'proof_battery':
        max_layers = int(call.get('max_graph_candidates') or call.get('graph_candidates') or 3)
        body, state = proof_battery_graph_body(h_eq, g_eq, max_layers=max(1, min(max_layers, 8)))
        state = state or {}
        return (body, protocolize_state(state, 'proof_battery', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'goal_superposition':
        body, state = superposition_prove_detailed(h_eq, g_eq, budget=float(call.get('budget') or call.get('time_budget') or 8.0), allow_var_overlap=bool(call.get('allow_var_overlap', False)))
        state = state or {}
        return (body, protocolize_state(state, 'goal_superposition', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'standard_aux_superposition':
        body, state = standard_aux_superposition_attempt(h_eq, g_eq, call)
        state = state or {}
        return (body, protocolize_state(state, 'standard_aux_superposition', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'ordered_completion':
        body, state = ordered_completion_attempt(h_eq, g_eq, call)
        state = state or {}
        return (body, protocolize_state(state, 'ordered_completion', status='proved' if body else state.get('status', 'stuck')))
    if tool in {'lemma_chain', 'lemma_hint', 'midpoint', 'midpoint_chain'}:
        body, state = hint_payload_attempt(call, h_eq, g_eq, capability_mask=capability_mask)
        state = state or {}
        return (body, protocolize_state(state, 'generic_midpoint_chain', status='proved' if body else state.get('status', 'stuck')))
    if tool == 'false_model_family':
        found, state = false_model_family_attempt(h_eq, g_eq, call)
        state = dict(state or {})
        state['candidate_ready'] = found is not None
        return (None, state)
    if tool == 'residue_ray_countermodel':
        code, state = residue_ray_countermodel_attempt(h_eq, g_eq, call)
        state = dict(state or {})
        state['candidate_ready'] = code is not None
        return (None, state)
    if tool == 'infinite_model_artifact':
        _code, state = validate_infinite_model_payload(call)
        return (None, state)
    return (None, protocol_state('MechanicalResponse', 'unsupported_tool', 'tool_registry', tool=raw_tool, need_hint='Choose one supported tool from the registry, or return a midpoint/lemma_chain/false_model_search/false_model_family/residue_ray_countermodel action.'))

def run_tool_call(call: dict[str, Any], h_eq: dict[str, Any], g_eq: dict[str, Any]):
    body, _state = run_tool_call_detailed(call, h_eq, g_eq)
    return body

def standard_aux_plausible_h(h_eq: dict[str, Any]) -> bool:
    return bool(one_sided_variables(h_eq))

def analysis(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str:
    advice = []
    advice.append('General midpoint engine is available: propose one small equation M or a short chain; each must be proved from H before use.')
    advice.append('Broad true-side consumer available: goal_superposition runs bounded proof-carrying paramodulation and reports a frontier if it gets stuck.')
    advice.append('Ordered completion is available for hard true goals: it targets a helper equation, simplifies critical pairs, and Lean-replays only the dependency closure.')
    advice.append('Broad grounding certificates available: broad_grounding_derived tries to derive collapse or factor-irrelevance helpers and then close G.')
    advice.append('Standard auxiliary consumer available: standard_aux_superposition tries const/projection/rowconst lemmas as explicit proved helpers.')
    advice.append('Helper-chain portfolio available: helper_chain_portfolio tries a small set of reusable lemma chains through the generic midpoint stitcher and reports proved-but-not-consumed chains.')
    if goal_generalization_actions(h_eq, g_eq):
        advice.append('Goal-generalization cards are active: G appears to be a special case of a stronger reusable law, so try proving the reusable law first.')
    one_sided = one_sided_variables(h_eq)
    if one_sided:
        advice.append(f'H has variables on only one side {one_sided}; standard_aux_superposition is a strong next tool because these often imply collapse/projection/rowconst helpers.')
    if h_eq['lhs'][0] == 'var' or h_eq['rhs'][0] == 'var':
        advice.append('H has a lone-variable side; collapse_certificates may derive a carrier-collapse witness and close the whole goal.')
    if self_root_absorption_h(h_eq):
        advice.append('H has self-root absorption form x = x ◇ T or x = T ◇ x; broad_grounding_derived gets a stronger helper-derivation budget.')
    if repeated_self_absorption_h(h_eq, g_eq):
        advice.append('H has repeated self-absorption form x = T[x,x,...] and G is x = compound; prefer an early true-side midpoint/lemma_chain before expensive false search.')
    if nested_tail_absorption_h(h_eq, g_eq):
        advice.append('H has nested-tail absorption form x = (y ◇ (z ◇ x)) ◇ (w ◇ x); try nested_absorb then the broad tail_any contraction helper.')
    if right_square_h_roles(h_eq):
        advice.append('H matches right_square_chain: try helpers u ◇ (v ◇ v)=v and u ◇ v=v ◇ v.')
    if square_sandwich_h_roles(h_eq):
        advice.append('H matches square_sandwich_chain: try square_const/right_id_square/sandwich helpers.')
    if rowconst_h_roles(h_eq):
        advice.append('H matches rowconst_certificates.')
    if square_rowconst_h_roles(h_eq):
        advice.append('H matches grounding_derived square-rowconst: derive a ◇ b = a ◇ a and close explicitly.')
    advice.append('If false, use false_model_search for fixed finite routes, false_model_family for a compact finite operation, or residue_ray_countermodel for an unbounded residue-controlled operation. Every candidate is mechanically checked; misses return concrete repair diagnostics.')
    return '\n'.join(advice)

def problem_analysis(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> str:
    h_args = ' '.join(h_eq['variables'])
    schema_args = [v.upper() for v in h_eq['variables']]
    schema_lhs = term_to_str_subst(h_eq['lhs'], dict(zip(h_eq['variables'], schema_args)))
    schema_rhs = term_to_str_subst(h_eq['rhs'], dict(zip(h_eq['variables'], schema_args)))
    lines = [f"h variables, in call order: {h_eq['variables']}", f"goal variables, introduce in this order if writing proof: {g_eq['variables']}", f"`h {h_args}` has type: {h_eq['text']}", f"schematically, h {' '.join(schema_args)} gives: {schema_lhs} = {schema_rhs}", 'goal subterms worth bridging: ' + ', '.join(goal_terms(g_eq, 8)), 'strict symbolic-family prefilter: ' + json.dumps(symbolic_invariant_report(h_eq, g_eq), ensure_ascii=False)]
    return '\n'.join(lines)

def tool_registry_text(capability_mask: Any=None, *, include_research_tools: bool=False) -> str:
    normalized_mask = normalize_capability_mask(capability_mask)
    disabled = set(normalized_mask['disabled'])
    rows = []
    for name, spec in TOOL_REGISTRY.items():
        if spec.get('deployability') == 'research_only' and (not include_research_tools):
            continue
        required = required_capabilities_for_tool(name)
        available = not any((capability in disabled for capability in required))
        if not available:
            continue
        row = {'tool': name, 'domain': spec['domain'], 'scope': spec.get('scope', 'whole_goal'), 'cost': spec.get('cost', 'medium'), 'feedback_quality': spec.get('feedback_quality', 'basic'), 'native_import': spec.get('native_import', 'collaborative'), 'aliases': spec.get('aliases', [])[:4], 'description': spec['description']}
        if capability_mask is not None:
            row['capability'] = f'tool:{name}'
            row['required_capabilities'] = required
        rows.append(row)
    return json.dumps(rows, ensure_ascii=False)

