def affine_skew_fiber_library(size: int) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[tuple[int, ...]] = set()
    for a, b, c in product(range(size), repeat=3):
        table = tuple(((a * left + b * right + c) % size for left in range(size) for right in range(size)))
        if table in seen:
            continue
        seen.add(table)
        rows.append({'params': [a, b, c], 'table': table})
    return rows

def skew_cp_eval(model: Any, term: Term, env: dict[str, Any], flat_operation: list[Any], carrier_size: int, counter: list[int], prefix: str) -> Any:
    if term[0] == 'var':
        return env[term[1]]
    left = skew_cp_eval(model, term[1], env, flat_operation, carrier_size, counter, prefix)
    right = skew_cp_eval(model, term[2], env, flat_operation, carrier_size, counter, prefix)
    if isinstance(left, int) and isinstance(right, int):
        return flat_operation[left * carrier_size + right]
    index = model.NewIntVar(0, carrier_size * carrier_size - 1, f'{prefix}_index_{counter[0]}')
    value = model.NewIntVar(0, carrier_size - 1, f'{prefix}_value_{counter[0]}')
    counter[0] += 1
    model.Add(index == left * carrier_size + right)
    model.AddElement(index, flat_operation, value)
    return value

def skew_equation_failure(equation: dict[str, Any], table: list[list[int]], deadline: float) -> dict[str, int] | None:
    for values in product(range(len(table)), repeat=len(equation['variables'])):
        if time.monotonic() >= deadline:
            raise TimeoutError
        env = dict(zip(equation['variables'], values))
        if eval_term(equation['lhs'], env, table) != eval_term(equation['rhs'], env, table):
            return {key: int(value) for key, value in env.items()}
    return None

