PCE_AFFINE = [(0, 0), (1, 0), (0, 1)]
PCE_BILINEAR = [(0, 0), (1, 0), (0, 1), (1, 1)]
PCE_QUADRATIC = [(0, 0), (1, 0), (0, 1), (1, 1), (2, 0), (0, 2)]
PCE_TIERS = [('affine', PCE_AFFINE, 18), ('bilinear', PCE_BILINEAR, 13), ('quadratic', PCE_QUADRATIC, 10)]

def polynomial_table(coeffs: tuple[int, ...], basis: list[tuple[int, int]], n: int) -> list[list[int]]:
    table = [[0] * n for _ in range(n)]
    for a in range(n):
        for b in range(n):
            total = 0
            for coeff, (ea, eb) in zip(coeffs, basis):
                if coeff:
                    total += coeff * a ** ea * b ** eb
            table[a][b] = total % n
    return table

def polynomial_formula(coeffs: tuple[int, ...], basis: list[tuple[int, int]], n: int) -> str:

    def mul(factors: list[str]) -> str:
        if not factors:
            return '1'
        expr = factors[0]
        for factor in factors[1:]:
            expr = f'Nat.mul ({expr}) {factor}'
        return expr
    terms: list[str] = []
    for coeff, (ea, eb) in zip(coeffs, basis):
        if coeff == 0:
            continue
        factors = ['i.val'] * ea + ['j.val'] * eb
        if coeff != 1 or not factors:
            factors.insert(0, str(coeff))
        terms.append(mul(factors))
    if not terms:
        total = '0'
    else:
        total = terms[0]
        for term in terms[1:]:
            total = f'Nat.add ({total}) ({term})'
    return f'Nat.mod ({total}) {n}'

def pce_eval(term: Term, env: dict[str, int], table: list[list[int]]) -> int:
    if term[0] == 'var':
        return env[term[1]]
    return table[pce_eval(term[1], env, table)][pce_eval(term[2], env, table)]

def pce_holds(eq: dict[str, Any], n: int, table: list[list[int]], deadline: float, check_every: int=4096) -> bool | None:
    for idx, vals in enumerate(product(range(n), repeat=len(eq['variables']))):
        if idx % check_every == 0 and time.monotonic() > deadline:
            return None
        env = dict(zip(eq['variables'], vals))
        if pce_eval(eq['lhs'], env, table) != pce_eval(eq['rhs'], env, table):
            return False
    return True

def pce_fails(eq: dict[str, Any], n: int, table: list[list[int]], deadline: float, check_every: int=4096) -> bool | None:
    for idx, vals in enumerate(product(range(n), repeat=len(eq['variables']))):
        if idx % check_every == 0 and time.monotonic() > deadline:
            return None
        env = dict(zip(eq['variables'], vals))
        if pce_eval(eq['lhs'], env, table) != pce_eval(eq['rhs'], env, table):
            return True
    return False

def find_poly_counterexample(h_eq: dict[str, Any], g_eq: dict[str, Any], *, nmax: int=18, time_budget: float=12.0, max_tier: int | None=None) -> tuple[int, list[list[int]], str, dict[str, Any]] | None:
    deadline = time.monotonic() + time_budget
    tiers = PCE_TIERS if max_tier is None else PCE_TIERS[:max_tier]
    checked = 0
    tier_stats: list[dict[str, Any]] = []
    for tier_index, (tier_name, basis, tier_nmax) in enumerate(tiers, start=1):
        tier_checked = 0
        for n in range(2, min(nmax, tier_nmax) + 1):
            if time.monotonic() > deadline:
                tier_stats.append({'tier': tier_name, 'checked': tier_checked, 'status': 'budget'})
                return None
            for coeffs in product(range(n), repeat=len(basis)):
                table = polynomial_table(tuple((int(c) for c in coeffs)), basis, n)
                checked += 1
                tier_checked += 1
                h_ok = pce_holds(h_eq, n, table, deadline)
                if h_ok is None:
                    tier_stats.append({'tier': tier_name, 'checked': tier_checked, 'status': 'budget'})
                    return None
                if not h_ok:
                    continue
                g_bad = pce_fails(g_eq, n, table, deadline)
                if g_bad is None:
                    tier_stats.append({'tier': tier_name, 'checked': tier_checked, 'status': 'budget'})
                    return None
                if g_bad:
                    meta = {'tier': tier_name, 'tier_index': tier_index, 'basis': basis, 'coefficients': list(coeffs), 'checked_candidates': checked, 'tier_stats': tier_stats + [{'tier': tier_name, 'checked': tier_checked, 'status': 'found'}]}
                    return (n, table, polynomial_formula(tuple((int(c) for c in coeffs)), basis, n), meta)
        tier_stats.append({'tier': tier_name, 'checked': tier_checked, 'status': 'exhausted'})
    return None

def false_route_continuations(trials: list[dict[str, Any]]) -> list[str]:
    tried = {str(t.get('route')) for t in trials if t.get('route') is not None}
    local_ns = sorted({int(t['n']) for t in trials if 'seed' in t and isinstance(t.get('n'), int)})
    model_ns = sorted({int(t['n']) for t in trials if 'seed' not in t and t.get('template') != 'cp_sat' and isinstance(t.get('n'), int)})
    cp_ns = sorted({int(t['n']) for t in trials if t.get('template') == 'cp_sat' and isinstance(t.get('n'), int)})
    skew_factors = [(int(t['control_size']), int(t['fiber_size'])) for t in trials if t.get('template') == 'skew_product' and isinstance(t.get('control_size'), int) and isinstance(t.get('fiber_size'), int)]
    candidate_ns = unique(local_ns + [6] + [min(8, n + 1) for n in local_ns])
    out: list[str] = []

    def add(route: str) -> None:
        if route not in tried and route not in out:
            out.append(route)
    if cp_sat_available() and cp_ns:
        cp_next = [min(9, n + 1) for n in cp_ns[-2:]]
        base_ns = [5, 6] if max(cp_ns) <= 6 else []
        for n in unique(cp_next + base_ns):
            if 2 <= n <= 9:
                add(f'cp_sat:n={n}')
    if skew_factors:
        control, fiber = skew_factors[-1]
        for next_control, next_fiber in ((fiber, control), (control, min(8, fiber + 1))):
            if next_control * next_fiber <= 40:
                add(f'skew_product:{next_control}x{next_fiber}')
    else:
        add('skew_product:2x3')
    if sympy_sat_available():
        for n in (6, 7, 8):
            add(f'sympy_sat:n={n}')
    for n in candidate_ns:
        if 2 <= n <= 8:
            for seed in (0, 1, 2, 3, 4):
                add(f'local_search:n={n}:seed={seed}')
    for n in unique(model_ns + [4, 5, 6, 7, 8]):
        if 2 <= n <= 8:
            add(f'model_finder_v2:n={n}')
    for n in unique(model_ns + [4, 5, 6]):
        if 2 <= n <= 7:
            add(f'model_finder:n={n}')
    add('poly_ce:tier=2:nmax=13')
    add('structured_ce:max_n=7')
    return out[:8]

def false_route_budget(routes: list[Any], requested_budget: float) -> float:
    budget = float(requested_budget or 0)
    cp_ns: list[int] = []
    sympy_ns: list[int] = []
    v2_ns: list[int] = []
    skew_factors: list[tuple[int, int]] = []
    for route in routes:
        route_l = str(route).lower()
        skew_match = re.search('(?:skew_product|skew|block_model)(?::|:factor=|=)?(\\d+)x(\\d+)', route_l)
        if skew_match:
            skew_factors.append((int(skew_match.group(1)), int(skew_match.group(2))))
            continue
        m_model = re.search('n=?(\\d+)', route_l)
        if not m_model:
            continue
        if 'cp_sat' in route_l or 'cpsat' in route_l or 'constraint_sat' in route_l:
            cp_ns.append(int(m_model.group(1)))
        elif 'sympy_sat' in route_l or 'sympy' in route_l:
            sympy_ns.append(int(m_model.group(1)))
        elif 'model_finder_v2' in route_l or 'goal_directed' in route_l:
            v2_ns.append(int(m_model.group(1)))
    if cp_ns:
        if max(cp_ns) >= 8:
            budget = max(budget, 24.0)
        elif max(cp_ns) >= 7:
            budget = max(budget, 16.0)
    if v2_ns:
        if max(v2_ns) >= 7:
            budget = max(budget, 45.0)
        elif max(v2_ns) >= 6:
            budget = max(budget, 24.0)
    if sympy_ns and sympy_sat_available():
        budget = max(budget, 120.0)
    if skew_factors:
        largest = max((control * fiber for control, fiber in skew_factors))
        budget = max(budget, 8.0 if largest > 8 else 4.0)
    return max(3.0, budget)

def assigned_ratio(profile: dict[str, Any] | None) -> float | None:
    if not isinstance(profile, dict):
        return None
    size = profile.get('size')
    assigned = profile.get('assigned_cells')
    try:
        denom = int(size) * int(size)
        return round(float(assigned) / float(denom), 3) if denom > 0 else None
    except Exception:
        return None

def false_trial_highlights(trials: list[dict[str, Any]], continuations: list[str]) -> dict[str, Any]:
    status_counts: Counter[str] = Counter()
    template_counts: Counter[str] = Counter()
    tried_routes: list[str] = []
    blocked: Counter[tuple[int, int]] = Counter()
    branched: Counter[tuple[int, int]] = Counter()
    best_progress: dict[str, Any] | None = None
    best_progress_score = -1.0
    propagation_routes: list[dict[str, Any]] = []
    cp_sat_routes: list[dict[str, Any]] = []
    sympy_sat_routes: list[dict[str, Any]] = []
    skew_routes: list[dict[str, Any]] = []
    for trial in trials:
        if not isinstance(trial, dict):
            continue
        route = str(trial.get('route') or '')
        if route:
            tried_routes.append(route)
        status_counts[str(trial.get('status') or 'unknown')] += 1
        template = str(trial.get('template') or ('local_search' if 'seed' in trial else 'model_finder'))
        template_counts[template] += 1
        has_propagation_diag = any((key in trial for key in ('nodes', 'forced_assignments', 'contradictions', 'propagation_checks', 'top_blocked_cells', 'top_branch_cells', 'best_partial_table_profile')))
        if has_propagation_diag:
            propagation_routes.append({'route': route, 'status': trial.get('status'), 'n': trial.get('n'), 'nodes': trial.get('nodes'), 'forced_assignments': trial.get('forced_assignments'), 'contradictions': trial.get('contradictions'), 'propagation_checks': trial.get('propagation_checks')})
        if template == 'cp_sat':
            cp_sat_routes.append({'route': route, 'status': trial.get('status'), 'n': trial.get('n'), 'skolem_count': trial.get('skolem_count'), 'infeasible_skolems': trial.get('cp_sat_infeasible_skolems'), 'unknown_skolems': trial.get('cp_sat_unknown_skolems'), 'trials': trial.get('trials')})
        if template == 'sympy_sat':
            sympy_sat_routes.append({'route': route, 'status': trial.get('status'), 'n': trial.get('n'), 'skolem_count': trial.get('skolem_count'), 'backend': trial.get('backend'), 'trials': trial.get('trials')})
        if template == 'skew_product':
            skew_routes.append({'route': route, 'status': trial.get('status'), 'control_size': trial.get('control_size'), 'fiber_size': trial.get('fiber_size'), 'carrier_size': trial.get('carrier_size'), 'backend': trial.get('backend'), 'iterations': trial.get('iterations'), 'lifted_h_constraints': trial.get('lifted_h_constraints'), 'quotient_tables_checked': trial.get('quotient_tables_checked'), 'quotient_candidates': trial.get('quotient_candidates'), 'selector_tuples_checked': trial.get('selector_tuples_checked'), 'seconds': trial.get('seconds'), 'suggested_factorizations': trial.get('suggested_factorizations')})
        for item in trial.get('top_blocked_cells') or []:
            cell = item.get('cell') if isinstance(item, dict) else None
            if isinstance(cell, list) and len(cell) == 2:
                blocked[int(cell[0]), int(cell[1])] += int(item.get('count') or 0)
        for item in trial.get('top_branch_cells') or []:
            cell = item.get('cell') if isinstance(item, dict) else None
            if isinstance(cell, list) and len(cell) == 2:
                branched[int(cell[0]), int(cell[1])] += int(item.get('count') or 0)
        profile = trial.get('best_partial_table_profile')
        ratio = assigned_ratio(profile)
        if ratio is not None and ratio > best_progress_score:
            best_progress_score = ratio
            best_progress = {'route': route, 'status': trial.get('status'), 'assigned_ratio': ratio, 'profile': profile}
    policy: list[str] = []
    if continuations:
        policy.append('Try recommended_next_call first; it is the first untried concrete route.')
    if blocked or branched:
        policy.append('Do not repeat exhausted routes; use hot blocked/branch cells as evidence that the next response should change route family, carrier size, seed, or provide a full table.')
    if best_progress and best_progress.get('assigned_ratio', 0) >= 0.8:
        policy.append('A propagation route reached a nearly complete partial table; a complete counterexample table or one nearby local_search continuation is especially useful.')
    if any((row.get('unknown_skolems') or 0 for row in cp_sat_routes)):
        policy.append('An exact cp_sat route reached UNKNOWN rather than infeasible; retry the same carrier with more budget, then move carrier size if it remains unknown.')
    if any((row.get('status') in {'timeout', 'unsat_or_timeout'} for row in sympy_sat_routes)):
        policy.append('A sympy_sat exact route timed out; retry only one carrier size with a larger budget, or switch to model_finder_v2/local_search using the same carrier.')
    if skew_routes and skew_routes[-1].get('status') in {'family_infeasible', 'search_incomplete', 'budget'}:
        policy.append('The compact quotient-by-fiber family did not close; try its suggested transposed/larger factorization before abandoning structured extensions.')
    if not policy:
        policy.append('Return one untried false_model_search route or switch to a true-side midpoint/lemma_chain.')
    return {'tried_routes': tried_routes[-8:], 'status_counts': dict(status_counts), 'template_counts': dict(template_counts), 'propagation_route_summaries': propagation_routes[-4:], 'cp_sat_route_summaries': cp_sat_routes[-3:], 'sympy_sat_route_summaries': sympy_sat_routes[-3:], 'skew_route_summaries': skew_routes[-3:], 'hot_blocked_cells': top_counter(blocked, limit=5), 'hot_branch_cells': top_counter(branched, limit=5), 'best_partial_progress': best_progress, 'next_action_policy': policy}

def dual_term(term: Term) -> Term:
    if term[0] == 'var':
        return term
    return ('op', dual_term(term[2]), dual_term(term[1]))

def dual_equation(eq: dict[str, Any]) -> dict[str, Any]:
    lhs = dual_term(eq['lhs'])
    rhs = dual_term(eq['rhs'])
    return {'text': f'{term_to_str(lhs)} = {term_to_str(rhs)}', 'variables': list(eq['variables']), 'lhs': lhs, 'rhs': rhs}

def transpose_table(table: list[list[int]]) -> list[list[int]]:
    return [[table[j][i] for j in range(len(table))] for i in range(len(table))]

def structured_counterexample_search(h_eq: dict[str, Any], g_eq: dict[str, Any], *, max_n: int=7, time_budget: float=8.0, allow_dual: bool=True) -> tuple[int, list[list[int]], str] | None:
    deadline = time.monotonic() + max(0.5, time_budget)
    limit = max(2, min(int(max_n), 9))
    for index, table in enumerate(witness_tables()):
        if len(table) <= limit and is_counterexample(h_eq, g_eq, table):
            return (len(table), table, f'named_witness:{index}')
    for index, table in enumerate(structured_tables(limit)):
        if time.monotonic() >= deadline:
            return None
        if is_counterexample(h_eq, g_eq, table):
            return (len(table), table, f'structured_family:{index}')
    if allow_dual:
        remaining = deadline - time.monotonic()
        if remaining > 0.25:
            found = structured_counterexample_search(dual_equation(h_eq), dual_equation(g_eq), max_n=limit, time_budget=remaining, allow_dual=False)
            if found is not None:
                n, table, route = found
                transposed = transpose_table(table)
                if is_counterexample(h_eq, g_eq, transposed):
                    return (n, transposed, f'dual:{route}')
    return None

def false_model_search_detailed(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any], default_budget: float=8.0, *, semantic_context: dict[str, Any] | None=None):
    if not finite_countermodel_search_allowed(semantic_context):
        state = semantic_status_state(semantic_context or {})
        return (None, protocol_state('FalseModelSearchState', 'finite_search_prohibited', 'false_model_search', tool='false_model_search', trials=[], semantic_status=state, need_hint=state.get('need_hint'), suggested_next_actions=state.get('suggested_next_actions')))
    routes = call.get('routes') or []
    budget = float(call.get('budget') or call.get('time_budget') or default_budget)
    if not routes:
        sizes = call.get('sizes') or [5, 6]
        seeds = call.get('seeds') or [0, 1, 2]
        template = str(call.get('template') or '').lower()
        if template in {'model_finder_v2', 'goal_directed', 'goal_directed_model_finder'}:
            routes = [f'model_finder_v2:n={int(n)}' for n in sizes]
        elif template in {'poly', 'poly_ce', 'polynomial'}:
            routes = ['poly_ce:tier=2:nmax=13']
        elif template in {'cp_sat', 'cpsat', 'constraint_sat'}:
            routes = [f'cp_sat:n={int(n)}' for n in sizes]
        elif template in {'skew_product', 'skew', 'block_model'}:
            control = int(call.get('control_size') or call.get('quotient_size') or 2)
            fiber = int(call.get('fiber_size') or 3)
            routes = [f'skew_product:{control}x{fiber}']
        elif template in {'sympy_sat', 'sympy', 'cnf_sat', 'dpll'}:
            routes = [f'sympy_sat:n={int(n)}' for n in sizes]
        elif template in {'structured_ce', 'ce_engine', 'witness_families'}:
            routes = ['structured_ce:max_n=7']
        elif template in {'model_finder', 'propagation', 'constraint_propagation'}:
            routes = [f'model_finder:n={int(n)}' for n in sizes]
        else:
            routes = [f'local_search:n={int(n)}:seed={int(s)}' for n in sizes for s in seeds]
    route_limit = max(1, int(call.get('max_routes') or 8))
    active_routes = list(routes[:route_limit])
    skipped_routes = [str(route) for route in routes[route_limit:]]
    cp_sat_ns = []
    sympy_sat_ns = []
    skew_factors = []
    for route in active_routes:
        route_l = str(route).lower()
        skew_match = re.search('(?:skew_product|skew|block_model)(?::|:factor=|=)?(\\d+)x(\\d+)', route_l)
        if skew_match:
            skew_factors.append((int(skew_match.group(1)), int(skew_match.group(2))))
            continue
        m_model = re.search('n=?(\\d+)', route_l)
        if not m_model:
            continue
        if 'cp_sat' in route_l or 'cpsat' in route_l or 'constraint_sat' in route_l:
            cp_sat_ns.append(int(m_model.group(1)))
        elif 'sympy_sat' in route_l or 'sympy' in route_l:
            sympy_sat_ns.append(int(m_model.group(1)))
    if cp_sat_ns:
        if max(cp_sat_ns) >= 8:
            budget = max(budget, 24.0)
        elif max(cp_sat_ns) >= 7:
            budget = max(budget, 16.0)
    if skew_factors:
        largest = max((control * fiber for control, fiber in skew_factors))
        budget = max(budget, 8.0 if largest > 8 else 4.0)
    per = max(0.5, budget / max(1, len(active_routes)))
    trials: list[dict[str, Any]] = []
    for route in active_routes:
        route_s = str(route)
        route_l = route_s.lower()
        skew_match = re.search('(?:skew_product|skew|block_model)(?::|:factor=|=)?(\\d+)x(\\d+)', route_l)
        if skew_match:
            control_size = int(skew_match.group(1))
            fiber_size = int(skew_match.group(2))
            status, table, meta = skew_product_counterexample_search(h_eq, g_eq, control_size, fiber_size, per)
            trials.append({'route': route_s, 'status': status, 'template': 'skew_product', **meta})
            if table is not None and is_counterexample(h_eq, g_eq, table):
                return ((len(table), table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': len(table), 'source': route_s, 'witness_style': 'quotient_fiber_skew_product', 'symbolic_parameters': {'control_size': meta.get('control_size'), 'fiber_size': meta.get('fiber_size'), 'control_table': meta.get('control_table'), 'fiber_parameters': meta.get('fiber_parameters')}}, 'false_model_search'))
            continue
        if 'structured_ce' in route_l or 'ce_engine' in route_l or 'witness_families' in route_l:
            m_nmax = re.search('(?:max_n|nmax)=?(\\d+)', route_l)
            max_n = int(m_nmax.group(1)) if m_nmax else 7
            found = structured_counterexample_search(h_eq, g_eq, max_n=max_n, time_budget=per)
            if found is None:
                trials.append({'route': route_s, 'status': 'no_model', 'template': 'structured_ce', 'max_n': max_n})
                continue
            n, table, source = found
            trials.append({'route': route_s, 'status': 'found', 'template': 'structured_ce', 'n': n, 'source': source})
            return ((n, table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': f'{route_s}:{source}', 'witness_style': 'native_structured_family'}, 'false_model_search'))
        if 'poly' in route_l:
            m_tier = re.search('tier=?(\\d+)', route_l)
            m_nmax = re.search('nmax=?(\\d+)', route_l)
            max_tier = int(m_tier.group(1)) if m_tier else 2
            nmax = int(m_nmax.group(1)) if m_nmax else 13
            result = find_poly_counterexample(h_eq, g_eq, nmax=nmax, time_budget=per, max_tier=max_tier)
            if result is None:
                trials.append({'route': route_s, 'status': 'no_model', 'template': 'poly_ce', 'nmax': nmax, 'max_tier': max_tier})
                continue
            n, table, formula, meta = result
            trials.append({'route': route_s, 'status': 'found', 'template': 'poly_ce', 'n': n, **meta})
            if is_counterexample(h_eq, g_eq, table):
                return ((n, table, formula), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': route_s, 'witness_style': 'polynomial_magma', 'op_formula': formula}, 'false_model_search'))
            continue
        if 'cp_sat' in route_l or 'cpsat' in route_l or 'constraint_sat' in route_l:
            m_model = re.search('n=?(\\d+)', route_l)
            if not m_model:
                continue
            n = int(m_model.group(1))
            if n < 2 or n > 9:
                continue
            status, table, meta = cp_sat_counterexample_search(h_eq, g_eq, n, per)
            trials.append({'route': route_s, 'status': status, 'template': 'cp_sat', **meta})
            if table is not None and is_counterexample(h_eq, g_eq, table):
                return ((n, table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': route_s, 'witness_style': 'cp_sat_table'}, 'false_model_search'))
            continue
        if 'sympy_sat' in route_l or 'sympy' in route_l:
            m_model = re.search('n=?(\\d+)', route_l)
            if not m_model:
                continue
            n = int(m_model.group(1))
            if n < 5 or n > 8:
                trials.append({'route': route_s, 'status': 'skipped_size', 'template': 'sympy_sat', 'n': n})
                continue
            status, table, meta = sympy_sat_counterexample_search(h_eq, g_eq, n, per)
            trials.append({'route': route_s, 'status': status, 'template': 'sympy_sat', **meta})
            if table is not None and is_counterexample(h_eq, g_eq, table):
                return ((n, table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': route_s, 'witness_style': 'sympy_sat_table'}, 'false_model_search'))
            continue
        if 'model_finder_v2' in route_l or 'goal_directed' in route_l:
            m_model = re.search('n=?(\\d+)', route_l)
            if not m_model:
                continue
            n = int(m_model.group(1))
            if n < 2 or n > 9:
                continue
            m_seed = re.search('seed=?(\\d+)', route_l)
            seed = int(m_seed.group(1)) if m_seed else 12648430
            slice_n9 = min(45.0, max(per, budget * 0.5)) if n >= 9 else per
            status, table, meta = goal_directed_model_finder(h_eq, g_eq, n, slice_n9, seed=seed)
            trials.append({'route': route_s, 'status': status, 'template': 'model_finder_v2', **meta})
            if table is not None and is_counterexample(h_eq, g_eq, table):
                return ((n, table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': route_s, 'witness_style': 'goal_directed_table'}, 'false_model_search'))
            continue
        if 'model_finder' in route_l or 'propagation' in route_l:
            m_model = re.search('n=?(\\d+)', route_l)
            if not m_model:
                continue
            n = int(m_model.group(1))
            if n < 2 or n > 7:
                continue
            status, table, meta = propagation_model_finder(h_eq, g_eq, n, per)
            trials.append({'route': route_s, 'status': status, **meta})
            if table is not None and is_counterexample(h_eq, g_eq, table):
                return ((n, table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': route_s}, 'false_model_search'))
            continue
        m = re.search('n=?(\\d+).*seed=?(\\d+)', route_l)
        if not m:
            continue
        n, seed = (int(m.group(1)), int(m.group(2)))
        if n < 2 or n > 8:
            continue
        table = local_search_route(h_eq, g_eq, n, seed, per)
        trials.append({'route': route_s, 'status': 'found' if table is not None else 'no_model', 'n': n, 'seed': seed})
        if table is not None and is_counterexample(h_eq, g_eq, table):
            return ((n, table), protocolize_state({'kind': 'FalseModelSearchState', 'status': 'found', 'trials': trials, 'counterexample_size': n, 'source': route_s}, 'false_model_search'))
    continuations = unique(skipped_routes + false_route_continuations(trials))
    highlights = false_trial_highlights(trials, continuations)
    next_call = {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': continuations[:1], 'budget': false_route_budget(continuations[:1], min(8.0, budget))} if continuations else None
    return (None, protocolize_state({'kind': 'FalseModelSearchState', 'status': 'no_countermodel_found', 'budget_seconds': budget, 'route_limit': route_limit, 'trials': trials, 'skipped_routes_due_limit': skipped_routes, 'diagnostic_highlights': highlights, 'untried_requested_routes': continuations, 'recommended_next_call': next_call, 'route_policy': 'Prefer one concrete untried route. Use diagnostic_highlights to avoid repeats and decide whether to change seed, carrier size, or route family.', 'need_hint': 'Use diagnostic_highlights. Try recommended_next_call first if present; otherwise change route family/size/seed, provide a complete counterexample_table, or switch to a true-side midpoint/lemma_chain.'}, 'false_model_search', suggested_next_actions=[next_call] if next_call else None))

def false_model_search(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any], default_budget: float=8.0, *, semantic_context: dict[str, Any] | None=None):
    found, _state = false_model_search_detailed(h_eq, g_eq, call, default_budget, semantic_context=semantic_context)
    return found

def goal_terms(g_eq: dict[str, Any], limit: int=12) -> list[str]:
    terms = sorted({term_to_str(t) for t in subterms(g_eq['lhs']) + subterms(g_eq['rhs'])}, key=lambda s: (-len(s), s))
    return terms[:limit]

def unary_terms(v: str) -> list[str]:
    return [v, f'({v} ◇ {v})', f'(({v} ◇ {v}) ◇ {v})', f'({v} ◇ ({v} ◇ {v}))']

def candidate_h_args(h_eq: dict[str, Any], g_eq: dict[str, Any], limit: int, extra_terms: list[str] | None=None):
    nargs = len(h_eq['variables'])
    if nargs == 0:
        return []
    vars_ = g_eq['variables'] or ['x']
    terms = unique((extra_terms or []) + goal_terms(g_eq, 14) + [t for v in vars_ for t in unary_terms(v)] + vars_)
    rows: list[tuple[str, ...]] = []
    seen: set[tuple[str, ...]] = set()

    def add(row: tuple[str, ...]):
        if len(row) == nargs and row not in seen:
            seen.add(row)
            rows.append(row)
    if nargs == 1:
        for a in terms:
            add((a,))
            if len(rows) >= limit:
                break
    else:
        for fill in vars_:
            for a in terms:
                for b in terms[:10]:
                    row = [fill] * nargs
                    row[0] = a
                    row[1] = b
                    add(tuple(row))
                    if len(rows) >= limit:
                        return rows
    return rows[:limit]

def render_h_type(h_eq: dict[str, Any], args: tuple[str, ...]) -> tuple[str, str]:
    sub = {v: args[i] for i, v in enumerate(h_eq['variables'])}
    return (term_to_str_subst(h_eq['lhs'], sub), term_to_str_subst(h_eq['rhs'], sub))

def match_pattern_term(pattern: Term, target: Term, pattern_vars: set[str], subst: dict[str, str]) -> bool:
    if pattern[0] == 'var' and pattern[1] in pattern_vars:
        value = term_to_str(target)
        old = subst.get(pattern[1])
        if old is None:
            subst[pattern[1]] = value
            return True
        return old == value
    if pattern[0] != target[0]:
        return False
    if pattern[0] == 'var':
        return pattern[1] == target[1]
    return match_pattern_term(pattern[1], target[1], pattern_vars, subst) and match_pattern_term(pattern[2], target[2], pattern_vars, subst)

def direct_lemma_goal_args(lemma_eq: dict[str, Any], g_eq: dict[str, Any]) -> list[tuple[str, ...]]:
    rows: list[tuple[str, ...]] = []
    pattern_vars = set(lemma_eq['variables'])

    def try_add(left_pattern: Term, right_pattern: Term, left_target: Term, right_target: Term) -> None:
        subst: dict[str, str] = {}
        if not match_pattern_term(left_pattern, left_target, pattern_vars, subst):
            return
        if not match_pattern_term(right_pattern, right_target, pattern_vars, subst):
            return
        if all((var in subst for var in lemma_eq['variables'])):
            rows.append(tuple((subst[var] for var in lemma_eq['variables'])))
    try_add(lemma_eq['lhs'], lemma_eq['rhs'], g_eq['lhs'], g_eq['rhs'])
    try_add(lemma_eq['lhs'], lemma_eq['rhs'], g_eq['rhs'], g_eq['lhs'])
    try_add(lemma_eq['rhs'], lemma_eq['lhs'], g_eq['lhs'], g_eq['rhs'])
    try_add(lemma_eq['rhs'], lemma_eq['lhs'], g_eq['rhs'], g_eq['lhs'])
    return unique_arg_rows(rows)

def candidate_lemma_args(lemma_eq: dict[str, Any], g_eq: dict[str, Any], limit: int):
    pool = unique(g_eq['variables'] + goal_terms(g_eq, 12))
    rows: list[tuple[str, ...]] = []
    for row in direct_lemma_goal_args(lemma_eq, g_eq):
        rows.append(row)
        if len(rows) >= limit:
            return unique_arg_rows(rows)
    for row in product(pool, repeat=len(lemma_eq['variables'])):
        rows.append(row)
        if len(rows) >= limit:
            break
    return unique_arg_rows(rows)

def safe_lean_name(raw: Any, fallback: str) -> str:
    base = re.sub("[^A-Za-z0-9_']", '_', str(raw or '').strip())
    base = re.sub('_+', '_', base).strip('_')
    if not base or not re.match('^[A-Za-z_]', base):
        base = fallback
    if base in {'G', 'h', 'inst', 'by', 'calc', 'have', 'intro', 'grind'}:
        base = fallback
    return base

def unique_lean_name(raw: Any, fallback: str, used: set[str]) -> str:
    base = safe_lean_name(raw, fallback)
    name = base
    idx = 2
    while name in used:
        name = f'{base}_{idx}'
        idx += 1
    used.add(name)
    return name

def equation_size(eq: dict[str, Any]) -> int:

    def size(t: Term) -> int:
        return 1 if t[0] == 'var' else 1 + size(t[1]) + size(t[2])
    return size(eq['lhs']) + size(eq['rhs'])

def all_tables_2() -> list[list[list[int]]]:
    out = []
    for values in product(range(2), repeat=4):
        out.append([list(values[:2]), list(values[2:])])
    return out

def hint_refutation(h_eq: dict[str, Any], hint_eq: dict[str, Any]) -> dict[str, Any] | None:
    for table in all_tables_2() + witness_tables() + list(structured_tables(3))[:6]:
        if eq_holds(h_eq, table) and (not eq_holds(hint_eq, table)):
            return {'kind': 'small_model_refutation', 'n': len(table), 'table': table, 'reason': 'table satisfies H but violates the proposed midpoint'}
    return None

def hint_score(hint: UniversalEquation, g_eq: dict[str, Any]) -> tuple[int, int, int]:
    goal_subterms = set(goal_terms(g_eq, 24))
    lhs = term_to_str(hint.eq['lhs'])
    rhs = term_to_str(hint.eq['rhs'])
    score = 0
    if lhs in goal_subterms:
        score += 8
    if rhs in goal_subterms:
        score += 8
    if helper_kind(hint.eq['text']):
        score += 4
    score += len(set(hint.eq['variables']) & set(g_eq['variables']))
    return (-score, equation_size(hint.eq), len(hint.eq['variables']))

def ordered_hints_for_payload(payload: dict[str, Any], hints: list[UniversalEquation], g_eq: dict[str, Any]) -> list[UniversalEquation]:
    kind = payload.get('tool') if payload.get('kind') == 'tool_call' else payload.get('kind')
    if kind in {'midpoint_chain', 'lemma_chain'}:
        return hints
    return sorted(hints, key=lambda hint: hint_score(hint, g_eq))

def hint_rows(value: Any) -> list[tuple[str, ...]]:
    return [tuple((str(cell) for cell in row)) for row in value or [] if isinstance(row, list) and all((isinstance(cell, str) for cell in row))]

def clean_equation_hint_text(raw: str) -> str:
    text = normalize(str(raw)).strip().strip('`')
    text = re.sub('^```(?:lean|json)?\\s*\\n?', '', text)
    text = re.sub('\\n?```\\s*$', '', text)
    text = re.sub('--.*$', '', text, flags=re.MULTILINE)
    text = re.sub('/-.*?-/', '', text, flags=re.DOTALL)
    text = text.split(':=', 1)[0].strip()
    text = re.sub("^\\s*(?:lemma|theorem|have)\\s+[A-Za-z0-9_']+\\s*:\\s*", '', text)
    if text.startswith('∀') or text.lower().startswith('forall'):
        parts = re.split(',', text, maxsplit=1)
        if len(parts) == 2:
            text = parts[1].strip()
    if ':' in text and '=' in text and (text.index(':') < text.index('=')):
        text = text.split(':', 1)[1].strip()
    text = text.splitlines()[0].strip().rstrip('.;')
    return text

def parse_universal_equations(payload: dict[str, Any]) -> list[UniversalEquation]:
    items: list[Any] = []
    payload_seed_rows = hint_rows(payload.get('seed_h_args') or payload.get('seed_args'))
    payload_use_rows = hint_rows(payload.get('use_args') or payload.get('lemma_args'))
    for key in ('lemma', 'midpoint', 'equation'):
        if isinstance(payload.get(key), str):
            items.append({'equation': payload[key], 'name': key})
    for key in ('lemmas', 'midpoints', 'lemma_chain', 'chain', 'steps', 'equations', 'lemma_hints', 'hints', 'candidates'):
        value = payload.get(key)
        if isinstance(value, str):
            items.append({'equation': value, 'name': key})
        elif isinstance(value, list):
            items.extend(value)
    out: list[UniversalEquation] = []
    used: set[str] = set()
    for idx, item in enumerate(items, start=1):
        if isinstance(item, str):
            eq_text = item
            raw_name = f'm{idx}'
            seed_rows: list[tuple[str, ...]] = []
            use_rows: list[tuple[str, ...]] = []
        elif isinstance(item, dict):
            eq_text = item.get('equation') or item.get('lemma') or item.get('claim') or item.get('text')
            raw_name = item.get('name') or item.get('kind') or f'm{idx}'
            seed_rows = hint_rows(item.get('seed_h_args') or item.get('seed_args'))
            if not seed_rows:
                seed_rows = payload_seed_rows
            use_rows = hint_rows(item.get('use_args') or item.get('lemma_args'))
            if not use_rows:
                use_rows = payload_use_rows
            origin_signature = item.get('_origin_signature')
            variant_kind = item.get('_variant_kind')
        else:
            continue
        if not isinstance(eq_text, str) or '=' not in eq_text:
            continue
        try:
            eq = parse_equation(clean_equation_hint_text(eq_text))
        except Exception:
            continue
        if eq['lhs'] == eq['rhs'] or len(eq['variables']) > 6 or equation_size(eq) > 40:
            continue
        name = unique_lean_name(raw_name, f'm{idx}', used)
        out.append(UniversalEquation(name=name, eq=eq, extra_args=seed_rows or use_rows, seed_args=seed_rows or None, use_args=use_rows or None, origin_signature=(str(origin_signature) if origin_signature else None) if isinstance(item, dict) else None, variant_kind=(str(variant_kind) if variant_kind else None) if isinstance(item, dict) else None))
    return out

def _canonical_hint_term(term: Term, variables: dict[str, str]) -> str:
    if term[0] == 'var':
        raw = str(term[1])
        if raw not in variables:
            variables[raw] = f'v{len(variables)}'
        return variables[raw]
    return f'({_canonical_hint_term(term[1], variables)}◇{_canonical_hint_term(term[2], variables)})'

def canonical_hint_signature(eq_or_text: dict[str, Any] | str) -> str:
    eq = eq_or_text if isinstance(eq_or_text, dict) else parse_equation(clean_equation_hint_text(eq_or_text))

    def oriented(left: Term, right: Term) -> str:
        variables: dict[str, str] = {}
        return f'{_canonical_hint_term(left, variables)}={_canonical_hint_term(right, variables)}'
    return min(oriented(eq['lhs'], eq['rhs']), oriented(eq['rhs'], eq['lhs']))

def _replace_variable_occurrence(term: Term, variable: str, occurrence: int, replacement: str, counts: dict[str, int]) -> Term:
    if term[0] == 'var':
        raw = str(term[1])
        counts[raw] = counts.get(raw, 0) + 1
        if raw == variable and counts[raw] == occurrence:
            return ('var', replacement)
        return term
    return ('op', _replace_variable_occurrence(term[1], variable, occurrence, replacement, counts), _replace_variable_occurrence(term[2], variable, occurrence, replacement, counts))

def fresh_variable_variants(hint: UniversalEquation, *, limit: int=4) -> list[UniversalEquation]:
    variables = list(hint.eq['variables'])
    if len(variables) >= 6:
        return []
    available = [ch for ch in 'abcdefghijklmnopqrstuv' if ch not in variables]
    if not available:
        return []
    occurrence_counts = Counter()

    def count_term(term: Term) -> None:
        if term[0] == 'var':
            occurrence_counts[str(term[1])] += 1
        else:
            count_term(term[1])
            count_term(term[2])
    count_term(hint.eq['lhs'])
    count_term(hint.eq['rhs'])
    variants: list[UniversalEquation] = []
    seen = {canonical_hint_signature(hint.eq)}
    for variable in variables:
        for occurrence in range(occurrence_counts[variable], 1, -1):
            replacement = available[0]
            counts: dict[str, int] = {}
            lhs = _replace_variable_occurrence(hint.eq['lhs'], variable, occurrence, replacement, counts)
            rhs = _replace_variable_occurrence(hint.eq['rhs'], variable, occurrence, replacement, counts)
            try:
                eq = parse_equation(f'{term_to_str(lhs)} = {term_to_str(rhs)}')
            except Exception:
                continue
            signature = canonical_hint_signature(eq)
            if signature in seen:
                continue
            seen.add(signature)
            variants.append(UniversalEquation(name=f'{hint.name}_fresh_{len(variants) + 1}', eq=eq, extra_args=list(hint.extra_args), seed_args=hint.seed_args, use_args=hint.use_args, origin_signature=canonical_hint_signature(hint.eq), variant_kind='fresh_variable_generalization'))
            if len(variants) >= limit:
                return variants
    return variants

def _match_hint_term(pattern: Term, target: Term, substitution: dict[str, Term]) -> bool:
    if pattern[0] == 'var':
        variable = str(pattern[1])
        previous = substitution.get(variable)
        if previous is None:
            substitution[variable] = target
            return True
        return previous == target
    return bool(target[0] == 'op' and _match_hint_term(pattern[1], target[1], substitution) and _match_hint_term(pattern[2], target[2], substitution))

def _substitute_hint_term(term: Term, substitution: dict[str, Term]) -> Term:
    if term[0] == 'var':
        return substitution.get(str(term[1]), term)
    return ('op', _substitute_hint_term(term[1], substitution), _substitute_hint_term(term[2], substitution))

def goal_specialization_variants(hint: UniversalEquation, g_eq: dict[str, Any], *, limit: int=2) -> list[UniversalEquation]:
    variants: list[UniversalEquation] = []
    seen = {canonical_hint_signature(hint.eq)}
    for pattern in (hint.eq['lhs'], hint.eq['rhs']):
        for target in (g_eq['lhs'], g_eq['rhs']):
            substitution: dict[str, Term] = {}
            if not _match_hint_term(pattern, target, substitution) or not substitution:
                continue
            lhs = _substitute_hint_term(hint.eq['lhs'], substitution)
            rhs = _substitute_hint_term(hint.eq['rhs'], substitution)
            if lhs == rhs:
                continue
            try:
                eq = parse_equation(f'{term_to_str(lhs)} = {term_to_str(rhs)}')
            except Exception:
                continue
            signature = canonical_hint_signature(eq)
            if signature in seen or len(eq['variables']) > 6:
                continue
            seen.add(signature)
            variants.append(UniversalEquation(name=f'{hint.name}_goal_{len(variants) + 1}', eq=eq, extra_args=list(hint.extra_args), seed_args=hint.seed_args, use_args=hint.use_args, origin_signature=canonical_hint_signature(hint.eq), variant_kind='goal_specialization'))
            if len(variants) >= limit:
                return variants
    return variants

def expand_hint_variants(hints: list[UniversalEquation], g_eq: dict[str, Any], *, limit: int=8) -> list[UniversalEquation]:
    originals: list[UniversalEquation] = []
    seen: set[str] = set()
    for hint in hints:
        signature = canonical_hint_signature(hint.eq)
        if signature in seen:
            continue
        seen.add(signature)
        hint.origin_signature = hint.origin_signature or signature
        hint.variant_kind = hint.variant_kind or 'llm_original'
        originals.append(hint)
    out = list(originals[:limit])
    for hint in originals:
        same_as_goal = canonical_hint_signature(hint.eq) == canonical_hint_signature(g_eq)
        variants = [*fresh_variable_variants(hint, limit=4 if same_as_goal else 2), *goal_specialization_variants(hint, g_eq, limit=2)]
        for variant in variants:
            signature = canonical_hint_signature(variant.eq)
            if signature in seen:
                continue
            seen.add(signature)
            out.append(variant)
            if len(out) >= limit:
                return out
    return out

@dataclass
class CandidateBlackboard:
    records: dict[str, dict[str, Any]] = field(default_factory=dict)
    events: list[dict[str, Any]] = field(default_factory=list)
    round_counter: int = 0

    def next_round(self) -> int:
        self.round_counter += 1
        return self.round_counter

    def snapshot(self) -> dict[str, Any]:
        rows = []
        for record in self.records.values():
            rows.append({key: record.get(key) for key in ('candidate_id', 'equation', 'status', 'variant_kind', 'first_round', 'last_round', 'proposal_count', 'leg_1', 'leg_2', 'need_hint') if record.get(key) is not None})
        rows.sort(key=lambda row: (row.get('first_round', 0), row.get('candidate_id', '')))
        return {'protocol_version': 'candidate-blackboard-v1', 'invariants': ['counterexample_found is decisive; budget-limited is not false', 'mechanically proved facts persist and are merged into later plans', 'alpha-renamed and reversed duplicates share one candidate id'], 'candidate_count': len(rows), 'candidates': rows[-10:]}

    def materialize_action(self, action: dict[str, Any], g_eq: dict[str, Any], *, round_index: int) -> tuple[dict[str, Any] | None, dict[str, Any]]:
        action_kind = action.get('tool') if action.get('kind') == 'tool_call' else action.get('kind')
        ordered_chain = action_kind in {'midpoint_chain', 'lemma_chain'}
        parsed_hints = parse_universal_equations(action)
        hints = parsed_hints if ordered_chain else expand_hint_variants(parsed_hints, g_eq)
        if not hints:
            return (action, protocol_state('CandidateBlackboardState', 'no_parseable_candidates', 'candidate_blackboard'))
        new_hints: list[UniversalEquation] = []
        blocked: list[dict[str, Any]] = []
        used_names: set[str] = set()
        for hint in hints:
            signature = canonical_hint_signature(hint.eq)
            record = self.records.get(signature)
            if record is not None and record.get('status') == 'counterexample_found':
                blocked.append({'candidate_id': record.get('candidate_id'), 'equation': record.get('equation'), 'reason': 'small model of H refutes this alpha/symmetry class'})
                continue
            seed_key = json.dumps({'seed': hint.seed_args or [], 'use': hint.use_args or []}, sort_keys=True)
            is_new_attempt = record is None or seed_key not in (record.get('attempt_keys') or [])
            if record is None:
                record = {'candidate_id': f'c{len(self.records) + 1}', 'signature': signature, 'equation': hint.eq['text'], 'name': hint.name, 'status': 'proposed', 'variant_kind': hint.variant_kind, 'origin_signature': hint.origin_signature, 'first_round': round_index, 'last_round': round_index, 'proposal_count': 0, 'attempt_keys': []}
                self.records[signature] = record
            record['last_round'] = round_index
            record['proposal_count'] = int(record.get('proposal_count') or 0) + 1
            if seed_key not in record['attempt_keys']:
                record['attempt_keys'].append(seed_key)
            if is_new_attempt:
                new_hints.append(hint)
        trusted_hints: list[UniversalEquation] = []
        for record in self.records.values():
            if record.get('status') not in {'mechanically_proved', 'proved_but_not_connected', 'second_leg_stuck'}:
                continue
            try:
                eq = parse_equation(record['equation'])
            except Exception:
                continue
            trusted_hints.append(UniversalEquation(name=unique_lean_name(record.get('name'), 'trusted', used_names), eq=eq, extra_args=[], origin_signature=record.get('origin_signature'), variant_kind=record.get('variant_kind') or 'persisted_proved_fact'))
        combined: list[UniversalEquation] = []
        seen: set[str] = set()
        for hint in [*trusted_hints, *new_hints]:
            signature = canonical_hint_signature(hint.eq)
            if signature in seen:
                continue
            seen.add(signature)
            hint.name = unique_lean_name(hint.name, f'm{len(combined) + 1}', used_names)
            combined.append(hint)
        if not new_hints:
            state = protocol_state('CandidateBlackboardState', 'no_new_candidates', 'candidate_blackboard', blocked_candidates=blocked, retained_proved_count=len(trusted_hints), need_hint='Every candidate was previously tried or refuted. Add a new bridge; proved-but-unconnected facts remain available in the blackboard.')
            self.events.append({'round': round_index, **state})
            return (None, state)
        materialized = {'kind': 'midpoint_chain', '_variants_expanded': True, '_ordered_chain': ordered_chain, 'lemmas': [{'name': hint.name, 'equation': hint.eq['text'], **({'_origin_signature': hint.origin_signature} if hint.origin_signature else {}), **({'_variant_kind': hint.variant_kind} if hint.variant_kind else {}), **({'seed_h_args': [list(row) for row in hint.seed_args]} if hint.seed_args else {}), **({'use_args': [list(row) for row in hint.use_args]} if hint.use_args else {})} for hint in combined]}
        for key in ('budget', 'time_budget', 'budget_policy'):
            if key in action:
                materialized[key] = action[key]
        state = protocol_state('CandidateBlackboardState', 'materialized', 'candidate_blackboard', new_candidate_count=len(new_hints), retained_proved_count=len(trusted_hints), blocked_candidates=blocked, candidate_ids=[self.records[canonical_hint_signature(hint.eq)]['candidate_id'] for hint in new_hints])
        self.events.append({'round': round_index, **state})
        return (materialized, state)

    def absorb_attempt(self, attempt_state: dict[str, Any], *, round_index: int) -> dict[str, Any]:
        updates = []
        conflicts = []
        for lifecycle in attempt_state.get('candidate_statuses') or []:
            equation = lifecycle.get('equation') if isinstance(lifecycle, dict) else None
            if not isinstance(equation, str):
                continue
            signature = canonical_hint_signature(equation)
            record = self.records.get(signature)
            if record is None:
                record = {'candidate_id': f'c{len(self.records) + 1}', 'signature': signature, 'equation': equation, 'name': lifecycle.get('name'), 'first_round': round_index, 'proposal_count': 1, 'attempt_keys': []}
                self.records[signature] = record
            incoming = str(lifecycle.get('status') or 'unproved_with_budget')
            prior = str(record.get('status') or 'proposed')
            if prior in {'mechanically_proved', 'proved_but_not_connected', 'second_leg_stuck'} and incoming == 'counterexample_found':
                conflicts.append({'candidate_id': record['candidate_id'], 'kind': 'refuted_after_proved'})
                continue
            if prior == 'counterexample_found' and incoming != 'counterexample_found':
                conflicts.append({'candidate_id': record['candidate_id'], 'kind': 'proved_after_refuted'})
                continue
            if incoming in {'proved_and_helpful', 'proved_but_not_connected', 'second_leg_stuck'}:
                record['status'] = 'mechanically_proved' if incoming == 'proved_and_helpful' else incoming
            elif prior not in {'mechanically_proved', 'proved_but_not_connected', 'second_leg_stuck'}:
                record['status'] = incoming
            record['last_round'] = round_index
            record['leg_1'] = lifecycle.get('leg_1')
            record['leg_2'] = lifecycle.get('leg_2')
            record['need_hint'] = lifecycle.get('need_hint')
            record['variant_kind'] = lifecycle.get('variant_kind') or record.get('variant_kind')
            updates.append({'candidate_id': record['candidate_id'], 'equation': record['equation'], 'status': record['status']})
        state = protocol_state('CandidateBlackboardUpdate', 'updated' if updates else 'no_candidate_update', 'candidate_blackboard', round=round_index, updates=updates, conflicts=conflicts, candidate_count=len(self.records), proved_fact_count=sum((record.get('status') in {'mechanically_proved', 'proved_but_not_connected', 'second_leg_stuck'} for record in self.records.values())))
        self.events.append(state)
        return state

def render_lemma_type(lemma_eq: dict[str, Any], args: tuple[str, ...]) -> tuple[str, str]:
    sub = {v: args[i] for i, v in enumerate(lemma_eq['variables'])}
    return (term_to_str_subst(lemma_eq['lhs'], sub), term_to_str_subst(lemma_eq['rhs'], sub))

def lemma_statement(lemma_eq: dict[str, Any]) -> str:
    lhs, rhs = (term_to_str(lemma_eq['lhs']), term_to_str(lemma_eq['rhs']))
    if not lemma_eq['variables']:
        return f'{lhs} = {rhs}'
    return f"∀ {' '.join(lemma_eq['variables'])} : G, {lhs} = {rhs}"

def build_graph_facts(h_eq: dict[str, Any], g_eq: dict[str, Any], limit: int=48, lemmas: list[dict[str, Any]] | None=None, lemma_limit: int=96, congruence_cap: int=0, extra_terms: list[str] | None=None, extra_args: list[tuple[str, ...]] | None=None):
    facts: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()

    def add(fact: dict[str, Any]):
        edge = (fact['lhs'], fact['rhs'])
        if edge in seen or (edge[1], edge[0]) in seen:
            return
        seen.add(edge)
        facts.append(fact)
    h_rows = unique_arg_rows(list(extra_args or []) + candidate_h_args(h_eq, g_eq, limit, extra_terms=extra_terms))
    for args in h_rows:
        lhs, rhs = render_h_type(h_eq, args)
        add({'name': f'f{len(facts) + 1}', 'kind': 'base', 'call': 'h ' + ' '.join(map(lean_arg, args)), 'lhs': lhs, 'rhs': rhs, 'deps': []})
    for lemma in lemmas or []:
        lemma_args = unique_arg_rows(list(lemma.get('extra_args') or []) + candidate_lemma_args(lemma['eq'], g_eq, lemma_limit))
        for args in lemma_args:
            lhs, rhs = render_lemma_type(lemma['eq'], args)
            add({'name': f'f{len(facts) + 1}', 'kind': 'base', 'call': lemma['name'] + ' ' + ' '.join(map(lean_arg, args)), 'lhs': lhs, 'rhs': rhs, 'deps': []})
    if congruence_cap <= 0:
        return facts
    contexts = unique(goal_terms(g_eq, 12) + g_eq['variables'])
    snapshot = list(facts)
    made = 0
    for fact in snapshot:
        for term in contexts:
            if made >= congruence_cap:
                return facts
            if term in (fact['lhs'], fact['rhs']):
                continue
            add({'name': f'f{len(facts) + 1}', 'kind': 'congruence', 'lhs': f"({fact['lhs']} ◇ {term})", 'rhs': f"({fact['rhs']} ◇ {term})", 'deps': [fact['name']], 'proof': f"by simpa using congrArg (fun __baby_arg => __baby_arg ◇ {term}) {fact['name']}"})
            made += 1
            if made >= congruence_cap:
                return facts
            add({'name': f'f{len(facts) + 1}', 'kind': 'congruence', 'lhs': f"({term} ◇ {fact['lhs']})", 'rhs': f"({term} ◇ {fact['rhs']})", 'deps': [fact['name']], 'proof': f"by simpa using congrArg (fun __baby_arg => {term} ◇ __baby_arg) {fact['name']}"})
            made += 1
    return facts

def fact_deps(facts_by_name: dict[str, dict[str, Any]], fact: dict[str, Any]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[str] = set()

    def visit(name: str):
        if name in seen:
            return
        seen.add(name)
        f = facts_by_name[name]
        for dep in f.get('deps', []):
            visit(dep)
        out.append(f)
    visit(fact['name'])
    return out

def h_graph_body(h_eq: dict[str, Any], g_eq: dict[str, Any], limit: int=48, lemmas=None, lemma_limit=96, congruence_cap=0, extra_terms=None, extra_args=None):
    facts = build_graph_facts(h_eq, g_eq, limit, lemmas=lemmas, lemma_limit=lemma_limit, congruence_cap=congruence_cap, extra_terms=extra_terms, extra_args=extra_args)
    facts_by_name = {f['name']: f for f in facts}
    start = term_to_str(g_eq['lhs'])
    target = term_to_str(g_eq['rhs'])
    adj: dict[str, list[tuple[str, dict[str, Any], bool]]] = {}
    for f in facts:
        adj.setdefault(f['lhs'], []).append((f['rhs'], f, False))
        adj.setdefault(f['rhs'], []).append((f['lhs'], f, True))
    parent: dict[str, tuple[str, dict[str, Any], bool] | None] = {start: None}
    queue = [start]
    while queue and target not in parent:
        cur = queue.pop(0)
        for nxt, fact, rev in adj.get(cur, []):
            if nxt not in parent:
                parent[nxt] = (cur, fact, rev)
                queue.append(nxt)
    if target not in parent:
        return None
    path = []
    node = target
    while parent[node] is not None:
        prev, fact, rev = parent[node]
        path.append((prev, node, fact, rev))
        node = prev
    path.reverse()
    intro = 'intro ' + ' '.join(g_eq['variables']) if g_eq['variables'] else ''
    if not path:
        return intro + '\nrfl'
    used: list[dict[str, Any]] = []
    seen_names: set[str] = set()
    for _, _, fact, _ in path:
        for f in fact_deps(facts_by_name, fact):
            if f['name'] not in seen_names:
                seen_names.add(f['name'])
                used.append(f)
    lines = [intro] if intro else []
    for f in used:
        if f['kind'] == 'base':
            lines.append(f"have {f['name']} := {f['call']}")
        else:
            lines.append(f"have {f['name']} : {f['lhs']} = {f['rhs']} := {f['proof']}")
    lines.append('calc')
    for i, (prev, nxt, fact, rev) in enumerate(path):
        lhs = prev if i == 0 else '_'
        suffix = '.symm' if rev else ''
        lines.append(f"  {lhs} = {nxt} := by simpa using {fact['name']}{suffix}")
    return '\n'.join(lines)

def short_text(text: str, limit: int=120) -> str:
    return text if len(text) <= limit else text[:limit - 3] + '...'

def compact_judge_diagnostic(result: dict[str, Any], limit: int=800) -> str:
    raw = str(result.get('stderr') or result.get('message') or '').strip()
    return raw if len(raw) <= limit else '...' + raw[-limit + 3:]

def classify_judge_failure(result: dict[str, Any]) -> str:
    status = str(result.get('status') or 'unknown').lower()
    if status == 'accepted':
        return 'accepted'
    if status == 'skipped':
        return str(result.get('reason') or 'skipped')
    raw = str(result.get('stderr') or result.get('message') or '')
    lowered = raw.lower()
    if 'maximum number of instances generated' in lowered:
        return 'grind_instance_limit'
    if 'maximum number of heartbeats' in lowered or ('heartbeat' in lowered and 'exceeded' in lowered):
        return 'heartbeat_limit'
    if 'lean_timeout' in lowered or 'timed out' in lowered or 'timeout' in lowered:
        return 'lean_timeout'
    if 'unknown identifier' in lowered:
        return 'unknown_identifier'
    if 'type mismatch' in lowered or 'application type mismatch' in lowered:
        return 'type_mismatch'
    if "declaration uses 'sorry'" in lowered or 'declaration uses ‘sorry’' in lowered:
        return 'disallowed_sorry'
    if 'unsolved goals' in lowered:
        return 'unsolved_goals'
    if '`grind` failed' in lowered or 'grind failed' in lowered:
        return 'grind_failed'
    if 'unexpected token' in lowered or 'parser' in lowered or 'syntax' in lowered:
        return 'lean_syntax_error'
    if result.get('error') or status in {'error', 'provider_error'}:
        return 'judge_infrastructure_error'
    return f'judge_{status}'

def judge_diagnostic_signals(result: dict[str, Any]) -> dict[str, Any]:
    raw = str(result.get('stderr') or result.get('message') or '').strip()
    lines = [line.rstrip() for line in raw.splitlines() if line.strip()]
    errors: list[str] = []
    goals: list[str] = []
    limits: list[str] = []
    for line in lines:
        stripped = line.strip()
        if 'error:' in stripped.lower() and stripped not in errors:
            errors.append(short_text(stripped, 360))
        if stripped.startswith('⊢') and stripped not in goals:
            goals.append(short_text(stripped[1:].strip(), 360))
        if (stripped.startswith('[limit]') or 'maximum number of instances generated' in stripped.lower() or 'maximum number of heartbeats' in stripped.lower()) and stripped not in limits:
            limits.append(short_text(stripped, 360))
    out: dict[str, Any] = {}
    if errors:
        out['error_lines'] = errors[:2]
    if goals:
        out['unresolved_goals'] = goals[-2:]
    if limits:
        out['limits_reached'] = limits[:3]
    if not out and raw:
        out['diagnostic_excerpt'] = compact_judge_diagnostic(result, 500)
    return out

def record_judge_feedback(route: str, verdict: str, code: str, result: dict[str, Any], *, source: str='baby_solver') -> None:
    entry: dict[str, Any] = {'attempt': len(_JUDGE_FEEDBACK_JOURNAL) + 1, 'route': route, 'verdict': verdict, 'status': str(result.get('status') or 'unknown'), 'failure_class': classify_judge_failure(result), 'source': source, 'certificate': {'characters': len(code), 'have_count': len(re.findall('(?m)^\\s*have\\s+', code)), 'uses_grind': bool(re.search('(?m)^\\s*grind\\b', code))}, **judge_diagnostic_signals(result)}
    _JUDGE_FEEDBACK_JOURNAL.append(entry)
    if len(_JUDGE_FEEDBACK_JOURNAL) > 16:
        del _JUDGE_FEEDBACK_JOURNAL[:-16]

def judge_feedback_json(*, attempt_limit: int=6, char_limit: int=6000) -> str:
    if not _JUDGE_FEEDBACK_JOURNAL:
        return json.dumps({'kind': 'JudgeAttemptSummary', 'attempt_count': 0, 'attempts': []})
    attempts = _JUDGE_FEEDBACK_JOURNAL[-max(1, attempt_limit):]
    payload = {'kind': 'JudgeAttemptSummary', 'attempt_count': len(_JUDGE_FEEDBACK_JOURNAL), 'omitted_older_attempts': max(0, len(_JUDGE_FEEDBACK_JOURNAL) - len(attempts)), 'attempts': attempts, 'instruction': 'Use failure_class, unresolved_goals, and limits_reached to change strategy; do not request the same failed certificate again.'}
    text = json.dumps(payload, ensure_ascii=False)
    if len(text) <= char_limit:
        return text
    compact_attempts = [{key: value for key, value in attempt.items() if key not in {'error_lines', 'diagnostic_excerpt'}} for attempt in attempts[-3:]]
    payload['attempts'] = compact_attempts
    payload['omitted_older_attempts'] = max(0, len(_JUDGE_FEEDBACK_JOURNAL) - len(compact_attempts))
    text = json.dumps(payload, ensure_ascii=False)
    while len(text) > char_limit and len(payload['attempts']) > 1:
        payload['attempts'] = payload['attempts'][1:]
        payload['omitted_older_attempts'] += 1
        text = json.dumps(payload, ensure_ascii=False)
    if len(text) <= char_limit:
        return text
    last = payload['attempts'][-1]
    return json.dumps({'kind': 'JudgeAttemptSummary', 'attempt_count': len(_JUDGE_FEEDBACK_JOURNAL), 'omitted_older_attempts': max(0, len(_JUDGE_FEEDBACK_JOURNAL) - 1), 'attempts': [{key: last.get(key) for key in ('attempt', 'route', 'verdict', 'status', 'failure_class')}], 'truncated': True}, ensure_ascii=False)

def right_context_contraction_actions(h_eq: dict[str, Any], target_eq: dict[str, Any]) -> list[dict[str, Any]]:
    actions: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_action(lemma: str, left_ctx: Term, simple_right: Term, complex_right: Term, orientation: str) -> None:
        if lemma in seen:
            return
        try:
            lemma_eq = parse_equation(lemma)
        except Exception:
            return
        refutation = hint_refutation(h_eq, lemma_eq)
        if refutation is not None:
            return
        seen.add(lemma)
        actions.append({'kind': 'midpoint', 'lemma': lemma, 'why': 'goal differs only in a right argument under the same left prefix; this reusable contraction can be proved once and then instantiated to the goal', 'target_match': {'orientation': orientation, 'left_context': term_to_str(left_ctx), 'simple_right': term_to_str(simple_right), 'complex_right': term_to_str(complex_right)}, 'refutation_checked': 'no_small_countermodel_found'})

    def inspect(left_ctx: Term, simple_right: Term, complex_right: Term, orientation: str) -> None:
        if simple_right[0] == 'var' and complex_right[0] == 'op' and (complex_right[1][0] == 'op') and (complex_right[1][1] == simple_right):
            add_action('a ◇ ((b ◇ c) ◇ d) = a ◇ b', left_ctx, simple_right, complex_right, orientation)
        if simple_right[0] == 'var' and complex_right[0] == 'op' and (complex_right[1] == simple_right) and (complex_right[2][0] == 'op'):
            add_action('a ◇ (b ◇ (c ◇ d)) = a ◇ b', left_ctx, simple_right, complex_right, orientation)
    lhs, rhs = (target_eq['lhs'], target_eq['rhs'])
    if lhs[0] == 'op' and rhs[0] == 'op' and (lhs[1] == rhs[1]):
        inspect(lhs[1], lhs[2], rhs[2], 'lhs_simple_rhs_complex')
        inspect(rhs[1], rhs[2], lhs[2], 'rhs_simple_lhs_complex')
    return actions

def goal_generalization_actions(h_eq: dict[str, Any], target_eq: dict[str, Any]) -> list[dict[str, Any]]:
    lhs, rhs = (target_eq['lhs'], target_eq['rhs'])
    actions: list[dict[str, Any]] = []
    seen: set[str] = set()

    def left_spine(t: Term) -> Term:
        while t[0] == 'op':
            t = t[1]
        return t

    def right_spine(t: Term) -> Term:
        while t[0] == 'op':
            t = t[2]
        return t

    def add(card: str, lemma: str, reason: str, *, action_kind: str='midpoint') -> None:
        if lemma in seen:
            return
        try:
            lemma_eq = parse_equation(lemma)
        except Exception:
            return
        refutation = hint_refutation(h_eq, lemma_eq)
        if refutation is not None:
            return
        seen.add(lemma)
        action: dict[str, Any]
        if action_kind == 'standard_aux':
            aux = []
            if lemma == 'a ◇ b = a':
                aux = ['proj_l']
            elif lemma == 'a ◇ b = b':
                aux = ['proj_r']
            elif lemma == 'a ◇ b = a ◇ c':
                aux = ['rowconst']
            elif lemma == 'a ◇ b = c ◇ b':
                aux = ['colconst']
            elif lemma == 'a = b':
                aux = ['const']
            action = {'kind': 'tool_call', 'tool': 'standard_aux_superposition', 'target': 'goal', 'lemmas': aux or ['const', 'proj_l', 'proj_r', 'rowconst'], 'budget': 10, 'why': reason}
        else:
            action = {'kind': 'midpoint', 'lemma': lemma, 'why': reason}
        actions.append({'card': card, 'lemma': lemma, 'reason': reason, 'action': action})
    if rhs[0] == 'op' and rhs[2] == lhs:
        add('generalize_goal_to_right_projection', 'a ◇ b = b', 'Goal is a special case of right projection: replace the compound goal term by a fresh variable.', action_kind='standard_aux')
    if lhs[0] == 'op' and lhs[2] == rhs:
        add('generalize_goal_to_right_projection', 'a ◇ b = b', 'Goal is a special case of right projection: prove a reusable projection law, then instantiate it.', action_kind='standard_aux')
    if rhs[0] == 'op' and rhs[1] == lhs:
        add('generalize_goal_to_left_projection', 'a ◇ b = a', 'Goal is a special case of left projection: replace the repeated outer term by a fresh variable.', action_kind='standard_aux')
    if lhs[0] == 'op' and lhs[1] == rhs:
        add('generalize_goal_to_left_projection', 'a ◇ b = a', 'Goal is a special case of left projection: prove a reusable projection law, then instantiate it.', action_kind='standard_aux')
    if rhs[0] == 'op' and left_spine(rhs) == lhs:
        add('generalize_nested_goal_to_left_projection', 'a ◇ b = a', 'Goal right side has left spine equal to the left side; left projection would collapse the whole tree.', action_kind='standard_aux')
    if lhs[0] == 'op' and left_spine(lhs) == rhs:
        add('generalize_nested_goal_to_left_projection', 'a ◇ b = a', 'Goal left side has left spine equal to the right side; left projection would collapse the whole tree.', action_kind='standard_aux')
    if rhs[0] == 'op' and right_spine(rhs) == lhs:
        add('generalize_nested_goal_to_right_projection', 'a ◇ b = b', 'Goal right side has right spine equal to the left side; right projection would collapse the whole tree.', action_kind='standard_aux')
    if lhs[0] == 'op' and right_spine(lhs) == rhs:
        add('generalize_nested_goal_to_right_projection', 'a ◇ b = b', 'Goal left side has right spine equal to the right side; right projection would collapse the whole tree.', action_kind='standard_aux')
    if lhs[0] == 'op' and rhs[0] == 'op':
        if lhs[1] == rhs[1] and lhs[2] != rhs[2]:
            add('generalize_same_left_to_rowconst', 'a ◇ b = a ◇ c', 'Goal has the same left argument on both sides; row-constancy is a stronger reusable bridge.', action_kind='standard_aux')
        if lhs[2] == rhs[2] and lhs[1] != rhs[1]:
            add('generalize_same_right_to_colconst', 'a ◇ b = c ◇ b', 'Goal has the same right argument on both sides; column-constancy is a stronger reusable bridge.')
    if h_eq['lhs'][0] == 'op' and lhs == h_eq['lhs'] and (rhs[0] == 'op'):
        add('rewrite_with_h_then_rowconst', 'a ◇ b = a ◇ c', "Goal left side matches H's left side; after one H rewrite, row-constancy may bridge the remaining right-argument mismatch.", action_kind='standard_aux')
    goal_subs = set(subterms(lhs) + subterms(rhs))
    if any((is_square(t) is not None for t in goal_subs)):
        add('square_terms_suggest_square_laws', 'a ◇ a = b ◇ b', 'Goal contains square terms; square-constancy is a common reusable midpoint.')
    return actions

def false_feedback_states(mechanical_feedback: list[dict[str, Any]] | None, limit: int | None=4) -> list[dict[str, Any]]:
    states: list[dict[str, Any]] = []

    def visit(value: Any) -> None:
        if isinstance(value, dict):
            if value.get('source') == 'false_model_search' or value.get('kind') == 'FalseModelSearchState':
                states.append(value)
            for key in ('tool_state', 'state', 'native_false_failed_attempts'):
                if key in value:
                    visit(value.get(key))
        elif isinstance(value, list):
            for item in value:
                visit(item)
    visit(mechanical_feedback or [])
    return states[-limit:] if limit is not None else states

def false_tried_routes_from_states(states: list[dict[str, Any]]) -> set[str]:
    routes: set[str] = set()
    for state in states:
        for trial in state.get('trials') or []:
            if isinstance(trial, dict) and trial.get('route') is not None:
                routes.add(str(trial.get('route')))
    return routes

def false_strategy_cards(mechanical_feedback: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
    cards: list[dict[str, Any]] = []
    seen_actions: set[str] = set()
    all_states = false_feedback_states(mechanical_feedback, limit=None)
    states = all_states[-4:]
    tried_routes = false_tried_routes_from_states(all_states)

    def add_card(card: dict[str, Any]) -> None:
        cards.append(card)

    def routes_already_tried(action: dict[str, Any]) -> bool:
        routes = [str(route) for route in action.get('routes') or []]
        return bool(routes) and all((route in tried_routes for route in routes))
    for state in reversed(states):
        next_call = state.get('recommended_next_call')
        if isinstance(next_call, dict):
            action = dict(next_call)
            action_routes = [str(route) for route in action.get('routes') or []]
            if routes_already_tried(action):
                continue
            highlights_for_budget = state.get('diagnostic_highlights') or {}
            cp_unknown_seen = any((isinstance(row, dict) and (row.get('unknown_skolems') or 0) for row in highlights_for_budget.get('cp_sat_route_summaries') or []))
            if cp_unknown_seen and any(('cp_sat' in route.lower() for route in action_routes)):
                action['budget'] = false_route_budget(action_routes, float(action.get('budget') or 0))
                action['why'] = 'follow false-search recommended_next_call; previous CP-SAT route reached UNKNOWN, so give the continuation more budget'
            sig = compact_tool_signature(action)
            if sig not in seen_actions:
                seen_actions.add(sig)
                add_card({'name': 'follow_false_recommended_next_call', 'principle': 'When false-search telemetry gives a concrete untried continuation, try that exact route before inventing another one.', 'trigger': 'A previous false_model_search route failed but emitted recommended_next_call.', 'recommended_action': action})
        highlights = state.get('diagnostic_highlights') or {}
        for row in highlights.get('cp_sat_route_summaries') or []:
            if not isinstance(row, dict) or not (row.get('unknown_skolems') or 0):
                continue
            route = str(row.get('route') or '')
            m = re.search('n=?(\\d+)', route)
            n = int(m.group(1)) if m else int(row.get('n') or 0)
            retry = {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': [f'cp_sat:n={n}'], 'budget': false_route_budget([f'cp_sat:n={n}'], 16.0), 'why': 'exact CP-SAT reached UNKNOWN; retry same carrier with more budget before changing route family'}
            nxt = {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': [f'cp_sat:n={min(9, n + 1)}'], 'budget': false_route_budget([f'cp_sat:n={min(9, n + 1)}'], 16.0), 'why': 'exact CP-SAT reached UNKNOWN; try the next carrier size if the same size remains unknown'}
            for action in (retry, nxt):
                if routes_already_tried(action):
                    continue
                sig = compact_tool_signature(action)
                if sig not in seen_actions:
                    seen_actions.add(sig)
                    add_card({'name': 'cp_sat_unknown_continuation', 'principle': 'UNKNOWN is not failure: continue exact finite-domain search with more budget or the next carrier size.', 'trigger': f"{route or 'cp_sat'} reached UNKNOWN on {row.get('unknown_skolems')} Skolem branches.", 'recommended_action': action})
        for row in highlights.get('sympy_sat_route_summaries') or []:
            if not isinstance(row, dict) or row.get('status') not in {'timeout', 'unsat_or_timeout'}:
                continue
            route = str(row.get('route') or '')
            m = re.search('n=?(\\d+)', route)
            n = int(m.group(1)) if m else int(row.get('n') or 0)
            if n <= 0:
                continue
            action = {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': [f'sympy_sat:n={n}'], 'budget': false_route_budget([f'sympy_sat:n={n}'], 120.0), 'why': 'sympy exact SAT timed out; retry only this carrier with the full exact-search budget'}
            if routes_already_tried(action):
                continue
            sig = compact_tool_signature(action)
            if sig not in seen_actions:
                seen_actions.add(sig)
                add_card({'name': 'sympy_sat_timeout_continuation', 'principle': 'A timed-out exact SAT route is inconclusive; retry a single carrier with a real budget before changing hypothesis.', 'trigger': f"{route or 'sympy_sat'} timed out or mixed UNSAT/timeouts.", 'recommended_action': action})
        progress = highlights.get('best_partial_progress')
        if isinstance(progress, dict) and (progress.get('assigned_ratio') or 0) >= 0.8:
            route = str(progress.get('route') or '')
            m = re.search('n=?(\\d+)', route)
            n = int(m.group(1)) if m else None
            if n:
                action = {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': [f'local_search:n={n}:seed=0'], 'budget': 10, 'why': 'propagation reached a nearly complete partial table; try nearby stochastic completions at the same carrier'}
                if routes_already_tried(action):
                    continue
                sig = compact_tool_signature(action)
                if sig not in seen_actions:
                    seen_actions.add(sig)
                    add_card({'name': 'complete_near_partial_table', 'principle': 'When propagation nearly fills a table but times out, switch to nearby local_search completions at the same carrier.', 'trigger': f"{route} reached assigned_ratio={progress.get('assigned_ratio')}.", 'recommended_action': action})

    def priority(card: dict[str, Any]) -> tuple[int, str]:
        action = card.get('recommended_action') or {}
        routes = [str(route).lower() for route in action.get('routes') or []] if isinstance(action, dict) else []
        if card.get('name') == 'follow_false_recommended_next_call' and any(('cp_sat' in route or 'cpsat' in route for route in routes)):
            return (0, str(card.get('name') or ''))
        if any(('cp_sat' in route or 'cpsat' in route for route in routes)):
            return (1, str(card.get('name') or ''))
        if any(('sympy_sat' in route or 'sympy' in route for route in routes)):
            return (1, str(card.get('name') or ''))
        if card.get('name') == 'complete_near_partial_table':
            return (2, str(card.get('name') or ''))
        if card.get('name') == 'follow_false_recommended_next_call':
            return (3, str(card.get('name') or ''))
        return (4, str(card.get('name') or ''))
    return sorted(cards, key=priority)[:6]

def top_false_recommended_action(mechanical_feedback: list[dict[str, Any]] | None) -> dict[str, Any] | None:
    for card in false_strategy_cards(mechanical_feedback):
        action = card.get('recommended_action')
        if isinstance(action, dict) and action.get('tool') == 'false_model_search':
            return action
    return None

def promoted_exact_false_action(mechanical_feedback: list[dict[str, Any]] | None) -> dict[str, Any] | None:
    states = false_feedback_states(mechanical_feedback, limit=None)
    if not states:
        return None
    highlights = states[-1].get('diagnostic_highlights') or {}
    progress = highlights.get('best_partial_progress') or {}
    try:
        assigned_ratio = float(progress.get('assigned_ratio') or 0.0)
    except Exception:
        assigned_ratio = 0.0
    if assigned_ratio < 0.65:
        return None
    action = top_false_recommended_action(mechanical_feedback)
    if not isinstance(action, dict):
        return None
    routes = [str(route).lower() for route in action.get('routes') or []]
    if any(('sympy_sat' in route or 'cp_sat' in route or 'cpsat' in route for route in routes)):
        promoted = dict(action)
        promoted['budget'] = false_route_budget(promoted.get('routes') or [], float(promoted.get('budget') or 0))
        promoted['why'] = 'native false telemetry reached a near-complete partial table; follow this exact route before LLM recovery'
        return promoted
    return None

def strategy_cards(h_eq: dict[str, Any], g_eq: dict[str, Any], mechanical_feedback: list[dict[str, Any]] | None=None, *, prefer_false: bool | str=False) -> list[dict[str, Any]]:
    cards: list[dict[str, Any]] = []
    for item in goal_generalization_actions(h_eq, g_eq):
        cards.append({'name': item['card'], 'principle': 'If G is a special instance of a simpler universal law, try the universal law first.', 'trigger': item['reason'], 'recommended_action': item['action']})
    if repeated_self_absorption_h(h_eq, g_eq):
        cards.append({'name': 'self_absorption_midpoint_chain', 'principle': 'When H rewrites a variable to a term containing repeated copies of the same variable, a multi-rung absorption chain is often better than one large direct midpoint.', 'trigger': 'H has x = T with x repeated inside T, and G asks for x = compound.', 'recommended_action': {'kind': 'tool_call', 'tool': 'lemma_chain', 'target': 'goal', 'lemmas': [{'name': 'absorb_step', 'equation': '<small absorption/contraction equation near a closest_pair>'}, {'name': 'goal_bridge', 'equation': '<second bridge that consumes the first helper toward G>'}], 'why': 'Use SearchState closest_pairs to fill the placeholders; the mechanical side will prove each rung before using it.'}})
    cards.extend([{'name': 'prefer_reusable_over_goal_specific', 'principle': 'A direct closest-pair bridge may be too specific; prefer a reusable projection, rowconst, opconst, square_const, or contraction law when it would imply G.', 'recommended_actions': [{'kind': 'midpoint', 'lemma': 'a ◇ b = a', 'why': 'left projection candidate'}, {'kind': 'midpoint', 'lemma': 'a ◇ b = b', 'why': 'right projection candidate'}, {'kind': 'midpoint', 'lemma': 'a ◇ b = a ◇ c', 'why': 'row-constant candidate'}, {'kind': 'midpoint', 'lemma': 'a ◇ b = c ◇ d', 'why': 'operation collapses to a constant product'}]}, {'name': 'repair_failed_specific_hint', 'principle': 'If a hinted bridge proves but does not close G, strengthen or generalize it; if it is refuted, change family instead of repeating it.', 'recommended_action': {'kind': 'tool_call', 'tool': 'lemma_chain', 'target': 'goal', 'lemmas': [{'name': 'proj_l', 'equation': 'a ◇ b = a'}, {'name': 'proj_r', 'equation': 'a ◇ b = b'}]}}, {'name': 'use_feedback_not_transcript', 'principle': 'Use SearchState closest_pairs, proved_not_consumed helpers, and refuted_by_small_model results to choose the next action.', 'recommended_action': {'kind': 'tool_call', 'tool': 'lemma_hint', 'target': 'goal', 'lemmas': [{'equation': '<non-refuted reusable bridge suggested by feedback>'}]}}])
    if prefer_false is True or prefer_false == 'balanced':
        cards = false_strategy_cards(mechanical_feedback) + cards
    return cards[:6]

def strategy_cards_text(h_eq: dict[str, Any], g_eq: dict[str, Any], mechanical_feedback: list[dict[str, Any]] | None=None, *, prefer_false: bool | str=False) -> str:
    return json.dumps(strategy_cards(h_eq, g_eq, mechanical_feedback, prefer_false=prefer_false), ensure_ascii=False)

def graph_search_state(h_eq: dict[str, Any], target_eq: dict[str, Any], assumptions: list[UniversalEquation] | None=None, *, h_limit: int=80, lemma_limit: int=180, congruence_cap: int=1600, status: str='stuck', failed_hints: list[dict[str, Any]] | None=None, extra_terms: list[str] | None=None, extra_args: list[tuple[str, ...]] | None=None) -> dict[str, Any]:
    lemmas = [assumption.as_lemma() for assumption in assumptions or []]
    facts = build_graph_facts(h_eq, target_eq, h_limit, lemmas=lemmas, lemma_limit=lemma_limit, congruence_cap=congruence_cap, extra_terms=extra_terms, extra_args=extra_args)
    start = term_to_str(target_eq['lhs'])
    target = term_to_str(target_eq['rhs'])
    adj: dict[str, set[str]] = {}
    for fact in facts:
        adj.setdefault(fact['lhs'], set()).add(fact['rhs'])
        adj.setdefault(fact['rhs'], set()).add(fact['lhs'])

    def component(seed: str) -> set[str]:
        seen = {seed}
        queue = [seed]
        while queue:
            cur = queue.pop(0)
            for nxt in adj.get(cur, set()):
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
        return seen

    def sample_terms(terms: set[str], n: int=6) -> list[str]:
        return [short_text(t) for t in sorted(terms, key=lambda s: (len(s), s))[:n]]
    left_comp = component(start)
    right_comp = component(target)
    left_sample = sample_terms(left_comp)
    right_sample = sample_terms(right_comp)
    pairs: list[dict[str, Any]] = []
    for left in left_sample[:6]:
        for right in right_sample[:6]:
            pairs.append({'left': left, 'right': right, 'similarity': round(difflib.SequenceMatcher(None, left, right).ratio(), 3)})
    pairs.sort(key=lambda p: p['similarity'], reverse=True)
    contraction_actions = right_context_contraction_actions(h_eq, target_eq)
    closest_action = {'kind': 'midpoint', 'lemma': f"{pairs[0]['left']} = {pairs[0]['right']}" if pairs else f'{short_text(start)} = {short_text(target)}', 'why': 'candidate bridge between current equality components'}
    suggested_next_actions = contraction_actions + ([closest_action] if status != 'proved' else [])
    recommended_next_action = suggested_next_actions[0] if suggested_next_actions and status != 'proved' else None
    return {'protocol_version': PROTOCOL_VERSION, 'kind': 'SearchState', 'status': status, 'source': 'graph_search', 'target': target_eq['text'], 'goal_left': short_text(start), 'goal_right': short_text(target), 'attempt': {'h_limit': h_limit, 'lemma_limit': lemma_limit, 'congruence_cap': congruence_cap, 'extra_terms': [short_text(t) for t in extra_terms or []][:8]}, 'facts_generated': len(facts), 'assumptions': [{'name': assumption.name, 'equation': assumption.eq['text']} for assumption in assumptions or []], 'seed_h_args_used': [list(row) for row in extra_args or []][:8], 'left_component_size': len(left_comp), 'right_component_size': len(right_comp), 'left_frontier': left_sample, 'right_frontier': right_sample, 'closest_pairs': pairs[:4], 'need_hint': {'kind': 'bridge_terms', 'left_term': pairs[0]['left'] if pairs else short_text(start), 'right_term': pairs[0]['right'] if pairs else short_text(target), 'reason': 'would connect the target equality components', 'recommended_next_action': recommended_next_action}, 'suggested_next_actions': suggested_next_actions if status != 'proved' else [], 'failed_hints': failed_hints or []}

def term_size(t: Term) -> int:
    return 1 if t[0] == 'var' else 1 + term_size(t[1]) + term_size(t[2])

def term_key(t: Term) -> str:
    return t[1] if t[0] == 'var' else '(' + term_key(t[1]) + term_key(t[2]) + ')'
NATIVE_SATURATION_CONFIGS: tuple[tuple[int, int, int, int], ...] = ((2, 10, 1, 16), (2, 10, 2, 24), (3, 14, 2, 40), (3, 14, 3, 48))

def instantiate_term(t: Term, subst: dict[str, Term]) -> Term:
    if t[0] == 'var':
        return subst.get(t[1], t)
    return ('op', instantiate_term(t[1], subst), instantiate_term(t[2], subst))

def native_saturation_combos(h_eq: dict[str, Any], g_eq: dict[str, Any], *, depth: int, pool_cap: int, slots: int) -> list[tuple[Term, ...]]:
    h_vars = list(h_eq['variables'])
    if not h_vars:
        return []
    goal_vars = list(g_eq['variables'])
    if not goal_vars:
        return []
    pad: Term = ('var', goal_vars[0])
    pool = sorted(set(subterms(g_eq['lhs']) + subterms(g_eq['rhs'])), key=lambda term: (term_size(term), term_key(term)))
    rows: list[tuple[Term, ...]] = []
    seen_rows: set[tuple[Term, ...]] = set()

    def add_row(row: tuple[Term, ...]) -> None:
        if row not in seen_rows:
            seen_rows.add(row)
            rows.append(row)
    for _round in range(max(1, depth)):
        new_terms: set[Term] = set()
        round_rows: list[tuple[Term, ...]] = []
        current = list(pool)
        for position in range(min(max(1, slots), len(h_vars))):
            for term in current:
                row = [pad for _ in h_vars]
                row[position] = term
                round_rows.append(tuple(row))
        round_rows.append(tuple((pad for _ in h_vars)))
        for row in round_rows:
            if row in seen_rows:
                continue
            add_row(row)
            subst = dict(zip(h_vars, row))
            new_terms.update(subterms(instantiate_term(h_eq['rhs'], subst)))
        pool = sorted(set(pool) | new_terms, key=lambda term: (term_size(term), term_key(term)))[:max(1, pool_cap)]
    return rows

def native_saturation_bodies(h_eq: dict[str, Any], g_eq: dict[str, Any]):
    goal_vars = list(g_eq['variables'])
    if not goal_vars or not h_eq['variables']:
        return
    intro = 'intro ' + ' '.join(goal_vars)
    seen: set[str] = set()
    for depth, pool_cap, slots, have_cap in NATIVE_SATURATION_CONFIGS:
        rows = native_saturation_combos(h_eq, g_eq, depth=depth, pool_cap=pool_cap, slots=slots)[:have_cap]
        if not rows:
            continue
        haves = [f'have sat{i} := h ' + ' '.join((lean_arg(term_to_str(term)) for term in row)) for i, row in enumerate(rows, start=1)]
        body = '\n'.join([intro, *haves, 'grind'])
        if body in seen:
            continue
        seen.add(body)
        yield (f'deep_saturation:d={depth}:slots={slots}:haves={len(rows)}', body)

def grounding_h_certificate_bodies(h_eq: dict[str, Any], g_eq: dict[str, Any]):
    lhs_vars = set(term_variables(h_eq['lhs']))
    rhs_vars = set(term_variables(h_eq['rhs']))
    only_l = lhs_vars - rhs_vars
    only_r = rhs_vars - lhs_vars
    goal_vars = list(g_eq['variables'])
    if not only_l or not only_r or (not goal_vars):
        return
    witness = goal_vars[0]
    lhs_binders = [v for v in h_eq['variables'] if v in lhs_vars]
    rhs_binders = [v for v in h_eq['variables'] if v in rhs_vars]
    args_a = [witness if v in only_r else v for v in h_eq['variables']]
    args_b = [witness if v in only_l else v for v in h_eq['variables']]
    lhs_grounded = term_to_str_subst(h_eq['lhs'], {v: witness for v in only_r})
    rhs_grounded = term_to_str_subst(h_eq['rhs'], {v: witness for v in only_r})
    lhs_grounded_b = term_to_str_subst(h_eq['lhs'], {v: witness for v in only_l})
    rhs_grounded_b = term_to_str_subst(h_eq['rhs'], {v: witness for v in only_l})
    prefix = ['intro ' + ' '.join(goal_vars)]
    prefix.extend([f"have groundA : ∀ {' '.join(lhs_binders)} : G, {lhs_grounded} = {rhs_grounded} := fun {' '.join(lhs_binders)} => h {' '.join(map(lean_arg, args_a))}", f"have groundB : ∀ {' '.join(rhs_binders)} : G, {rhs_grounded_b} = {lhs_grounded_b} := fun {' '.join(rhs_binders)} => (h {' '.join(map(lean_arg, args_b))}).symm"])
    yield ('grounding_h:base', '\n'.join([*prefix, 'grind']))
    flood_terms = list(goal_vars)
    flood_tiers = [flood_terms + [f'({witness} ◇ {witness})'], flood_terms + [f'({witness} ◇ {witness})', f'({witness} ◇ ({witness} ◇ {witness}))']]
    accumulated: list[str] = []
    have_index = 0
    for tier_index, terms in enumerate(flood_tiers, start=1):
        for lemma_name, binders in (('groundA', lhs_binders), ('groundB', rhs_binders)):
            emitted = 0
            for args in product(terms, repeat=len(binders)):
                have_index += 1
                emitted += 1
                accumulated.append(f'have ground_use{have_index} := {lemma_name} ' + ' '.join(map(lean_arg, args)))
                if emitted >= 128:
                    break
        yield (f'grounding_h:flood={tier_index}', '\n'.join([*prefix, *accumulated, 'grind']))

def pc_canon(l: Term, r: Term) -> tuple[Term, Term]:
    if term_size(l) > term_size(r) or (term_size(l) == term_size(r) and term_key(l) > term_key(r)):
        l, r = (r, l)
    ren: dict[str, Term] = {}

    def go(t: Term) -> Term:
        if t[0] == 'var':
            if str(t[1]).startswith('#'):
                return t
            if t[1] not in ren:
                ren[t[1]] = ('var', f'v{len(ren)}')
            return ren[t[1]]
        return ('op', go(t[1]), go(t[2]))
    return (go(l), go(r))

def pc_walk(t: Term, sub: dict[str, Term]) -> Term:
    while t[0] == 'var' and t[1] in sub:
        t = sub[t[1]]
    return t

def pc_occurs(v: str, t: Term, sub: dict[str, Term]) -> bool:
    t = pc_walk(t, sub)
    if t[0] == 'var':
        return t[1] == v
    return pc_occurs(v, t[1], sub) or pc_occurs(v, t[2], sub)

def pc_unify(s: Term, t: Term, sub: dict[str, Term]) -> dict[str, Term] | None:
    s = pc_walk(s, sub)
    t = pc_walk(t, sub)
    if s[0] == 'var' and (not str(s[1]).startswith('#')):
        if s == t:
            return sub
        if pc_occurs(s[1], t, sub):
            return None
        sub2 = dict(sub)
        sub2[s[1]] = t
        return sub2
    if t[0] == 'var' and (not str(t[1]).startswith('#')):
        return pc_unify(t, s, sub)
    if s[0] == 'op' and t[0] == 'op':
        sub2 = pc_unify(s[1], t[1], sub)
        return None if sub2 is None else pc_unify(s[2], t[2], sub2)
    return sub if s == t else None

def pc_apply(t: Term, sub: dict[str, Term]) -> Term:
    t = pc_walk(t, sub)
    if t[0] == 'var':
        return t
    return ('op', pc_apply(t[1], sub), pc_apply(t[2], sub))

def pc_positions(t: Term, p: tuple[int, ...]=()) -> list[tuple[tuple[int, ...], Term]]:
    out = [(p, t)]
    if t[0] == 'op':
        out += pc_positions(t[1], p + (0,))
        out += pc_positions(t[2], p + (1,))
    return out

def pc_replace_at(t: Term, p: tuple[int, ...], r: Term) -> Term:
    if not p:
        return r
    if p[0] == 0:
        return ('op', pc_replace_at(t[1], p[1:], r), t[2])
    return ('op', t[1], pc_replace_at(t[2], p[1:], r))

def pc_vars_of(t: Term, acc: list[str] | None=None) -> list[str]:
    acc = acc if acc is not None else []
    if t[0] == 'var':
        if not str(t[1]).startswith('#') and t[1] not in acc:
            acc.append(t[1])
    else:
        pc_vars_of(t[1], acc)
        pc_vars_of(t[2], acc)
    return acc

def pc_apply_names(t: Term, rho: dict[str, str]) -> Term:
    if t[0] == 'var':
        return ('var', rho.get(t[1], t[1]))
    return ('op', pc_apply_names(t[1], rho), pc_apply_names(t[2], rho))

def pc_rename_tracked(binders: list[str], lhs: Term, rhs: Term, counter: list[int]) -> tuple[list[str], Term, Term]:
    ren = {v: f'_s{counter[0] + i}' for i, v in enumerate(binders)}
    counter[0] += len(binders)

    def go(t: Term) -> Term:
        return ('var', ren[t[1]]) if t[0] == 'var' else ('op', go(t[1]), go(t[2]))
    return ([ren[v] for v in binders], go(lhs), go(rhs))

def pc_paramodulants(rec_a: dict[str, Any], rec_b: dict[str, Any], counter: list[int], max_size: int, allow_var_overlap: bool=False):
    fb_a, la_a, ra_a = pc_rename_tracked(rec_a['binders'], rec_a['lhs'], rec_a['rhs'], counter)
    fb_b, la_b, ra_b = pc_rename_tracked(rec_b['binders'], rec_b['lhs'], rec_b['rhs'], counter)
    out = []
    for la, ra, a_symm in ((la_a, ra_a, False), (ra_a, la_a, True)):
        for lb, rb, b_symm in ((la_b, ra_b, False), (ra_b, la_b, True)):
            for pos, subterm in pc_positions(la):
                if subterm[0] == 'var' and (not allow_var_overlap):
                    continue
                subst = pc_unify(subterm, lb, {})
                if subst is None:
                    continue
                rl = pc_apply(pc_replace_at(la, pos, rb), subst)
                rr = pc_apply(ra, subst)
                if rl == rr or term_size(rl) + term_size(rr) > max_size:
                    continue
                args_a = [pc_apply(('var', fb_a[k]), subst) for k in range(len(rec_a['binders']))]
                args_b = [pc_apply(('var', fb_b[k]), subst) for k in range(len(rec_b['binders']))]
                all_vars: list[str] = []
                for t in [rl, rr] + args_a + args_b:
                    for v in pc_vars_of(t):
                        if v not in all_vars:
                            all_vars.append(v)
                rho = {v: f'v{k}' for k, v in enumerate(all_vars)}
                cl = lambda t: pc_apply_names(t, rho)
                before = cl(pc_apply(la, subst))
                source_l = cl(pc_apply(lb, subst))
                source_r = cl(pc_apply(rb, subst))
                out.append((cl(rl), cl(rr), [f'v{k}' for k in range(len(all_vars))], [cl(a) for a in args_a], [cl(a) for a in args_b], {'before': before, 'source_l': source_l, 'source_r': source_r, 'pos': pos, 'a_symm': a_symm, 'b_symm': b_symm}))
    return out

def pc_saturate(start: list[tuple[Term, Term]], target, max_rounds: int=5, max_eqs: int=900, max_size: int=20, time_budget: float | None=None, cpu_budget: float | None=None, allow_var_overlap: bool=False) -> tuple[int | None, list[dict[str, Any]], dict[str, Any]]:
    deadline = time.monotonic() + time_budget if time_budget else None
    cpu_deadline = time.process_time() + cpu_budget if cpu_budget else None
    counter = [0]
    recs: list[dict[str, Any]] = []
    seen: dict[tuple[str, str], int] = {}
    meta = {'rounds': 0, 'stop_reason': 'saturated', 'max_rounds': max_rounds, 'max_eqs': max_eqs, 'max_size': max_size, 'budget_clock': 'cpu_with_wall_cap' if cpu_deadline is not None else 'wall'}

    def budget_exhausted() -> bool:
        if deadline is not None and time.monotonic() > deadline:
            meta['stop_reason'] = 'time_budget'
            meta['limit_clock'] = 'wall'
            return True
        if cpu_deadline is not None and time.process_time() > cpu_deadline:
            meta['stop_reason'] = 'time_budget'
            meta['limit_clock'] = 'cpu'
            return True
        return False

    def add(l: Term, r: Term, binders: list[str], deriv, base=None) -> int | None:
        cl, cr = pc_canon(l, r)
        if cl == cr:
            return None
        sig = (term_key(cl), term_key(cr))
        if sig in seen:
            return seen[sig]
        rid = len(recs)
        recs.append({'lhs': l, 'rhs': r, 'binders': binders, 'deriv': deriv, 'base': base})
        seen[sig] = rid
        return rid
    for i, (l, r) in enumerate(start):
        binders = pc_vars_of(l) + [v for v in pc_vars_of(r) if v not in pc_vars_of(l)]
        rid = add(l, r, binders, None, i)
        if rid is not None and target((recs[rid]['lhs'], recs[rid]['rhs'])):
            meta['stop_reason'] = 'target_found'
            return (rid, recs, meta)
    for round_idx in range(max_rounds):
        meta['rounds'] = round_idx + 1
        added = False
        ids = list(range(len(recs)))
        for i in ids:
            if budget_exhausted():
                return (None, recs, meta)
            for j in ids:
                if budget_exhausted():
                    return (None, recs, meta)
                for rl, rr, binders, args_a, args_b, proof_info in pc_paramodulants(recs[i], recs[j], counter, max_size, allow_var_overlap=allow_var_overlap):
                    before = len(recs)
                    rid = add(rl, rr, binders, (i, j, args_a, args_b, proof_info))
                    if rid is not None and rid == before:
                        added = True
                        if target((recs[rid]['lhs'], recs[rid]['rhs'])):
                            meta['stop_reason'] = 'target_found'
                            return (rid, recs, meta)
        if not added:
            meta['stop_reason'] = 'saturated'
            break
        if len(recs) > max_eqs:
            meta['stop_reason'] = 'max_eqs'
            break
    return (None, recs, meta)

def pc_derivation_chain(target_id: int, recs: list[dict[str, Any]]) -> list[int]:
    need: set[int] = set()
    order: list[int] = []

    def visit(rid: int) -> None:
        if rid in need:
            return
        deriv = recs[rid]['deriv']
        if deriv is not None:
            visit(deriv[0])
            visit(deriv[1])
        need.add(rid)
        order.append(rid)
    visit(target_id)
    return order

def pc_arg(t: Term) -> str:
    return t[1] if t[0] == 'var' else f'({term_to_str(t)})'

def pc_term_with_hole(t: Term, pos: tuple[int, ...], hole: str='__pc_hole') -> str:
    if not pos:
        return hole
    if t[0] == 'var':
        return term_to_str(t)
    if pos[0] == 0:
        return f'({pc_term_with_hole(t[1], pos[1:], hole)} ◇ {term_to_str(t[2])})'
    return f'({term_to_str(t[1])} ◇ {pc_term_with_hole(t[2], pos[1:], hole)})'

def pc_oriented_expr(name: str, symm: bool) -> str:
    return f'({name}).symm' if symm else name

def pc_match_term(pat: Term, val: Term, binders: set[str], sub: dict[str, Term]) -> dict[str, Term] | None:
    if pat[0] == 'var' and pat[1] in binders:
        old = sub.get(pat[1])
        if old is None:
            sub2 = dict(sub)
            sub2[pat[1]] = val
            return sub2
        return sub if old == val else None
    if pat[0] == 'op' and val[0] == 'op':
        s1 = pc_match_term(pat[1], val[1], binders, sub)
        return None if s1 is None else pc_match_term(pat[2], val[2], binders, s1)
    return sub if pat == val else None

def pc_target_proof_expr(name: str, lhs_pat: Term, rhs_pat: Term, binders: list[str], goal_lhs: Term | None, goal_rhs: Term | None) -> str | None:
    if goal_lhs is None or goal_rhs is None or (not binders):
        return None

    def try_match(a: Term, b: Term, symm: bool) -> str | None:
        sub = pc_match_term(lhs_pat, a, set(binders), {})
        if sub is None:
            return None
        sub = pc_match_term(rhs_pat, b, set(binders), sub)
        if sub is None or any((v not in sub for v in binders)):
            return None
        args = ' '.join((pc_arg(sub[v]) for v in binders))
        call = f'{name} {args}' if args else name
        return f'({call}).symm' if symm else call
    return try_match(goal_lhs, goal_rhs, False) or try_match(goal_rhs, goal_lhs, True)

def pc_target_exact_line(name: str, lhs_pat: Term, rhs_pat: Term, binders: list[str], goal_lhs: Term | None, goal_rhs: Term | None) -> str | None:
    expr = pc_target_proof_expr(name, lhs_pat, rhs_pat, binders, goal_lhs, goal_rhs)
    return None if expr is None else f'exact {expr}'

def pc_subst_term(t: Term, sub: dict[str, Term]) -> Term:
    if t[0] == 'var' and t[1] in sub:
        return sub[t[1]]
    if t[0] == 'op':
        return ('op', pc_subst_term(t[1], sub), pc_subst_term(t[2], sub))
    return t

def pc_stitch_pool(goal_lhs: Term | None, goal_rhs: Term | None, limit: int=14) -> list[Term]:
    out: list[Term] = []
    seen: set[str] = set()
    for root in (goal_lhs, goal_rhs):
        if root is None:
            continue
        for t in subterms(root):
            sig = term_key(t)
            if sig not in seen:
                seen.add(sig)
                out.append(t)
    out.sort(key=lambda t: (term_size(t), term_key(t)))
    return out[:limit]

def pc_bounded_completions(base: dict[str, Term], binders: list[str], pool: list[Term], max_missing: int=3, max_total: int=350):
    rem = [v for v in binders if v not in base]
    if len(rem) > max_missing:
        return
    seen: set[tuple[str, ...]] = set()
    total = 0
    for vals in product(pool, repeat=len(rem)):
        sub = dict(base)
        for v, val in zip(rem, vals):
            sub[v] = val
        sig = tuple((term_key(sub[v]) for v in binders))
        if sig in seen:
            continue
        seen.add(sig)
        yield sub
        total += 1
        if total >= max_total:
            return

def pc_lemma_edges_from(term: Term, lhs_pat: Term, rhs_pat: Term, binders: list[str], pool: list[Term], name: str, max_missing: int=3):
    bset = set(binders)
    for side in (0, 1):
        pat = lhs_pat if side == 0 else rhs_pat
        other = rhs_pat if side == 0 else lhs_pat
        base = pc_match_term(pat, term, bset, {})
        if base is None:
            continue
        for sub in pc_bounded_completions(base, binders, pool, max_missing=max_missing):
            out = pc_subst_term(other, sub)
            if out == term:
                continue
            args = ' '.join((pc_arg(sub[v]) for v in binders))
            call = f'{name} {args}' if args else name
            proof = call if side == 0 else f'({call}).symm'
            yield (out, proof)

def pc_add_subterms_to_pool(pool: list[Term], seen: set[str], term: Term, limit: int) -> None:
    for t in subterms(term):
        sig = term_key(t)
        if sig not in seen:
            seen.add(sig)
            pool.append(t)
            if len(pool) >= limit:
                return

def pc_one_h_target_calc(hrec: dict[str, Any] | None, target_lhs: Term, target_rhs: Term, target_binders: list[str], goal_lhs: Term | None, goal_rhs: Term | None, h_name: str='h', target_name: str='target') -> str | None:
    if goal_lhs is None or goal_rhs is None or (not hrec) or (not target_binders):
        return None
    hvars = hrec.get('binders') or []
    if not hvars:
        return None
    pool = pc_stitch_pool(goal_lhs, goal_rhs)
    if not pool:
        return None

    def complete(base: dict[str, Term]):
        rem = [v for v in hvars if v not in base]
        if len(rem) > 4:
            return
        seen: set[tuple[str, ...]] = set()
        for vals in product(pool, repeat=len(rem)):
            sub = dict(base)
            for v, val in zip(rem, vals):
                sub[v] = val
            sig = tuple((term_key(sub[v]) for v in hvars))
            if sig in seen:
                continue
            seen.add(sig)
            yield sub

    def h_call(sub: dict[str, Term]) -> str:
        return f'{h_name} ' + ' '.join((pc_arg(sub[v]) for v in hvars))
    for side, endpoint in ((0, goal_lhs), (1, goal_lhs), (0, goal_rhs), (1, goal_rhs)):
        hside = hrec['lhs'] if side == 0 else hrec['rhs']
        base = pc_match_term(hside, endpoint, set(hvars), {})
        if base is None:
            continue
        for sub in complete(base):
            hl = pc_subst_term(hrec['lhs'], sub)
            hr = pc_subst_term(hrec['rhs'], sub)
            call = h_call(sub)
            if side == 0 and hl != endpoint:
                continue
            if side == 1 and hr != endpoint:
                continue
            if endpoint == goal_lhs:
                mid = hr if side == 0 else hl
                p1 = call if side == 0 else f'({call}).symm'
                p2 = pc_target_proof_expr(target_name, target_lhs, target_rhs, target_binders, mid, goal_rhs)
                if p2 is not None:
                    return '\n'.join(['calc', f'  {term_to_str(goal_lhs)} = {term_to_str(mid)} := {p1}', f'  _ = {term_to_str(goal_rhs)} := {p2}'])
            else:
                mid = hr if side == 0 else hl
                p1 = pc_target_proof_expr(target_name, target_lhs, target_rhs, target_binders, goal_lhs, mid)
                p2 = f'({call}).symm' if side == 0 else call
                if p1 is not None:
                    return '\n'.join(['calc', f'  {term_to_str(goal_lhs)} = {term_to_str(mid)} := {p1}', f'  _ = {term_to_str(goal_rhs)} := {p2}'])
    return None

def pc_path_target_calc(hrec: dict[str, Any] | None, target_lhs: Term, target_rhs: Term, target_binders: list[str], goal_lhs: Term | None, goal_rhs: Term | None, h_name: str='h', target_name: str='target') -> str | None:
    if goal_lhs is None or goal_rhs is None or (not target_binders):
        return None
    hvars = (hrec or {}).get('binders') or []
    pool = pc_stitch_pool(goal_lhs, goal_rhs, limit=16)
    pool_seen = {term_key(t) for t in pool}
    target_key = term_key(goal_rhs)
    start_key = term_key(goal_lhs)
    nodes = {start_key: goal_lhs}
    parent: dict[str, tuple[str, str] | None] = {start_key: None}
    queue = [goal_lhs]
    max_nodes, max_depth, qi = (120, 5, 0)

    def depth_of(k: str) -> int:
        depth = 0
        while parent.get(k) is not None:
            k = parent[k][0]
            depth += 1
        return depth
    while qi < len(queue) and len(nodes) < max_nodes:
        cur = queue[qi]
        qi += 1
        ck = term_key(cur)
        if ck == target_key:
            break
        if depth_of(ck) >= max_depth:
            continue
        edges = list(pc_lemma_edges_from(cur, target_lhs, target_rhs, target_binders, pool, target_name, max_missing=3))
        if hrec is not None and hvars:
            edges.extend(pc_lemma_edges_from(cur, hrec['lhs'], hrec['rhs'], hvars, pool, h_name, max_missing=3))
        for nxt, proof in edges:
            nk = term_key(nxt)
            if nk in nodes or term_size(nxt) > 18:
                continue
            nodes[nk] = nxt
            parent[nk] = (ck, proof)
            queue.append(nxt)
            pc_add_subterms_to_pool(pool, pool_seen, nxt, 24)
            if nk == target_key:
                qi = len(queue)
                break
    if target_key not in parent:
        return None
    path = []
    k = target_key
    while parent[k] is not None:
        pk, proof = parent[k]
        path.append((nodes[pk], nodes[k], proof))
        k = pk
    path.reverse()
    if not path:
        return None
    lines = ['calc']
    for i, (a, b, proof) in enumerate(path):
        lines.append(f"  {(term_to_str(a) if i == 0 else '_')} = {term_to_str(b)} := {proof}")
    return '\n'.join(lines)

def pc_render_step_body(rec: dict[str, Any], ia_line: str, ib_line: str) -> str:
    deriv = rec['deriv']
    if deriv is None:
        raise ValueError('base record has no renderable step')
    proof_info = deriv[4] if len(deriv) >= 5 else None
    binders = ' '.join(rec['binders'])
    intro = f'intro {binders}; ' if binders else ''
    if not proof_info:
        return f'by {intro}{ia_line}; {ib_line}; grind'
    before = proof_info['before']
    pos = tuple(proof_info['pos'])
    context = pc_term_with_hole(before, pos)
    ib_expr = pc_oriented_expr('ib', bool(proof_info.get('b_symm')))
    ia_expr = pc_oriented_expr('ia', bool(proof_info.get('a_symm')))
    before_s = term_to_str(before)
    after_s = term_to_str(rec['lhs'])
    return f'by {intro}{ia_line}; {ib_line}; have step : {before_s} = {after_s} := congrArg (fun __pc_hole => {context}) ({ib_expr}); exact step.symm.trans ({ia_expr})'

def pc_render(target_id: int, recs: list[dict[str, Any]], goal_vars: list[str], goal_lhs: Term | None=None, goal_rhs: Term | None=None, base_names: list[str] | None=None) -> str:
    base_names = base_names or ['h']

    def lemma_name(rid: int) -> str:
        if recs[rid]['deriv'] is not None:
            return f'E{rid}'
        base = recs[rid].get('base')
        if isinstance(base, int) and 0 <= base < len(base_names):
            return base_names[base]
        return 'h'
    order = pc_derivation_chain(target_id, recs)
    lines = ['intro ' + ' '.join(goal_vars)] if goal_vars else []
    for rid in order:
        rec = recs[rid]
        if rec['deriv'] is None:
            continue
        ai, bi, args_a, args_b = rec['deriv'][:4]
        an = lemma_name(ai)
        bn = lemma_name(bi)
        binders = rec['binders']
        ia = f'have ia := {an} ' + ' '.join((pc_arg(x) for x in args_a)) if args_a else f'have ia := {an}'
        ib = f'have ib := {bn} ' + ' '.join((pc_arg(x) for x in args_b)) if args_b else f'have ib := {bn}'
        lhs = term_to_str(rec['lhs'])
        rhs = term_to_str(rec['rhs'])
        binder_chunk = ' '.join(binders)
        lines.append(f'have E{rid} : ∀ ({binder_chunk} : G), {lhs} = {rhs} := {pc_render_step_body(rec, ia, ib)}')
    target_rec = recs[target_id]
    if target_rec['deriv'] is not None:
        ess = pc_vars_of(target_rec['lhs'])
        for v in pc_vars_of(target_rec['rhs']):
            if v not in ess:
                ess.append(v)
        exact_line = pc_target_exact_line('target', target_rec['lhs'], target_rec['rhs'], ess, goal_lhs, goal_rhs)
        hrec = None
        for rec in recs:
            if rec['deriv'] is None:
                base = rec.get('base')
                if base is None or (isinstance(base, int) and base < len(base_names) and (base_names[base] == 'h')):
                    hrec = rec
                    break
        calc_line = pc_one_h_target_calc(hrec, target_rec['lhs'], target_rec['rhs'], ess, goal_lhs, goal_rhs)
        if calc_line is None:
            calc_line = pc_path_target_calc(hrec, target_rec['lhs'], target_rec['rhs'], ess, goal_lhs, goal_rhs)
        if ess and (len(ess) < len(target_rec['binders']) or exact_line is not None or calc_line is not None):
            d0 = ess[0]
            args = ' '.join((v if v in ess else d0 for v in target_rec['binders']))
            lhs = term_to_str(target_rec['lhs'])
            rhs = term_to_str(target_rec['rhs'])
            lines.append(f"have target : ∀ ({' '.join(ess)} : G), {lhs} = {rhs} := fun {' '.join(ess)} => E{target_id} {args}")
            if exact_line is not None:
                lines.append(exact_line)
                return '\n'.join(lines)
            if calc_line is not None:
                lines.append(calc_line)
                return '\n'.join(lines)
    if target_rec['deriv'] is None and goal_lhs is not None and (goal_rhs is not None):
        base_exact = pc_target_exact_line(lemma_name(target_id), target_rec['lhs'], target_rec['rhs'], target_rec['binders'], goal_lhs, goal_rhs)
        if base_exact is not None:
            lines.append(base_exact)
            return '\n'.join(lines)
    lines.append('grind')
    return '\n'.join(lines)

def pc_rec_summary(rec: dict[str, Any]) -> dict[str, Any]:
    return {'lhs': short_text(term_to_str(rec['lhs']), 120), 'rhs': short_text(term_to_str(rec['rhs']), 120), 'binders': rec.get('binders', [])[:6], 'derived': rec.get('deriv') is not None}

def completion_match(pattern: Term, subject: Term, substitution: dict[str, Term]) -> bool:
    if pattern[0] == 'var':
        previous = substitution.get(pattern[1])
        if previous is None:
            substitution[pattern[1]] = subject
            return True
        return previous == subject
    return subject[0] == 'op' and completion_match(pattern[1], subject[1], substitution) and completion_match(pattern[2], subject[2], substitution)

def completion_substitute(term: Term, substitution: dict[str, Term]) -> Term:
    if term[0] == 'var':
        return substitution.get(term[1], term)
    return ('op', completion_substitute(term[1], substitution), completion_substitute(term[2], substitution))

def completion_rewrite_once(term: Term, lhs: Term, rhs: Term) -> tuple[Term, bool]:
    if term[0] == 'op':
        rewritten, changed = completion_rewrite_once(term[1], lhs, rhs)
        if changed:
            return (('op', rewritten, term[2]), True)
        rewritten, changed = completion_rewrite_once(term[2], lhs, rhs)
        if changed:
            return (('op', term[1], rewritten), True)
    substitution: dict[str, Term] = {}
    if completion_match(lhs, term, substitution):
        return (completion_substitute(rhs, substitution), True)
    return (term, False)

def completion_orient(lhs: Term, rhs: Term) -> tuple[Term, Term]:
    left_key = (term_size(lhs), term_key(lhs))
    right_key = (term_size(rhs), term_key(rhs))
    return (lhs, rhs) if left_key > right_key else (rhs, lhs)

def completion_equation(lhs: Term, rhs: Term) -> dict[str, Any]:
    variables = pc_vars_of(lhs)
    variables += [var for var in pc_vars_of(rhs) if var not in variables]
    return {'text': f'{term_to_str(lhs)} = {term_to_str(rhs)}', 'variables': variables, 'lhs': lhs, 'rhs': rhs}

def ordered_completion_discover(h_eq: dict[str, Any], target_eq: dict[str, Any], *, budget: float, max_rules: int=500, max_size: int=100) -> tuple[list[dict[str, Any]] | None, list[int], dict[str, Any]]:
    started = time.monotonic()
    deadline = started + max(0.1, budget)
    active: list[dict[str, Any]] = []
    pending: list[tuple[Any, ...]] = []
    seen: set[tuple[str, str]] = set()
    counter = [0]
    serial = 0
    generated = 0
    target_text = f"{term_to_str(target_eq['lhs'])}={term_to_str(target_eq['rhs'])}"

    def normal_form(term: Term) -> tuple[Term, set[int]]:
        dependencies: set[int] = set()
        for _step in range(100):
            changed = False
            for rule_id, record in enumerate(active):
                if not record.get('rewritable', True):
                    continue
                rewritten, did_rewrite = completion_rewrite_once(term, record['lhs'], record['rhs'])
                if did_rewrite:
                    term = rewritten
                    dependencies.add(rule_id)
                    changed = True
                    break
            if not changed:
                break
        return (term, dependencies)

    def push(lhs: Term, rhs: Term, depth: int, parents: tuple[int, ...]) -> None:
        nonlocal serial, generated
        lhs, left_dependencies = normal_form(lhs)
        rhs, right_dependencies = normal_form(rhs)
        if lhs == rhs:
            return
        lhs, rhs = completion_orient(lhs, rhs)
        canonical = pc_canon(lhs, rhs)
        signature = (term_key(canonical[0]), term_key(canonical[1]))
        if signature in seen:
            return
        seen.add(signature)
        all_parents = tuple(dict.fromkeys([*parents, *sorted(left_dependencies | right_dependencies)]))
        equation_text = f'{term_to_str(lhs)}={term_to_str(rhs)}'
        similarity = difflib.SequenceMatcher(None, equation_text, target_text, autojunk=False).ratio()
        serial += 1
        generated += 1
        heapq.heappush(pending, (term_size(lhs) + term_size(rhs), depth, -similarity, serial, lhs, rhs, all_parents))
        if len(pending) > 60000:
            del pending[30000:]
            heapq.heapify(pending)
    push(h_eq['lhs'], h_eq['rhs'], 0, ())
    target_dependencies: set[int] = set()
    stop_reason = 'saturated'
    while pending and len(active) < max_rules:
        if time.monotonic() >= deadline:
            stop_reason = 'time_budget'
            break
        _size, depth, _similarity, _serial, lhs, rhs, parents = heapq.heappop(pending)
        lhs, left_dependencies = normal_form(lhs)
        rhs, right_dependencies = normal_form(rhs)
        if lhs == rhs:
            continue
        lhs, rhs = completion_orient(lhs, rhs)
        parent_ids = tuple(dict.fromkeys([*parents, *sorted(left_dependencies | right_dependencies)]))
        lhs_vars = set(pc_vars_of(lhs))
        rhs_vars = set(pc_vars_of(rhs))
        record = {'lhs': lhs, 'rhs': rhs, 'binders': pc_vars_of(lhs) + [var for var in pc_vars_of(rhs) if var not in pc_vars_of(lhs)], 'parents': parent_ids, 'depth': depth, 'rewritable': rhs_vars.issubset(lhs_vars)}
        record_id = len(active)
        active.append(record)
        normalized_left, left_target_dependencies = normal_form(target_eq['lhs'])
        normalized_right, right_target_dependencies = normal_form(target_eq['rhs'])
        if normalized_left == normalized_right:
            target_dependencies = left_target_dependencies | right_target_dependencies
            stop_reason = 'target_joined'
            break
        for other_id in range(len(active)):
            if time.monotonic() >= deadline:
                stop_reason = 'time_budget'
                break
            for first_id, second_id in ((record_id, other_id), (other_id, record_id)):
                for new_lhs, new_rhs, _binders, _args_first, _args_second, _proof_info in pc_paramodulants(active[first_id], active[second_id], counter, max_size, allow_var_overlap=False):
                    push(new_lhs, new_rhs, max(active[first_id]['depth'], active[second_id]['depth']) + 1, (first_id, second_id))
            if stop_reason == 'time_budget':
                break
        if stop_reason == 'time_budget':
            break
    if len(active) >= max_rules and stop_reason == 'saturated':
        stop_reason = 'max_rules'
    elapsed = time.monotonic() - started
    state = {'kind': 'OrderedCompletionDiscoveryState', 'status': 'proof_plan_found' if target_dependencies else 'stuck', 'target': target_eq['text'], 'active_rules': len(active), 'generated_equations': generated, 'pending_equations': len(pending), 'target_dependencies': sorted(target_dependencies), 'stop_reason': stop_reason, 'elapsed_seconds': round(elapsed, 3), 'frontier': [{'equation': f"{term_to_str(record['lhs'])} = {term_to_str(record['rhs'])}", 'depth': record['depth'], 'parent_count': len(record['parents'])} for record in active[-8:]], 'need_hint': None if target_dependencies else {'kind': 'completion_target_not_joined', 'target': target_eq['text'], 'reason': stop_reason, 'next_action': 'Propose a smaller auxiliary equation near the completion frontier, or grant this tool a larger bounded budget.'}}
    return (active if target_dependencies else None, sorted(target_dependencies), state)

def completion_dependency_closure(active: list[dict[str, Any]], target_dependencies: list[int]) -> list[int]:
    needed: set[int] = set()

    def visit(rule_id: int) -> None:
        if rule_id in needed or rule_id < 0 or rule_id >= len(active):
            return
        for parent in active[rule_id].get('parents', ()):
            visit(parent)
        needed.add(rule_id)
    for dependency in target_dependencies:
        visit(dependency)
    return sorted(needed)

def completion_focused_replay(target_eq: dict[str, Any], parent_ids: list[int], equations: dict[int, dict[str, Any]], names: dict[int, str], *, rounds: int, time_budget: float) -> tuple[str | None, dict[str, Any]]:
    parent_ids = [parent for parent in parent_ids if parent in equations and parent in names]
    if not parent_ids:
        return (None, {'status': 'no_available_parents'})
    start = [(equations[parent]['lhs'], equations[parent]['rhs']) for parent in parent_ids]
    target_signature = pc_canon(target_eq['lhs'], target_eq['rhs'])
    target_size = term_size(target_eq['lhs']) + term_size(target_eq['rhs'])
    target_id, records, metadata = pc_saturate(start, lambda pair: pc_canon(*pair) == target_signature, max_rounds=rounds, max_eqs=25000, max_size=max(80, target_size * 3), time_budget=time_budget, allow_var_overlap=False)
    state = {'status': 'proved' if target_id is not None else 'stuck', 'parent_ids': parent_ids, 'parent_names': [names[parent] for parent in parent_ids], 'records_generated': len(records), 'saturation': metadata}
    if target_id is None:
        return (None, state)
    state['derivation_length'] = len(pc_derivation_chain(target_id, records))
    return (pc_render(target_id, records, target_eq['variables'], target_eq['lhs'], target_eq['rhs'], base_names=[names[parent] for parent in parent_ids]), state)

def completion_linear_replay(target_eq: dict[str, Any], parent_ids: list[int], equations: dict[int, dict[str, Any]], names: dict[int, str], *, max_depth: int, beam_width: int, time_budget: float) -> tuple[str | None, dict[str, Any]]:
    parent_ids = [parent for parent in parent_ids if parent in equations and parent in names]
    if len(parent_ids) < 2:
        return (None, {'status': 'insufficient_available_parents', 'parent_ids': parent_ids})
    records: list[dict[str, Any]] = []
    seen: dict[tuple[str, str], int] = {}
    for base_index, parent in enumerate(parent_ids):
        equation = equations[parent]
        canonical = pc_canon(equation['lhs'], equation['rhs'])
        signature = (term_key(canonical[0]), term_key(canonical[1]))
        seen[signature] = len(records)
        records.append({'lhs': equation['lhs'], 'rhs': equation['rhs'], 'binders': equation['variables'], 'deriv': None, 'base': base_index})
    target_signature = pc_canon(target_eq['lhs'], target_eq['rhs'])
    target_text = f"{term_to_str(target_eq['lhs'])}={term_to_str(target_eq['rhs'])}"
    target_size = term_size(target_eq['lhs']) + term_size(target_eq['rhs'])
    max_size = max(80, target_size * 3)
    frontier = [0]
    rule_ids = list(range(1, len(parent_ids)))
    counter = [0]
    deadline = time.monotonic() + max(0.1, time_budget)
    depth_rows: list[dict[str, Any]] = []
    for depth in range(1, max_depth + 1):
        candidates: list[tuple[float, int]] = []
        for current_id in frontier:
            if time.monotonic() >= deadline:
                return (None, {'status': 'time_budget', 'parent_ids': parent_ids, 'records_generated': len(records), 'depths': depth_rows})
            for rule_id in rule_ids:
                for left_id, right_id in ((current_id, rule_id), (rule_id, current_id)):
                    for lhs, rhs, binders, args_left, args_right, proof_info in pc_paramodulants(records[left_id], records[right_id], counter, max_size, allow_var_overlap=False):
                        canonical = pc_canon(lhs, rhs)
                        signature = (term_key(canonical[0]), term_key(canonical[1]))
                        if signature in seen:
                            continue
                        record_id = len(records)
                        seen[signature] = record_id
                        records.append({'lhs': lhs, 'rhs': rhs, 'binders': binders, 'deriv': (left_id, right_id, args_left, args_right, proof_info), 'base': None})
                        if canonical == target_signature:
                            return (pc_render(record_id, records, target_eq['variables'], target_eq['lhs'], target_eq['rhs'], base_names=[names[parent] for parent in parent_ids]), {'status': 'proved', 'parent_ids': parent_ids, 'parent_names': [names[parent] for parent in parent_ids], 'records_generated': len(records), 'depth': depth, 'derivation_length': len(pc_derivation_chain(record_id, records)), 'depths': depth_rows})
                        candidate_text = f'{term_to_str(lhs)}={term_to_str(rhs)}'
                        score = difflib.SequenceMatcher(None, candidate_text, target_text, autojunk=False).ratio()
                        candidates.append((score, record_id))
        candidates.sort(reverse=True)
        frontier = [record_id for _score, record_id in candidates[:beam_width]]
        depth_rows.append({'depth': depth, 'candidates': len(candidates), 'retained': len(frontier), 'best_similarity': round(candidates[0][0], 4) if candidates else None})
        if not frontier:
            break
    return (None, {'status': 'depth_exhausted', 'parent_ids': parent_ids, 'records_generated': len(records), 'depths': depth_rows})

def ordered_completion_replay(h_eq: dict[str, Any], g_eq: dict[str, Any], active: list[dict[str, Any]], target_dependencies: list[int], *, budget: float) -> tuple[str | None, dict[str, Any]]:
    started = time.monotonic()
    deadline = started + max(1.0, budget)
    closure = completion_dependency_closure(active, target_dependencies)
    equations = {rule_id: completion_equation(record['lhs'], record['rhs']) for rule_id, record in enumerate(active)}
    equations[0] = h_eq
    names = {0: 'h'}
    declarations: list[str] = []
    assumptions: list[UniversalEquation] = []
    attempts: list[dict[str, Any]] = []
    for rule_id in closure:
        if rule_id == 0:
            continue
        remaining = deadline - time.monotonic()
        if remaining <= 0.5:
            return (None, {'kind': 'OrderedCompletionReplayState', 'status': 'budget_exhausted', 'dependency_closure': closure, 'proved_rules': sorted(names), 'attempts': attempts, 'need_hint': {'kind': 'completion_replay_budget_exhausted', 'blocked_rule': equations[rule_id]['text']}})
        parent_ids = list(active[rule_id].get('parents', ()))
        proof_body, focused_state = completion_focused_replay(equations[rule_id], parent_ids, equations, names, rounds=4, time_budget=min(4.0, max(0.25, remaining)))
        linear_state = None
        if proof_body is None and len(parent_ids) >= 2:
            linear_attempts: list[dict[str, Any]] = []
            for source_index in range(len(parent_ids)):
                remaining = deadline - time.monotonic()
                if remaining <= 0.5:
                    break
                rotated = parent_ids[source_index:] + parent_ids[:source_index]
                proof_body, one_linear_state = completion_linear_replay(equations[rule_id], rotated, equations, names, max_depth=6, beam_width=60, time_budget=min(10.0, max(0.25, remaining)))
                linear_attempts.append({'source_parent': rotated[0], 'state': one_linear_state})
                if proof_body is not None:
                    break
            linear_state = {'status': 'proved' if proof_body else 'stuck', 'attempts': linear_attempts}
        broad_state = None
        if proof_body is None:
            remaining = deadline - time.monotonic()
            parent_assumptions = [UniversalEquation(names[parent], equations[parent], []) for parent in parent_ids if parent != 0 and parent in names]
            if remaining > 0.5:
                proof_body, broad_state = prove_with_assumptions_detailed(h_eq, equations[rule_id], parent_assumptions, superposition_budget=min(6.0, max(0.25, remaining)))
        attempts.append({'rule_id': rule_id, 'equation': equations[rule_id]['text'], 'parent_ids': parent_ids, 'status': 'proved' if proof_body else 'replay_failed', 'focused': focused_state, 'linear': linear_state, 'broad': broad_state})
        if proof_body is None:
            return (None, {'kind': 'OrderedCompletionReplayState', 'status': 'replay_failed', 'dependency_closure': closure, 'proved_rules': sorted(names), 'attempts': attempts, 'need_hint': {'kind': 'completion_edge_not_replayed', 'blocked_rule': equations[rule_id]['text'], 'parents': [equations[parent]['text'] for parent in parent_ids if parent in equations], 'next_action': 'Propose this blocked equation as a smaller midpoint or simplify its parent set.'}})
        name = f'completion_rule_{rule_id}'
        names[rule_id] = name
        assumption = UniversalEquation(name, equations[rule_id], [])
        assumptions.append(assumption)
        declarations.extend([f'have {name} : {lemma_statement(equations[rule_id])} := by', indent(proof_body, 2)])
    remaining = deadline - time.monotonic()
    if remaining <= 0.5:
        return (None, {'kind': 'OrderedCompletionReplayState', 'status': 'goal_consume_budget_exhausted', 'dependency_closure': closure, 'proved_rules': sorted(names), 'attempts': attempts})
    goal_body, goal_state = prove_with_assumptions_detailed(h_eq, g_eq, assumptions, superposition_budget=min(12.0, max(0.5, remaining)))
    state = {'kind': 'OrderedCompletionReplayState', 'status': 'body_built' if goal_body else 'helper_proved_not_consumed', 'dependency_closure': closure, 'proved_rules': sorted(names), 'replayed_rule_count': len(assumptions), 'attempts': attempts, 'goal_state': goal_state, 'elapsed_seconds': round(time.monotonic() - started, 3), 'need_hint': None if goal_body else {'kind': 'completion_plan_not_consumed', 'proved_equations': [assumption.eq['text'] for assumption in assumptions[-8:]], 'next': goal_state.get('need_hint') if isinstance(goal_state, dict) else None}}
    if goal_body is None:
        return (None, state)
    return ('\n'.join([*declarations, goal_body]), state)

def ordered_completion_targets(h_eq: dict[str, Any], call: dict[str, Any] | None=None) -> list[tuple[str, dict[str, Any]]]:
    call = call or {}
    targets: list[tuple[str, dict[str, Any]]] = []
    for key in ('midpoint', 'lemma', 'equation', 'target_equation'):
        raw = call.get(key)
        values = raw if isinstance(raw, list) else [raw]
        for value in values:
            if isinstance(value, str) and '=' in value:
                try:
                    equation = parse_equation(value)
                except Exception:
                    continue
                targets.append((f'proposed_{len(targets) + 1}', equation))
    explicit_aux = any((key in call for key in ('lemmas', 'aux', 'kinds', 'targets')))
    kinds = standard_aux_order(call) if explicit_aux else implied_standard_aux_lemmas(h_eq)
    if not kinds and (not targets):
        kinds = standard_aux_order(None)
    for kind in kinds:
        equation = standard_aux_equation(kind)
        canonical = pc_canon(equation['lhs'], equation['rhs'])
        if any((pc_canon(item['lhs'], item['rhs']) == canonical for _label, item in targets)):
            continue
        targets.append((kind, equation))
    return targets

def ordered_completion_attempt(h_eq: dict[str, Any], g_eq: dict[str, Any], call: dict[str, Any] | None=None) -> tuple[str | None, dict[str, Any]]:
    call = call or {}
    total_budget = float(call.get('budget') or call.get('time_budget') or 120.0)
    deadline = time.monotonic() + max(1.0, total_budget)
    targets = ordered_completion_targets(h_eq, call)
    attempts: list[dict[str, Any]] = []
    unresolved: list[tuple[str, dict[str, Any]]] = []
    for label, target_eq in targets:
        remaining = deadline - time.monotonic()
        if remaining <= 1.0:
            break
        active, dependencies, discovery = ordered_completion_discover(h_eq, target_eq, budget=min(2.5, max(0.5, remaining)))
        attempt = {'target_kind': label, 'target': target_eq['text'], 'phase': 'scout', 'discovery': discovery}
        attempts.append(attempt)
        if active is None:
            unresolved.append((label, target_eq))
            continue
        replay_budget = max(1.0, deadline - time.monotonic())
        body, replay = ordered_completion_replay(h_eq, g_eq, active, dependencies, budget=replay_budget)
        attempt['replay'] = replay
        if body:
            return (body, {'kind': 'OrderedCompletionState', 'status': 'body_built', 'winning_target': label, 'winning_equation': target_eq['text'], 'attempts': attempts})
    for index, (label, target_eq) in enumerate(unresolved):
        remaining = deadline - time.monotonic()
        if remaining <= 1.0:
            break
        remaining_targets = max(1, len(unresolved) - index)
        discovery_budget = min(50.0, max(8.0, remaining / remaining_targets))
        active, dependencies, discovery = ordered_completion_discover(h_eq, target_eq, budget=min(remaining, discovery_budget))
        attempt = {'target_kind': label, 'target': target_eq['text'], 'phase': 'extended', 'discovery': discovery}
        attempts.append(attempt)
        if active is None:
            continue
        replay_budget = max(1.0, deadline - time.monotonic())
        body, replay = ordered_completion_replay(h_eq, g_eq, active, dependencies, budget=replay_budget)
        attempt['replay'] = replay
        if body:
            return (body, {'kind': 'OrderedCompletionState', 'status': 'body_built', 'winning_target': label, 'winning_equation': target_eq['text'], 'attempts': attempts})
    return (None, {'kind': 'OrderedCompletionState', 'status': 'stuck', 'targets': [{'kind': label, 'equation': equation['text']} for label, equation in targets], 'attempts': attempts, 'need_hint': {'kind': 'ordered_completion_failed', 'reason': 'No targeted completion plan was both discovered and replayed into the goal.', 'best_frontiers': [attempt['discovery'].get('frontier', []) for attempt in attempts[-3:]], 'next_action': 'Propose a custom midpoint equation near one of these completion frontiers.'}})
RIGIDITY_COLLAPSE_LADDER: tuple[tuple[str, str, float], ...] = (('square_overlap_bridge', '(((x * x) * y) * (x * y)) = x * (x * x)', 4.0), ('squares_equal', 'x * x = y * y', 22.0), ('square_left_identity', '(x * x) * y = y', 6.0), ('t_cancellation', '(x * (x * y)) * y = x', 6.0), ('square_absorption', '(x * (y * y)) * x = x', 6.0), ('square_transport', 'x * (y * y) = x * x', 6.0), ('carrier_collapse', 'x = y', 12.0))
