def symbolic_model_strategy_cards(*, require_infinite: bool) -> list[dict[str, Any]]:
    cards = [{'family': 'affine_or_linear', 'representations': ['symbolic_finite', 'infinite'], 'shape': 'Use Fin n with an explicit operation, integers, vectors, or products with an affine operation.', 'repair_signal': 'Translate H and not-G into coefficient constraints before writing Lean.'}, {'family': 'translation_invariant', 'representations': ['infinite'], 'shape': 'On an additive carrier, try x ◇ y = x + f(y - x), with f piecewise by residue/sign.', 'repair_signal': 'Reduce H to a functional equation for f; use a concrete goal-breaking tuple.'}, {'family': 'modified_base_model', 'representations': ['infinite', 'symbolic_finite'], 'shape': 'Start from a simple model of H, force one failure of G, trace the new H failures, then coalesce the required repairs into a residue or region rule.', 'repair_signal': 'Preserve the G-breaking witness while generalizing repeated patches.'}, {'family': 'product_or_bundle', 'representations': ['symbolic_finite', 'infinite'], 'shape': 'Use a product, sum, quotient, or fibers over a small control magma.', 'repair_signal': 'Let one coordinate enforce H and another retain a G-breaking witness.'}, {'family': 'free_or_term_model', 'representations': ['infinite'], 'shape': 'Use terms or a quotient by H when a normal-form invariant separates G.', 'repair_signal': 'Provide a computable invariant or normalization lemma that Lean can check.'}]
    if require_infinite:
        return [card for card in cards if 'infinite' in card['representations']]
    return cards

def _symbolic_fragment(value: Any, *, field_name: str, byte_limit: int) -> tuple[str | None, str | None]:
    if not isinstance(value, str) or not value.strip():
        return (None, f'{field_name} must be a nonempty Lean fragment')
    text = value.strip()
    if len(text.encode('utf-8')) > byte_limit:
        return (None, f'{field_name} exceeds {byte_limit} bytes')
    match = _SYMBOLIC_MODEL_BANNED_RE.search(text)
    if match:
        return (None, f'{field_name} contains disallowed placeholder/declaration: {match.group(0)}')
    if re.search('\\bZMod\\b', text):
        return (None, f'{field_name} uses ZMod, which is outside the official declaration allowlist')
    return (text, None)

def _normalize_symbolic_tactic_fragment(text: str) -> tuple[str, list[str]]:
    repairs: list[str] = []
    lines = text.strip().splitlines()
    if lines and lines[0].strip() == 'by':
        lines = lines[1:]
        repairs.append('removed_redundant_outer_by')
        baseline = min((len(line) - len(line.lstrip()) for line in lines if line.strip()), default=0)
        lines = textwrap.dedent('\n'.join(lines)).splitlines()
        if baseline > 0:
            repairs.append(f'dedented_following_tactics_by_{baseline}')
    if len(lines) > 1:
        baseline = min((len(line) - len(line.lstrip()) for line in lines[1:] if line.strip()), default=0)
        if baseline > 0:
            lines = [lines[0]] + [line[baseline:] if line.strip() else line for line in lines[1:]]
            repairs.append(f'dedented_following_tactics_by_{baseline}')
    return ('\n'.join(lines).strip(), repairs)

def normalize_symbolic_model_plan(action: dict[str, Any]) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    source = action.get('plan') if isinstance(action.get('plan'), dict) else action
    schema_repairs: list[dict[str, Any]] = []
    raw_imports = source.get('imports') or []
    if isinstance(raw_imports, str):
        raw_imports = [raw_imports]
        schema_repairs.append({'field': 'imports', 'repair': 'wrapped_single_import_as_list'})
    raw_setup = source.get('setup') or []
    if isinstance(raw_setup, str):
        raw_setup = [raw_setup]
        schema_repairs.append({'field': 'setup', 'repair': 'wrapped_single_setup_fragment_as_list'})
    if isinstance(raw_setup, list):
        merged_setup: list[Any] = []
        open_tactic_block = False
        declaration_start = re.compile('^(?:have|let|set|suffices|show|refine|exact|constructor)\\b')
        for item in raw_setup:
            text = str(item)
            starts_declaration = bool(declaration_start.match(text.strip()))
            if merged_setup and open_tactic_block and (not starts_declaration):
                merged_setup[-1] = str(merged_setup[-1]).rstrip() + '\n  ' + text.strip()
                schema_repairs.append({'field': 'setup', 'repair': 'merged_dangling_tactic_fragment'})
                continue
            merged_setup.append(item)
            open_tactic_block = text.rstrip().endswith(':= by')
        raw_setup = merged_setup
    raw_definitions = source.get('definitions') or source.get('pre_model_setup') or []
    if isinstance(raw_definitions, str):
        raw_definitions = [raw_definitions]
        schema_repairs.append({'field': 'definitions', 'repair': 'wrapped_single_definition_fragment_as_list'})
    if source.get('pre_model_setup') and (not source.get('definitions')):
        schema_repairs.append({'field': 'definitions', 'repair': 'renamed_pre_model_setup_to_definitions'})
    representation = str(source.get('representation') or 'unspecified').strip().lower()
    if representation in {'finite', 'large_finite', 'formula_finite'}:
        representation = 'symbolic_finite'
        schema_repairs.append({'field': 'representation', 'repair': 'normalized_finite_representation'})
    if representation in {'infinite_model', 'symbolic_infinite'}:
        representation = 'infinite'
        schema_repairs.append({'field': 'representation', 'repair': 'normalized_infinite_representation'})
    operation = source.get('operation')
    if operation in (None, '') and isinstance(raw_definitions, list):
        defined_names = []
        for value in raw_definitions:
            match = re.match("\\s*(?:let|def)\\s+([A-Za-z_][A-Za-z0-9_']*)\\b", str(value))
            if match:
                defined_names.append(match.group(1))
        if 'op' in defined_names:
            operation = 'op'
            schema_repairs.append({'field': 'operation', 'repair': 'inferred_operation_from_local_op_definition'})
    plan = {'kind': 'symbolic_model_plan', 'version': SYMBOLIC_MODEL_PLAN_VERSION, 'representation': representation, 'model_name': str(source.get('model_name') or 'model').strip(), 'imports': list(raw_imports) if isinstance(raw_imports, list) else raw_imports, 'carrier': source.get('carrier'), 'definitions': list(raw_definitions) if isinstance(raw_definitions, list) else raw_definitions, 'operation': operation, 'setup': list(raw_setup) if isinstance(raw_setup, list) else raw_setup, 'hypothesis_proof': source.get('hypothesis_proof'), 'counterexample_proof': source.get('counterexample_proof')}
    errors: list[dict[str, Any]] = []
    if representation not in {'unspecified', 'symbolic_finite', 'infinite'}:
        errors.append({'field': 'representation', 'message': 'representation must be symbolic_finite, infinite, or unspecified'})
    if not _SYMBOLIC_MODEL_NAME_RE.fullmatch(plan['model_name']):
        errors.append({'field': 'model_name', 'message': 'model_name must be a Lean identifier'})
    if not isinstance(plan['imports'], list):
        errors.append({'field': 'imports', 'message': 'imports must be a list of names'})
        plan['imports'] = []
    elif len(plan['imports']) > 12:
        errors.append({'field': 'imports', 'message': 'at most 12 imports are allowed'})
    normalized_imports = ['JudgeProblem']
    for item in plan['imports']:
        name = str(item).strip()
        if not _SYMBOLIC_MODEL_IMPORT_RE.fullmatch(name):
            errors.append({'field': 'imports', 'message': f'invalid import name: {name}'})
        elif re.search('(?:^|\\.)ZMod(?:\\.|$)', name):
            errors.append({'field': 'imports', 'message': 'ZMod imports are outside the official declaration allowlist'})
        elif name != 'JudgeProblem' and name not in normalized_imports:
            normalized_imports.append(name)
    plan['imports'] = normalized_imports
    completed: list[str] = []
    missing: list[str] = []
    syntax_repairs: list[dict[str, Any]] = []
    for field_name, byte_limit in (('carrier', 1000), ('operation', 6000), ('hypothesis_proof', 10000), ('counterexample_proof', 8000)):
        value = plan.get(field_name)
        if value in (None, ''):
            missing.append(field_name)
            continue
        fragment, error = _symbolic_fragment(value, field_name=field_name, byte_limit=byte_limit)
        if error:
            errors.append({'field': field_name, 'message': error})
            continue
        if field_name in {'hypothesis_proof', 'counterexample_proof'}:
            fragment, repairs = _normalize_symbolic_tactic_fragment(fragment)
            syntax_repairs.extend(({'field': field_name, 'repair': repair} for repair in repairs))
        plan[field_name] = fragment
        completed.append(field_name)
    if not isinstance(plan['definitions'], list):
        errors.append({'field': 'definitions', 'message': 'definitions must be a list of Lean fragments'})
        plan['definitions'] = []
    elif len(plan['definitions']) > 12:
        errors.append({'field': 'definitions', 'message': 'at most 12 pre-model definitions are allowed'})
    normalized_definitions = []
    for index, value in enumerate(plan['definitions'][:12]):
        fragment, error = _symbolic_fragment(value, field_name=f'definitions[{index}]', byte_limit=8000)
        if error:
            errors.append({'field': f'definitions[{index}]', 'message': error})
        else:
            if re.match('^def\\b', fragment):
                fragment = re.sub('^def\\b', 'let', fragment, count=1)
                syntax_repairs.append({'field': f'definitions[{index}]', 'repair': 'rewrote_local_def_as_let'})
            normalized_definitions.append(fragment)
    plan['definitions'] = normalized_definitions
    completed.append('definitions')
    if not isinstance(plan['setup'], list):
        errors.append({'field': 'setup', 'message': 'setup must be a list of Lean fragments'})
        plan['setup'] = []
    elif len(plan['setup']) > 20:
        errors.append({'field': 'setup', 'message': 'at most 20 setup fragments are allowed'})
    normalized_setup = []
    for index, value in enumerate(plan['setup'][:20]):
        fragment, error = _symbolic_fragment(value, field_name=f'setup[{index}]', byte_limit=10000)
        if error:
            errors.append({'field': f'setup[{index}]', 'message': error})
        else:
            normalized_setup.append(fragment)
    plan['setup'] = normalized_setup
    completed.append('setup')
    state = {'kind': 'SymbolicModelPlanState', 'version': SYMBOLIC_MODEL_PLAN_VERSION, 'status': 'invalid_plan' if errors else 'missing_parts' if missing else 'plan_ready', 'representation': representation, 'completed_parts': completed, 'missing_parts': missing, 'errors': errors, 'schema_repairs': schema_repairs, 'syntax_repairs': syntax_repairs, 'part_count': len(completed), 'total_parts': len(SYMBOLIC_MODEL_PART_FIELDS), 'need_hint': 'Repair the listed Lean fragment envelope errors.' if errors else f"Provide the missing structured parts: {', '.join(missing)}." if missing else 'The plan is complete; assemble it and use Lean diagnostics for local repairs.', 'trust_boundary': 'Structured parts remain untrusted until the mechanically assembled submission is accepted by the Lean judge.'}
    return (None if errors else plan, state)

def merge_symbolic_model_patch(base: dict[str, Any], patch: dict[str, Any]) -> dict[str, Any]:
    source = base.get('plan') if isinstance(base.get('plan'), dict) else base
    merged = deepcopy(source)
    updates = patch.get('set') if isinstance(patch.get('set'), dict) else patch
    for field_name in ('representation', 'model_name', 'imports', 'carrier', 'definitions', 'operation', 'setup', 'hypothesis_proof', 'counterexample_proof'):
        if field_name in updates:
            merged[field_name] = deepcopy(updates[field_name])
    for field_name, value in updates.items():
        match = re.fullmatch('(definitions|setup)\\[(\\d+)\\]', str(field_name))
        if not match:
            continue
        collection_name = match.group(1)
        index = int(match.group(2))
        collection = list(merged.get(collection_name) or [])
        if value is None and index < len(collection):
            collection.pop(index)
        elif index < len(collection):
            collection[index] = deepcopy(value)
        elif index == len(collection):
            collection.append(deepcopy(value))
        merged[collection_name] = collection
    merged['kind'] = 'symbolic_model_plan'
    merged['version'] = SYMBOLIC_MODEL_PLAN_VERSION
    return merged

def _indent_symbolic_fragment(fragment: str, spaces: int) -> list[str]:
    prefix = ' ' * spaces
    return [prefix + line if line.strip() else line for line in fragment.splitlines()]

def assemble_symbolic_model_plan(action: dict[str, Any]) -> tuple[str | None, dict[str, Any]]:
    plan, state = normalize_symbolic_model_plan(action)
    if plan is None or state['status'] != 'plan_ready':
        return (None, state)
    lines: list[str] = []
    line_ranges: dict[str, Any] = {}

    def add(lines_to_add: list[str], part: str | None=None) -> None:
        start = len(lines) + 1
        lines.extend(lines_to_add)
        if part is not None:
            line_ranges[part] = {'start': start, 'end': len(lines)}
    add([f'import {name}' for name in plan['imports']], 'imports')
    add(['', 'def submission : Goal := by'])
    definition_ranges = []
    for index, fragment in enumerate(plan['definitions']):
        start = len(lines) + 1
        add(_indent_symbolic_fragment(fragment, 2))
        definition_ranges.append({'index': index, 'start': start, 'end': len(lines)})
    line_ranges['definitions'] = definition_ranges
    add([f"  let {plan['model_name']} : Magma ({plan['carrier']}) := ⟨{plan['operation']}⟩"], 'operation')
    add([f"  use ({plan['carrier']}), {plan['model_name']}"], 'carrier')
    setup_ranges = []
    for index, fragment in enumerate(plan['setup']):
        start = len(lines) + 1
        add(_indent_symbolic_fragment(fragment, 2))
        setup_ranges.append({'index': index, 'start': start, 'end': len(lines)})
    line_ranges['setup'] = setup_ranges
    add(['  constructor'])
    add(['  · ' + _indent_symbolic_fragment(plan['hypothesis_proof'], 4)[0].lstrip()] + _indent_symbolic_fragment(plan['hypothesis_proof'], 4)[1:], 'hypothesis_proof')
    add(['  · ' + _indent_symbolic_fragment(plan['counterexample_proof'], 4)[0].lstrip()] + _indent_symbolic_fragment(plan['counterexample_proof'], 4)[1:], 'counterexample_proof')
    code = '\n'.join(lines) + '\n'
    artifact_bytes = len(code.encode('utf-8'))
    if artifact_bytes > 20000:
        return (None, {**state, 'status': 'artifact_too_large', 'artifact_bytes': artifact_bytes, 'maximum_artifact_bytes': 20000, 'need_hint': 'The assembled false certificate exceeds 20,000 bytes. Shorten proof fragments or factor repeated reasoning into local setup lemmas.'})
    return (code, {**state, 'status': 'candidate_ready', 'artifact_bytes': artifact_bytes, 'maximum_artifact_bytes': 20000, 'line_ranges': line_ranges, 'assembly': {'model_name': plan['model_name'], 'carrier': plan['carrier'], 'representation': plan['representation'], 'import_count': len(plan['imports']), 'definition_count': len(plan['definitions']), 'setup_count': len(plan['setup'])}, 'need_hint': None})

def symbolic_model_judge_feedback(result: dict[str, Any], assembly_state: dict[str, Any]) -> dict[str, Any]:
    stderr = str(result.get('stderr') or result.get('message') or '')
    line_numbers = [int(value) for value in re.findall('(?:Submission\\.lean|submission\\.lean):(\\d+)', stderr)]
    failed_parts: list[str] = []
    ranges = assembly_state.get('line_ranges') or {}
    for part in ('imports', 'carrier', 'operation', 'hypothesis_proof', 'counterexample_proof'):
        span = ranges.get(part)
        if not isinstance(span, dict):
            continue
        if any((int(span['start']) <= line <= int(span['end']) for line in line_numbers)):
            failed_parts.append(part)
    for span in ranges.get('setup') or []:
        if any((int(span['start']) <= line <= int(span['end']) for line in line_numbers)):
            failed_parts.append(f"setup[{span.get('index')}]")
    for span in ranges.get('definitions') or []:
        if any((int(span['start']) <= line <= int(span['end']) for line in line_numbers)):
            failed_parts.append(f"definitions[{span.get('index')}]")
    lowered = stderr.lower()
    error_classes = []
    for label, needles in (('unknown_identifier', ('unknown identifier', 'unknown constant')), ('type_mismatch', ('type mismatch', 'application type mismatch')), ('unsolved_goals', ('unsolved goals', 'unsolved goal')), ('timeout', ('timed out', 'timeout')), ('syntax', ('unexpected token', 'parser error', 'expected token')), ('disallowed_axiom', ('disallowed axiom', 'uses disallowed'))):
        if any((needle in lowered for needle in needles)):
            error_classes.append(label)
    if not failed_parts:
        if 'hypothesis' in lowered:
            failed_parts.append('hypothesis_proof')
        elif 'counterexample' in lowered or 'not_forall' in lowered:
            failed_parts.append('counterexample_proof')
    failed_bases = {part.split('[', 1)[0] for part in failed_parts}
    return {'failed_parts': failed_parts, 'error_classes': error_classes or ['lean_rejection'], 'error_lines': line_numbers[:8], 'preserve_parts': [part for part in SYMBOLIC_MODEL_PART_FIELDS if part not in failed_bases], 'stderr': short_text(stderr, 1600)}

def validate_infinite_model_payload(data: dict[str, Any]) -> tuple[str | None, dict[str, Any]]:
    code = data.get('code') or data.get('lean_code') or data.get('artifact')
    errors: list[dict[str, Any]] = []
    if not isinstance(code, str) or not code.strip():
        errors.append(ProtocolIssue('missing_infinite_model_code', 'An infinite_model artifact must contain non-empty Lean code.', 'code').to_dict())
    elif 'def submission' not in code or 'Goal' not in code:
        errors.append(ProtocolIssue('missing_submission_definition', 'Lean code must define `submission : Goal` for the judge-controlled false goal.', 'code').to_dict())
    elif re.search('\\bZMod\\b', code):
        errors.append(ProtocolIssue('disallowed_zmod_dependency', 'The official proof policy rejects ZMod/ZMod.* declarations; use Fin, Nat, Int, products, or a submission-defined carrier.', 'code').to_dict())
    elif len(code.encode('utf-8')) > 20000:
        errors.append(ProtocolIssue('infinite_model_artifact_too_large', 'The official false-certificate cap is 20,000 UTF-8 bytes.', 'code').to_dict())
    if errors:
        return (None, protocol_state('InfiniteModelArtifactState', 'invalid_envelope', 'infinite_model_artifact', tool='infinite_model_artifact', errors=errors, need_hint='Return complete Lean code importing JudgeProblem and defining `submission : Goal`.'))
    return (str(code), protocol_state('InfiniteModelArtifactState', 'ready_for_lean_verification', 'infinite_model_artifact', tool='infinite_model_artifact', artifact_bytes=len(str(code).encode('utf-8')), trust_boundary='Envelope checks are syntactic; only the Lean judge can accept the mathematics.'))

def normalize_false_model_payload(data: dict[str, Any]) -> dict[str, Any]:
    out = dict(data)
    out['kind'] = 'tool_call'
    out['tool'] = 'false_model_search'
    if 'route' in out and 'routes' not in out:
        out['routes'] = [out.pop('route')]
    if 'carrier_size' in out and 'sizes' not in out:
        out['sizes'] = [out['carrier_size']]
    return out

def apply_false_route_memory(false_state: dict[str, Any], tried_routes: set[str], budget: float) -> dict[str, Any]:
    state = dict(false_state)
    for trial in state.get('trials') or []:
        route = trial.get('route') if isinstance(trial, dict) else None
        if route:
            tried_routes.add(str(route))
    continuations = [str(route) for route in state.get('untried_requested_routes') or [] if str(route) not in tried_routes]
    state['untried_requested_routes'] = continuations
    highlights = dict(state.get('diagnostic_highlights') or {})
    policy = list(highlights.get('next_action_policy') or [])
    if continuations:
        state['recommended_next_call'] = {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': continuations[:1], 'budget': false_route_budget(continuations[:1], min(8.0, budget))}
        state['suggested_next_actions'] = [state['recommended_next_call']]
        policy = ['Try recommended_next_call first; it is untried in this collaboration pass.', *[item for item in policy if not str(item).startswith('Try recommended_next_call')]][:4]
    else:
        state['recommended_next_call'] = None
        state['suggested_next_actions'] = []
        state['need_hint'] = 'All locally recommended false-search continuations have already been tried in this collaboration pass; propose a new route family or switch to a true-side midpoint/lemma_chain.'
        policy = ['All local continuations have already been tried in this collaboration pass.', 'Do not repeat the tried routes; propose a new route family, a larger/smaller carrier size, a new seed, a full table, or a true-side midpoint/lemma_chain.', *[item for item in policy if 'repeat' not in str(item).lower() and (not str(item).startswith('Try recommended_next_call'))]][:4]
    if highlights:
        highlights['next_action_policy'] = policy
        highlights['untried_after_memory'] = continuations
        highlights['tried_in_collaboration'] = sorted(tried_routes)[-12:]
        state['diagnostic_highlights'] = highlights
    return state

def normalize_llm_action(data: dict[str, Any]) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not isinstance(data, dict):
        issue = ProtocolIssue('not_object', 'LLM response was not a JSON object')
        return (None, protocol_state('LLMAdapterState', 'rejected', 'llm_adapter', errors=[issue.to_dict()], need_hint='Return exactly one JSON object.'))
    repairs: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    out = dict(data)
    if str(out.get('kind') or '').strip() in {'candidate_bundle', 'proposal_bundle', 'ranked_candidates'}:
        raw_candidates = out.get('candidates')
        lemmas: list[dict[str, Any]] = []
        if isinstance(raw_candidates, list):
            for rank, candidate in enumerate(raw_candidates[:6], start=1):
                if isinstance(candidate, str):
                    equation = candidate
                    name = f'candidate_{rank}'
                elif isinstance(candidate, dict):
                    equation = candidate.get('equation') or candidate.get('lemma') or candidate.get('midpoint') or candidate.get('claim')
                    name = candidate.get('name') or f'candidate_{rank}'
                else:
                    continue
                if isinstance(equation, str) and '=' in equation:
                    lemmas.append({'name': name, 'equation': equation, 'rank': rank})
        if lemmas:
            out = {'kind': 'midpoint_chain', 'lemmas': lemmas, **({'budget': data['budget']} if 'budget' in data else {}), **({'budget_policy': data['budget_policy']} if 'budget_policy' in data else {}), **({'why': data['why']} if 'why' in data else {})}
            repairs.append(ProtocolIssue('candidate_bundle_normalized', 'Normalized ranked candidate bundle to the midpoint-chain consumer', 'candidates').to_dict())
        else:
            errors.append(ProtocolIssue('empty_candidate_bundle', 'candidate_bundle must contain 1-6 equation candidates', 'candidates').to_dict())
    if isinstance(out.get('action'), dict) and (not any((key in out for key in ('kind', 'tool', 'lemma', 'lemmas', 'midpoint', 'midpoints', 'verdict', 'counterexample_table', 'table')))):
        out = dict(out['action'])
        repairs.append(ProtocolIssue('action_envelope', 'Unwrapped top-level action object', 'action').to_dict())
    if 'type' in out and 'kind' not in out:
        action_type = str(out.pop('type') or '').strip()
        if action_type in {'false_model_search', 'countermodel_search', 'finite_model_search'}:
            out['kind'] = 'tool_call'
            out['tool'] = 'false_model_search'
        else:
            out['kind'] = action_type
        repairs.append(ProtocolIssue('type_alias', 'Renamed type to protocol kind/tool', 'type').to_dict())
    if 'route' in out and 'routes' not in out:
        out['routes'] = [out.pop('route')]
        repairs.append(ProtocolIssue('route_alias', 'Renamed singular route to routes list', 'route').to_dict())
    if 'tool_name' in out and 'tool' not in out:
        out['tool'] = out.pop('tool_name')
        repairs.append(ProtocolIssue('field_alias', 'Renamed tool_name to tool', 'tool_name').to_dict())
    if out.get('tool') and (not out.get('kind')):
        out['kind'] = 'tool_call'
        repairs.append(ProtocolIssue('tool_call_kind_inferred', 'Inferred kind=tool_call from the tool field', 'kind').to_dict())
    if out.get('kind') == 'tool':
        out['kind'] = 'tool_call'
        repairs.append(ProtocolIssue('kind_alias', 'Renamed kind=tool to kind=tool_call', 'kind').to_dict())
    if not out.get('tool') and str(out.get('kind') or '') in {'residue_ray_countermodel', 'residue_clamped_affine_search', 'residue_ray_search', 'symbolic_ray_search'}:
        raw_kind = str(out['kind'])
        out['kind'] = 'tool_call'
        out['tool'] = TOOL_ALIASES[raw_kind]
        repairs.append(ProtocolIssue('tool_kind_alias', f'Normalized kind={raw_kind} to a tool_call', 'kind').to_dict())
    if 'proof_body' in out and 'proof' not in out:
        out['proof'] = out.pop('proof_body')
        repairs.append(ProtocolIssue('field_alias', 'Renamed proof_body to proof', 'proof_body').to_dict())
    if 'lemma_chain' in out and 'lemmas' not in out:
        out['lemmas'] = out.pop('lemma_chain')
        if not out.get('kind'):
            out['kind'] = 'lemma_chain'
        repairs.append(ProtocolIssue('field_alias', 'Normalized top-level lemma_chain payload to kind=lemma_chain with lemmas', 'lemma_chain').to_dict())
    raw_tool = str(out.get('tool') or '').strip()
    if raw_tool:
        tool = TOOL_ALIASES.get(raw_tool, raw_tool)
        if tool != raw_tool:
            out['tool'] = tool
            repairs.append(ProtocolIssue('tool_alias', f'Normalized tool alias {raw_tool} to {tool}', 'tool').to_dict())
    elif out.get('kind') == 'tool_call':
        errors.append(ProtocolIssue('missing_tool', 'tool_call responses must name a supported tool', 'tool').to_dict())
    if out.get('kind') == 'tool_call':
        tool = TOOL_ALIASES.get(str(out.get('tool') or '').strip(), out.get('tool'))
        if tool not in TOOL_REGISTRY:
            errors.append(ProtocolIssue('unknown_tool', f"Unsupported tool {out.get('tool')!r}. For true-side bridges, return kind=midpoint with a lemma equation or tool=lemma_chain with lemmas.", 'tool').to_dict())
    if is_false_model_family_payload(out):
        out['kind'] = 'tool_call'
        out['tool'] = 'false_model_family'
    elif is_symbolic_model_plan_payload(out):
        original_kind = str(out.get('kind') or '')
        out['kind'] = 'symbolic_model_plan'
        if original_kind != out['kind']:
            repairs.append(ProtocolIssue('symbolic_plan_kind_alias', f'Normalized {original_kind} to symbolic_model_plan', 'kind').to_dict())
    elif is_symbolic_model_patch_payload(out):
        original_kind = str(out.get('kind') or '')
        out['kind'] = 'symbolic_model_patch'
        if original_kind != out['kind']:
            repairs.append(ProtocolIssue('symbolic_patch_kind_alias', f'Normalized {original_kind} to symbolic_model_patch', 'kind').to_dict())
    elif is_infinite_model_payload(out):
        out['kind'] = 'tool_call'
        out['tool'] = 'infinite_model_artifact'
    elif is_false_model_payload(out):
        before = dict(out)
        out = normalize_false_model_payload(out)
        if out != before:
            repairs.append(ProtocolIssue('false_payload_normalized', 'Normalized false-model hint to false_model_search tool call').to_dict())
    elif is_hint_payload(out):
        kind = str(out.get('kind') or '').strip()
        if kind not in {'tool_call', 'midpoint', 'midpoint_chain', 'lemma_hint', 'lemma_chain'}:
            out['kind'] = 'midpoint_chain' if isinstance(out.get('lemmas'), list) else 'midpoint'
            repairs.append(ProtocolIssue('hint_kind_inferred', f"Inferred hint kind {out['kind']}", 'kind').to_dict())
        if out.get('kind') == 'tool_call':
            tool = TOOL_ALIASES.get(str(out.get('tool') or '').strip(), out.get('tool'))
            if tool in {'lemma_chain', 'lemma_hint', 'midpoint', 'midpoint_chain'}:
                out['tool'] = tool
    elif out.get('kind') in {'false_table', 'goal_proof', 'tool_call'} or out.get('verdict') in {'true', 'false'}:
        pass
    else:
        errors.append(ProtocolIssue('unsupported_action', 'Response did not match a supported protocol-v0 action').to_dict())
    if errors:
        return (None, protocol_state('LLMAdapterState', 'rejected', 'llm_adapter', errors=errors, raw_kind=data.get('kind'), need_hint='Return a supported action: tool_call, midpoint, midpoint_chain, lemma_chain, false_model_search, false_model_family, residue_ray_countermodel, symbolic_model_plan, symbolic_model_patch, infinite_model, false_table, or goal_proof.'))
    if repairs:
        return (out, protocol_state('LLMAdapterState', 'syntax_repaired', 'llm_adapter', repairs=repairs, normalized_action=compact_tool_signature(out) if 'compact_tool_signature' in globals() else out))
    return (out, None)

def compact_feedback_value(value: Any, *, string_limit: int, depth: int=0) -> Any:
    if depth >= 6:
        return short_text(str(value), min(string_limit, 180))
    if isinstance(value, dict):
        return {str(k): compact_feedback_value(v, string_limit=string_limit, depth=depth + 1) for k, v in value.items()}
    if isinstance(value, list):
        keep = 8 if depth <= 2 else 4
        out = [compact_feedback_value(v, string_limit=string_limit, depth=depth + 1) for v in value[:keep]]
        if len(value) > keep:
            out.append({'truncated_items': len(value) - keep})
        return out
    if isinstance(value, str):
        return short_text(value, string_limit)
    return value

def feedback_json(feedback: list[dict[str, Any]]) -> str:
    if not feedback:
        return 'No solver-side midpoint feedback yet.'
    recent = feedback[-3:]
    for item_count in (3, 2, 1):
        for string_limit in (800, 400, 220, 120):
            compact = [compact_feedback_value(item, string_limit=string_limit) for item in recent[-item_count:]]
            text = json.dumps(compact, ensure_ascii=False)
            if len(text) <= 8000:
                return text
    fallback = [{'kind': item.get('kind'), 'status': item.get('status'), 'source': item.get('source'), 'need_hint': short_text(str(item.get('need_hint')), 500)} for item in recent[-1:]]
    return json.dumps(fallback, ensure_ascii=False)

def latest_midpoint_recommendation(feedback: list[dict[str, Any]]) -> dict[str, Any] | None:

    def find(value: Any) -> dict[str, Any] | None:
        if isinstance(value, dict):
            action = value.get('recommended_next_action')
            if isinstance(action, dict) and action.get('kind') == 'midpoint':
                return action
            for child in value.values():
                found = find(child)
                if found:
                    return found
        elif isinstance(value, list):
            for child in value:
                found = find(child)
                if found:
                    return found
        return None
    for state in reversed(feedback):
        found = find(state)
        if found:
            return found
    return None

def frontier_prompt_advice(action: dict[str, Any], h_eq: dict[str, Any]) -> tuple[dict[str, Any], str]:
    lemma = str(action.get('lemma') or '').strip()
    equation: dict[str, Any] | None = None
    try:
        equation = parse_equation(lemma)
        node_count = term_size(equation['lhs']) + term_size(equation['rhs'])
    except (TypeError, ValueError):
        node_count = 999
    idempotence_frontier = False
    self_embedding_frontier = False
    if equation is not None:
        for variable_side, product_side in ((equation['lhs'], equation['rhs']), (equation['rhs'], equation['lhs'])):
            if variable_side[0] == 'var' and product_side[0] == 'op' and (product_side[1] == variable_side) and (product_side[2] == variable_side):
                idempotence_frontier = True
                break
            if variable_side[0] == 'var' and product_side[0] == 'op' and (product_side[1] == variable_side) and (variable_side[1] in pc_vars_of(product_side[2])):
                self_embedding_frontier = True
    collapse_ladder = {'kind': 'tool_call', 'tool': 'lemma_chain', 'target': 'goal', 'lemmas': [{'name': 'idempotence', 'equation': 'a = a ◇ a'}, {'name': 'proj_l', 'equation': 'a ◇ b = a'}, {'name': 'collapse', 'equation': 'a = b'}]}
    large_frontier = node_count > 18 or len(lemma) > 120
    if not large_frontier:
        if (idempotence_frontier or self_embedding_frontier) and one_sided_variables(h_eq) and (h_eq['lhs'][0] == 'var' or h_eq['rhs'][0] == 'var'):
            return ({'kind': 'proof_carrying_collapse_ladder_recommendation', 'frontier_evidence': action, 'frontier_shape': 'idempotence' if idempotence_frontier else 'self_embedding_absorption', 'recommended_next_action': collapse_ladder, 'instruction': 'A compact self-embedding absorption law is a mechanically reached first rung under a collapse-shaped hypothesis. Complete the dependency ladder: idempotence, one supported projection, then a = b. Do not stop after resubmitting proved-but-not-connected rungs; the final collapse is the new bridge that lets arbitrary goals close.'}, ' The compact frontier is self-embedding absorption in a collapse-shaped problem. Complete the full idempotence-to-projection-to-collapse ladder. If earlier rungs are already proved_but_not_connected, add a = b instead of repeating only them.')
        return ({'kind': 'proof_carrying_frontier_recommendation', 'recommended_next_action': action, 'instruction': 'Use this compact mechanically reached equation as the first rung of an ordered lemma_chain; do not repeat the failed direct tool call.'}, ' Follow the compact proof-carrying frontier recommendation before generic tool advice. Later chain rungs may use every earlier proved lemma.')
    advice = {'kind': 'frontier_abstraction_recommendation', 'frontier_evidence': action, 'frontier_nodes': node_count, 'instruction': 'This frontier is too large to copy as a midpoint. Treat it as evidence: remove repeated contexts and propose the smallest reusable law or ordered dependency ladder that explains the movement. Do not return the literal frontier unchanged. An ordered chain contains dependencies, not competing alternatives; put alternatives in candidate_bundle.', 'candidate_families': ['idempotence or absorption', 'one projection direction', 'row/factor irrelevance', 'contraction after a shared context is removed']}
    if one_sided_variables(h_eq) and (h_eq['lhs'][0] == 'var' or h_eq['rhs'][0] == 'var'):
        advice['conditional_repair'] = {'trigger': 'H has a lone-variable side and one-sided variables, so a collapse ladder is structurally plausible. Try it only as an ordered proof plan; the mechanical consumer will reject any unproved rung.', 'action': collapse_ladder}
    directive = ' The proof-carrying frontier is large: use it as structural evidence, not as a mandatory literal first rung. Propose a smaller reusable law or dependency ladder. Do not repeat an unchanged unproved_with_budget candidate. Do not place incompatible alternatives such as both projections in one ordered chain.'
    return (advice, directive)

def llm_context(h_eq: dict[str, Any], g_eq: dict[str, Any], mechanical_feedback: list[dict[str, Any]], collaboration_goal: str, *, prefer_false: bool | str=False, semantic_context: dict[str, Any] | None=None, capability_mask: Any=None, allow_infinite_model_artifacts: bool=False, active_symbolic_plan: dict[str, Any] | None=None, candidate_blackboard: CandidateBlackboard | None=None) -> dict[str, Any]:
    if not finite_countermodel_search_allowed(semantic_context):
        phase_directive = 'Finite countermodel search is prohibited by the audited semantic status. Do not return a finite table or finite_model_search call. Instead propose a structured infinite symbolic model.' + (' Prefer symbolic_model_plan so local Lean failures can be repaired with symbolic_model_patch; a complete infinite_model artifact remains an expert path.' if allow_infinite_model_artifacts else ' The Lean judge goal can express an infinite model, but this pass has not enabled whole-artifact responses.')
        advice_prefer_false = False
    elif prefer_false is True:
        phase_directive = 'This is a false-preferred recovery pass. Return false_model_search, false_model_family, residue_ray_countermodel, false_table, or a concrete midpoint/lemma_chain only. Prefer recommended_next_call when present. If fixed routes are exhausted, propose a coherent symbolic family rather than arbitrary table patches. Never repeat routes listed in diagnostic_highlights.tried_routes or diagnostic_highlights.tried_in_collaboration. Do not call standard_aux_superposition, proof_battery, forward_saturation, or goal_superposition in this pass; those true-side routes were already tried or are low-confidence.'
        advice_prefer_false = True
    elif prefer_false == 'balanced':
        if false_strategy_cards(mechanical_feedback):
            phase_directive = 'This is a balanced pre-child recovery pass with concrete false-route telemetry. Return the false_model_search recommended_next_call, a coherent false_model_family, a concrete false_table, or a real midpoint/lemma_chain only. Never repeat routes listed in diagnostic_highlights.tried_routes or diagnostic_highlights.tried_in_collaboration. Do not call standard_aux_superposition, proof_battery, forward_saturation, or goal_superposition while a false continuation card is available.'
        else:
            phase_directive = 'This is a balanced pre-child recovery pass after native true and false tools failed. Prefer a concrete midpoint/lemma_chain that repairs the failed true-side attempts. Use false_model_search only if the feedback gives a specific untried countermodel route; never repeat stale false routes listed in diagnostic_highlights.tried_routes or diagnostic_highlights.tried_in_collaboration.'
        advice_prefer_false = False
    else:
        phase_directive = 'This is a true-collaboration pass. Prefer the top focused true tool or a concrete midpoint/lemma_chain; use false_model_search only if a finite countermodel route is specifically plausible.'
        advice_prefer_false = False
    symbolic_only = not finite_countermodel_search_allowed(semantic_context)
    if symbolic_only:
        symbolic_advice: Any = {'kind': 'audited_semantic_recommendation', 'recommended_next_action': {'kind': 'symbolic_model_patch' if active_symbolic_plan else 'symbolic_model_plan'}, 'prohibited': ['finite_model_search', 'false_table', 'symbolic_finite', 'true_side_tools'], 'reason': 'The finite implication is audited true while the unrestricted implication is false.'}
        cards_for_prompt = json.dumps(symbolic_model_strategy_cards(require_infinite=True), ensure_ascii=False)
        fewshots_for_prompt = 'For this lane, return only symbolic_model_plan, symbolic_model_patch, or a complete infinite_model artifact. A plan separates carrier, pre-model definitions, operation, setup lemmas, the universal H proof, and a concrete refutation of G. After rejection, patch only failed_parts.'
    else:
        frontier_action = latest_midpoint_recommendation(mechanical_feedback)
        if frontier_action and (not advice_prefer_false):
            symbolic_advice, frontier_directive = frontier_prompt_advice(frontier_action, h_eq)
            phase_directive += frontier_directive
        else:
            symbolic_advice = tool_advice(h_eq, g_eq, prefer_false=advice_prefer_false)
        cards_for_prompt = strategy_cards_text(h_eq, g_eq, mechanical_feedback, prefer_false=prefer_false)
        fewshots_for_prompt = sidecar_fewshots(h_eq)
    context = {'problem_analysis': problem_analysis(h_eq, g_eq), 'analysis': analysis(h_eq, g_eq), 'tool_registry': tool_registry_text(capability_mask, include_research_tools=allow_infinite_model_artifacts), 'tool_advice': symbolic_advice, 'strategy_cards': cards_for_prompt, 'phase_directive': phase_directive, 'judge_feedback': judge_feedback_json(), 'mechanical_feedback': feedback_json(mechanical_feedback), 'candidate_blackboard': json.dumps(candidate_blackboard.snapshot() if candidate_blackboard else {'protocol_version': 'candidate-blackboard-v1', 'candidate_count': 0, 'candidates': []}, ensure_ascii=False), 'fewshots': fewshots_for_prompt, 'collaboration_goal': collaboration_goal}
    if symbolic_only:
        context['allowed_action_override'] = ['symbolic_model_plan', 'symbolic_model_patch', 'infinite_model']
    if capability_mask is not None:
        context['capability_manifest'] = capability_manifest(capability_mask)
    if semantic_context and semantic_context.get('semantic_class') != 'unclassified':
        context['semantic_context'] = semantic_context
    if allow_infinite_model_artifacts:
        require_infinite = not finite_countermodel_search_allowed(semantic_context)
        context['symbolic_model_contract'] = {'preferred_action': {'kind': 'symbolic_model_plan', 'representation': 'infinite' if require_infinite else 'symbolic_finite', 'model_name': 'model', 'imports': ['Mathlib.Tactic'], 'carrier': 'Lean carrier type, such as ℕ, ℤ, Fin n, a product, or a submission-defined inductive type', 'definitions': ['local definitions needed before the Magma value, such as parity and op'], 'operation': 'a total Lean expression or a name introduced in definitions', 'setup': ['local helper declarations/proofs'], 'hypothesis_proof': 'tactic body proving H universally', 'counterexample_proof': 'tactic body exhibiting a concrete failure of G'}, 'proof_policy': 'Do not use ZMod or ZMod.* declarations. Keep helper definitions and lemmas local inside def submission, or name them under submission.*.', 'repair_action': {'kind': 'symbolic_model_patch', 'set': {'failed_part_name': 'complete replacement fragment'}}, 'whole_artifact_fast_path': {'kind': 'infinite_model', 'code': 'complete Lean source importing JudgeProblem and defining submission : Goal'}, 'construction_cards': symbolic_model_strategy_cards(require_infinite=require_infinite), 'repair_rule': 'After Lean rejects a plan, preserve every component in preserve_parts and replace only failed_parts unless the diagnostic proves a dependency changed.', 'trust_boundary': 'The solver may sample or assemble a candidate, but only the official Lean judge can accept the universal hypothesis proof and concrete refutation.'}
    if active_symbolic_plan is not None:
        context['active_symbolic_plan'] = json.dumps(active_symbolic_plan, ensure_ascii=False)
        context['active_symbolic_plan_instruction'] = 'This is the complete current plan from the previous round. Return a symbolic_model_patch changing only missing_parts or failed_parts; do not regenerate components listed in preserve_parts.'
    return context

def compact_tool_signature(data: dict[str, Any]) -> str:
    if data.get('tool') == 'false_model_search':
        return json.dumps({'tool': 'false_model_search', 'routes': data.get('routes') or [], 'sizes': data.get('sizes') or [], 'seeds': data.get('seeds') or [], 'template': data.get('template')}, sort_keys=True)
    if is_false_model_family_payload(data):
        family = normalize_symbolic_family_payload(data)
        return json.dumps({'tool': 'false_model_family', 'carrier_size': family.get('carrier_size'), 'default': family.get('default'), 'rules': family.get('rules') or [], 'patches': family.get('patches') or []}, sort_keys=True, ensure_ascii=False)[:2000]
    if is_hint_payload(data):
        return json.dumps({'kind': data.get('kind'), 'tool': data.get('tool'), 'lemmas': data.get('lemmas') or data.get('lemma') or data.get('midpoints') or data.get('midpoint')}, sort_keys=True, ensure_ascii=False)
    if is_symbolic_model_plan_payload(data):
        return json.dumps({'kind': 'symbolic_model_plan', 'representation': data.get('representation'), 'carrier': data.get('carrier'), 'definition_count': len(data.get('definitions') or []), 'operation': short_text(str(data.get('operation') or ''), 500), 'setup_count': len(data.get('setup') or []), 'hypothesis_proof': short_text(str(data.get('hypothesis_proof') or ''), 300), 'counterexample_proof': short_text(str(data.get('counterexample_proof') or ''), 300)}, sort_keys=True, ensure_ascii=False)
    if is_symbolic_model_patch_payload(data):
        updates = data.get('set') if isinstance(data.get('set'), dict) else data
        return json.dumps({'kind': 'symbolic_model_patch', 'fields': sorted((key for key in updates if key in {'representation', 'carrier', 'definitions', 'operation', 'setup', 'hypothesis_proof', 'counterexample_proof'})), 'content': {key: short_text(str(value), 300) for key, value in updates.items() if key in {'carrier', 'definitions', 'operation', 'setup', 'hypothesis_proof', 'counterexample_proof'}}}, sort_keys=True, ensure_ascii=False)
    if data.get('kind') == 'tool_call' or data.get('tool'):
        return json.dumps({key: value for key, value in data.items() if key not in {'why', 'reason', 'rationale', 'explanation'}}, sort_keys=True, ensure_ascii=False)[:1000]
    return json.dumps(data, sort_keys=True, ensure_ascii=False)[:500]

def repair_starved_standard_aux_action(data: dict[str, Any], mechanical_feedback: list[dict[str, Any]]) -> tuple[dict[str, Any], dict[str, Any] | None]:
    raw_tool = str(data.get('tool') or '').strip()
    tool = TOOL_ALIASES.get(raw_tool, raw_tool)
    if tool != 'standard_aux_superposition':
        return (data, None)
    starved: dict[str, float] = {}
    stack: list[Any] = list(mechanical_feedback)
    seen: set[int] = set()
    while stack:
        value = stack.pop()
        if isinstance(value, dict):
            marker = id(value)
            if marker in seen:
                continue
            seen.add(marker)
            if value.get('kind') == 'StandardAuxSuperpositionState':
                for attempt in value.get('attempts') or []:
                    if not isinstance(attempt, dict) or attempt.get('status') != 'budget_starved':
                        continue
                    kind = str(attempt.get('kind') or '')
                    if kind:
                        starved[kind] = max(starved.get(kind, 0.0), _finite_float(attempt.get('attempt_budget'), 0.0))
            stack.extend(value.values())
        elif isinstance(value, list):
            stack.extend(value)
    if not starved:
        return (data, None)
    requested = standard_aux_order(data)
    focused = [kind for kind in requested if kind in starved]
    if not focused:
        return (data, None)
    previous_budget = max((starved[kind] for kind in focused))
    renewed_budget = min(40.0, max(16.0, previous_budget * 2.0))
    current_budget = _finite_float(data.get('budget', data.get('time_budget')), 0.0)
    out = dict(data)
    out['lemmas'] = focused
    out.pop('lemma', None)
    out.pop('time_budget', None)
    out['budget'] = max(current_budget, renewed_budget)
    if out == data:
        return (data, None)
    return (out, protocol_state('LLMAdapterState', 'budget_repaired', 'llm_adapter', tool='standard_aux_superposition', repairs=[ProtocolIssue('renew_budget_starved_aux', 'Focused the call on the implied budget-starved auxiliary and doubled its prior grant.', 'budget').to_dict()], prior_attempt_budget=previous_budget, normalized_action={'kind': 'tool_call', 'tool': 'standard_aux_superposition', 'lemmas': focused, 'budget': out['budget']}))

def feedback_driven_aux_retry_action(h_eq: dict[str, Any], aux_state: dict[str, Any], remaining_budget: float) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    frontier = latest_midpoint_recommendation([aux_state])
    if frontier is None:
        return (None, None)
    advice, _directive = frontier_prompt_advice(frontier, h_eq)
    if advice.get('kind') != 'proof_carrying_collapse_ladder_recommendation':
        return (None, None)
    attempted = [str(attempt.get('kind')) for attempt in aux_state.get('attempts') or [] if isinstance(attempt, dict) and attempt.get('kind')]
    if not attempted:
        return (None, None)
    previous_budget = max([_finite_float(attempt.get('attempt_budget'), 0.0) for attempt in aux_state.get('attempts') or [] if isinstance(attempt, dict)] or [0.0])
    action, repair_state = repair_starved_standard_aux_action({'kind': 'tool_call', 'tool': 'standard_aux_superposition', 'target': 'goal', 'lemmas': attempted, 'budget': previous_budget}, [aux_state])
    if repair_state is None:
        return (None, None)
    renewed_budget = _finite_float(action.get('budget'), 0.0)
    if renewed_budget < 12.0 or remaining_budget < renewed_budget:
        return (None, None)
    return (action, protocol_state('AuxContinuationState', 'frontier_supported_retry', 'feedback_scheduler', frontier=frontier, frontier_advice=advice, retry_action=action, need_hint='If the focused retry still fails, use the collapse ladder in frontier_advice as an ordered lemma_chain.'))

def should_try_collaboration_first(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> bool:
    return bool(right_square_h_roles(h_eq) or square_sandwich_h_roles(h_eq) or rowconst_h_roles(h_eq) or repeated_self_absorption_h(h_eq, g_eq) or goal_generalization_actions(h_eq, g_eq))

def try_llm_collaboration(h_eq: dict[str, Any], g_eq: dict[str, Any], budget: float, *, max_rounds: int, collaboration_goal: str, initial_feedback: list[dict[str, Any]] | None=None, prefer_false: bool | str=False, feedback_sink: list[dict[str, Any]] | None=None, semantic_context: dict[str, Any] | None=None, capability_mask: Any=None, allow_infinite_model_artifacts: bool=False, hint_budget_cap: float | None=None, failed_signatures: set[str] | None=None, candidate_blackboard: CandidateBlackboard | None=None) -> str | None:
    mechanical_feedback: list[dict[str, Any]] = list(initial_feedback or [])
    opening_feedback: list[dict[str, Any]] = list(mechanical_feedback)
    finite_search_allowed = finite_countermodel_search_allowed(semantic_context)
    if semantic_context and semantic_context.get('semantic_class') != 'unclassified':
        mechanical_feedback.insert(0, semantic_status_state(semantic_context))
    failed_signatures = failed_signatures if failed_signatures is not None else set()
    candidate_blackboard = candidate_blackboard or CandidateBlackboard()
    tried_false_routes: set[str] = false_tried_routes_from_states(false_feedback_states(mechanical_feedback, limit=None))
    active_symbolic_plan: dict[str, Any] | None = None
    deadline = time.monotonic() + max(8.0, min(90.0, budget * 0.35))
    rounds = 0
    alternate_model_enabled = True
    while rounds < max_rounds and time.monotonic() < deadline:
        rounds += 1
        blackboard_round = candidate_blackboard.next_round()
        round_model = LLM_ALTERNATE_MODEL if alternate_model_enabled and _LLM_CALLS_THIS_SOLVE >= 1 and (_LLM_CALLS_THIS_SOLVE % 2 == 1) else None
        round_feedback = opening_feedback if round_model is not None else mechanical_feedback
        resp = call_llm(llm_context(h_eq, g_eq, round_feedback, collaboration_goal, prefer_false=prefer_false, semantic_context=semantic_context, capability_mask=capability_mask, allow_infinite_model_artifacts=allow_infinite_model_artifacts, active_symbolic_plan=active_symbolic_plan, candidate_blackboard=candidate_blackboard), model=round_model)
        if resp.get('error'):
            if round_model is not None:
                alternate_model_enabled = False
                mechanical_feedback.append(protocol_state('LLMAdapterState', 'alternate_model_unavailable', 'llm_provider', errors=[ProtocolIssue('provider_error', short_text(str(resp.get('error')), 300)).to_dict()], need_hint='Alternate model unavailable; continuing on the default model.'))
                continue
            mechanical_feedback.append(protocol_state('LLMAdapterState', 'provider_error', 'llm_provider', errors=[ProtocolIssue('provider_error', short_text(str(resp.get('error')), 500)).to_dict()], need_hint='LLM provider failed; stop this collaboration pass and fall back to deterministic routes.'))
            break
        data = extract_json(resp.get('response', ''))
        if not data:
            mechanical_feedback.append(protocol_state('LLMAdapterState', 'parse_failed', 'llm_adapter', errors=[ProtocolIssue('no_json_object', 'No JSON object could be extracted from the LLM response').to_dict()], need_hint='Return exactly one JSON object containing a midpoint, midpoint_chain, tool_call, false_model_family, proof, or false_table.'))
            continue
        data, adapter_state = normalize_llm_action(data)
        if adapter_state is not None:
            mechanical_feedback.append(adapter_state)
        if not data:
            continue
        if is_residue_ray_payload(data):
            sig = compact_tool_signature(data)
            gate_state = capability_gate_state('residue_ray_countermodel', capability_mask)
            if gate_state is not None:
                mechanical_feedback.append(gate_state)
                failed_signatures.add(sig)
                continue
            if sig in failed_signatures:
                mechanical_feedback.append(protocol_state('MechanicalResponse', 'duplicate_failed_call', 'scheduler', tool='residue_ray_countermodel', need_hint='Do not repeat this exact residue-ray search. Narrow or change its modulus/coefficient sets using the reported H and involution failures.'))
                continue
            code, ray_state = residue_ray_countermodel_attempt(h_eq, g_eq, data)
            mechanical_feedback.append(ray_state)
            if code is not None:
                result = judge_infinite_model_artifact_attributed('llm:residue_ray_countermodel', code, detail={'signature': sig, 'family': 'residue_controlled_clamped_affine', 'checked_candidates': (ray_state.get('search_state') or {}).get('checked_candidates')})
                if result.get('status') == 'accepted':
                    return 'accepted_false_residue_ray_llm'
                mechanical_feedback.append(protocol_state('ResidueRayCertificateState', 'judge_rejected', 'lean_judge', tool='residue_ray_countermodel', candidate=ray_state.get('candidate'), errors=[ProtocolIssue('judge_rejected_residue_ray', short_text(result.get('stderr') or result.get('message') or '', 1000)).to_dict()], need_hint='Preserve the discovered operation and repair only the reported symbolic proof obligation.'))
            failed_signatures.add(sig)
            continue
        if is_symbolic_model_plan_payload(data) or is_symbolic_model_patch_payload(data):
            sig = compact_tool_signature(data)
            gate_state = capability_gate_state('infinite_model_artifact', capability_mask)
            if gate_state is not None:
                mechanical_feedback.append(gate_state)
                failed_signatures.add(sig)
                continue
            if not allow_infinite_model_artifacts:
                mechanical_feedback.append(protocol_state('SymbolicModelPlanState', 'disabled_in_this_pass', 'symbolic_model_plan', tool='infinite_model_artifact', need_hint='This pass did not enable Type-level symbolic models. Use a supported action for this phase or wait for the symbolic-model lane.'))
                failed_signatures.add(sig)
                continue
            if is_symbolic_model_patch_payload(data):
                if active_symbolic_plan is None:
                    mechanical_feedback.append(protocol_state('SymbolicModelPlanState', 'patch_without_parent', 'symbolic_model_plan', tool='infinite_model_artifact', errors=[ProtocolIssue('patch_without_parent', 'No prior symbolic_model_plan exists in this collaboration pass.').to_dict()], need_hint='Return a complete symbolic_model_plan before sending a patch.'))
                    failed_signatures.add(sig)
                    continue
                candidate_plan = merge_symbolic_model_patch(active_symbolic_plan, data)
            else:
                candidate_plan = data
            normalized_plan, plan_state = normalize_symbolic_model_plan(candidate_plan)
            mechanical_feedback.append(plan_state)
            if normalized_plan is None:
                failed_signatures.add(sig)
                continue
            if not finite_search_allowed and normalized_plan.get('representation') == 'symbolic_finite':
                mechanical_feedback.append(protocol_state('SymbolicModelPlanState', 'semantically_blocked', 'semantic_registry', tool='infinite_model_artifact', representation='symbolic_finite', need_hint='Audited semantics rule out every finite model. Change the carrier and representation to a genuinely infinite construction.'))
                failed_signatures.add(sig)
                continue
            active_symbolic_plan = normalized_plan
            code, assembly_state = assemble_symbolic_model_plan(normalized_plan)
            mechanical_feedback.append(assembly_state)
            if code is None:
                failed_signatures.add(sig)
                continue
            result = judge_infinite_model_artifact_attributed('llm:symbolic_model_plan', code, detail={'signature': sig, 'representation': normalized_plan.get('representation'), 'structured': True})
            if result.get('status') == 'accepted':
                return 'accepted_false_symbolic_model_llm'
            failure = symbolic_model_judge_feedback(result, assembly_state)
            mechanical_feedback.append(protocol_state('SymbolicModelPlanState', 'judge_rejected', 'lean_judge', tool='infinite_model_artifact', representation=normalized_plan.get('representation'), active_plan={key: value for key, value in normalized_plan.items() if key not in {'hypothesis_proof', 'counterexample_proof', 'setup'}}, failed_parts=failure['failed_parts'], preserve_parts=failure['preserve_parts'], error_classes=failure['error_classes'], error_lines=failure['error_lines'], errors=[ProtocolIssue('judge_rejected_symbolic_model', failure['stderr']).to_dict()], need_hint='Return symbolic_model_patch replacing only failed_parts and preserving preserve_parts. Use the exact Lean diagnostic.'))
            failed_signatures.add(sig)
            continue
        if is_false_model_family_payload(data):
            sig = compact_tool_signature(data)
            gate_state = capability_gate_state('false_model_family', capability_mask)
            if gate_state is not None:
                mechanical_feedback.append(gate_state)
                failed_signatures.add(sig)
                continue
            if not finite_search_allowed:
                mechanical_feedback.append(semantic_status_state(semantic_context or {}))
                failed_signatures.add(sig)
                continue
            if sig in failed_signatures:
                mechanical_feedback.append(protocol_state('MechanicalResponse', 'duplicate_failed_call', 'scheduler', tool='false_model_family', need_hint='Do not repeat this exact failed symbolic family; repair its H/G diagnostics or change representation.'))
                continue
            found, family_state = false_model_family_attempt(h_eq, g_eq, data)
            if found is not None:
                n, table = found
                emit_attribution_attempt('llm:false_model_family:table', 'false', source='llm_symbolic_family', detail={'signature': sig, 'family_summary': family_state.get('family_summary')})
                code = make_false_code(n, table)
                result = call_judge('false', code)
                record_judge_feedback('llm:false_model_family:table', 'false', code, result, source='llm_symbolic_family')
                if result.get('status') == 'accepted':
                    return 'accepted_false_model_family_llm'
                mechanical_feedback.append(protocol_state('FalseModelFamilyState', 'judge_rejected', 'lean_judge', tool='false_model_family', family_state=family_state, errors=[ProtocolIssue('judge_rejected_false_model_family', short_text(result.get('stderr') or result.get('message') or '', 1000)).to_dict()], need_hint='The family passed Python H/G validation but its Lean certificate was rejected; repair using the exact judge diagnostic.'))
            else:
                mechanical_feedback.append(family_state)
