            ray_call = {'kind': 'tool_call', 'tool': 'residue_ray_countermodel', 'target': 'goal', 'moduli': [2], 'a_values': [-1, 0, 1], 'b_values': [-1, 0, 1], 'c_values': [-1, 0, 1], 'candidate_cap': 2000, 'budget': 2}
