@dataclass(frozen=True)
class ProtocolIssue:
    code: str
    message: str
    field: str | None = None

    def to_dict(self) -> dict[str, Any]:
        out = {'code': self.code, 'message': self.message}
        if self.field:
            out['field'] = self.field
        return out

def protocol_state(kind: str, status: str, source: str, **extra: Any) -> dict[str, Any]:
    out: dict[str, Any] = {'protocol_version': PROTOCOL_VERSION, 'kind': kind, 'status': status, 'source': source}
    contract = tool_contract(extra.get('tool') or source) if 'tool_contract' not in extra else None
    if contract:
        out['tool_contract'] = contract
    for key, value in extra.items():
        if value is not None:
            out[key] = value
    return out

def protocolize_state(state: dict[str, Any] | None, source: str, *, status: str | None=None, suggested_next_actions: list[dict[str, Any]] | None=None, errors: list[dict[str, Any]] | None=None, **extra: Any) -> dict[str, Any]:
    out = dict(state or {})
    out.setdefault('protocol_version', PROTOCOL_VERSION)
    out.setdefault('kind', 'MechanicalState')
    if 'source' in out and out['source'] != source:
        out.setdefault('artifact_source', out['source'])
    out['source'] = source
    contract = tool_contract(out.get('tool') or source)
    if contract:
        out.setdefault('tool_contract', contract)
    if status is not None:
        out['status'] = status
    else:
        out.setdefault('status', 'unknown')
    if suggested_next_actions:
        out['suggested_next_actions'] = suggested_next_actions
    if errors:
        out['errors'] = errors
    for key, value in extra.items():
        if value is not None:
            out[key] = value
    return out

def _finite_float(value: Any, default: float) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return default
    if parsed != parsed or parsed in (float('inf'), float('-inf')):
        return default
    return parsed

def _clamped_float(value: Any, default: float, low: float, high: float) -> float:
    return max(low, min(high, _finite_float(value, default)))

def _clamped_int(value: Any, default: int, low: int, high: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return default
    return max(low, min(high, parsed))

