@dataclass
class BudgetWorkItem:
    task_id: str
    base_score: float
    metadata: dict[str, Any] = field(default_factory=dict)
    enabled: bool = True
    status: str = 'ready'
    grant_count: int = 0
    committed_budget: float = 0.0
    failures: int = 0
    progress: float = 0.0
    companion_succeeded: bool = False
    last_context_version: int = -1

class RenewableBudgetBroker:

    def __init__(self, policy: MidpointBudgetPolicy):
        self.policy = policy
        self.tasks: dict[str, BudgetWorkItem] = {}
        self.events: list[dict[str, Any]] = []
        self.committed_budget = 0.0
        self.context_version = 0

    def register(self, task_id: str, *, base_score: float, metadata: dict[str, Any] | None=None, enabled: bool=True) -> None:
        if task_id in self.tasks:
            raise ValueError(f'duplicate budget task: {task_id}')
        self.tasks[task_id] = BudgetWorkItem(task_id=task_id, base_score=float(base_score), metadata=dict(metadata or {}), enabled=enabled)

    @property
    def remaining_budget(self) -> float:
        return max(0.0, self.policy.total_budget - self.committed_budget)

    def advance_context(self) -> int:
        self.context_version += 1
        self.events.append({'event': 'context_advanced', 'context_version': self.context_version})
        return self.context_version

    def update(self, task_id: str, *, enabled: bool | None=None, companion_succeeded: bool | None=None, base_score: float | None=None) -> None:
        task = self.tasks[task_id]
        if enabled is not None:
            task.enabled = enabled
        if companion_succeeded is not None:
            task.companion_succeeded = companion_succeeded
        if base_score is not None:
            task.base_score = float(base_score)

    def _tie_break(self, task_id: str) -> float:
        encoded = f'{self.policy.seed}:{task_id}'.encode('utf-8')
        return (zlib.crc32(encoded) & 4294967295) / 4294967295 * self.policy.tie_break_weight

    def score(self, task: BudgetWorkItem) -> float:
        exploration = self.policy.exploration_weight / (1.0 + task.grant_count) ** 0.5
        return task.base_score + exploration + self.policy.progress_weight * task.progress + (self.policy.companion_success_weight if task.companion_succeeded else 0.0) - self.policy.failure_penalty * task.failures + self._tie_break(task.task_id)

    def _eligible(self, task: BudgetWorkItem) -> bool:
        if not task.enabled or task.status in {'succeeded', 'refuted', 'cancelled'}:
            return False
        if task.grant_count == 0:
            return True
        if task.grant_count < self.policy.max_grants_per_task:
            return True
        return task.last_context_version < self.context_version

    def next_grant(self) -> tuple[BudgetWorkItem, float] | None:
        if self.remaining_budget <= 1e-09:
            return None
        eligible = [task for task in self.tasks.values() if self._eligible(task)]
        if not eligible:
            return None
        unstarted = [task for task in eligible if task.grant_count == 0]
        pool = unstarted or eligible
        task = max(pool, key=lambda item: (self.score(item), -len(item.task_id), item.task_id))
        requested = min(self.policy.max_grant, self.policy.initial_grant * self.policy.grant_growth ** task.grant_count)
        grant = min(requested, self.remaining_budget)
        if grant <= 1e-09:
            return None
        score = self.score(task)
        task.grant_count += 1
        task.committed_budget += grant
        task.last_context_version = self.context_version
        self.committed_budget += grant
        self.events.append({'event': 'grant', 'task_id': task.task_id, 'leg': task.metadata.get('leg'), 'candidate': task.metadata.get('candidate'), 'grant': round(grant, 6), 'grant_index': task.grant_count, 'score': round(score, 6), 'context_version': self.context_version, 'committed_total': round(self.committed_budget, 6), 'remaining': round(self.remaining_budget, 6)})
        return (task, grant)

    def report(self, task_id: str, outcome: str, *, progress: float=0.0, elapsed_seconds: float | None=None, detail: Any=None) -> None:
        task = self.tasks[task_id]
        task.progress = max(0.0, min(1.0, float(progress)))
        if outcome in {'succeeded', 'refuted', 'cancelled'}:
            task.status = outcome
        else:
            task.status = 'retryable'
            task.failures += 1
        event: dict[str, Any] = {'event': 'report', 'task_id': task.task_id, 'outcome': task.status, 'progress': round(task.progress, 6), 'context_version': self.context_version}
        if elapsed_seconds is not None:
            event['elapsed_seconds'] = round(max(0.0, elapsed_seconds), 6)
        if detail is not None:
            event['detail'] = detail
        self.events.append(event)

    def snapshot(self) -> dict[str, Any]:
        return {'kind': 'renewable_budget_broker', 'policy_id': self.policy.policy_id, 'policy': self.policy.to_mapping(), 'committed_budget': round(self.committed_budget, 6), 'remaining_budget': round(self.remaining_budget, 6), 'context_version': self.context_version, 'tasks': [{'task_id': task.task_id, 'status': task.status, 'enabled': task.enabled, 'grant_count': task.grant_count, 'committed_budget': round(task.committed_budget, 6), 'failures': task.failures, 'progress': round(task.progress, 6), 'companion_succeeded': task.companion_succeeded, **task.metadata} for task in self.tasks.values()], 'events': list(self.events)}
