def read_msg() -> dict[str, Any]:
    line = sys.stdin.readline()
    if not line:
        sys.exit(0)
    return json.loads(line)

def send_msg(msg: dict[str, Any]) -> None:
    print(json.dumps(msg), flush=True)

def call_judge(verdict: str, code: str) -> dict[str, Any]:
    send_msg({'call': 'judge', 'verdict': verdict, 'code': code})
    return read_msg()

def call_llm(context: dict[str, Any]) -> dict[str, Any]:
    send_msg({'call': 'llm', 'context': context})
    return read_msg()
PROTOCOL_VERSION = 'sair-collab-protocol-v0'
_DECISIVE_TRUE_JUDGE_REJECTIONS: set[str] = set()
_JUDGE_FEEDBACK_JOURNAL: list[dict[str, Any]] = []

@dataclass(frozen=True)
class ProtocolIssue:
    code: str
    message: str
    field: str | None = None

    def to_dict(self) -> dict[str, Any]:
        out = {'code': self.code, 'message': self.message}
        if self.field:
            out['field'] = self.field
        return out

def protocol_state(kind: str, status: str, source: str, **extra: Any) -> dict[str, Any]:
    out: dict[str, Any] = {'protocol_version': PROTOCOL_VERSION, 'kind': kind, 'status': status, 'source': source}
    contract = tool_contract(extra.get('tool') or source) if 'tool_contract' not in extra else None
    if contract:
        out['tool_contract'] = contract
    for key, value in extra.items():
        if value is not None:
            out[key] = value
    return out

def protocolize_state(state: dict[str, Any] | None, source: str, *, status: str | None=None, suggested_next_actions: list[dict[str, Any]] | None=None, errors: list[dict[str, Any]] | None=None, **extra: Any) -> dict[str, Any]:
    out = dict(state or {})
    out.setdefault('protocol_version', PROTOCOL_VERSION)
    out.setdefault('kind', 'MechanicalState')
    if 'source' in out and out['source'] != source:
        out.setdefault('artifact_source', out['source'])
    out['source'] = source
    contract = tool_contract(out.get('tool') or source)
    if contract:
        out.setdefault('tool_contract', contract)
    if status is not None:
        out['status'] = status
    else:
        out.setdefault('status', 'unknown')
    if suggested_next_actions:
        out['suggested_next_actions'] = suggested_next_actions
    if errors:
        out['errors'] = errors
    for key, value in extra.items():
        if value is not None:
            out[key] = value
    return out

def _finite_float(value: Any, default: float) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return default
    if parsed != parsed or parsed in (float('inf'), float('-inf')):
        return default
    return parsed

def _clamped_float(value: Any, default: float, low: float, high: float) -> float:
    return max(low, min(high, _finite_float(value, default)))

def _clamped_int(value: Any, default: int, low: int, high: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return default
    return max(low, min(high, parsed))

@dataclass(frozen=True)
class MidpointBudgetPolicy:
    total_budget: float
    initial_grant: float = 2.5
    grant_growth: float = 2.0
    max_grant: float = 10.0
    max_grants_per_task: int = 3
    attain_priority: float = 1.0
    consume_priority: float = 1.2
    goal_priority: float = 1.1
    relevance_weight: float = 0.35
    reuse_weight: float = 0.25
    exploration_weight: float = 0.3
    progress_weight: float = 0.4
    companion_success_weight: float = 1.25
    failure_penalty: float = 0.15
    tie_break_weight: float = 0.001
    seed: int = 0

    @classmethod
    def from_mapping(cls, value: Any=None, *, candidate_count: int=1, requested_total: Any=None) -> 'MidpointBudgetPolicy':
        raw = dict(value) if isinstance(value, dict) else {}
        default_total = max(10.0, 10.0 * (max(1, min(5, candidate_count)) + 1))
        total = raw.get('total_budget', raw.get('total', requested_total))
        total_budget = _clamped_float(total, default_total, 1.0, 600.0)
        initial = _clamped_float(raw.get('initial_grant', raw.get('minimum_grant')), 2.5, 0.1, min(60.0, total_budget))
        max_grant = _clamped_float(raw.get('max_grant'), 10.0, initial, min(120.0, total_budget))
        return cls(total_budget=total_budget, initial_grant=initial, grant_growth=_clamped_float(raw.get('grant_growth', raw.get('growth_factor')), 2.0, 1.0, 4.0), max_grant=max_grant, max_grants_per_task=_clamped_int(raw.get('max_grants_per_task'), 3, 1, 8), attain_priority=_clamped_float(raw.get('attain_priority'), 1.0, 0.0, 10.0), consume_priority=_clamped_float(raw.get('consume_priority'), 1.2, 0.0, 10.0), goal_priority=_clamped_float(raw.get('goal_priority'), 1.1, 0.0, 10.0), relevance_weight=_clamped_float(raw.get('relevance_weight'), 0.35, 0.0, 10.0), reuse_weight=_clamped_float(raw.get('reuse_weight'), 0.25, 0.0, 10.0), exploration_weight=_clamped_float(raw.get('exploration_weight'), 0.3, 0.0, 10.0), progress_weight=_clamped_float(raw.get('progress_weight'), 0.4, 0.0, 10.0), companion_success_weight=_clamped_float(raw.get('companion_success_weight'), 1.25, 0.0, 10.0), failure_penalty=_clamped_float(raw.get('failure_penalty'), 0.15, 0.0, 10.0), tie_break_weight=_clamped_float(raw.get('tie_break_weight'), 0.001, 0.0, 1.0), seed=_clamped_int(raw.get('seed'), 0, 0, 2 ** 31 - 1))

    def to_mapping(self) -> dict[str, Any]:
        return {'total_budget': self.total_budget, 'initial_grant': self.initial_grant, 'grant_growth': self.grant_growth, 'max_grant': self.max_grant, 'max_grants_per_task': self.max_grants_per_task, 'attain_priority': self.attain_priority, 'consume_priority': self.consume_priority, 'goal_priority': self.goal_priority, 'relevance_weight': self.relevance_weight, 'reuse_weight': self.reuse_weight, 'exploration_weight': self.exploration_weight, 'progress_weight': self.progress_weight, 'companion_success_weight': self.companion_success_weight, 'failure_penalty': self.failure_penalty, 'tie_break_weight': self.tie_break_weight, 'seed': self.seed}

    @property
    def policy_id(self) -> str:
        encoded = json.dumps(self.to_mapping(), sort_keys=True, separators=(',', ':')).encode('utf-8')
        return f'midpoint_budget_v1_{zlib.crc32(encoded) & 4294967295:08x}'

@dataclass
class BudgetWorkItem:
    task_id: str
    base_score: float
    metadata: dict[str, Any] = field(default_factory=dict)
    enabled: bool = True
    status: str = 'ready'
    grant_count: int = 0
    committed_budget: float = 0.0
    failures: int = 0
    progress: float = 0.0
    companion_succeeded: bool = False
    last_context_version: int = -1

class RenewableBudgetBroker:

    def __init__(self, policy: MidpointBudgetPolicy):
        self.policy = policy
        self.tasks: dict[str, BudgetWorkItem] = {}
        self.events: list[dict[str, Any]] = []
        self.committed_budget = 0.0
        self.context_version = 0

    def register(self, task_id: str, *, base_score: float, metadata: dict[str, Any] | None=None, enabled: bool=True) -> None:
        if task_id in self.tasks:
            raise ValueError(f'duplicate budget task: {task_id}')
        self.tasks[task_id] = BudgetWorkItem(task_id=task_id, base_score=float(base_score), metadata=dict(metadata or {}), enabled=enabled)

    @property
    def remaining_budget(self) -> float:
        return max(0.0, self.policy.total_budget - self.committed_budget)

    def advance_context(self) -> int:
        self.context_version += 1
        self.events.append({'event': 'context_advanced', 'context_version': self.context_version})
        return self.context_version

    def update(self, task_id: str, *, enabled: bool | None=None, companion_succeeded: bool | None=None, base_score: float | None=None) -> None:
        task = self.tasks[task_id]
        if enabled is not None:
            task.enabled = enabled
        if companion_succeeded is not None:
            task.companion_succeeded = companion_succeeded
        if base_score is not None:
            task.base_score = float(base_score)

    def _tie_break(self, task_id: str) -> float:
        encoded = f'{self.policy.seed}:{task_id}'.encode('utf-8')
        return (zlib.crc32(encoded) & 4294967295) / 4294967295 * self.policy.tie_break_weight

    def score(self, task: BudgetWorkItem) -> float:
        exploration = self.policy.exploration_weight / (1.0 + task.grant_count) ** 0.5
        return task.base_score + exploration + self.policy.progress_weight * task.progress + (self.policy.companion_success_weight if task.companion_succeeded else 0.0) - self.policy.failure_penalty * task.failures + self._tie_break(task.task_id)

    def _eligible(self, task: BudgetWorkItem) -> bool:
        if not task.enabled or task.status in {'succeeded', 'refuted', 'cancelled'}:
            return False
        if task.grant_count == 0:
            return True
        if task.grant_count < self.policy.max_grants_per_task:
            return True
        return task.last_context_version < self.context_version

    def next_grant(self) -> tuple[BudgetWorkItem, float] | None:
        if self.remaining_budget <= 1e-09:
            return None
        eligible = [task for task in self.tasks.values() if self._eligible(task)]
        if not eligible:
            return None
        unstarted = [task for task in eligible if task.grant_count == 0]
        pool = unstarted or eligible
        task = max(pool, key=lambda item: (self.score(item), -len(item.task_id), item.task_id))
        requested = min(self.policy.max_grant, self.policy.initial_grant * self.policy.grant_growth ** task.grant_count)
        grant = min(requested, self.remaining_budget)
        if grant <= 1e-09:
            return None
        score = self.score(task)
        task.grant_count += 1
        task.committed_budget += grant
        task.last_context_version = self.context_version
        self.committed_budget += grant
        self.events.append({'event': 'grant', 'task_id': task.task_id, 'leg': task.metadata.get('leg'), 'candidate': task.metadata.get('candidate'), 'grant': round(grant, 6), 'grant_index': task.grant_count, 'score': round(score, 6), 'context_version': self.context_version, 'committed_total': round(self.committed_budget, 6), 'remaining': round(self.remaining_budget, 6)})
        return (task, grant)

    def report(self, task_id: str, outcome: str, *, progress: float=0.0, elapsed_seconds: float | None=None, detail: Any=None) -> None:
        task = self.tasks[task_id]
        task.progress = max(0.0, min(1.0, float(progress)))
        if outcome in {'succeeded', 'refuted', 'cancelled'}:
            task.status = outcome
        else:
            task.status = 'retryable'
            task.failures += 1
        event: dict[str, Any] = {'event': 'report', 'task_id': task.task_id, 'outcome': task.status, 'progress': round(task.progress, 6), 'context_version': self.context_version}
        if elapsed_seconds is not None:
            event['elapsed_seconds'] = round(max(0.0, elapsed_seconds), 6)
        if detail is not None:
            event['detail'] = detail
        self.events.append(event)

    def snapshot(self) -> dict[str, Any]:
        return {'kind': 'renewable_budget_broker', 'policy_id': self.policy.policy_id, 'policy': self.policy.to_mapping(), 'committed_budget': round(self.committed_budget, 6), 'remaining_budget': round(self.remaining_budget, 6), 'context_version': self.context_version, 'tasks': [{'task_id': task.task_id, 'status': task.status, 'enabled': task.enabled, 'grant_count': task.grant_count, 'committed_budget': round(task.committed_budget, 6), 'failures': task.failures, 'progress': round(task.progress, 6), 'companion_succeeded': task.companion_succeeded, **task.metadata} for task in self.tasks.values()], 'events': list(self.events)}
