def normalize(text: str) -> str:
    return text.replace('*', '◇') if isinstance(text, str) else text

def variables_of(text: str) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for v in re.findall('\\b([a-z][a-z0-9_]*)\\b', text):
        if v not in seen:
            seen.add(v)
            out.append(v)
    return out

def strip_outer(s: str) -> str:
    s = s.strip()
    while len(s) >= 2 and s[0] == '(' and (s[-1] == ')'):
        depth = 0
        wraps = True
        for i, c in enumerate(s):
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            if depth == 0 and i < len(s) - 1:
                wraps = False
                break
        if not wraps:
            break
        s = s[1:-1].strip()
    return s

def parse_term(text: str, variables: set[str]) -> Term:
    s = strip_outer(normalize(text))
    depth = 0
    last_op = -1
    for i, c in enumerate(s):
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
        elif c == '◇' and depth == 0:
            last_op = i
    if last_op >= 0:
        return ('op', parse_term(s[:last_op], variables), parse_term(s[last_op + 1:], variables))
    if s in variables:
        return ('var', s)
    raise ValueError(f'cannot parse term: {text!r}')

def parse_equation(text: str) -> dict[str, Any]:
    text = normalize(text)
    lhs_s, rhs_s = [p.strip() for p in text.split('=', 1)]
    vs = variables_of(text)
    vset = set(vs)
    lhs = parse_term(lhs_s, vset)
    rhs = parse_term(rhs_s, vset)
    return {'text': f'{term_to_str(lhs)} = {term_to_str(rhs)}', 'variables': vs, 'lhs': lhs, 'rhs': rhs}

def term_to_str(t: Term) -> str:
    if t[0] == 'var':
        return t[1]
    return f'({term_to_str(t[1])} ◇ {term_to_str(t[2])})'

def term_to_str_subst(t: Term, subst: dict[str, str]) -> str:
    if t[0] == 'var':
        return subst.get(t[1], t[1])
    return f'({term_to_str_subst(t[1], subst)} ◇ {term_to_str_subst(t[2], subst)})'

def subterms(t: Term) -> list[Term]:
    if t[0] == 'var':
        return [t]
    return [t] + subterms(t[1]) + subterms(t[2])

def term_variables(t: Term) -> list[str]:
    if t[0] == 'var':
        return [t[1]]
    return unique(term_variables(t[1]) + term_variables(t[2]))

def term_var_count(t: Term, var: str) -> int:
    if t[0] == 'var':
        return 1 if t[1] == var else 0
    return term_var_count(t[1], var) + term_var_count(t[2], var)

def term_leaf_sequence(t: Term) -> tuple[str, ...]:
    if t[0] == 'var':
        return (t[1],)
    return term_leaf_sequence(t[1]) + term_leaf_sequence(t[2])

def term_occurrence_signature(t: Term, modulus: int | None=None) -> tuple[tuple[str, int], ...]:
    counts = Counter(term_leaf_sequence(t))
    if modulus is None:
        return tuple(sorted(((var, int(count)) for var, count in counts.items())))
    return tuple(sorted(((var, int(count) % modulus) for var, count in counts.items() if int(count) % modulus)))

def term_left_path_depth(t: Term) -> int:
    return 0 if t[0] == 'var' else 1 + term_left_path_depth(t[1])

def term_right_path_depth(t: Term) -> int:
    return 0 if t[0] == 'var' else 1 + term_right_path_depth(t[2])

def equation_signature_holds(eq: dict[str, Any], signature) -> bool:
    return signature(eq['lhs']) == signature(eq['rhs'])

def symbolic_invariant_report(h_eq: dict[str, Any], g_eq: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen_actions: set[str] = set()

    def add(family: str, signature, action: dict[str, Any] | None, reason: str) -> None:
        h_holds = equation_signature_holds(h_eq, signature)
        if not h_holds:
            return
        g_holds = equation_signature_holds(g_eq, signature)
        action_key = json.dumps(action, sort_keys=True) if action is not None else family
        if action_key in seen_actions:
            return
        seen_actions.add(action_key)
        rows.append({'family': family, 'h_holds': True, 'g_holds': g_holds, 'separates_goal': not g_holds, 'reason': reason, 'action': action})
    add('left_projection', lambda term: term_leaf_sequence(term)[0], {'kind': 'false_model_family', 'carrier_size': 2, 'default': {'kind': 'left'}, 'budget': 3}, 'terms evaluate to their leftmost leaf')
    add('right_projection', lambda term: term_leaf_sequence(term)[-1], {'kind': 'false_model_family', 'carrier_size': 2, 'default': {'kind': 'right'}, 'budget': 3}, 'terms evaluate to their rightmost leaf')
    add('set_semilattice', lambda term: frozenset(term_leaf_sequence(term)), {'kind': 'false_model_family', 'carrier_size': 2, 'default': {'kind': 'max'}, 'budget': 3}, 'the two-element join semilattice evaluates a term by the set of variables assigned 1')
    add('free_semigroup_leaf_sequence', term_leaf_sequence, None, 'H preserves exact leaf order; a finite semigroup quotient may separate a different goal word')
    for modulus in (2, 3, 5, 7):
        add(f'occurrence_counts_mod_{modulus}', lambda term, modulus=modulus: term_occurrence_signature(term, modulus), {'kind': 'false_model_family', 'carrier_size': modulus, 'default': {'kind': 'affine', 'params': [1, 1, 0]}, 'budget': 3}, f'addition modulo {modulus} evaluates occurrence-count vectors')
    add('left_successor_mod_3', lambda term: (term_leaf_sequence(term)[0], term_left_path_depth(term) % 3), {'kind': 'false_model_family', 'carrier_size': 3, 'default': {'kind': 'left_successor'}, 'budget': 3}, 'a ◇ b = a+1 mod 3 tracks the leftmost variable and left-path depth')
    add('right_successor_mod_3', lambda term: (term_leaf_sequence(term)[-1], term_right_path_depth(term) % 3), {'kind': 'false_model_family', 'carrier_size': 3, 'default': {'kind': 'right_successor'}, 'budget': 3}, 'a ◇ b = b+1 mod 3 tracks the rightmost variable and right-path depth')
