def tool_advice(h_eq: dict[str, Any], g_eq: dict[str, Any], prefer_false: bool=False) -> str:
    ranked = []
    for invariant in symbolic_invariant_report(h_eq, g_eq):
        action = invariant.get('action')
        if invariant.get('separates_goal') and isinstance(action, dict):
            ranked.append({'tool': 'false_model_family', 'score': 100, 'why': f"Strict {invariant['family']} invariant satisfies H and separates G: {invariant['reason']}.", 'call': action})
    for item in goal_generalization_actions(h_eq, g_eq):
        action = item['action']
        ranked.append({'tool': action.get('tool') or action.get('kind', 'midpoint'), 'score': 96, 'why': item['reason'], 'strategy_card': item['card'], 'call': action})
    for action in right_context_contraction_actions(h_eq, g_eq):
        ranked.append({'tool': 'lemma_hint', 'score': 91, 'why': 'Goal differs only by a right argument under a shared left prefix; try this non-refuted reusable contraction helper.', 'call': action})
    if right_square_chain_body(h_eq, g_eq) or right_square_h_roles(h_eq):
        ranked.append({'tool': 'right_square_chain', 'score': 98, 'why': 'H/G match the trusted right-square absorption helper-chain renderer.', 'call': {'kind': 'tool_call', 'tool': 'right_square_chain', 'target': 'goal', 'budget': 15}})
        ranked.append({'tool': 'lemma_chain', 'score': 90, 'why': 'Same proof through generic helper-chain consumer.', 'call': {'kind': 'tool_call', 'tool': 'lemma_chain', 'target': 'goal', 'lemmas': [{'name': 'square_absorb', 'equation': 'u ◇ (v ◇ v) = v'}, {'name': 'right_square', 'equation': 'u ◇ v = v ◇ v'}]}})
    if repeated_self_absorption_h(h_eq, g_eq):
        ranked.append({'tool': 'helper_chain_portfolio', 'score': 93, 'why': 'H has repeated self-absorption; try reusable helper chains through the generic midpoint consumer and use their proved/not-consumed feedback.', 'call': {'kind': 'tool_call', 'tool': 'helper_chain_portfolio', 'target': 'goal', 'chains': ['generic_right_square_absorption'], 'budget': 12}})
    if nested_tail_absorption_h(h_eq, g_eq):
        ranked.append({'tool': 'helper_chain_portfolio', 'score': 97, 'why': 'H has nested-tail absorption; prove nested_absorb, then the broad tail_any contraction law and instantiate it to G.', 'call': {'kind': 'tool_call', 'tool': 'helper_chain_portfolio', 'target': 'goal', 'chains': ['nested_tail_absorption'], 'budget': 36}})
    if square_sandwich_h_roles(h_eq):
        ranked.append({'tool': 'lemma_chain', 'score': 98, 'why': 'H has the square-witness/sandwich shape; use the four-helper chain.', 'call': {'kind': 'tool_call', 'tool': 'lemma_chain', 'target': 'goal', 'lemmas': [{'name': 'square_const', 'equation': 'u ◇ u = v ◇ v'}, {'name': 'right_id_square', 'equation': 'u ◇ (v ◇ v) = u'}, {'name': 'sandwich', 'equation': '(v ◇ u) ◇ v = u'}, {'name': 'left_sandwich', 'equation': 'v ◇ (u ◇ v) = u'}]}})
        ranked.append({'tool': 'square_sandwich_chain', 'score': 92, 'why': 'Focused equivalent renderer for the square-witness helper chain.', 'call': {'kind': 'tool_call', 'tool': 'square_sandwich_chain', 'target': 'goal', 'budget': 15}})
    if rowconst_h_roles(h_eq):
        ranked.append({'tool': 'rowconst_certificates', 'score': 85, 'why': 'H matches a row-constant certificate pattern.', 'call': {'kind': 'tool_call', 'tool': 'rowconst_certificates', 'target': 'goal'}})
    if square_rowconst_h_roles(h_eq):
        ranked.append({'tool': 'grounding_derived', 'score': 84, 'why': 'H matches square-rowconst grounding; derive/use a◇b=a◇a with an explicit final close.', 'call': {'kind': 'tool_call', 'tool': 'grounding_derived', 'target': 'goal', 'budget': 12}})
    if residue_ray_promising_h(h_eq):
        ranked.append({'tool': 'residue_ray_countermodel', 'score': 95, 'why': 'H returns a lone variable through nested left translations. Search a small residue-controlled clamped-affine family whose left actions may become involutions.', 'call': {'kind': 'tool_call', 'tool': 'residue_ray_countermodel', 'target': 'goal', 'moduli': [2], 'a_values': [-1, 0, 1], 'b_values': [-1, 0, 1], 'c_values': [-1, 0, 1], 'candidate_cap': 2000, 'budget': 2}})
    if h_eq['lhs'][0] == 'var' or h_eq['rhs'][0] == 'var':
        ranked.append({'tool': 'collapse_certificates', 'score': 72, 'why': 'H has a lone-variable side; try deriving a carrier-collapse witness and closing the goal from triviality.', 'call': {'kind': 'tool_call', 'tool': 'collapse_certificates', 'target': 'goal', 'budget': 12}})
    if broad_grounding_orientable(h_eq['lhs'], h_eq['rhs']):
        bg_score = 86 if self_root_absorption_h(h_eq) else 74
        bg_why = 'H has self-root absorption form; derive a factor-irrelevance helper with the broad grounding certificate route.' if self_root_absorption_h(h_eq) else 'H is orientable; try deriving a collapse or factor-irrelevance helper and let Lean close the goal.'
        ranked.append({'tool': 'broad_grounding_derived', 'score': bg_score, 'why': bg_why, 'call': {'kind': 'tool_call', 'tool': 'broad_grounding_derived', 'target': 'goal', 'budget': 12}})
    ranked.append({'tool': 'proof_battery', 'score': 46, 'why': 'Try old battery h-instance layers through the explicit equality graph before risky grind bodies.', 'call': {'kind': 'tool_call', 'tool': 'proof_battery', 'target': 'goal', 'max_graph_candidates': 3}})
    aux_score = 88 if standard_aux_plausible_h(h_eq) else 42
    aux_why = 'H has variables on only one side; try collapse/projection/rowconst lemmas through proof-carrying superposition.' if standard_aux_plausible_h(h_eq) else 'Try standard collapse/projection/rowconst lemmas through proof-carrying superposition and consume any proved helper.'
    ranked.append({'tool': 'standard_aux_superposition', 'score': aux_score, 'why': aux_why, 'call': {'kind': 'tool_call', 'tool': 'standard_aux_superposition', 'target': 'goal', 'lemmas': ['const', 'proj_l', 'proj_r', 'rowconst'], 'budget': 10}})
    ranked.append({'tool': 'lemma_hint', 'score': 50, 'why': 'Use closest_pairs from mechanical feedback to propose a concrete bridge equation; never return the placeholder text.', 'call': {'kind': 'tool_call', 'tool': 'lemma_hint', 'target': 'goal', 'lemmas': ['<small bridge equation>']}})
    ranked.append({'tool': 'forward_saturation', 'score': 45, 'why': 'Try extra h-instantiation seed terms near the frontier.', 'call': {'kind': 'tool_call', 'tool': 'forward_saturation', 'target': 'goal', 'seed_terms': goal_terms(g_eq, 4), 'budget': 3}})
    ranked.append({'tool': 'goal_superposition', 'score': 43, 'why': 'Broad proof-carrying paramodulation consumer; useful when graph search needs unification-on-demand.', 'call': {'kind': 'tool_call', 'tool': 'goal_superposition', 'target': 'goal', 'budget': 8}})
    false_routes = ['local_search:n=6:seed=0', 'local_search:n=6:seed=1', 'local_search:n=7:seed=0', 'model_finder_v2:n=7', 'model_finder_v2:n=8', 'sympy_sat:n=6', 'skew_product:2x3', 'cp_sat:n=5', 'cp_sat:n=6', 'poly_ce:tier=2:nmax=13', 'structured_ce:max_n=7'] if prefer_false else ['model_finder_v2:n=5', 'skew_product:2x3', 'local_search:n=6:seed=2', 'poly_ce:tier=2:nmax=13', 'structured_ce:max_n=7']
    ranked.append({'tool': 'false_model_search', 'score': 94 if prefer_false else 40, 'why': 'Prefer concrete finite-countermodel routes now; true-side tools have already failed or are low-confidence.' if prefer_false else 'Try bounded finite countermodel routes if false is plausible; model_finder_v2 gives goal-directed Skolem feedback and poly_ce can find structured larger witnesses.', 'call': {'kind': 'tool_call', 'tool': 'false_model_search', 'target': 'goal', 'routes': false_routes, 'budget': 12 if prefer_false else 8}})
    ranked.append({'tool': 'false_model_family', 'score': 92 if prefer_false else 35, 'why': 'Propose a compact finite operation family when fixed routes are exhausted; the consumer returns exact H/G repair diagnostics.', 'call': {'kind': 'false_model_family', 'carrier_size': 8, 'default': {'kind': 'affine', 'params': [1, 0, 0]}, 'rules': [{'when': {'kind': 'diagonal'}, 'value': 'i + 1'}], 'budget': 8}})
    ranked.sort(key=lambda item: item['score'], reverse=True)
    return json.dumps({'kind': 'tool_recommendations', 'recommended_next_action': ranked[0]['call'] if ranked else None, 'ranked': ranked[:6]}, ensure_ascii=False)

def try_true(body: str) -> bool:
    code = make_true_code(body)
    result = call_judge('true', code)
    record_judge_feedback('legacy:true', 'true', code, result, source='legacy_helper')
    return result.get('status') == 'accepted'

def try_false(n: int, table: list[list[int]]) -> bool:
    code = make_false_code(n, table)
    result = call_judge('false', code)
    record_judge_feedback('legacy:false_table', 'false', code, result, source='legacy_helper')
    return result.get('status') == 'accepted'

def try_false_artifact(found: tuple[Any, ...]) -> bool:
    n = int(found[0])
    table = found[1]
    if len(found) >= 3 and isinstance(found[2], str) and found[2].strip():
        code = make_false_formula_code(n, found[2])
        result = call_judge('false', code)
        record_judge_feedback('legacy:false_formula', 'false', code, result, source='legacy_helper')
        if result.get('status') == 'accepted':
            return True
    return try_false(n, table)

def emit_attribution_attempt(route: str, verdict: str, *, source: str='baby_solver', detail: dict[str, Any] | None=None) -> None:
    payload = {'protocol_version': PROTOCOL_VERSION, 'event': 'judge_attempt', 'route': route, 'verdict': verdict, 'source': source}
    if detail:
        payload['detail'] = detail
    print('ATTRIBUTION ' + json.dumps(payload, ensure_ascii=False, sort_keys=True), file=sys.stderr, flush=True)

def resource_heavy_grind_probe(route: str, body: str) -> dict[str, Any] | None:
    route_name = route.lower()
    if 'grind' not in body or not any((family in route_name for family in ('deep_saturation', 'old_haves_grind'))):
        return None
    instance_count = len(re.findall('(?m)^\\s*have\\s+(?:sat|h)\\d+\\s*:?=', body))
    if instance_count < 40:
        return None
    return {'reason': 'resource_heavy_grind_probe', 'instance_count': instance_count, 'policy': 'Broad 40-plus-instance grind bodies may guide structured proof search but are not submitted to the judge.'}

def decisive_true_judge_rejection(result: dict[str, Any]) -> bool:
    if result.get('status') not in {'incorrect', 'rejected', 'invalid'}:
        return False
    diagnostic = json.dumps(result, ensure_ascii=False).lower()
    return not any((marker in diagnostic for marker in ('timeout', 'timed out', 'temporarily unavailable', 'connection error', 'provider error')))

def judge_true_attributed(route: str, body: str, *, source: str='baby_solver', detail: dict[str, Any] | None=None) -> dict[str, Any]:
    skipped = resource_heavy_grind_probe(route, body)
    if skipped is not None:
        payload = {'protocol_version': PROTOCOL_VERSION, 'event': 'judge_candidate_skipped', 'route': route, 'verdict': 'true', 'source': source, 'detail': {**(detail or {}), **skipped}}
        print('ATTRIBUTION ' + json.dumps(payload, ensure_ascii=False, sort_keys=True), file=sys.stderr, flush=True)
        return {'status': 'skipped', **skipped}
    code = make_true_code(body)
    if code in _DECISIVE_TRUE_JUDGE_REJECTIONS:
        payload = {'protocol_version': PROTOCOL_VERSION, 'event': 'judge_candidate_skipped', 'route': route, 'verdict': 'true', 'source': source, 'detail': {**(detail or {}), 'reason': 'duplicate_decisive_rejection', 'policy': 'Exact Lean bodies decisively rejected earlier in this solve are not resubmitted.'}}
        print('ATTRIBUTION ' + json.dumps(payload, ensure_ascii=False, sort_keys=True), file=sys.stderr, flush=True)
        return {'status': 'skipped', 'reason': 'duplicate_decisive_rejection'}
    emit_attribution_attempt(route, 'true', source=source, detail=detail)
    result = call_judge('true', code)
    record_judge_feedback(route, 'true', code, result, source=source)
    if decisive_true_judge_rejection(result):
        _DECISIVE_TRUE_JUDGE_REJECTIONS.add(code)
    return result

def try_true_attributed(route: str, body: str, *, source: str='baby_solver', detail: dict[str, Any] | None=None) -> bool:
    result = judge_true_attributed(route, body, source=source, detail=detail)
