        phase_directive = 'This is a false-preferred recovery pass. Return false_model_search, false_model_family, residue_ray_countermodel, false_table, or a concrete midpoint/lemma_chain only. Prefer recommended_next_call when present. If fixed routes are exhausted, propose a coherent symbolic family rather than arbitrary table patches. Never repeat routes listed in diagnostic_highlights.tried_routes or diagnostic_highlights.tried_in_collaboration. Do not call standard_aux_superposition, proof_battery, forward_saturation, or goal_superposition in this pass; those true-side routes were already tried or are low-confidence.'
        advice_prefer_false = True
    elif prefer_false == 'balanced':
        if false_strategy_cards(mechanical_feedback):
            phase_directive = 'This is a balanced pre-child recovery pass with concrete false-route telemetry. Return the false_model_search recommended_next_call, a coherent false_model_family, a concrete false_table, or a real midpoint/lemma_chain only. Never repeat routes listed in diagnostic_highlights.tried_routes or diagnostic_highlights.tried_in_collaboration. Do not call standard_aux_superposition, proof_battery, forward_saturation, or goal_superposition while a false continuation card is available.'
        else:
            phase_directive = 'This is a balanced pre-child recovery pass after native true and false tools failed. Prefer a concrete midpoint/lemma_chain that repairs the failed true-side attempts. Use false_model_search only if the feedback gives a specific untried countermodel route; never repeat stale false routes listed in diagnostic_highlights.tried_routes or diagnostic_highlights.tried_in_collaboration.'
        advice_prefer_false = False
    else:
        phase_directive = 'This is a true-collaboration pass. Prefer the top focused true tool or a concrete midpoint/lemma_chain; use false_model_search only if a finite countermodel route is specifically plausible.'
        advice_prefer_false = False
    symbolic_only = not finite_countermodel_search_allowed(semantic_context)
    if symbolic_only:
        symbolic_advice: Any = {'kind': 'audited_semantic_recommendation', 'recommended_next_action': {'kind': 'symbolic_model_patch' if active_symbolic_plan else 'symbolic_model_plan'}, 'prohibited': ['finite_model_search', 'false_table', 'symbolic_finite', 'true_side_tools'], 'reason': 'The finite implication is audited true while the unrestricted implication is false.'}
        cards_for_prompt = json.dumps(symbolic_model_strategy_cards(require_infinite=True), ensure_ascii=False)
        fewshots_for_prompt = 'For this lane, return only symbolic_model_plan, symbolic_model_patch, or a complete infinite_model artifact. A plan separates carrier, pre-model definitions, operation, setup lemmas, the universal H proof, and a concrete refutation of G. After rejection, patch only failed_parts.'
    else:
        frontier_action = latest_midpoint_recommendation(mechanical_feedback)
        if frontier_action and (not advice_prefer_false):
            symbolic_advice, frontier_directive = frontier_prompt_advice(frontier_action, h_eq)
            phase_directive += frontier_directive
        else:
            symbolic_advice = tool_advice(h_eq, g_eq, prefer_false=advice_prefer_false)
        cards_for_prompt = strategy_cards_text(h_eq, g_eq, mechanical_feedback, prefer_false=prefer_false)
        fewshots_for_prompt = sidecar_fewshots(h_eq)
    context = {'problem_analysis': problem_analysis(h_eq, g_eq), 'analysis': analysis(h_eq, g_eq), 'tool_registry': tool_registry_text(capability_mask, include_research_tools=allow_infinite_model_artifacts), 'tool_advice': symbolic_advice, 'strategy_cards': cards_for_prompt, 'phase_directive': phase_directive, 'judge_feedback': judge_feedback_json(), 'mechanical_feedback': feedback_json(mechanical_feedback), 'candidate_blackboard': json.dumps(candidate_blackboard.snapshot() if candidate_blackboard else {'protocol_version': 'candidate-blackboard-v1', 'candidate_count': 0, 'candidates': []}, ensure_ascii=False), 'fewshots': fewshots_for_prompt, 'collaboration_goal': collaboration_goal}
    if symbolic_only:
        context['allowed_action_override'] = ['symbolic_model_plan', 'symbolic_model_patch', 'infinite_model']
    if capability_mask is not None:
        context['capability_manifest'] = capability_manifest(capability_mask)
